/// Sections on the left rail. Section-specific controls (e.g. the
/// "Open in default editor" button in Advanced) are shown / hidden on
/// the active section; non-specific controls stay visible across
/// sections.
pub const Section = enum(u32) {
    appearance,
    terminal,
    shell,
    /// The user profiles, a row for each of their fields (`ReferenceList`,
    /// `ListKind.profiles`): the profile editor.
    profiles,
    privacy,
    updates,
    keybindings,
    advanced,
    /// Every config key, in one list (`ReferenceList`): the reference page.
    reference,

    fn fromButtonId(id: usize) ?Section {
        return switch (id) {
            BTN_SECTION_APPEARANCE => .appearance,
            BTN_SECTION_TERMINAL => .terminal,
            BTN_SECTION_SHELL => .shell,
            BTN_SECTION_PRIVACY => .privacy,
            BTN_SECTION_UPDATES => .updates,
            BTN_SECTION_KEYBINDINGS => .keybindings,
            BTN_SECTION_ADVANCED => .advanced,
            BTN_SECTION_REFERENCE => .reference,
            BTN_SECTION_PROFILES => .profiles,
            else => null,
        };
    }

    fn label(self: Section) [*:0]const u16 {
        return switch (self) {
            .appearance => std.unicode.utf8ToUtf16LeStringLiteral("Appearance"),
            .terminal => std.unicode.utf8ToUtf16LeStringLiteral("Terminal"),
            .shell => std.unicode.utf8ToUtf16LeStringLiteral("Shell"),
            .profiles => std.unicode.utf8ToUtf16LeStringLiteral("Profiles"),
            .privacy => std.unicode.utf8ToUtf16LeStringLiteral("Privacy"),
            .updates => std.unicode.utf8ToUtf16LeStringLiteral("Updates"),
            .keybindings => std.unicode.utf8ToUtf16LeStringLiteral("Keybindings"),
            .advanced => std.unicode.utf8ToUtf16LeStringLiteral("Advanced"),
            .reference => std.unicode.utf8ToUtf16LeStringLiteral("All settings"),
        };
    }

    fn headerText(self: Section) []const u8 {
        return switch (self) {
            .appearance => "Appearance",
            .terminal => "Terminal",
            .shell => "Shell",
            .profiles => "Profiles",
            .privacy => "Privacy",
            .updates => "Updates",
            .keybindings => "Keybindings",
            .advanced => "Advanced",
            .reference => "All settings",
        };
    }

    fn placeholderText(self: Section) []const u8 {
        return switch (self) {
            .appearance => "Fonts, theme, opacity, cursor, and window padding.",
            .terminal => "Scrollback, closing, copying, and clipboard trimming.",
            .shell => "The program a new tab starts, and how noctty works with your shell.",
            .profiles => "Your own profiles: command lines a new tab can start, each with a name, a starting folder and environment variables. Enter edits the selected field, Insert adds a profile and Delete removes what is selected. Save writes the changes to the config file.",
            .privacy => "What programs may do with your clipboard, links, and notifications.",
            .updates => "Whether noctty checks for updates, and which releases it follows.",
            .keybindings => "Key bindings are set in the config file. Every binding in effect is listed below: Enter opens the config file, and Ctrl+C copies a binding's lines.",
            .advanced => "Open the config file in your text editor for settings that have no control here. The file Settings saves to, the problems found in the config, and changes you have not saved yet are listed below.",
            .reference => "Every setting the config file can hold, with the value in effect and what it does. Enter opens the config file, Ctrl+C copies a setting's name, and F2 edits one that has a control in Settings.",
        };
    }
};
const section_count = std.enums.values(Section).len;
comptime {
    if (section_count != win32_uia.widgets.settings_section_count) {
        @compileError("settings section UIA provider count must match Section");
    }
}

fn clickedButton(id: usize, notify: u16, expected_id: usize) bool {
    return id == expected_id and notify == BN_CLICKED;
}

fn clickedSection(id: usize, notify: u16) ?Section {
    if (notify != BN_CLICKED) return null;
    return Section.fromButtonId(id);
}

fn validatedSectionClickFocusTarget(source: ?HWND, expected: ?HWND) ?HWND {
    const source_hwnd = source orelse return null;
    const expected_hwnd = expected orelse return null;
    return if (source_hwnd == expected_hwnd) source_hwnd else null;
}

fn backgroundBlurFromCheckbox(
    current: Config.BackgroundBlur,
    checked: bool,
) Config.BackgroundBlur {
    if (!checked) return .false;

    return switch (current) {
        .radius => |radius| if (radius > 0) current else .true,
        .false, .true => .true,
    };
}

/// Ownership-safe native settings tracked by the transaction model. The three
/// arena-backed edit fields use a parallel tracker below because transaction
/// values must not borrow slices from replaceable Config snapshots.
pub const SettingField = field_model.SettingField;

const OwnedSettingField = enum {
    font_family,
    theme,
    command,
    /// A dropdown, not a text field: a choice is staged at once and never
    /// waits in `owned_text_changed`.
    default_profile,

    fn section(self: OwnedSettingField) Section {
        return nativeSection(self.descriptor().section);
    }

    fn label(self: OwnedSettingField) []const u8 {
        return self.descriptor().label;
    }
    fn descriptor(self: OwnedSettingField) field_model.Descriptor {
        return field_model.forKey(switch (self) {
            .font_family => .@"font-family",
            .theme => .theme,
            .command => .command,
            .default_profile => .@"default-profile",
        }).?;
    }
};

const owned_setting_field_count = std.enums.values(OwnedSettingField).len;

test "settings field model covers each Settings-owned Config key exactly once" {
    inline for (field_model.descriptors) |spec| {
        if (spec.nativeNames()) |names| {
            try expectNativeFieldNames(names, spec.kind, spec.section);
            if (names.form_label) |label| {
                if (std.mem.indexOf(u8, label, "new terminals") != null) {
                    try std.testing.expectEqual(field_model.ApplyPolicy.new_terminals, spec.apply);
                }
            }
        }
        inline for (spec.projections) |part| try expectNativeFieldNames(part.native, .boolean, spec.section);
    }
    comptime field_model.assertCoverage(editable_keys);
}

test "settings field model round trips every descriptor" {
    try field_model.testRoundTrips(std.testing.allocator);
}

// Name contracts protect the generated form from silently using palette
// wording for UIA or the longer visible field captions. Providers stay intact.
fn expectNativeFieldNames(names: field_model.NativeNames, kind: field_model.Kind, section: field_model.Section) !void {
    var control_index: ?usize = null;
    for (settings_control_specs, 0..) |spec, index| {
        if (!std.mem.eql(u8, spec.name, names.accessible_name)) continue;
        try std.testing.expect(control_index == null);
        control_index = index;
        const role: SettingsControlRole = switch (kind) {
            .boolean, .blur => .check_box,
            .choice, .profile => .combo_box,
            else => .edit,
        };
        try std.testing.expectEqual(role, spec.role);
    }
    const index = control_index orelse return error.TestExpectedEqual;
    var model_uses: usize = 0;
    inline for (field_model.descriptors) |spec| {
        if (spec.nativeNames()) |other| {
            if (std.mem.eql(u8, other.accessible_name, names.accessible_name)) model_uses += 1;
        }
        for (spec.projections) |part| {
            if (std.mem.eql(u8, part.native.accessible_name, names.accessible_name)) model_uses += 1;
        }
    }
    try std.testing.expectEqual(@as(usize, 1), model_uses);
    var form_uses: usize = 0;
    for (formItemsForSection(nativeSection(section))) |item| {
        if (item.control_index != index) continue;
        form_uses += 1;
        if (names.form_label) |label| {
            try std.testing.expectEqualStrings(label, settings_label_specs[item.label_index orelse return error.TestExpectedEqual]);
        } else try std.testing.expect(item.label_index == null);
        try std.testing.expectEqual(names.caption != null, item.checkbox);
        if (names.caption) |caption| try std.testing.expectEqualStrings(caption, checkbox_captions[index].?);
    }
    try std.testing.expectEqual(@as(usize, 1), form_uses);
}

/// Native notifications keep their existing typed/arena-owned adapters. This
/// independent set is checked against the descriptor and persistence allowlist;
/// a displayed row never silently grants permission to save a new Config key.
const FieldAdapter = struct {
    display: *const fn (*SettingsWindow) void,
    changed: *const fn (*SettingsWindow) void,
    left: ?*const fn (*SettingsWindow) void = null,
    /// The typed field a generic adapter edits through its own descriptor's
    /// control; checked against the row the adapter is keyed by.
    field: ?SettingField = null,
};
fn ownedEditChanged(comptime field: OwnedSettingField, comptime binding: []const u8) *const fn (*SettingsWindow) void {
    return struct {
        fn changed(self: *SettingsWindow) void {
            if (@field(self.fields, binding)) |edit| self.markOwnedTextChanged(field, edit);
        }
    }.changed;
}
fn display_edit_font_family(self: *SettingsWindow) void {
    if (!self.owned_text_changed[@intFromEnum(OwnedSettingField.font_family)]) self.displayFontFamilyInEdit();
}
fn display_edit_theme(self: *SettingsWindow) void {
    if (!self.owned_text_changed[@intFromEnum(OwnedSettingField.theme)]) self.displayThemeInEdit();
}
fn display_edit_command(self: *SettingsWindow) void {
    if (!self.owned_text_changed[@intFromEnum(OwnedSettingField.command)]) self.displayCommandInEdit();
}
/// A dropdown whose items are the field's curated `Combo` options.
fn comboAdapter(comptime field: SettingField) FieldAdapter {
    const bound = struct {
        fn display(self: *SettingsWindow) void {
            self.displayCombo(field);
        }
        fn changed(self: *SettingsWindow) void {
            self.syncCombo(field);
        }
    };
    return .{ .display = bound.display, .changed = bound.changed, .field = field };
}
/// A checkbox for a plain bool field or a bool projection.
fn checkboxAdapter(comptime field: SettingField) FieldAdapter {
    const bound = struct {
        fn display(self: *SettingsWindow) void {
            self.displayCheckbox(field);
        }
        fn changed(self: *SettingsWindow) void {
            self.syncCheckbox(field);
        }
    };
    return .{ .display = bound.display, .changed = bound.changed, .field = field };
}
/// A number text field (scrollback, font size, opacity).
fn numberAdapter(comptime field: RawScalarField) FieldAdapter {
    const bound = struct {
        fn display(self: *SettingsWindow) void {
            self.displayNumberInEdit(field);
        }
        fn changed(self: *SettingsWindow) void {
            self.syncNumberFromEdit(field);
        }
    };
    return .{ .display = bound.display, .changed = bound.changed, .field = field.setting() };
}
/// A window padding text field: one value or a comma-separated pair.
fn paddingAdapter(comptime field: RawScalarField) FieldAdapter {
    const bound = struct {
        fn display(self: *SettingsWindow) void {
            self.displayPaddingInEdit(field);
        }
        fn changed(self: *SettingsWindow) void {
            self.syncPaddingFromEdit(field);
        }
    };
    return .{ .display = bound.display, .changed = bound.changed, .field = field.setting() };
}
const field_adapters = .{
    .edit_scrollback = numberAdapter(.scrollback_limit),
    .edit_font_size = numberAdapter(.font_size),
    .edit_bg_opacity = numberAdapter(.background_opacity),
    .chk_trim_trail = checkboxAdapter(.trim_trailing_spaces),
    .chk_desktop_notifications = checkboxAdapter(.desktop_notifications),
    .combo_confirm_close = comboAdapter(.confirm_close),
    .combo_copy_on_select = comboAdapter(.copy_on_select),
    .combo_link_url = comboAdapter(.link_url),
    .combo_link_previews = comboAdapter(.link_previews),
    .combo_window_theme = comboAdapter(.window_theme),
    .combo_shell_integ = comboAdapter(.shell_integration),
    .combo_cursor_style = comboAdapter(.cursor_style),
    .chk_bg_blur = FieldAdapter{ .display = SettingsWindow.displayBgBlurInCheckbox, .changed = SettingsWindow.syncBgBlurFromCheckbox },
    .combo_pad_balance = comboAdapter(.padding_balance),
    .combo_auto_update = comboAdapter(.auto_update),
    .combo_auto_update_channel = comboAdapter(.auto_update_channel),
    .edit_font_family = FieldAdapter{ .display = display_edit_font_family, .changed = ownedEditChanged(.font_family, "edit_font_family"), .left = SettingsWindow.syncFontFamilyFromEdit },
    .edit_theme = FieldAdapter{ .display = display_edit_theme, .changed = ownedEditChanged(.theme, "edit_theme"), .left = SettingsWindow.syncThemeFromEdit },
    .edit_command = FieldAdapter{ .display = display_edit_command, .changed = ownedEditChanged(.command, "edit_command"), .left = SettingsWindow.syncCommandFromEdit },
    .combo_default_profile = FieldAdapter{ .display = SettingsWindow.displayDefaultProfile, .changed = SettingsWindow.syncDefaultProfileFromCombo },
    .edit_pad_x = paddingAdapter(.window_padding_x),
    .edit_pad_y = paddingAdapter(.window_padding_y),
    .chk_app_notify_clipboard = checkboxAdapter(.app_notify_clipboard),
    .chk_app_notify_config = checkboxAdapter(.app_notify_config),
    .combo_clipboard_read = comboAdapter(.clipboard_read),
    .combo_clipboard_write = comboAdapter(.clipboard_write),
};

comptime {
    field_model.assertCoverage(editable_keys);
    for (field_model.form_fields) |row| {
        if (!@hasField(@TypeOf(field_adapters), row.native.binding))
            @compileError("Editable Settings descriptor has no native adapter: " ++ row.native.binding);
        if (@field(field_adapters, row.native.binding).field) |field| {
            if (row.field == null or row.field.? != field)
                @compileError("Settings adapter edits another field than its row: " ++ row.native.binding);
        }
        // A scalar/projection uses the value-safe transaction; an owned field
        // must have the matching explicit arena-owned adapter.
        if (row.field == null) {
            var matches: usize = 0;
            for (std.enums.values(OwnedSettingField)) |owned| {
                if (owned.descriptor().key == row.descriptor.key) matches += 1;
            }
            if (matches != 1) @compileError("Owned Settings descriptor needs exactly one adapter");
        }
    }
    for (std.meta.fields(@TypeOf(field_adapters))) |adapter| {
        var matches: usize = 0;
        for (field_model.form_fields) |row| {
            if (std.mem.eql(u8, adapter.name, row.native.binding)) matches += 1;
        }
        if (matches != 1) @compileError("Settings adapter needs exactly one editable descriptor: " ++ adapter.name);
    }
    for (std.enums.values(OwnedSettingField)) |owned| {
        var matches: usize = 0;
        for (field_model.form_fields) |row| if (row.field == null and row.descriptor.key == owned.descriptor().key) {
            matches += 1;
        };
        if (matches != 1) @compileError("Owned Settings adapter needs exactly one editable descriptor");
    }
}

/// The complete persistence allowlist. Effective config contains derived fields
/// and expanded include/shader paths which the native form does not edit.
pub const editable_keys = .{
    Config.Key.@"scrollback-limit",       Config.Key.@"font-size",         Config.Key.@"background-opacity",
    Config.Key.@"window-padding-x",       Config.Key.@"window-padding-y",  Config.Key.@"clipboard-trim-trailing-spaces",
    Config.Key.@"desktop-notifications",  Config.Key.@"app-notifications", Config.Key.@"confirm-close-surface",
    Config.Key.@"copy-on-select",         Config.Key.@"clipboard-read",    Config.Key.@"clipboard-write",
    Config.Key.@"link-url",               Config.Key.@"link-previews",     Config.Key.@"window-theme",
    Config.Key.@"shell-integration",      Config.Key.@"cursor-style",      Config.Key.@"background-blur",
    Config.Key.@"window-padding-balance", Config.Key.@"auto-update",       Config.Key.@"auto-update-channel",
    Config.Key.@"font-family",            Config.Key.theme,                Config.Key.command,
    Config.Key.@"default-profile",
};

/// A control that goes with a number field and writes the field as typing
/// would (`SettingsWindow.sliderMoved`, `spinStep`), so the field keeps
/// its whole-text read, its limit and its validation, and the opacity's
/// preview keeps its floor: a trackbar for the opacity, an up-down for the
/// font size and the scrollback limit. The padding fields take one value or
/// a pair, which a single up-down cannot step, so they have none.
const Companion = enum {
    opacity_slider,
    font_size_spin,
    scrollback_spin,

    const count = std.enums.values(Companion).len;

    fn field(self: Companion) RawScalarField {
        return switch (self) {
            .opacity_slider => .background_opacity,
            .font_size_spin => .font_size,
            .scrollback_spin => .scrollback_limit,
        };
    }

    fn of(self_field: RawScalarField) ?Companion {
        return switch (self_field) {
            .background_opacity => .opacity_slider,
            .font_size => .font_size_spin,
            .scrollback_limit => .scrollback_spin,
            else => null,
        };
    }

    /// The form control (`settings_control_specs`) the companion goes with.
    fn controlIndex(comptime self: Companion) usize {
        const binding = switch (self) {
            .opacity_slider => "edit_bg_opacity",
            .font_size_spin => "edit_font_size",
            .scrollback_spin => "edit_scrollback",
        };
        inline for (settings_control_specs, 0..) |spec, index| {
            if (comptime std.mem.eql(u8, spec.binding, binding)) return index;
        }
        @compileError("no control " ++ binding);
    }

    /// The companion of form control `index`, if it has one.
    fn ofControl(index: usize) ?Companion {
        inline for (comptime std.enums.values(Companion)) |kind| {
            if (index == comptime kind.controlIndex()) return kind;
        }
        return null;
    }

    /// What one step of an up-down adds: a point of font size, a megabyte
    /// of scrollback.
    fn step(self: Companion) f64 {
        return switch (self) {
            .opacity_slider => 0.01,
            .font_size_spin => 1,
            .scrollback_spin => 1_000_000,
        };
    }
};

fn numberAsF64(value: anytype) f64 {
    return switch (@typeInfo(@TypeOf(value))) {
        .int, .comptime_int => @floatFromInt(value),
        .float, .comptime_float => @floatCast(value),
        else => @compileError("not a number"),
    };
}

const INITCOMMONCONTROLSEX = extern struct { size: u32 = @sizeOf(INITCOMMONCONTROLSEX), classes: u32 };
extern "comctl32" fn InitCommonControlsEx(init: *const INITCOMMONCONTROLSEX) callconv(.winapi) BOOL;
const NMHDR = extern struct { hwndFrom: ?HWND, idFrom: usize, code: u32 };
const NMUPDOWN = extern struct { hdr: NMHDR, pos: i32, delta: i32 };
const NMCUSTOMDRAW = extern struct { hdr: NMHDR, stage: u32, hdc: HDC, rc: RECT, item: usize, state: u32, item_lparam: LPARAM };

test "settings mirrors of the SDK's notification and init structs keep its layout" {
    // Read from the Windows SDK's headers (10.0.28000.0): NMHDR in winuser.h;
    // NMUPDOWN, NMCUSTOMDRAW (tagNMCUSTOMDRAWINFO) and INITCOMMONCONTROLSEX in
    // commctrl.h. None sits in a pshpack region (commctrl.h's pshpack1 ones
    // hold the list, tree and tab key-down structs, the pager's NMPGSCROLL
    // and the task dialog's; winuser.h's pshpack2 one the dialog templates),
    // so each has natural alignment. These are LLP64's offsets, the same on
    // x64 and ARM64.
    comptime {
        if (@sizeOf(usize) != 8) @compileError("these layouts are LLP64's (8-byte pointers)");
    }
    const expectEqual = std.testing.expectEqual;
    // NMHDR: hwndFrom, idFrom (UINT_PTR), code (UINT).
    try expectEqual(@as(usize, 24), @sizeOf(NMHDR));
    try expectEqual(@as(usize, 0), @offsetOf(NMHDR, "hwndFrom"));
    try expectEqual(@as(usize, 8), @offsetOf(NMHDR, "idFrom"));
    try expectEqual(@as(usize, 16), @offsetOf(NMHDR, "code"));
    // NMUPDOWN: hdr, iPos, iDelta (int).
    try expectEqual(@as(usize, 32), @sizeOf(NMUPDOWN));
    try expectEqual(@as(usize, 0), @offsetOf(NMUPDOWN, "hdr"));
    try expectEqual(@as(usize, 24), @offsetOf(NMUPDOWN, "pos"));
    try expectEqual(@as(usize, 28), @offsetOf(NMUPDOWN, "delta"));
    // NMCUSTOMDRAW: hdr, dwDrawStage (DWORD), hdc, rc (RECT), dwItemSpec
    // (DWORD_PTR), uItemState (UINT), lItemlParam (LPARAM).
    try expectEqual(@as(usize, 80), @sizeOf(NMCUSTOMDRAW));
    try expectEqual(@as(usize, 0), @offsetOf(NMCUSTOMDRAW, "hdr"));
    try expectEqual(@as(usize, 24), @offsetOf(NMCUSTOMDRAW, "stage"));
    try expectEqual(@as(usize, 32), @offsetOf(NMCUSTOMDRAW, "hdc"));
    try expectEqual(@as(usize, 40), @offsetOf(NMCUSTOMDRAW, "rc"));
    try expectEqual(@as(usize, 56), @offsetOf(NMCUSTOMDRAW, "item"));
    try expectEqual(@as(usize, 64), @offsetOf(NMCUSTOMDRAW, "state"));
    try expectEqual(@as(usize, 72), @offsetOf(NMCUSTOMDRAW, "item_lparam"));
    try expectEqual(@as(usize, 16), @sizeOf(RECT));
    // INITCOMMONCONTROLSEX: dwSize, dwICC (DWORD); dwSize is the struct's own size.
    try expectEqual(@as(usize, 8), @sizeOf(INITCOMMONCONTROLSEX));
    try expectEqual(@as(usize, 0), @offsetOf(INITCOMMONCONTROLSEX, "size"));
    try expectEqual(@as(usize, 4), @offsetOf(INITCOMMONCONTROLSEX, "classes"));
    try expectEqual(@as(u32, 8), (INITCOMMONCONTROLSEX{ .classes = 0 }).size);
}

/// Scalar EDIT controls whose raw text can temporarily be invalid and
/// therefore cannot yet be represented by the typed settings transaction.
const RawScalarField = enum {
    scrollback_limit,
    font_size,
    background_opacity,
    window_padding_x,
    window_padding_y,

    /// The typed field the text parses into once it is valid.
    fn setting(self: RawScalarField) SettingField {
        return switch (self) {
            inline else => |field| @field(SettingField, @tagName(field)),
        };
    }

    fn section(self: RawScalarField) Section {
        return nativeSection(field_model.descriptor(self.setting()).section);
    }
};

fn nativeSection(section: field_model.Section) Section {
    return switch (section) {
        inline else => |value| @field(Section, @tagName(value)),
    };
}

const raw_scalar_field_count = std.enums.values(RawScalarField).len;

const SettingsStatus = union(enum) {
    raw_validation: RawScalarField,
    owned_validation: HWND,
    conflict: SettingField,
    owned_conflict: OwnedSettingField,
    none,
};

/// What the status line says while no validation error or conflict needs the
/// user. A note is replaced by the next edit.
const StatusNote = enum {
    none,
    saved,
    saved_overridden,
    save_failed,
    /// The config file is UTF-16 or UTF-32 text that a save cannot patch.
    unsupported_encoding,
    /// The config path is a link whose target is missing.
    dangling_link,
    /// The config file holds NUL bytes without a byte order mark.
    binary_config,
    /// A config file, or a file it includes, will not open. Names it.
    file_unopenable,
    /// The in-place rewrite stopped part way. Names the complete copy.
    write_incomplete,
    close_failed,
    /// "Discard changes" threw the draft away.
    discarded,
    discard_failed,
    editor_open_failed,
    resolve_first,
    conflict_not_resolved,
    disk_value_not_adopted,
    /// An edit whose result shows in the open terminals at once.
    previews_live,
    /// An edit that only takes effect once it is saved.
    applies_on_save,
    /// A field was put back to its default. Names it (`resetNoteText`).
    field_reset,
    /// A reset was asked of a field that already has its default. Names it.
    already_default,
    /// A reset could not make what it needs (memory for the copies, or a
    /// save in progress); the field keeps its value. Names it.
    reset_failed,
    /// The All settings page copied a key's name, or the Keybindings page a
    /// binding. Names it.
    key_copied,
    /// The clipboard would not take it. Names it.
    key_copy_failed,
    /// What a key did on the Profiles page. Its words are `note_text`, which
    /// names a profile or a field, never a value.
    profile_said,
    /// What to type into the Profiles page's field (`note_text`): read on
    /// request, not announced, since the field's own name and help say it.
    profile_hint,
    /// A value the Profiles page refused, and why (`note_text`).
    profile_refused,

    fn text(self: StatusNote) []const u8 {
        return switch (self) {
            .none => "",
            .saved => "Settings saved.",
            .saved_overridden => "Saved, but a later config file or command-line option overrides some of these values, so they will not take effect.",
            .save_failed => "Save failed. Your edits are kept. Check that the config file can be written and is not open in another program, then try again.",
            .unsupported_encoding => "Nothing was saved: the config file is not readable as UTF-8 text (Windows PowerShell 5.1 writes UTF-16). Save it as UTF-8 in an editor, then save again. Your edits are kept.",
            .dangling_link => "Nothing was saved: the config file is a link to a file that does not exist. Fix or remove the link, then save again. Your edits are kept.",
            .binary_config => "Nothing was saved: the config file contains NUL bytes, so it is a binary file or text in UTF-16 or UTF-32. Save it as UTF-8 in an editor, then save again. Your edits are kept.",
            .file_unopenable => "Nothing was saved: a config file cannot be opened. Close any program that has it open, or check its permissions, then save again. Your edits are kept.",
            .write_incomplete => "Saving stopped part way through the config file, which may now be incomplete. The complete new text is kept in a temporary file beside it. Copy that over the config file, then save again. Your edits are kept.",
            .close_failed => "Could not close the settings window; your edits are kept.",
            .discarded => "Changes discarded.",
            .discard_failed => "Could not discard the changes; they are kept.",
            .editor_open_failed => @import("../os/windows_text_editor.zig").failure_message,
            .resolve_first => "Fix the invalid fields or choose Keep mine or Use disk before saving.",
            .conflict_not_resolved => "Could not resolve the conflict; your edit is kept.",
            .disk_value_not_adopted => "Could not take the value from disk; your edit is kept.",
            .previews_live => "Previewing now. Save to keep it.",
            .applies_on_save => "Applies when you save.",
            .field_reset => "The setting is back to its default. Save to keep it.",
            .already_default => "The setting already has its default.",
            .reset_failed => "Could not reset the setting; it keeps its value.",
            .key_copied => "Copied the setting's name.",
            .key_copy_failed => "Could not copy the setting's name.",
            .profile_said, .profile_hint => "",
            .profile_refused => "Error: Settings did not take that value.",
        };
    }

    /// Whether the sentence can name what it is about (`textWithDetail`): a
    /// file, or for a save that a later layer overrides, the settings.
    fn takesDetail(self: StatusNote) bool {
        return switch (self) {
            .file_unopenable, .write_incomplete, .unsupported_encoding, .binary_config, .saved_overridden => true,
            .field_reset, .already_default, .reset_failed => true,
            .key_copied, .key_copy_failed => true,
            .profile_said, .profile_hint, .profile_refused => true,
            else => false,
        };
    }

    /// `text` with the file named: what `detail` holds is a path, or a short
    /// phrase ending in one; for `saved_overridden`, the config keys. Owned.
    fn textWithDetail(self: StatusNote, alloc: std.mem.Allocator, detail: []const u8) std.mem.Allocator.Error![]u8 {
        return switch (self) {
            .saved_overridden => std.fmt.allocPrint(alloc, "Saved, but a later config file or command-line option overrides {s}, so the saved value is not used.", .{detail}),
            .unsupported_encoding => std.fmt.allocPrint(alloc, "Nothing was saved: {s} is not readable as UTF-8 text (Windows PowerShell 5.1 writes UTF-16). Save it as UTF-8 in an editor, then save again. Your edits are kept.", .{detail}),
            .binary_config => std.fmt.allocPrint(alloc, "Nothing was saved: {s} contains NUL bytes, so it is a binary file or text in UTF-16 or UTF-32. Save it as UTF-8 in an editor, then save again. Your edits are kept.", .{detail}),
            .file_unopenable => std.fmt.allocPrint(alloc, "Nothing was saved: {s} cannot be opened. Close any program that has it open, or check its permissions, then save again. Your edits are kept.", .{detail}),
            .write_incomplete => std.fmt.allocPrint(alloc, "Saving stopped part way through the config file, which may now be incomplete. The complete new text is kept in {s}. Copy that over the config file, then save again. Your edits are kept.", .{detail}),
            .key_copied => std.fmt.allocPrint(alloc, "Copied {s}.", .{detail}),
            .key_copy_failed => std.fmt.allocPrint(alloc, "Could not copy {s}: the clipboard is busy or unavailable.", .{detail}),
            else => alloc.dupe(u8, self.text()),
        };
    }
};

/// Shown beside the disabled Save button, so that "nothing to save" is said in
/// words and does not have to be read from the button's shade (a disabled Save
/// is nearly indistinguishable from an enabled one in the dark theme).
const nothing_to_save_text = "No changes to save.";
const unsaved_changes_text = "You have unsaved changes.";

pub const SettingValue = field_model.SettingValue;

fn settingValueEql(a: SettingValue, b: SettingValue) bool {
    return std.meta.eql(a, b);
}

const SettingsTransaction = settings_transaction.Transaction(SettingField, SettingValue, settingValueEql);
pub const setting_field_count = std.enums.values(SettingField).len;

/// The lowest background opacity a live preview shows. The Background opacity
/// field previews every keystroke, so typing 0.85 passes through 0 and the
/// terminal window turns invisible until the next digit arrives. The floor
/// applies to the preview of an edit only: the draft, the transaction and the
/// saved value keep what was typed, and a rollback restores the exact
/// original. A saved value already below the floor lowers it, so a preview
/// never shows a window more transparent than the one the user already has.
const preview_opacity_floor: f64 = 0.2;

/// The value a live edit previews, which differs from the typed one only for
/// the opacity floor above.
fn previewValue(transaction: *const SettingsTransaction, typed: SettingValue) SettingValue {
    switch (typed) {
        .background_opacity => |opacity| {
            const saved = (transaction.entryConst(.background_opacity) orelse return typed).current.background_opacity;
            return .{ .background_opacity = @max(opacity, @min(preview_opacity_floor, saved)) };
        },
        else => return typed,
    }
}

/// The command palette's row for `field`. The id and the payload stay the
/// field's tag: saved recents and the dispatch of a chosen row key on it. What
/// the user reads and searches is the label and the config key.
pub fn paletteDescriptor(field: SettingField) palette_catalog.Descriptor {
    const key = @tagName(field);
    return .{
        .item = .{
            .id = palette_catalog.stableStringId(.setting, key),
            .title = field.label(),
            .subtitle = field_model.descriptor(field).support.paletteSubtitle(),
            .keywords = field.paletteKeywords(),
        },
        .payload = .{ .setting = key },
    };
}

/// What a live preview of a field has to refresh once the App shows it.
/// Rebuilding the theme costs 80-150 ms of UI thread (every host's brushes,
/// fonts and DWM attributes, a forced redraw of everything, then the Settings
/// window), and the preview fires on every keystroke, so each field gets only
/// the work that shows it. A field with `.none` is not previewed at all: font
/// size, padding, cursor style and blur have no consumer on a live surface,
/// which reads its own copy of the config, so a preview of them could only
/// have reached terminals opened before the draft was saved (PKG-39). A field
/// that gains a consumer in the open windows must be listed here.
///
/// The App keeps a preview out of the config it hands back
/// (`currentConfig`), which new terminals and reloads read.
///
/// The status line reads this too: only a field with an effect other than
/// `.none` can say "Previewing now".
pub const PreviewEffect = field_model.PreviewEffect;
pub fn previewEffect(field: SettingField) PreviewEffect {
    return field_model.descriptor(field).preview;
}

pub const ConflictResolution = SettingsTransaction.Resolution;
pub const ApplyId = SettingsTransaction.ApplyId;

pub const settingValue = field_model.settingValue;
pub const setSettingValue = field_model.setSettingValue;

/// `field`'s value in `config`, unwrapped from the transaction's union.
fn fieldValue(config: *const Config, comptime field: SettingField) @FieldType(SettingValue, @tagName(field)) {
    return @field(settingValue(config, field), @tagName(field));
}

/// `text` without its backticks. The CLI help is written for Markdown; the
/// Settings window shows plain text, where a backtick is just noise.
fn withoutBackticks(comptime text: []const u8) *const [text.len - std.mem.count(u8, text, "`")]u8 {
    comptime {
        var out: [text.len - std.mem.count(u8, text, "`")]u8 = undefined;
        var len: usize = 0;
        for (text) |byte| {
            if (byte == '`') continue;
            out[len] = byte;
            len += 1;
        }
        const result = out;
        return &result;
    }
}

fn keybindingsHelpText() []const u8 {
    return "Commands to run in a terminal:\n" ++
        comptime withoutBackticks(cli_help.keybinding_discovery_hint) ++
            "\n" ++
            "Example lines for the config file:\n" ++
            "  keybind = ctrl+shift+c=copy_to_clipboard\n" ++
            "  keybind = ctrl+a>n=new_window\n" ++
            "  keybind = chain=goto_split:left";
}

