const class_name = std.unicode.utf8ToUtf16LeStringLiteral("noctty.win32.settings");
const window_title = std.unicode.utf8ToUtf16LeStringLiteral("noctty settings");
/// The title while there are edits to save, so the taskbar and Alt+Tab say so
/// before the close prompt does. In words: a reader speaks the title.
const window_title_unsaved = std.unicode.utf8ToUtf16LeStringLiteral("noctty settings (unsaved changes)");
/// The child window that holds the form: it clips the fields to the band
/// between the section header and the action bar, and owns the scroll bar.
const viewport_class_name = std.unicode.utf8ToUtf16LeStringLiteral("noctty.win32.settings.viewport");
const edit_text_max_code_units: usize = 4096;
const edit_text_max_utf8: usize = edit_text_max_code_units * 3;

/// `scrollback-limit` is a byte budget per terminal, and 0 turns scrollback off
/// (Config.zig, Screen.zig); there is no "unlimited". Only new terminals read it.
/// The accessible name stays the prefix, "Scrollback limit".
const scrollback_label = field_model.forKey(.@"scrollback-limit").?.native.?.form_label.?;

const SettingsControlRole = win32_uia.SettingsControlProvider.Role;
const FormControl = struct {
    role: SettingsControlRole,
    name: []const u8,
    binding: []const u8,
    id: usize,
    section: ?Section = null,
    order: usize = 0,
    label: ?[]const u8 = null,
    caption: ?[]const u8 = null,
    help: []const u8 = "",
    /// More words the search finds the row by (`settings_search_text`).
    keywords: []const u8 = "",
};

/// The words a form row is found by besides its names and help: the name the
/// command palette gives it and the palette's keywords, less the words every
/// row's keywords start with. Those let the palette find any setting by
/// "settings"; here they would make that word find every row.
fn rowSearchKeywords(comptime row: field_model.FormField) []const u8 {
    const shared = "settings preferences configuration ";
    const keywords = if (row.field) |field| field.paletteKeywords() else row.descriptor.keywords;
    const label = if (row.field) |field| field.label() else row.descriptor.label;
    return label ++ "\n" ++ if (std.mem.startsWith(u8, keywords, shared)) keywords[shared.len..] else keywords;
}

fn fieldRole(kind: field_model.Kind) SettingsControlRole {
    return switch (kind) {
        .boolean, .blur => .check_box,
        .choice, .profile => .combo_box,
        else => .edit,
    };
}

fn displayRowSpec(row: field_model.DisplayRow) FormControl {
    return .{
        .role = if (row.kind == .action) .button else .text,
        .name = row.native.accessible_name,
        .binding = row.native.binding,
        .id = row.native.id,
        .section = nativeSection(row.section),
        .order = row.native.order,
        .label = row.native.form_label,
        .caption = row.native.caption,
        .help = row.help,
        .keywords = row.keywords,
    };
}

/// `style` adds the window's final visibility and group (`WS_VISIBLE`, `WS_GROUP`).
fn makeDisplayControl(parent: HWND, hinstance: HINSTANCE, comptime spec: FormControl, style: u32) ?HWND {
    return switch (comptime spec.role) {
        .button => sys.CreateWindowExW(0, std.unicode.utf8ToUtf16LeStringLiteral("BUTTON"), std.unicode.utf8ToUtf16LeStringLiteral(spec.caption.?), WS_CHILD | WS_TABSTOP | BS_PUSHBUTTON | style, 0, 0, settings_field_max_width, settings_control_height, parent, @ptrFromInt(spec.id), hinstance, null),
        .text => blk: {
            const text = makeStatic(parent, hinstance, spec.caption orelse spec.name, style);
            if (text) |control| _ = sys.SetWindowLongPtrW(control, -12, @intCast(spec.id)); // GWLP_ID
            break :blk text;
        },
        else => @compileError("Display-only Settings rows cannot create editable controls"),
    };
}

// Display-only rows are independent of persistence ownership and edit adapters.
const settings_form_actions = rows: {
    var result: [field_model.display_rows.len]FormControl = undefined;
    for (field_model.display_rows, 0..) |row, i| result[i] = displayRowSpec(row);
    break :rows result;
};
/// The controls outside the form: the search field in the header and the
/// action bar's buttons.
const settings_action_controls = [_]FormControl{
    .{ .role = .edit, .name = search_field_name, .binding = "edit_search", .id = EDIT_SEARCH, .help = search_field_help },
    .{ .role = .button, .name = "Save", .binding = "btn_save", .id = BTN_SAVE },
    .{ .role = .button, .name = "Keep mine", .binding = "btn_conflict_keep", .id = BTN_CONFLICT_KEEP },
    .{ .role = .button, .name = "Use disk", .binding = "btn_conflict_use_disk", .id = BTN_CONFLICT_USE_DISK },
    .{ .role = .button, .name = "Keep editing", .binding = "btn_close_keep_editing", .id = BTN_CLOSE_KEEP_EDITING },
    .{ .role = .button, .name = "Discard changes", .binding = "btn_discard_changes", .id = BTN_DISCARD_CHANGES },
};
const settings_control_specs = specs: {
    @setEvalBranchQuota(20000);
    var result: [field_model.form_fields.len + settings_form_actions.len + settings_action_controls.len]FormControl = undefined;
    for (field_model.form_fields, 0..) |row, i| result[i] = .{
        .role = fieldRole(row.kind()),
        .name = row.native.accessible_name,
        .binding = row.native.binding,
        .id = row.native.id,
        .section = nativeSection(row.descriptor.section),
        .order = row.native.order,
        .label = row.native.form_label,
        .caption = row.native.caption,
        .help = row.descriptor.helpText(),
        .keywords = rowSearchKeywords(row),
    };
    @memcpy(result[field_model.form_fields.len..][0..settings_form_actions.len], &settings_form_actions);
    @memcpy(result[field_model.form_fields.len + settings_form_actions.len ..], &settings_action_controls);
    break :specs result;
};
const settings_control_count = settings_control_specs.len;
const settings_header_control_count = settings_action_controls.len;
const settings_clipped_control_count = settings_control_count - settings_header_control_count;

comptime {
    for (settings_control_specs, 0..) |spec, i| {
        if (spec.id <= 1) @compileError("Settings control ID is reserved for static/default dialog controls");
        for (settings_control_specs[0..i]) |other| {
            if (spec.id == other.id) @compileError("Duplicate Settings control ID");
            if (spec.section != null and spec.section == other.section and spec.order == other.order)
                @compileError("Duplicate Settings form row position");
        }
        for (.{ BTN_SECTION_APPEARANCE, BTN_SECTION_TERMINAL, BTN_SECTION_SHELL, BTN_SECTION_PROFILES, BTN_SECTION_KEYBINDINGS, BTN_SECTION_ADVANCED, BTN_SECTION_PRIVACY, BTN_SECTION_UPDATES, BTN_SECTION_REFERENCE }) |id| {
            if (spec.id == id) @compileError("Settings form ID collides with section navigation");
        }
        if (spec.id >= BTN_RESET_FIRST and spec.id < BTN_RESET_FIRST + form_field_count)
            @compileError("Settings control ID collides with a Reset button");
        if (spec.id == BTN_CLOSE_DISCARD)
            @compileError("Settings control ID collides with the close prompt's Discard");
        if (spec.id == BTN_CLOSE_SAVE)
            @compileError("Settings control ID collides with the close prompt's Save and close");
    }
}

const FieldWindows = handles: {
    const empty: ?HWND = null;
    var members: [settings_clipped_control_count]std.builtin.Type.StructField = undefined;
    for (settings_control_specs[0..settings_clipped_control_count], 0..) |row, i| members[i] = .{
        .name = row.binding ++ "\x00",
        .type = ?HWND,
        .default_value_ptr = @ptrCast(&empty),
        .is_comptime = false,
        .alignment = @alignOf(?HWND),
    };
    break :handles @Type(.{ .@"struct" = .{ .layout = .auto, .fields = &members, .decls = &.{}, .is_tuple = false } });
};

const settings_label_specs = labels: {
    var count: usize = 0;
    for (settings_control_specs) |spec| if (spec.label != null) {
        count += 1;
    };
    var result: [count][]const u8 = undefined;
    var index: usize = 0;
    for (settings_control_specs) |spec| if (spec.label) |label| {
        result[index] = label;
        index += 1;
    };
    break :labels result;
};
const checkbox_captions = captions: {
    var result: [settings_control_count]?[]const u8 = @splat(null);
    for (settings_control_specs, 0..) |spec, i| if (spec.role == .check_box) {
        result[i] = spec.caption;
    };
    break :captions result;
};
/// What a row's Reset button is called. Its caption is "Reset"; its name adds
/// the field's own, so the buttons of one page read apart while the visible
/// word still starts it (voice control matches "Reset").
const reset_button_names = names: {
    var result: [form_field_count][]const u8 = undefined;
    for (field_model.form_fields, 0..) |row, i| result[i] = "Reset " ++ row.native.accessible_name;
    break :names result;
};
const reset_button_help = help: {
    var result: [form_field_count][]const u8 = undefined;
    for (field_model.form_fields, 0..) |row, i|
        result[i] = "Puts " ++ row.native.accessible_name ++ " back to its default. " ++ reset_shortcut_text ++ " in the field does the same.";
    break :help result;
};
/// The command of a row's context menu that resets it.
const row_menu_reset: usize = 1;

/// Indices of the text providers: the header texts, then the field labels.
const text_header_index = 0;
const text_summary_index = 1;
/// The status line, which also says the close prompt's question while the
/// prompt is up: the two never show at once, so one window is enough.
const text_status_index = 2;
const text_help_index = 3;
const text_first_label_index = 4;
const settings_text_count = text_first_label_index + settings_label_specs.len;
const background_blur_label = field_model.descriptor(.background_blur).nativeNames().?.caption.?;

const FormItem = struct {
    control_index: usize,
    label_index: ?usize = null,
    checkbox: bool = false,
};
const section_form_items = forms: {
    @setEvalBranchQuota(20000);
    var result: [section_count][settings_clipped_control_count]FormItem = undefined;
    for (std.enums.values(Section), 0..) |section, section_index| {
        var count: usize = 0;
        var label_index: usize = 0;
        for (settings_control_specs, 0..) |spec, i| {
            if (spec.section == section) {
                result[section_index][count] = .{ .control_index = i, .label_index = if (spec.label != null) label_index else null, .checkbox = spec.role == .check_box };
                count += 1;
            }
            if (spec.label != null) label_index += 1;
        }
        // Section order is descriptor data; no parallel per-section indices.
        for (0..count) |i| for (i + 1..count) |j| {
            if (settings_control_specs[result[section_index][j].control_index].order <
                settings_control_specs[result[section_index][i].control_index].order)
                std.mem.swap(FormItem, &result[section_index][i], &result[section_index][j]);
        };
    }
    break :forms result;
};
fn formItemCount(section: Section) usize {
    var count: usize = 0;
    for (settings_control_specs) |spec| if (spec.section == section) {
        count += 1;
    };
    return count;
}
fn formItemsForSection(section: Section) []const FormItem {
    return section_form_items[@intFromEnum(section)][0..formItemCount(section)];
}
const settings_max_form_items = maximum: {
    var result: usize = 0;
    for (std.enums.values(Section)) |section| result = @max(result, formItemCount(section));
    break :maximum result;
};

/// What the search finds each form row by, in lower case: its name, its label,
/// its caption, its help and its keywords, a line each so no word runs on into
/// the next.
const settings_search_text = text: {
    @setEvalBranchQuota(400_000);
    var result: [settings_clipped_control_count][]const u8 = undefined;
    for (settings_control_specs[0..settings_clipped_control_count], 0..) |spec, i| {
        result[i] = asciiLowerComptime(spec.name ++ "\n" ++ (spec.label orelse "") ++ "\n" ++
            (spec.caption orelse "") ++ "\n" ++ spec.help ++ "\n" ++ spec.keywords);
    }
    break :text result;
};

/// For each config key, the form rows (control indexes) that edit it: one,
/// two for a key shown as two checkboxes (`app-notifications`), or none.
const reference_form_rows: [settings_reference.key_count][]const usize = rows: {
    var result: [settings_reference.key_count][]const usize = @splat(&.{});
    for (field_model.form_fields, 0..) |row, i| {
        const key = settings_reference.index(row.descriptor.key);
        result[key] = result[key] ++ &[_]usize{i};
    }
    break :rows result;
};

/// The config key (an index into `settings_reference.keys`) each form field
/// row edits.
const form_row_keys: [form_field_count]u16 = keys: {
    var result: [form_field_count]u16 = undefined;
    for (field_model.form_fields, 0..) |row, i| result[i] = settings_reference.index(row.descriptor.key);
    break :keys result;
};

/// For each config key, the words its form rows are searched by
/// (`settings_search_text`), so the All settings page finds a key by
/// everything that finds one of its fields.
const reference_extra_search: [settings_reference.key_count][]const u8 = extra: {
    @setEvalBranchQuota(100_000);
    var result: [settings_reference.key_count][]const u8 = @splat("");
    for (reference_form_rows, 0..) |rows, key| for (rows) |row| {
        result[key] = result[key] ++ settings_search_text[row] ++ "\n";
    };
    break :extra result;
};

fn asciiLowerComptime(comptime text: []const u8) []const u8 {
    var lower: [text.len]u8 = undefined;
    for (text, 0..) |c, i| lower[i] = std.ascii.toLower(c);
    const final = lower;
    return &final;
}

/// What is typed in the search field, read for matching: the words, in lower
/// case, and whether `@modified` is among them. Every word has to be found in
/// a row's text (`settings_search_text`) for the row to show; `@modified`
/// keeps only the rows whose value differs from its default.
const SearchQuery = struct {
    /// Bytes kept of what is typed: the field holds `search_text_max_code_units`
    /// UTF-16 units, at most three bytes each.
    const capacity = search_text_max_code_units * 3;
    /// Room for every word the kept text can hold: a word and the space
    /// after it take two bytes at least, so no word is ever left out.
    const max_words = (capacity + 1) / 2;
    const modified_word = "@modified";

    /// What was typed, without the spaces around it, for the message that
    /// says nothing matched.
    typed: [capacity]u8 = undefined,
    typed_len: usize = 0,
    lower: [capacity]u8 = undefined,
    word_starts: [max_words]u16 = undefined,
    word_lens: [max_words]u16 = undefined,
    word_count: usize = 0,
    modified: bool = false,

    fn parse(text: []const u8) SearchQuery {
        var query: SearchQuery = .{};
        const trimmed = std.mem.trim(u8, text, " \t\r\n");
        var len = @min(trimmed.len, capacity);
        // Never cut a UTF-8 sequence in two.
        while (len < trimmed.len and len > 0 and (trimmed[len] & 0xC0) == 0x80) len -= 1;
        @memcpy(query.typed[0..len], trimmed[0..len]);
        query.typed_len = len;
        for (trimmed[0..len], 0..) |c, i| query.lower[i] = std.ascii.toLower(c);
        var start: usize = 0;
        while (start < len) {
            while (start < len and std.ascii.isWhitespace(query.lower[start])) start += 1;
            var end = start;
            while (end < len and !std.ascii.isWhitespace(query.lower[end])) end += 1;
            if (end > start) {
                if (std.mem.eql(u8, query.lower[start..end], modified_word)) {
                    query.modified = true;
                } else {
                    query.word_starts[query.word_count] = @intCast(start);
                    query.word_lens[query.word_count] = @intCast(end - start);
                    query.word_count += 1;
                }
            }
            start = end;
        }
        return query;
    }

    /// Whether there is a search: anything typed but spaces.
    fn active(self: *const SearchQuery) bool {
        return self.word_count != 0 or self.modified;
    }

    fn word(self: *const SearchQuery, index: usize) []const u8 {
        return self.lower[self.word_starts[index]..][0..self.word_lens[index]];
    }

    /// Whether `text` (lower case) holds every word.
    fn matchesText(self: *const SearchQuery, text: []const u8) bool {
        for (0..self.word_count) |index| {
            if (std.mem.indexOf(u8, text, self.word(index)) == null) return false;
        }
        return true;
    }

    /// Whether `other` looks for the same rows: what a key that only adds a
    /// space, or changes case, leaves alone.
    fn sameSearch(self: *const SearchQuery, other: *const SearchQuery) bool {
        if (self.modified != other.modified or self.word_count != other.word_count) return false;
        for (0..self.word_count) |index| {
            if (!std.mem.eql(u8, self.word(index), other.word(index))) return false;
        }
        return true;
    }

    fn typedText(self: *const SearchQuery) []const u8 {
        return self.typed[0..self.typed_len];
    }
};

fn controlCountForRole(role: SettingsControlRole) usize {
    var count: usize = 0;
    for (settings_control_specs) |spec| if (spec.role == role) {
        count += 1;
    };
    return count;
}

fn controlIndexIsCheckbox(index: usize) bool {
    for (std.enums.values(Section)) |section| for (formItemsForSection(section)) |item| {
        if (item.control_index == index) return item.checkbox;
    };
    return false;
}

fn labelIndexIsCheckbox(index: usize) bool {
    for (std.enums.values(Section)) |section| for (formItemsForSection(section)) |item| {
        if (item.label_index == index) return item.checkbox;
    };
    return false;
}

/// The All settings page's config file (`readConfigSource`).
pub const ConfigSource = settings_reference.ConfigSource;

/// Error set returned from `AppHandle.saveAndReload`. The settings
/// window surfaces these inline so users can re-try without losing
/// edits.
pub const SaveError = error{
    PathResolveFailed,
    /// The config path is a link to a file that does not exist. Writing would
    /// replace the link, so nothing is written.
    DanglingLink,
    TempCreateFailed,
    SerializeFailed,
    ReplaceFailed,
    ReloadFailed,
    OutOfMemory,
    /// The config file is UTF-16 or UTF-32 text. Patching it with UTF-8 lines
    /// would leave a file that mixes encodings, so nothing is written.
    UnsupportedEncoding,
    /// The config file holds NUL bytes but no byte order mark: a binary file,
    /// or UTF-16 or UTF-32 text without one.
    BinaryConfig,
    /// A config file, or a file it includes, exists but will not open. The
    /// load would skip it and apply the rest, so nothing is saved.
    FileUnopenable,
    /// The in-place rewrite of a hard-linked file stopped after its first
    /// byte: the file may hold new bytes followed by old ones.
    IncompleteWrite,
    /// The palette's theme pick found the theme changed in the config file.
    /// There is no conflict prompt there, so the pick is refused.
    DiskChanged,
    /// Write + reload both succeeded, but at least one GUI-edited
    /// field is masked by a later layer (included `config-file`,
    /// subsequent `--config-file`, `--config-default-files=false`
    /// with no remaining base). The persisted bytes on disk are
    /// correct; the effective runtime value doesn't match. UI
    /// should surface this as a distinct warning, NOT as a
    /// generic write failure.
    SavedButMasked,
};

pub const SaveReloadOutcome = union(enum) {
    completed,
    completed_masked,
    failed: SaveError,
};

/// The file a failed save is about, when the status line should name it: an
/// include that will not open, or the complete copy of a half-written config.
/// Owned by whoever runs the save (`AppHandle.failureDetail` lends it).
pub const FailureDetail = struct {
    text: ?[]u8 = null,

    pub fn set(self: *FailureDetail, alloc: std.mem.Allocator, text: []const u8) void {
        self.clear(alloc);
        self.text = alloc.dupe(u8, text) catch null;
    }

    pub fn clear(self: *FailureDetail, alloc: std.mem.Allocator) void {
        if (self.text) |text| alloc.free(text);
        self.text = null;
    }
};

/// What the status line says about a save that wrote nothing (or, for
/// `IncompleteWrite`, too little). Most failures share one hint (the file
/// cannot be written); the ones the user can act on are named.
fn saveFailureNote(err: SaveError) StatusNote {
    return switch (err) {
        error.UnsupportedEncoding => .unsupported_encoding,
        error.BinaryConfig => .binary_config,
        error.DanglingLink => .dangling_link,
        error.FileUnopenable => .file_unopenable,
        error.IncompleteWrite => .write_incomplete,
        else => .save_failed,
    };
}

/// What the notification for a save that something overrides says. It names
/// the settings, in the words a config file uses for them, when the app told
/// which; the pointer to the log it used to give is gone, since a GUI launch
/// has none to read.
/// The masked-save notification's body: the settings with where each value
/// that wins is set (`detail`), or, when that does not fit `buf`, the
/// settings alone (`keys`), or else a sentence without them.
fn maskedNotificationBody(buf: []u8, detail: ?[]const u8, keys: ?[]const u8) []const u8 {
    const generic = "A later config file or a command-line option overrides them, so they will not take effect. Check the config-file lines and the launch options.";
    for ([_]?[]const u8{ detail, keys }) |candidate| {
        const named = candidate orelse continue;
        return std.fmt.bufPrint(
            buf,
            "{s}: a later config file or a command-line option overrides the saved value, so it will not take effect. Check the config-file lines and the launch options.",
            .{named},
        ) catch continue;
    }
    return generic;
}

pub fn saveReloadOutcome(result: SaveError!void) SaveReloadOutcome {
    result catch |err| return switch (err) {
        error.SavedButMasked => .completed_masked,
        else => .{ .failed = err },
    };
    return .completed;
}

const SettingsThemeAdapter = struct {
    colors: win32_theme.SettingsColors = win32_theme.settingsColors(
        win32_theme.lightTheme(),
        .{
            .window = 0,
            .window_text = 0,
            .button_face = 0,
            .button_text = 0,
            .gray_text = 0,
            .highlight = 0,
            .highlight_text = 0,
        },
        false,
    ),
    window_brush: HBRUSH = null,
    rail_brush: HBRUSH = null,
    edit_brush: HBRUSH = null,
    button_brush: HBRUSH = null,
    applying: bool = false,

    fn deinit(self: *SettingsThemeAdapter) void {
        self.deleteBrushes();
    }

    fn deleteBrushes(self: *SettingsThemeAdapter) void {
        if (self.window_brush) |brush| _ = sys.DeleteObject(brush);
        if (self.rail_brush) |brush| _ = sys.DeleteObject(brush);
        if (self.edit_brush) |brush| _ = sys.DeleteObject(brush);
        if (self.button_brush) |brush| _ = sys.DeleteObject(brush);
        self.window_brush = null;
        self.rail_brush = null;
        self.edit_brush = null;
        self.button_brush = null;
    }

    /// What `apply` reaches: the window alone (its brushes, DWM attributes
    /// and own theme), for `open`, whose children are themed as they are
    /// created (`SettingsWindow.finishChild`); or every child as well, for a
    /// theme that changed under existing windows.
    const Scope = enum { frame, window };

    fn apply(
        self: *SettingsThemeAdapter,
        hwnd: HWND,
        colors: win32_theme.SettingsColors,
        scope: Scope,
    ) void {
        if (self.applying) return;
        self.applying = true;
        defer self.applying = false;
        self.deleteBrushes();
        self.colors = colors;
        self.window_brush = sys.CreateSolidBrush(colors.window_bg);
        self.rail_brush = sys.CreateSolidBrush(colors.rail_bg);
        self.edit_brush = sys.CreateSolidBrush(colors.edit_bg);
        self.button_brush = sys.CreateSolidBrush(colors.button_bg);

        win32_theme.WindowThemeAdapter.applySettings(hwnd, colors);
        applyNativeControlTheme(hwnd, colors);
        if (scope == .frame) return;
        _ = sys.EnumChildWindows(
            hwnd,
            applyNativeControlThemeToChild,
            @bitCast(@intFromPtr(&self.colors)),
        );
        _ = sys.InvalidateRect(hwnd, null, 1);
        _ = sys.EnumChildWindows(hwnd, invalidateThemeChild, 0);
    }

    fn controlBrush(self: *const SettingsThemeAdapter, message: UINT) HBRUSH {
        return switch (message) {
            WM_CTLCOLOREDIT, WM_CTLCOLORLISTBOX => self.edit_brush,
            WM_CTLCOLORBTN => self.button_brush,
            WM_CTLCOLORMSGBOX, WM_CTLCOLORDLG, WM_CTLCOLORSTATIC => self.window_brush,
            else => null,
        };
    }
};

fn applyNativeControlTheme(hwnd: HWND, colors: win32_theme.SettingsColors) void {
    win32_theme.WindowThemeAdapter.applyNativeControl(hwnd, colors);
}

fn applyNativeControlThemeToChild(hwnd: HWND, lParam: LPARAM) callconv(.winapi) BOOL {
    const colors: *const win32_theme.SettingsColors =
        @ptrFromInt(@as(usize, @bitCast(lParam)));
    applyNativeControlTheme(hwnd, colors.*);
    return 1;
}

/// The frame too: a text field's frame and the viewport's scroll bar are
/// non-client, and their colours come from the theme as well.
fn invalidateThemeChild(hwnd: HWND, _: LPARAM) callconv(.winapi) BOOL {
    const rdw_erase: u32 = 0x0004;
    const rdw_frame: u32 = 0x0400;
    _ = sys.RedrawWindow(hwnd, null, null, RDW_INVALIDATE | rdw_erase | rdw_frame);
    return 1;
}

fn pointerLresult(pointer: anytype) LRESULT {
    return @bitCast(@intFromPtr(pointer));
}

/// One profile the Default profile dropdown can save: its key, which is what
/// `default-profile` gets (never the label, which a rename changes), and the
/// label the picker shows.
pub const ProfileChoice = struct {
    key: []const u8,
    label: []const u8,
    /// Named by `profile-hidden`: offered only while it is the saved value
    /// or the draft's.
    hidden: bool = false,
};

/// What `AppHandle.profileChoices` answers. Every string is owned by the
/// allocator it was made with.
pub const ProfileChoices = struct {
    items: []ProfileChoice = &.{},
    /// The item the value asked about starts, if one does.
    selected: ?usize = null,
    /// The label of the profile the value asked about starts when no item
    /// is it: the loaded config resolved it without the list (an `ssh:`
    /// alias outside the SSH config, say), so it does start.
    saved_label: ?[]const u8 = null,
    /// Whether `items` is the whole list. A value no item matches in a
    /// complete list names nothing here; in a partial one it may still.
    complete: bool = false,
    /// The value asked about, when no item is it and it has no
    /// `saved_label`, names nothing here: the loaded config found nothing
    /// for it, or the list is complete and holds nothing it names. Shown as
    /// "(not found)".
    saved_not_found: bool = false,
    /// The label the draft's value, the one asked about apart from the
    /// saved value, starts under when no item's key is it: a `wsl:` or
    /// `ssh:` key starts without being listed, so one a reload left out of
    /// the list (SSH config hosts switched off) is not called missing.
    draft_label: ?[]const u8 = null,

    pub fn deinit(self: *ProfileChoices, alloc: std.mem.Allocator) void {
        for (self.items) |item| {
            alloc.free(item.key);
            alloc.free(item.label);
        }
        alloc.free(self.items);
        if (self.saved_label) |label| alloc.free(label);
        if (self.draft_label) |label| alloc.free(label);
        self.* = .{};
    }
};

/// What a row of the Default profile dropdown shows.
const ProfileRow = union(enum) {
    /// No `default-profile` line.
    automatic,
    /// `ProfileChoices.items[index]`; choosing it saves its key.
    choice: usize,
    /// The saved value, as written, when no listed profile matches it.
    kept,
    /// The draft's value when it is neither the saved value nor a listed
    /// profile: a choice whose profile left the list after it was made (a
    /// reload took it out), which Save would still write.
    draft,
};

/// The rows of the Default profile dropdown, built from the app's choices,
/// the saved value (the window's baseline) and the draft's value. The row
/// the saved value starts is `saved`, and choosing it keeps that value as
/// written (`pwsh` stays `pwsh`, not `pwsh.exe`), so the line is rewritten
/// only when another row is chosen. A saved or draft value that names no
/// listed profile gets a row of its own, and a hidden profile is listed only
/// while one of them names it, so the dropdown always shows what Save
/// writes.
const ProfileRows = struct {
    /// `len` rows in use, owned by the allocator `build` was given.
    storage: []ProfileRow = &.{},
    len: usize = 0,
    /// The row of the saved value (Automatic for none).
    saved: usize = 0,

    fn build(
        alloc: std.mem.Allocator,
        choices: *const ProfileChoices,
        saved_value: ?[]const u8,
        draft_value: ?[]const u8,
    ) std.mem.Allocator.Error!ProfileRows {
        // Automatic, every item, and the saved and draft values' own rows.
        var result: ProfileRows = .{ .storage = try alloc.alloc(ProfileRow, choices.items.len + 3) };
        // The draft as a value apart from the saved one.
        const draft: ?[]const u8 = if (draft_value) |text|
            if (saved_value != null and std.mem.eql(u8, saved_value.?, text)) null else text
        else
            null;
        result.append(.automatic);
        var draft_listed = false;
        for (choices.items, 0..) |item, index| {
            const saved = saved_value != null and choices.selected == index;
            const drafted = draft != null and std.mem.eql(u8, item.key, draft.?);
            if (item.hidden and !saved and !drafted) continue;
            if (saved) result.saved = result.len;
            if (drafted) draft_listed = true;
            result.append(.{ .choice = index });
        }
        if (saved_value != null and choices.selected == null) {
            result.saved = result.len;
            result.append(.kept);
        }
        if (draft != null and !draft_listed) result.append(.draft);
        return result;
    }

    fn deinit(self: *ProfileRows, alloc: std.mem.Allocator) void {
        alloc.free(self.storage);
        self.* = .{};
    }

    /// The row that shows `value`, the draft's: the saved row for the saved
    /// value, Automatic for none, else the profile whose key it is (a key
    /// this dropdown staged), else the draft's own row.
    fn rowFor(
        self: *const ProfileRows,
        choices: *const ProfileChoices,
        saved_value: ?[]const u8,
        value: ?[]const u8,
    ) usize {
        const text = value orelse return 0;
        if (saved_value) |saved| if (std.mem.eql(u8, saved, text)) return self.saved;
        for (self.slice(), 0..) |row, index| switch (row) {
            .choice => |item| if (std.mem.eql(u8, choices.items[item].key, text)) return index,
            .draft => return index,
            else => {},
        };
        return self.saved;
    }

    /// What choosing `row` stages: null for Automatic.
    fn valueFor(
        self: *const ProfileRows,
        choices: *const ProfileChoices,
        saved_value: ?[]const u8,
        draft_value: ?[]const u8,
        row: usize,
    ) ?[]const u8 {
        if (row == self.saved) return saved_value;
        return switch (self.storage[row]) {
            .automatic => null,
            .choice => |item| choices.items[item].key,
            // Only the saved value has a row of its own.
            .kept => saved_value,
            .draft => draft_value,
        };
    }

    fn append(self: *ProfileRows, row: ProfileRow) void {
        self.storage[self.len] = row;
        self.len += 1;
    }

    fn slice(self: *const ProfileRows) []const ProfileRow {
        return self.storage[0..self.len];
    }
};

/// Room for a Default profile row's text (512 UTF-8 bytes at most, so as many
/// UTF-16 units) and its terminating zero.
const combo_text_max = 513;

/// A combo's selected row and its text, which must fit `buf` with its zero.
fn comboSelectionText(combo: HWND, buf: []u16) ?struct { index: usize, text: []const u16 } {
    const CB_GETLBTEXT: UINT = 0x0148;
    const CB_GETLBTEXTLEN: UINT = 0x0149;
    const index = sys.SendMessageW(combo, CB_GETCURSEL, 0, 0);
    if (index < 0) return null;
    const len = sys.SendMessageW(combo, CB_GETLBTEXTLEN, @intCast(index), 0);
    if (len < 0 or len >= buf.len) return null;
    const n = sys.SendMessageW(combo, CB_GETLBTEXT, @intCast(index), @bitCast(@intFromPtr(buf.ptr)));
    if (n < 0) return null;
    return .{ .index = @intCast(index), .text = buf[0..@intCast(n)] };
}

/// What the Default profile dropdown says for `row`. A saved value that
/// names no listed profile shows the label of the profile it starts, else
/// it is shown as written, as is a draft whose profile left the list.
fn writeProfileRowText(
    writer: *std.Io.Writer,
    row: ProfileRow,
    choices: *const ProfileChoices,
    saved_value: ?[]const u8,
    draft_value: ?[]const u8,
) !void {
    switch (row) {
        .automatic => try writer.writeAll(automatic_profile_text),
        .choice => |index| {
            const item = choices.items[index];
            try writer.writeAll(item.label);
            if (item.hidden) try writer.writeAll(" (hidden)");
        },
        .kept => if (choices.saved_label) |label| {
            try writer.writeAll(label);
        } else {
            try writer.writeAll(saved_value orelse "");
            if (choices.saved_not_found) try writer.writeAll(" (not found)");
        },
        .draft => if (choices.draft_label) |label| {
            try writer.writeAll(label);
        } else {
            try writer.writeAll(draft_value orelse "");
            if (choices.complete) try writer.writeAll(" (not found)");
        },
    }
}

/// A row's text in `buf`. Text that does not fit (a profile label may be
/// thousands of bytes long) is cut at a character boundary and ends in an
/// ellipsis, so the row never comes out empty or cut inside a character.
fn profileRowText(
    buf: []u8,
    row: ProfileRow,
    choices: *const ProfileChoices,
    saved_value: ?[]const u8,
    draft_value: ?[]const u8,
) []const u8 {
    var writer: std.Io.Writer = .fixed(buf);
    writeProfileRowText(&writer, row, choices, saved_value, draft_value) catch {
        const ellipsis = "\u{2026}";
        const written = writer.buffered().len;
        var end = @min(written, buf.len - ellipsis.len);
        while (end > 0 and end < written and buf[end] & 0xC0 == 0x80) end -= 1;
        @memcpy(buf[end..][0..ellipsis.len], ellipsis);
        return buf[0 .. end + ellipsis.len];
    };
    return writer.buffered();
}

test "settings default profile row text is cut at a character with an ellipsis" {
    var items = [_]ProfileChoice{
        // 1 + 2 * 300 bytes: the 512-byte row ends inside a character.
        .{ .key = "user:long", .label = "a" ++ "\u{e9}" ** 300 },
        .{ .key = "user:short", .label = "Short", .hidden = true },
    };
    const choices: ProfileChoices = .{ .items = &items, .complete = true };
    var buf: [512]u8 = undefined;
    const long = profileRowText(&buf, .{ .choice = 0 }, &choices, null, null);
    try std.testing.expect(long.len <= buf.len);
    try std.testing.expect(std.unicode.utf8ValidateSlice(long));
    try std.testing.expect(std.mem.endsWith(u8, long, "\u{e9}\u{2026}"));
    try std.testing.expect(std.mem.startsWith(u8, items[0].label, long[0 .. long.len - "\u{2026}".len]));
    var wide: [512]u16 = undefined;
    try std.testing.expect(std.mem.len(utf8ToW(&wide, long)) > 0);
    try std.testing.expectEqualStrings("Short (hidden)", profileRowText(&buf, .{ .choice = 1 }, &choices, null, null));
}

test "settings default profile rows hold every listed profile and keep the saved one past 255" {
    const alloc = std.testing.allocator;
    var items: [300]ProfileChoice = undefined;
    var keys: [300][16]u8 = undefined;
    for (&items, &keys, 0..) |*item, *key, index| {
        const text = std.fmt.bufPrint(key, "ssh:h{d}", .{index}) catch unreachable;
        item.* = .{ .key = text, .label = text };
    }
    const choices: ProfileChoices = .{ .items = &items, .selected = 299, .complete = true };
    var rows = try ProfileRows.build(alloc, &choices, "ssh:h299", null);
    defer rows.deinit(alloc);
    // Automatic and all 300, the saved one last.
    try std.testing.expectEqual(@as(usize, 301), rows.len);
    try std.testing.expectEqual(@as(usize, 300), rows.saved);
    try std.testing.expectEqual(@as(usize, 300), rows.rowFor(&choices, "ssh:h299", "ssh:h299"));
    try std.testing.expectEqualStrings("ssh:h298", rows.valueFor(&choices, "ssh:h299", null, 299).?);
}

const automatic_profile_text = "Automatic";

/// Minimal hook into the apprt `App` so the settings module can fetch
/// the chrome brush colors without pulling in the whole app type.
pub const AppHandle = struct {
    ctx: *anyopaque,
    /// Allocator used for `Config.shallowClone` on the pending draft.
    /// The clone's `_arena` is owned by this allocator; `Config.deinit`
    /// on the clone frees it.
    alloc: std.mem.Allocator,
    /// HINSTANCE used for window class registration + creation.
    hinstance: HINSTANCE,
    ownerWindow: ?*const fn (ctx: *anyopaque) ?HWND = null,
    /// The application icon at the caption size (`small`) or the Alt+Tab and
    /// taskbar size. Without one the window shows the generic application
    /// glyph.
    appIcon: ?*const fn (ctx: *anyopaque, small: bool) HICON = null,
    /// Chrome background color (COLORREF) to paint into the settings
    /// content pane. Queried per paint so theme swaps propagate.
    chromeBg: *const fn (ctx: *anyopaque) COLORREF,
    /// Primary text color.
    textPrimary: *const fn (ctx: *anyopaque) COLORREF,
    /// Full resolved app palette and High Contrast state for native Settings
    /// theming. Optional defaults retain compatibility with model-only tests.
    themeColors: ?*const fn (ctx: *anyopaque) win32_theme.ThemeColors = null,
    highContrast: ?*const fn (ctx: *anyopaque) bool = null,
    /// Fire-and-forget shell-out to the OS default text editor with
    /// the resolved `ghostty.conf` path. Used by the Advanced-pane
    /// escape hatch.
    openInEditor: *const fn (ctx: *anyopaque) void,
    /// Optional. Put `text` on the clipboard as plain text: the All settings
    /// page's "Copy name". False when the clipboard would not take it. Tests
    /// pass a recorder; none may touch the real clipboard. Without it the page
    /// offers no copy.
    copyText: ?*const fn (ctx: *anyopaque, text: []const u8) bool = null,
    /// Snapshot the currently-active Config. The returned pointer is
    /// only valid until the next config reload; the settings window
    /// holds it as `original` for the duration of the pending-clone
    /// session.
    currentConfig: *const fn (ctx: *anyopaque) *const Config,
    /// Serialise `pending` to disk (atomic-rename via `ReplaceFileW`
    /// where supported, falling back to `MoveFileExW`) and refresh
    /// the live app config + all surfaces. `original` is the
    /// snapshot captured when the settings window opened; the save
    /// path diffs pending against it (NOT against `App.config`) so
    /// an external `reload_config` or file edit that fires while the
    /// window is open doesn't get silently reverted by our save.
    /// Caller owns both.
    saveAndReload: *const fn (
        ctx: *anyopaque,
        pending: *const Config,
        original: *const Config,
    ) SaveError!void,
    /// Optional monotonic revision of the effective config. When absent, the
    /// settings window maintains a local revision for compatibility.
    configRevision: ?*const fn (ctx: *anyopaque) u64 = null,
    /// Optional live-preview hook for ownership-safe fields. Effects are
    /// idempotent: apply `value` as the current preview for `field`.
    previewField: ?*const fn (ctx: *anyopaque, field: SettingField, value: SettingValue) void = null,
    /// Optional conflict notification. The UI model retains the draft until
    /// `resolveConflict` is called with keep-mine or use-disk.
    notifyConflict: ?*const fn (ctx: *anyopaque, field: SettingField) void = null,
    /// Optional. Asked before a save writes anything: the file may have been
    /// edited since this window last read it, with no reload to say so. When
    /// it finds an edit to a setting that is also being edited here, it applies
    /// the file as a reload does, so `externalConfigChanged` flags what
    /// overlaps and the save stops at the conflict. A save that wrote over such
    /// an edit would lose it without a word. An error means the file could not
    /// be checked, and nothing is saved.
    reconcileDisk: ?*const fn (ctx: *anyopaque, pending: *const Config, original: *const Config) SaveError!void = null,
    /// Optional. The file a save that just failed was about, for the errors
    /// whose status sentence names one (`StatusNote.takesDetail`). Borrowed
    /// until the next save.
    failureDetail: ?*const fn (ctx: *anyopaque) ?[]const u8 = null,
    /// Optional. The config keys the save that just completed wrote and a later
    /// config file or command-line option overrides, comma separated, for
    /// the status line and the notification. Borrowed until the next save.
    maskedKeys: ?*const fn (ctx: *anyopaque) ?[]const u8 = null,
    /// Optional. The file a save writes, copied into `buf` (at least 243 bytes),
    /// for the Advanced page; null when it cannot be resolved. Looking must not
    /// create the file.
    saveTarget: ?*const fn (ctx: *anyopaque, buf: []u8) ?[]const u8 = null,
    /// Optional. The file a save writes as the All settings page reads it:
    /// its complete path (not shortened for display) and its bytes, owned by
    /// `alloc`, through `readConfigSource`. Without it the page names no file.
    configSource: ?*const fn (ctx: *anyopaque, alloc: std.mem.Allocator) settings_reference.ConfigSource = null,
    /// Optional. The problems the config load found, as the Advanced page lists
    /// them (`config_problems.Problems.listText`), copied into `buf`.
    configProblems: ?*const fn (ctx: *anyopaque, buf: []u8) []const u8 = null,
    /// Optional. The profiles the Default profile dropdown offers, from the
    /// list the profile picker shows (hidden profiles included and marked),
    /// and which of them `reference` (a `default-profile` value) starts, and
    /// the label `draft` (the draft's value) starts under when it is not
    /// `reference` and no listed key is it. Allocated with `alloc`; the caller frees it with `deinit`. Must not
    /// discover profiles on this thread: with no list yet it asks for one and
    /// answers what it has, and the app calls `profilesChanged` when the list
    /// arrives. `ask` false: answer only what the windows already have and
    /// never ask (that refill, which must not start another discovery when
    /// one failed). Without it the dropdown offers only Automatic.
    profileChoices: ?*const fn (ctx: *anyopaque, alloc: std.mem.Allocator, reference: ?[]const u8, draft: ?[]const u8, ask: bool) std.mem.Allocator.Error!ProfileChoices = null,
    /// Fire-and-forget success toast for the app-level in-app stack
    /// (e.g. "Settings saved"). Borrowed title + body — caller must
    /// keep them alive only for the duration of the call; the stack
    /// copies internally.
    notifySuccess: *const fn (ctx: *anyopaque, title: []const u8, body: []const u8) void,
    /// Custom UIA providers touch HWND state and therefore require the UI
    /// thread's confirmed STA initialization. When unavailable, native Win32
    /// providers remain the safe fallback.
    customUiaProvidersEnabled: ?*const fn (ctx: *anyopaque) bool = null,
    /// Queue UIA provider disconnect/release outside synchronous window
    /// teardown. UiaDisconnectProvider may reject COM callouts from
    /// WM_NCDESTROY with RPC_E_CANTCALLOUT_ININPUTSYNCCALL.
    deferUiaDisconnect: ?*const fn (
        ctx: *anyopaque,
        provider_ctx: *anyopaque,
        disconnect: *const fn (*anyopaque) win32_uia.HRESULT,
        release: *const fn (*anyopaque) void,
    ) void = null,
    /// Fired after the settings window's HWND is destroyed. Lets the
    /// app re-evaluate its quit-timer policy (the settings HWND
    /// participates in the "has live UI windows" count so closing
    /// the last terminal while settings is open does not auto-quit;
    /// once settings itself closes the timer can kick in).
    onClosed: *const fn (ctx: *anyopaque) void,
    /// Optional. WM_QUERYENDSESSION and WM_ENDSESSION reach every top-level
    /// window, this one included, and the app answers for all of its windows:
    /// a Restart Manager close (`ENDSESSION_CLOSEAPP`) is declined while this
    /// window has unsaved edits, and otherwise quits the whole app. Without
    /// them, the window agrees and does nothing.
    queryEndSession: ?*const fn (ctx: *anyopaque, lParam: LPARAM) bool = null,
    endSession: ?*const fn (ctx: *anyopaque, ending: bool, lParam: LPARAM) void = null,
};

pub const SettingsWindow = struct {
    handle: AppHandle,
    combo_trace: bench_trace.SettingsComboTrace = .{},
    /// How long each step of the last `open` took, when the App's
    /// `NOCTTY_SETTINGS_OPEN_TRACE` is on; the App writes and empties it.
    creation_stamps: bench_trace.SettingsCreationStamps = .{},
    hwnd: ?HWND = null,
    /// The form's own window (`viewport_class_name`): every field, its label
    /// and the help text are its children, so its client area is what clips
    /// them. Window regions cannot: the stock control classes carry
    /// `CS_PARENTDC`, which paints through the parent's clip and ignores a
    /// window region, so scrolled fields drew over the header and the action
    /// bar.
    viewport: ?HWND = null,
    /// Stays out of the UIA control view (`layout_pane`), so the fields keep
    /// reading as children of the window.
    viewport_uia_provider: ?*win32_uia.SettingsControlProvider = null,
    btn_open_editor: ?HWND = null,
    btn_section_appearance: ?HWND = null,
    btn_section_terminal: ?HWND = null,
    btn_section_shell: ?HWND = null,
    btn_section_profiles: ?HWND = null,
    btn_section_privacy: ?HWND = null,
    btn_section_updates: ?HWND = null,
    btn_section_keybindings: ?HWND = null,
    btn_section_advanced: ?HWND = null,
    btn_section_reference: ?HWND = null,
    section_button_prev_proc: ?*const anyopaque = null,
    section_hovered: ?HWND = null,
    /// The "All settings" page: every config key (`settings_reference.Model`), built
    /// the first time the page or a search needs it and again after the
    /// config changes, and the list that shows it.
    reference_model: settings_reference.Model = .{},
    reference_stale: bool = true,
    /// Counts the builds of `reference_model`, so what is measured from it
    /// is measured again after one.
    reference_generation: u64 = 0,
    reference_list: ReferenceList = .{ .kind = .reference },
    /// The key bindings in effect, for the Keybindings page's list, built as
    /// `reference_model` is (`ensureKeybindModel`), and that list.
    keybind_model: settings_keybinds.Model = .{},
    keybind_stale: bool = true,
    keybind_generation: u64 = 0,
    keybind_list: ReferenceList = .{ .kind = .keybindings },
    /// The Profiles page: the draft's user profiles (`settings_profiles.Model`),
    /// built from `pending` when the page or a search needs them and again
    /// after the draft changes, and the list that shows them.
    profile_model: settings_profiles.Model = .{},
    profile_stale: bool = true,
    profile_generation: u64 = 0,
    profile_list: ReferenceList = .{ .kind = .profiles },
    /// Which of `profile_model`'s rows the search found, and how many.
    profile_found: []bool = &.{},
    profile_found_count: u16 = 0,
    /// The field of the Profiles page being typed into, while one is
    /// (`beginProfileEdit`).
    profile_edit: ?ProfileEdit = null,
    /// The profile row whose removal the first Delete asked to confirm
    /// (`Row.identity`).
    profile_remove_armed: ?u64 = null,
    /// How many profile fields the draft changed (`refreshProfileChanges`).
    profile_changes: usize = 0,
    /// One class for both lists, registered once per window object.
    reference_list_class_atom: ATOM = 0,
    /// How the user last reached a section button. The rail's owner-drawn
    /// buttons paint a focus ring only in `.keyboard` mode, the way native
    /// controls honour `UISF_HIDEFOCUS`: the section that opened with the
    /// window, or was just clicked, holds focus but shows no ring until a
    /// navigation key arrives. The native EDIT / COMBOBOX / BUTTON
    /// children already behave this way through the dialog manager.
    focus_input_mode: focus_cue.InputMode = .pointer,
    /// How many times a toggle switch was painted (`paintToggle`), for tests.
    proof_toggle_paint_count: u32 = 0,
    /// The number fields' trackbar and up-downs (`Companion`), made with
    /// their fields' section.
    companions: [Companion.count]?HWND = @splat(null),
    section_uia_group: ?*win32_uia.SettingsSectionGroupProvider = null,
    section_uia_providers: [section_count]?*win32_uia.SettingsSectionProvider = [_]?*win32_uia.SettingsSectionProvider{null} ** section_count,
    /// Writes the draft; while the close prompt is up, the prompt's "Save
    /// and close" (`placeSaveButton`).
    btn_save: ?HWND = null,
    /// Throws the draft away and shows what is saved, without closing.
    btn_discard_changes: ?HWND = null,
    btn_keybindings_editor: ?HWND = null,
    btn_conflict_keep: ?HWND = null,
    btn_conflict_use_disk: ?HWND = null,
    btn_close_keep_editing: ?HWND = null,
    text_header: ?HWND = null,
    text_summary: ?HWND = null,
    text_status: ?HWND = null,
    status_note: StatusNote = .none,
    /// The sentence for `status_note` when it names a file (`takesDetail`).
    /// Owned; only meaningful while `status_note` takes a detail.
    note_text: ?[]u8 = null,
    /// The status text measured for `status_measure_width` / `status_measure_dpi`:
    /// how wide it is on one line, and how tall it is wrapped to that width.
    /// `-1` means it has to be measured again.
    status_measure_width: i32 = -1,
    status_measure_dpi: u32 = 0,
    status_measure_single_line: i32 = 0,
    status_measure_wrapped: i32 = 0,
    /// The status row the last layout applied (see `StatusRow`).
    status_row_separate: bool = false,
    status_row_height: i32 = 0,
    /// What the status line says when the close prompt does not hold its
    /// window (`setStatus`); written back when the prompt goes.
    status_line: [status_line_capacity]u8 = undefined,
    status_line_len: usize = 0,
    text_help: ?HWND = null,
    /// The search field in the header (Ctrl+F): it narrows every page to the
    /// rows that match (`runSearch`).
    edit_search: ?HWND = null,
    /// Whether the search field has its MSAA name, which is given with the
    /// first annotation pass that runs (`annotateAccessibleControls`).
    search_named: bool = false,
    search_query: SearchQuery = .{},
    /// Which form rows the search found, by control index; meaningful while
    /// `search_query` is active.
    search_found: [settings_clipped_control_count]bool = @splat(false),
    /// Which config keys the search found on the All settings page, by key.
    reference_found: [settings_reference.key_count]bool = @splat(false),
    /// Which bindings it found on the Keybindings page, by row of
    /// `keybind_model` (the window's allocator's; `forgetReference`), and how
    /// many.
    keybind_found: []bool = &.{},
    keybind_found_count: u16 = 0,
    /// How many rows the search found on each page, and how many settings in
    /// all: every key it found on the All settings page (which lists every
    /// key, and finds a key by its controls' words too), the rows of the other
    /// pages that are no key (their "Open config" buttons), and every binding
    /// it found on the Keybindings page (each a `keybind` line of its own).
    search_counts: [section_count]u16 = @splat(0),
    search_total: usize = 0,
    /// The rows of the shown page the search found, in form order:
    /// `formItems` while a search is typed.
    search_items: [settings_max_form_items]FormItem = undefined,
    search_item_count: usize = 0,
    /// For timing: how long the last search pass took to find its rows and
    /// lay them out, and with the repaint, in microseconds.
    proof_search_filter_us: u32 = 0,
    proof_search_total_us: u32 = 0,
    field_labels: [settings_label_specs.len]?HWND = [_]?HWND{null} ** settings_label_specs.len,
    text_uia_prev_proc: ?*const anyopaque = null,
    text_uia_providers: [settings_text_count]?*win32_uia.SettingsControlProvider = [_]?*win32_uia.SettingsControlProvider{null} ** settings_text_count,
    control_uia_prev_procs: [settings_control_count]?*const anyopaque = [_]?*const anyopaque{null} ** settings_control_count,
    control_uia_providers: [settings_control_count]?*win32_uia.SettingsControlProvider = [_]?*win32_uia.SettingsControlProvider{null} ** settings_control_count,
    ui_font: HGDIOBJ = null,
    secondary_font: HGDIOBJ = null,
    emphasis_font: HGDIOBJ = null,
    header_font: HGDIOBJ = null,
    theme_adapter: SettingsThemeAdapter = .{},
    /// DPI the UI fonts were last built for, how many times `themeChanged`
    /// has actually re-themed the window and how many times the fonts were
    /// built (tests read the counts).
    ui_font_dpi: u32 = 0,
    theme_applications: u32 = 0,
    font_builds: u32 = 0,
    close_prompt_measure_width: i32 = -1,
    close_prompt_measure_dpi: u32 = 0,
    close_prompt_measure_quitting: bool = false,
    close_prompt_measure_height: i32 = 0,
    fields: FieldWindows = std.mem.zeroes(FieldWindows),
    /// The sections whose rows exist. `open` makes the selected section's; the
    /// others are made the first time they are shown (`materializeSection`).
    materialized: std.EnumSet(Section) = .initEmpty(),
    active_section: Section = .appearance,
    dpi: u32 = 96,
    /// Class atoms lazily registered the first time `open` runs.
    class_atom: ATOM = 0,
    viewport_class_atom: ATOM = 0,
    /// Line height of the field font, which the text fields centre their text
    /// on (`fieldFrameInsets`). Measured when the fonts are built.
    field_text_height: i32 = 0,
    /// The field whose frame was last painted as invalid, so the frame can be
    /// repainted when `validation_control` moves on.
    framed_invalid_field: ?HWND = null,
    /// Whether the last layout showed the help text (Keybindings, Advanced).
    help_shown: bool = false,
    /// What the frame window painted last time: when the action bar or the
    /// column changes height or width without the window resizing, the old
    /// separators have to be painted over.
    background_geometry: ?BackgroundGeometry = null,

    /// Every editable row's value when nothing sets it: `Config.default` for
    /// this build, made when the window opens. Null when it could not be made,
    /// which leaves the rows unmarked and offers no reset.
    defaults: ?Config = null,
    /// Which form rows' draft differs from `defaults`, as the marker, the
    /// Reset button and UIA last said it (`syncDefaultMarks`).
    differs_from_default: [form_field_count]bool = @splat(false),
    /// What each field's MSAA description says (`fieldDescription`), as a
    /// hash of the text the last annotation that took set (0: none), tried
    /// again on every pass until it matches.
    described: [form_field_count]u64 = @splat(0),
    /// Where each made row's saved value comes from, as its label shows it on
    /// the right and its MSAA description says (`OriginNote`). A switch has
    /// no label, and its row no room beside its caption, so it says so only
    /// in its description. Worked out when the row is made and once per
    /// config Settings holds (`syncOriginNotes`), never on a paint, a search
    /// or a page switch.
    origin_notes: [form_field_count]OriginNote = @splat(.{}),
    /// How many times a row's origin was looked up (`config.origin.of`), for
    /// tests.
    proof_origin_lookups: u32 = 0,
    /// The file Settings saves to as it is now, against `current`, for the
    /// notes of rows whose value came from one of its lines (`targetNow`):
    /// read once per config Settings holds, when a note first names a line
    /// of a file. Null when Settings names no file or cannot read it.
    target_now: ?TargetNow = null,
    /// Whether `target_now` was read for the config Settings holds.
    target_read: bool = false,
    /// `current`'s loader problems, indexed (`config.origin.Index`) for the
    /// rows' origins: made the first time a row asks, and dropped with
    /// `current` (`forgetTarget`). It borrows `current`.
    origin_index: ?config_origin.Index = null,
    /// For tests: the annotation service the marks use in place of oleacc's.
    annotation_service: ?*IAccPropServices = null,
    /// A row's Reset button: the shown page's rows that differ from their
    /// default have one, hidden while the row does not differ. Another page's
    /// rows give theirs up to `reset_spares` (`syncDefaultMarks`).
    reset_buttons: [form_field_count]?HWND = @splat(null),
    /// Reset buttons no row of the shown page holds: hidden, for the next
    /// page's rows to take before any is made. A page switch then makes and
    /// destroys none (about 0.6 ms to make and 0.3 ms to destroy each,
    /// measured, so ten on Appearance took about 9 ms a round trip), and the
    /// window holds no more buttons than the most one page has needed (ten,
    /// on Appearance). Where a spare sits in z-order does not matter: Tab and
    /// the arrow keys pass over a hidden window, and a Reset button has no
    /// `WS_GROUP` to end a group with.
    reset_spares: [form_field_count]HWND = undefined,
    reset_spare_count: usize = 0,
    reset_uia_providers: [form_field_count]?*win32_uia.SettingsControlProvider = @splat(null),
    reset_uia_prev_proc: ?*const anyopaque = null,
    /// Where each row's marker is drawn in the viewport now, or null: a
    /// change repaints exactly where a marker was and where it goes.
    marker_rects: [form_field_count]?RECT = @splat(null),
    /// For tests: answers a row's context menu (the command chosen, 0 for
    /// none) instead of the menu loop, which a test cannot drive.
    context_menu_pick: ?*const fn (menu: win32_types.HMENU) usize = null,

    /// Frozen snapshot of the config at the moment the window last
    /// opened. Independently owned via `Config.clone` so an
    /// external `reload_config` that fires while the window is open
    /// does not mutate our diff baseline. Only valid while
    /// `pending != null`.
    original: ?Config = null,
    /// Latest effective config snapshot used for preview rollback and
    /// three-way external-edit resolution.
    current: ?Config = null,
    /// Editable draft owned by `handle.alloc`. Created on open via a
    /// deep `Config.clone(handle.alloc)` and freed on close/save.
    pending: ?Config = null,
    transaction_storage: [setting_field_count]SettingsTransaction.Entry = undefined,
    transaction: ?SettingsTransaction = null,
    local_revision: u64 = 1,
    close_prompt_visible: bool = false,
    /// The existing inline prompt can discard the draft without closing.
    discard_prompt: bool = false,
    discard_prompt_count: usize = 0,
    close_after_save: bool = false,
    close_posted: bool = false,
    close_notified: bool = false,
    /// The app's quit waits on the close prompt: set by
    /// `holdQuitForUnsavedChanges`, cleared by Keep editing or a failed
    /// save, and taken by the app's `onClosed` once Save or Discard closed
    /// the window. Outlives the window's state reset in WM_NCDESTROY,
    /// which runs before `onClosed`.
    quit_after_close: bool = false,
    close_prior_focus: ?HWND = null,
    validation_control: ?HWND = null,
    owned_validation_control: ?HWND = null,
    owned_validation_message: ?[]const u8 = null,
    owned_text_changed: [owned_setting_field_count]bool = [_]bool{false} ** owned_setting_field_count,
    owned_dirty: [owned_setting_field_count]bool = [_]bool{false} ** owned_setting_field_count,
    owned_conflict: [owned_setting_field_count]bool = [_]bool{false} ** owned_setting_field_count,
    /// Raw scalar text that has not parsed successfully yet. Keep this
    /// separate from the typed transaction so invalid/empty edits still
    /// participate in dirty-close confirmation and survive config reloads.
    raw_scalar_dirty: [raw_scalar_field_count]bool = [_]bool{false} ** raw_scalar_field_count,
    /// Borrowed static validation messages for each unparsed scalar field.
    raw_scalar_error: [raw_scalar_field_count]?[]const u8 = [_]?[]const u8{null} ** raw_scalar_field_count,
    /// Whether the message in `raw_scalar_error` is on screen yet. Text that
    /// does not parse is wrong for as long as it is half typed ("1" on the way
    /// to "16"), so the message waits for `validation_quiet_ms` without a key,
    /// for the field to lose focus, or for a save. Until then the field only
    /// keeps Save off (`raw_scalar_dirty`).
    raw_scalar_shown: [raw_scalar_field_count]bool = [_]bool{false} ** raw_scalar_field_count,
    active_raw_validation: ?RawScalarField = null,
    /// What each rail button and the title were last drawn to say
    /// (`syncMarkers`), so only a change repaints.
    section_markers: [section_count]win32_uia.SettingsSectionMarker = [_]win32_uia.SettingsSectionMarker{.none} ** section_count,
    title_marked: bool = false,
    active_conflict_field: ?SettingField = null,
    active_owned_conflict_field: ?OwnedSettingField = null,
    content_scroll_y: i32 = 0,
    content_scroll_max: i32 = 0,
    proof_viewport_top: i32 = 0,
    proof_viewport_bottom: i32 = 0,
    proof_killfocus_count: u32 = 0,
    proof_redraw_succeeded: bool = false,
    proof_update_pending: bool = false,
    proof_paint_count: u32 = 0,
    /// Whether the last layout moved its windows in deferred batches.
    proof_layout_batched: bool = false,
    /// Guard flag so the EN_CHANGE handler doesn't fire a cascade
    /// when we programmatically set the EDIT text on open.
    suppress_edit_events: bool = false,
    /// The child that held keyboard focus when the window was deactivated.
    /// `DefWindowProc` hands focus to the frame on activation, so without this
    /// the field the user was typing in stops receiving keys after Alt+Tab.
    focus_before_deactivate: ?HWND = null,
    /// Wheel movement not yet turned into whole pixels, in 1/`WHEEL_DELTA`
    /// pixel: a precision touchpad sends deltas far below one notch.
    wheel_remainder: i32 = 0,
    /// Set while `forwardFrameFocus` moves focus, so the focus notification
    /// does not scroll the form.
    restoring_focus: bool = false,
    /// Lines per wheel notch for tests; null reads the system setting.
    wheel_lines_override: ?u32 = null,
    /// What the Default profile dropdown was last filled from
    /// (`displayDefaultProfile`): the app's profiles, the rows, and the saved
    /// value they were built for, as written (owned by `handle.alloc`).
    profile_choices: ProfileChoices = .{},
    profile_rows: ProfileRows = .{},
    profile_saved_value: ?[]u8 = null,
    /// The draft's value the rows were built for, when it is not the saved
    /// one (owned by `handle.alloc`).
    profile_draft_value: ?[]u8 = null,
    /// The profile list or the config changed while the dropdown was open;
    /// it is refilled when it closes.
    profile_rows_stale: bool = false,
    /// A refill put off while the list was open was to ask the app for a
    /// list (`fillDefaultProfile`'s `ask`).
    profile_rows_ask: bool = false,

    pub fn init(handle: AppHandle) SettingsWindow {
        return .{ .handle = handle, .combo_trace = bench_trace.SettingsComboTrace.init(handle.alloc) };
    }

    fn canInitializeCustomUiaProviders(self: *const SettingsWindow) bool {
        const probe = self.handle.customUiaProvidersEnabled orelse return false;
        return probe(self.handle.ctx);
    }

    fn px(self: *const SettingsWindow, logical: i32) i32 {
        return scaleForDpi(logical, self.dpi);
    }

    fn appIcon(self: *const SettingsWindow, small: bool) HICON {
        const provide = self.handle.appIcon orelse return null;
        return provide(self.handle.ctx, small);
    }

    /// What clicking Save does, gated on the button's own state so a shortcut
    /// cannot save while the button is disabled, hidden or the prompt is open.
    fn saveIfAllowed(self: *SettingsWindow) void {
        // A shortcut for a Save that is off because a field is still inside its
        // quiet period says why now.
        if (!self.close_prompt_visible) self.showRawScalarErrors(null);
        const button_enabled = if (self.btn_save) |button| sys.IsWindowEnabled(button) != 0 else false;
        const button_visible = if (self.btn_save) |button| sys.IsWindowVisible(button) != 0 else false;
        if (saveCommandCanDispatch(
            self.close_prompt_visible,
            self.close_posted,
            button_enabled,
            button_visible,
        )) self.save();
    }

    /// Keys the dialog manager does not handle the way a settings window needs.
    /// The App pump asks this BEFORE `IsDialogMessageW`; true means consumed.
    ///   * Ctrl+S saves. (Enter never saves: in a field it does nothing.)
    ///   * Enter presses the focused push button.
    ///   * An auto-repeated Escape is swallowed, so holding the key does not
    ///     toggle the close prompt open and shut.
    ///   * Ctrl+Shift+Delete puts the focused field (or the field of the
    ///     focused Reset button) back to its default.
    ///   * Ctrl+F goes to the search field and selects what it holds. Enter
    ///     there goes to the first setting found, and Escape there clears it
    ///     (an empty field leaves Escape to close the window).
    /// Only keys for this window come here, so the terminal's own bindings,
    /// Ctrl+F among them, are not touched.
    pub fn handleAccelerator(self: *SettingsWindow, target: ?HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) bool {
        // Cheapest test first: this runs for every message while Settings is open.
        if (msg != WM_KEYDOWN) return false;
        if (wParam != 'S' and wParam != 'F' and wParam != VK_RETURN and wParam != VK_ESCAPE and wParam != VK_DELETE) return false;
        const hwnd = self.hwnd orelse return false;
        const control = target orelse return false;
        if (control != hwnd and IsChild(hwnd, control) == 0) return false;
        const repeat = (lParam & (1 << 30)) != 0;
        const in_search = self.edit_search != null and control == self.edit_search.?;
        // The Profiles page's field: Enter keeps what it holds and Escape
        // puts it back, before the dialog manager takes either.
        if (self.profile_edit) |edit| if (edit.hwnd == control) switch (wParam) {
            VK_RETURN => {
                if (!repeat) _ = self.commitProfileEdit(.stay);
                return true;
            },
            VK_ESCAPE => {
                if (!repeat) self.cancelProfileEdit();
                return true;
            },
            else => {},
        };
        switch (wParam) {
            'S' => {
                if (!isSaveShortcut(
                    'S',
                    win32_input.keyPressed(VK_CONTROL),
                    win32_input.keyPressed(VK_MENU),
                    win32_input.keyPressed(VK_SHIFT),
                )) return false;
                // A profile field being typed into is kept first, so Save
                // has it to save.
                if (!repeat and self.profile_edit != null and !self.commitProfileEdit(.stay)) return true;
                self.saveIfAllowed();
                return true;
            },
            'F' => {
                if (!isFindShortcut(
                    win32_input.keyPressed(VK_CONTROL),
                    win32_input.keyPressed(VK_MENU),
                    win32_input.keyPressed(VK_SHIFT),
                )) return false;
                const search = self.edit_search orelse return false;
                if (!repeat) {
                    self.showKeyboardCues();
                    _ = SetFocus(search);
                    _ = SendMessageW(search, EM_SETSEL, 0, -1);
                }
                return true;
            },
            VK_RETURN => {
                // A page's list: the selected row's action.
                for ([_]*ReferenceList{ &self.reference_list, &self.keybind_list, &self.profile_list }) |list| if (list.hwnd != null and control == list.hwnd) {
                    if (!repeat) list.invokeSelected();
                    return true;
                };
                if (!in_search) return self.pressFocusedButton(repeat);
                if (!repeat) self.goToFirstMatch();
                return true;
            },
            VK_ESCAPE => {
                // The field holds something to clear; an empty one leaves
                // Escape to the dialog manager, which asks to close. While the
                // close prompt is up, Escape is its "Keep editing".
                if (in_search and !self.close_prompt_visible and sys.GetWindowTextLengthW(control) > 0) {
                    if (!repeat) self.clearSearch();
                    return true;
                }
                return repeat;
            },
            VK_DELETE => {
                if (!win32_input.keyPressed(VK_CONTROL) or !win32_input.keyPressed(VK_SHIFT) or
                    win32_input.keyPressed(VK_MENU)) return false;
                const row = self.rowOfWindow(control) orelse return false;
                if (!repeat) self.resetRow(row);
                return true;
            },
            else => return false,
        }
    }

    fn deleteUiFont(self: *SettingsWindow) void {
        if (self.ui_font) |font| _ = sys.DeleteObject(font);
        self.ui_font = null;
        if (self.secondary_font) |font| _ = DeleteObject(font);
        self.secondary_font = null;
        if (self.emphasis_font) |font| _ = DeleteObject(font);
        self.emphasis_font = null;
        if (self.header_font) |font| _ = DeleteObject(font);
        self.header_font = null;
    }

    pub fn deinit(self: *SettingsWindow) void {
        defer self.combo_trace.deinit();
        self.freeNoteText();
        if (self.hwnd) |h| {
            if (sys.IsWindow(h) != 0) _ = sys.DestroyWindow(h);
        }
        self.releaseSectionUiaProviders();
        self.releaseTextUiaProviders();
        self.releaseControlUiaProviders();
        self.releaseResetUiaProviders();
        self.forgetDefaults();
        self.hwnd = null;
        self.forgetFormWindows();
        self.deleteUiFont();
        self.theme_adapter.deinit();
        self.btn_section_appearance = null;
        self.btn_section_terminal = null;
        self.btn_section_shell = null;
        self.btn_section_profiles = null;
        self.btn_section_privacy = null;
        self.btn_section_updates = null;
        self.btn_section_keybindings = null;
        self.btn_section_advanced = null;
        self.btn_section_reference = null;
        self.forgetReference();
        self.section_button_prev_proc = null;
        self.section_hovered = null;
        // The window object outlives its HWND. A reopened window is
        // reached by whatever opened it, not by the keys pressed in the
        // previous one, so it starts ring-less like a fresh one.
        self.focus_input_mode = .pointer;
        self.focus_before_deactivate = null;
        self.text_uia_prev_proc = null;
        self.btn_save = null;
        self.btn_discard_changes = null;
        self.btn_conflict_keep = null;
        self.btn_conflict_use_disk = null;
        self.btn_close_keep_editing = null;
        self.resetClosePromptState();
        self.quit_after_close = false;
        self.clearPending();
        self.forgetProfileRows();
    }

    /// Put every live preview back to the saved value, the window's own
    /// `current` snapshot.
    fn rollbackPreviews(self: *SettingsWindow) void {
        const transaction = &(self.transaction orelse return);
        var effects: [setting_field_count]SettingsTransaction.Effect = undefined;
        if (transaction.dispatch(.revert, &effects)) |emitted| {
            self.dispatchEffects(emitted);
        } else |err| std.log.warn("settings: preview rollback failed err={}", .{err});
    }

    /// Drop the pending draft (if any) and its arena. Safe to call
    /// multiple times. Called from close paths and after Save so the
    /// next `open` starts with a fresh clone of the (possibly just-
    /// reloaded) app config.
    fn clearPending(self: *SettingsWindow) void {
        self.rollbackPreviews();
        self.transaction = null;
        self.validation_control = null;
        self.owned_validation_control = null;
        self.owned_validation_message = null;
        self.owned_text_changed = [_]bool{false} ** owned_setting_field_count;
        self.owned_dirty = [_]bool{false} ** owned_setting_field_count;
        self.owned_conflict = [_]bool{false} ** owned_setting_field_count;
        self.raw_scalar_dirty = [_]bool{false} ** raw_scalar_field_count;
        self.raw_scalar_error = [_]?[]const u8{null} ** raw_scalar_field_count;
        self.raw_scalar_shown = [_]bool{false} ** raw_scalar_field_count;
        self.killValidationTimer();
        self.active_raw_validation = null;
        self.active_conflict_field = null;
        self.active_owned_conflict_field = null;
        if (self.pending) |*p| p.deinit();
        self.pending = null;
        if (self.original) |*o| o.deinit();
        self.original = null;
        self.profile_changes = 0;
        self.forgetTarget();
        if (self.current) |*c| c.deinit();
        self.current = null;
        // An open Default profile list keeps the rows it shows, so a choice
        // made in it after a save (which starts the draft over) is still
        // staged; they are rebuilt when it closes (`fillDefaultProfile`).
        if (!self.profileListOpen()) self.forgetProfileRows();
        self.updateSaveEnabled();
    }

    fn profileListOpen(self: *const SettingsWindow) bool {
        const combo = self.fields.combo_default_profile orelse return false;
        return sys.IsWindow(combo) != 0 and sys.SendMessageW(combo, CB_GETDROPPEDSTATE, 0, 0) != 0;
    }

    fn forgetProfileRows(self: *SettingsWindow) void {
        self.profile_choices.deinit(self.handle.alloc);
        if (self.profile_saved_value) |value| self.handle.alloc.free(value);
        self.profile_saved_value = null;
        if (self.profile_draft_value) |value| self.handle.alloc.free(value);
        self.profile_draft_value = null;
        self.profile_rows.deinit(self.handle.alloc);
        self.profile_rows_stale = false;
        self.profile_rows_ask = false;
    }

    fn currentRevision(self: *const SettingsWindow) u64 {
        if (self.handle.configRevision) |get_revision| {
            return get_revision(self.handle.ctx);
        }
        return self.local_revision;
    }

    fn initTransaction(self: *SettingsWindow) void {
        const current = self.current orelse return;
        var initial: [setting_field_count]SettingsTransaction.FieldValue = undefined;
        for (std.enums.values(SettingField), 0..) |field, i| {
            initial[i] = .{ .field = field, .value = settingValue(&current, field) };
        }
        self.transaction = SettingsTransaction.init(
            &self.transaction_storage,
            &initial,
            self.currentRevision(),
        ) catch |err| {
            std.log.err("settings: transaction initialization failed err={}", .{err});
            return;
        };
    }

    fn dispatchEffects(self: *SettingsWindow, effects: []const SettingsTransaction.Effect) void {
        for (effects) |effect| switch (effect) {
            .set_preview => |change| if (self.handle.previewField) |preview| {
                preview(self.handle.ctx, change.field, change.value);
            },
            .conflict_detected => |field| if (self.handle.notifyConflict) |notify| {
                notify(self.handle.ctx, field);
            },
            .apply_requested, .persist_field => {},
        };
    }

    fn trackFieldEdit(self: *SettingsWindow, field: SettingField) void {
        self.trackEdit(field, previewEffect(field) != .none);
    }

    fn trackEdit(self: *SettingsWindow, field: SettingField, live_preview: bool) void {
        const pending = self.pending orelse return;
        const transaction = &(self.transaction orelse return);
        var effects: [1]SettingsTransaction.Effect = undefined;
        const emitted = transaction.dispatch(.{ .edit = .{
            .field = field,
            .value = settingValue(&pending, field),
            .live_preview = live_preview,
        } }, &effects) catch |err| {
            std.log.warn("settings: edit transaction failed field={s} err={}", .{ @tagName(field), err });
            return;
        };
        if (live_preview) for (emitted) |*effect| switch (effect.*) {
            .set_preview => |*change| change.value = previewValue(transaction, change.value),
            else => {},
        };
        self.dispatchEffects(emitted);
        self.refreshNativeSectionText();
        // Whether the edit shows in the open windows now or only after a save
        // is told by what its preview refreshes.
        self.status_note = if (previewEffect(field) != .none) .previews_live else .applies_on_save;
        self.updateSaveEnabled();
    }

    pub fn hasPendingChanges(self: *const SettingsWindow) bool {
        for (self.raw_scalar_dirty) |dirty| if (dirty) return true;
        if (self.profileDraftDiffers() or self.profileEditTypedInto()) return true;
        for (self.owned_text_changed, self.owned_dirty, self.owned_conflict) |text_changed, dirty, conflict| {
            if (text_changed or dirty or conflict) return true;
        }
        const transaction = &(self.transaction orelse return false);
        for (transaction.entries) |entry| if (entry.dirty or entry.conflict) return true;
        return false;
    }

    fn pendingFieldCount(self: *const SettingsWindow) usize {
        var fields = [_]bool{false} ** setting_field_count;
        if (self.transaction) |transaction| for (transaction.entries) |entry| {
            fields[@intFromEnum(entry.field)] = entry.dirty or entry.conflict;
        };
        for (std.enums.values(RawScalarField)) |field| {
            if (self.raw_scalar_dirty[@intFromEnum(field)]) fields[@intFromEnum(field.setting())] = true;
        }
        var count: usize = self.profileChangeCount() + @intFromBool(self.profileEditTypedInto());
        for (fields) |changed| count += @intFromBool(changed);
        for (self.owned_text_changed, self.owned_dirty, self.owned_conflict) |text, dirty, conflict| {
            count += @intFromBool(text or dirty or conflict);
        }
        return count;
    }

    /// Whether the bar's Save may save: something to save, and nothing
    /// invalid or in conflict.
    fn canSave(self: *const SettingsWindow) bool {
        return self.validation_control == null and
            !self.hasRawScalarEdits() and
            self.conflictCount() == 0 and
            self.hasPendingChanges();
    }

    fn updateSaveEnabled(self: *SettingsWindow) void {
        const enabled = self.canSave();
        // While the prompt is up the button is its "Save and close", which
        // `updateClosePromptActions` enables.
        if (!self.close_prompt_visible) if (self.btn_save) |button| {
            _ = sys.EnableWindow(button, @intFromBool(enabled));
        };
        if (self.btn_discard_changes) |button| if (!self.close_prompt_visible) {
            const discardable = self.hasPendingChanges();
            // Disabling the focused button would strand the keyboard on it.
            if (!discardable and GetFocus() == button) self.focusAfterConflictResolution();
            _ = sys.EnableWindow(button, @intFromBool(discardable));
        };
        self.updateClosePromptActions();
        self.syncIdleStatus();
        self.syncFieldFrames();
        self.syncMarkers();
    }

    /// Say an outcome (`note`) now, whatever else the line shows, and keep
    /// saying it until the next edit or a new attempt replaces it. It goes up
    /// even while a conflict or a validation error holds the line, as the
    /// ad-hoc messages it replaces did.
    fn setNote(self: *SettingsWindow, note: StatusNote) void {
        self.freeNoteText();
        self.status_note = note;
        self.setStatus(note.text());
    }

    pub fn editorOpenFailed(self: *SettingsWindow) void {
        self.setNote(.editor_open_failed);
    }

    /// `setNote` for a failed save: when the sentence names a file, the app
    /// says which.
    fn setSaveFailureNote(self: *SettingsWindow, err: SaveError) void {
        const note = saveFailureNote(err);
        self.setNote(note);
        if (!note.takesDetail()) return;
        const lend = self.handle.failureDetail orelse return;
        const detail = lend(self.handle.ctx) orelse return;
        self.note_text = note.textWithDetail(self.handle.alloc, detail) catch return;
        self.setStatus(self.noteText());
    }

    fn freeNoteText(self: *SettingsWindow) void {
        if (self.note_text) |text| self.handle.alloc.free(text);
        self.note_text = null;
    }

    fn noteText(self: *const SettingsWindow) []const u8 {
        if (self.note_text) |text| if (self.status_note.takesDetail()) return text;
        return self.status_note.text();
    }

    /// What the status line says when no validation error or conflict holds it.
    fn idleStatusText(self: *const SettingsWindow) []const u8 {
        switch (self.status_note) {
            // A save's result stays up whatever the draft looks like now.
            .saved, .discarded, .editor_open_failed => return self.status_note.text(),
            .saved_overridden, .already_default, .reset_failed, .key_copied, .key_copy_failed => return self.noteText(),
            .profile_said, .profile_hint, .profile_refused => return self.noteText(),
            // These are about edits that are still there to be saved.
            .field_reset,
            .save_failed,
            .unsupported_encoding,
            .binary_config,
            .dangling_link,
            .file_unopenable,
            .write_incomplete,
            .close_failed,
            .discard_failed,
            .resolve_first,
            .conflict_not_resolved,
            .disk_value_not_adopted,
            => if (self.hasPendingChanges()) return self.noteText(),
            .none, .previews_live, .applies_on_save => {},
        }
        if (!self.hasPendingChanges()) return nothing_to_save_text;
        const text = self.noteText();
        return if (text.len != 0) text else unsaved_changes_text;
    }

    fn syncIdleStatus(self: *SettingsWindow) void {
        switch (self.nextStatus()) {
            .none => self.setStatus(self.idleStatusText()),
            else => {},
        }
    }

    fn hasRawScalarEdits(self: *const SettingsWindow) bool {
        for (self.raw_scalar_dirty) |dirty| if (dirty) return true;
        return false;
    }

    fn markRawScalarEdit(self: *SettingsWindow, field: RawScalarField) void {
        self.raw_scalar_dirty[@intFromEnum(field)] = true;
    }

    fn finishRawScalarEdit(self: *SettingsWindow, field: RawScalarField) void {
        const index = @intFromEnum(field);
        self.raw_scalar_error[index] = null;
        self.raw_scalar_shown[index] = false;
        if (self.active_raw_validation == field) {
            self.active_raw_validation = null;
            // The remaining errors go to the status line. Moving the user to
            // another field, or another section, while they type a valid value
            // here would take the keyboard out from under them. Only the close
            // prompt's "Save and close" moves focus to an error (Save itself
            // is disabled while one exists).
            self.surfaceNextValidation(false);
        }
        // That status refresh must still see an edit: the caller transfers
        // the parsed value to the typed transaction immediately after this.
        // Only its final update can decide whether Discard is now unnecessary.
        self.raw_scalar_dirty[index] = false;
        if (!self.hasRawScalarEdits()) self.killValidationTimer();
    }

    fn shouldRefreshRawScalar(self: *const SettingsWindow, field: RawScalarField) bool {
        return !self.raw_scalar_dirty[@intFromEnum(field)];
    }

    fn setValidationError(self: *SettingsWindow, control: HWND, message: []const u8) void {
        self.owned_validation_control = control;
        self.owned_validation_message = message;
        self.surfaceNextValidation(false);
    }

    fn clearValidationError(self: *SettingsWindow, control: HWND) void {
        if (self.owned_validation_control != control) return;
        self.owned_validation_control = null;
        self.owned_validation_message = null;
        if (self.validation_control == control) self.surfaceNextValidation(false);
    }

    /// Record that `field`'s text does not parse. The message is shown at once
    /// when the field already shows an error (so it stays true to what is
    /// typed), otherwise after the quiet period; Save is off either way.
    fn setRawScalarValidationError(
        self: *SettingsWindow,
        field: RawScalarField,
        control: HWND,
        message: []const u8,
    ) void {
        const index = @intFromEnum(field);
        self.raw_scalar_error[index] = message;
        if (self.raw_scalar_shown[index]) {
            self.active_raw_validation = field;
            self.validation_control = control;
            self.setErrorStatus(message);
        } else {
            self.armValidationTimer();
        }
        self.updateSaveEnabled();
    }

    fn armValidationTimer(self: *SettingsWindow) void {
        const hwnd = self.hwnd orelse return;
        // The same id restarts the countdown, so it is a quiet period.
        _ = sys.SetTimer(hwnd, validation_timer_id, validation_quiet_ms, null);
    }

    fn killValidationTimer(self: *SettingsWindow) void {
        const hwnd = self.hwnd orelse return;
        _ = sys.KillTimer(hwnd, validation_timer_id);
    }

    /// Show the errors of the fields that have not shown theirs yet: all of
    /// them (`only` null), or the one that lost focus.
    fn showRawScalarErrors(self: *SettingsWindow, only: ?RawScalarField) void {
        var changed = false;
        for (std.enums.values(RawScalarField)) |field| {
            const index = @intFromEnum(field);
            if (only != null and only.? != field) continue;
            if (self.raw_scalar_error[index] == null or self.raw_scalar_shown[index]) continue;
            self.raw_scalar_shown[index] = true;
            self.active_raw_validation = field;
            changed = true;
        }
        if (changed) self.surfaceNextValidation(false);
    }

    /// Focus left `field`'s text field (`WM_SETTINGS_FIELD_LEFT`, posted from
    /// its `EN_KILLFOCUS`): say what is wrong with it without waiting out the
    /// quiet period. Pressing "Discard changes" takes focus first, and its
    /// click throws the text away, so an error would flash up for nothing.
    fn fieldLeft(self: *SettingsWindow, field: RawScalarField) void {
        if (self.close_notified) return;
        if (self.btn_discard_changes) |button| if (GetFocus() == button) return;
        self.showRawScalarErrors(field);
    }

    /// `validation_quiet_ms` passed without a key in an invalid field.
    fn validationQuietElapsed(self: *SettingsWindow) void {
        self.killValidationTimer();
        self.showRawScalarErrors(null);
    }

    fn nextRawScalarValidation(self: *const SettingsWindow) ?RawScalarField {
        if (self.active_raw_validation) |field| {
            const index = @intFromEnum(field);
            if (self.raw_scalar_error[index] != null and self.raw_scalar_shown[index]) return field;
        }
        for (std.enums.values(RawScalarField)) |field| {
            const index = @intFromEnum(field);
            if (self.raw_scalar_error[index] != null and self.raw_scalar_shown[index]) return field;
        }
        return null;
    }

    /// `message` as the status line's error: the word comes first so the line
    /// is not an error by its colour alone.
    fn setErrorStatus(self: *SettingsWindow, message: []const u8) void {
        var buf: [256]u8 = undefined;
        self.setStatus(std.fmt.bufPrint(&buf, "Error: {s}", .{message}) catch message);
    }

    fn nextStatus(self: *const SettingsWindow) SettingsStatus {
        if (self.nextRawScalarValidation()) |field| return .{ .raw_validation = field };
        if (self.owned_validation_control) |control| return .{ .owned_validation = control };
        if (self.active_conflict_field) |field| return .{ .conflict = field };
        if (self.active_owned_conflict_field) |field| return .{ .owned_conflict = field };
        return .none;
    }

    fn rawScalarEdit(self: *const SettingsWindow, field: RawScalarField) ?HWND {
        return switch (field) {
            inline else => |raw| self.fieldControl(raw.setting()),
        };
    }

    /// The native control of `field`, by the binding its descriptor names.
    fn fieldControl(self: *const SettingsWindow, comptime field: SettingField) ?HWND {
        inline for (field_model.form_fields) |row| if (comptime row.field == field) {
            return @field(self.fields, row.native.binding);
        };
        @compileError("No Settings control edits " ++ @tagName(field));
    }

    fn rawScalarDestination(self: *const SettingsWindow, field: RawScalarField) struct { section: Section, hwnd: ?HWND } {
        return .{ .section = field.section(), .hwnd = self.rawScalarEdit(field) };
    }

    fn ownedEdit(self: *const SettingsWindow, field: OwnedSettingField) ?HWND {
        return switch (field) {
            inline else => |owned| @field(self.fields, owned.descriptor().native.?.binding),
        };
    }

    /// What each section holds that its rail button should say. An invalid
    /// value is the more urgent, so it wins over unsaved changes.
    fn sectionMarkers(self: *const SettingsWindow) [section_count]win32_uia.SettingsSectionMarker {
        const Marker = win32_uia.SettingsSectionMarker;
        var markers = [_]Marker{.none} ** section_count;
        const Mark = struct {
            fn at(all: *[section_count]Marker, section: Section, marker: Marker) void {
                const slot = &all[@intFromEnum(section)];
                if (@intFromEnum(marker) > @intFromEnum(slot.*)) slot.* = marker;
            }
        };
        if (self.transaction) |transaction| for (transaction.entries) |entry| {
            if (entry.dirty or entry.conflict) Mark.at(&markers, self.settingDestination(entry.field).section, .unsaved);
        };
        for (std.enums.values(RawScalarField)) |field| {
            const index = @intFromEnum(field);
            if (self.raw_scalar_dirty[index]) Mark.at(&markers, field.section(), .unsaved);
            if (self.raw_scalar_error[index] != null and self.raw_scalar_shown[index]) Mark.at(&markers, field.section(), .invalid);
        }
        if (self.profileDraftDiffers()) Mark.at(&markers, .profiles, .unsaved);
        for (std.enums.values(OwnedSettingField)) |field| {
            const index = @intFromEnum(field);
            if (self.owned_text_changed[index] or self.owned_dirty[index] or self.owned_conflict[index]) {
                Mark.at(&markers, field.section(), .unsaved);
            }
            if (self.owned_validation_control != null and self.owned_validation_control == self.ownedEdit(field)) {
                Mark.at(&markers, field.section(), .invalid);
            }
        }
        return markers;
    }

    /// Whether `field`'s control is showing an error now.
    fn fieldIsInvalid(self: *const SettingsWindow, control: HWND) bool {
        for (std.enums.values(RawScalarField)) |field| {
            const index = @intFromEnum(field);
            if (self.rawScalarEdit(field) == control) return self.raw_scalar_error[index] != null and self.raw_scalar_shown[index];
        }
        return self.owned_validation_control == control;
    }

    /// Bring everything that says "there is something here" up to date: a dot
    /// or a mark on the rail buttons, the title, and the same facts for UIA.
    /// Cheap and idempotent; it runs with every change of state.
    fn syncMarkers(self: *SettingsWindow) void {
        const markers = self.sectionMarkers();
        for (std.enums.values(Section)) |section| {
            const index = @intFromEnum(section);
            if (markers[index] == self.section_markers[index]) continue;
            self.section_markers[index] = markers[index];
            if (self.sectionProvider(section)) |provider| provider.setMarker(markers[index]);
            if (self.sectionButton(section)) |button| _ = InvalidateRect(button, null, 0);
        }
        const marked = self.hasPendingChanges();
        if (marked != self.title_marked) {
            self.title_marked = marked;
            if (self.hwnd) |hwnd| {
                _ = sys.SetWindowTextW(hwnd, if (marked) window_title_unsaved else window_title);
            }
        }
        for (0..settings_clipped_control_count) |index| {
            const provider = self.control_uia_providers[index] orelse continue;
            const control = self.controlHwnd(index) orelse continue;
            provider.setDataInvalid(self.fieldIsInvalid(control));
        }
        self.syncDefaultMarks();
    }

    /// Whether `row`'s draft differs from its default, as the app takes both
    /// (`effectiveSettingValue`: the copies are of a finalized config, the
    /// defaults are not). A row that cannot be reset (Windows does not support
    /// it) is never marked.
    fn rowDiffersFromDefault(self: *const SettingsWindow, comptime row: field_model.FormField) bool {
        if (comptime !row.resettable()) return false;
        const pending = if (self.pending) |*config| config else return false;
        const defaults = if (self.defaults) |*config| config else return false;
        if (comptime row.field) |field| return !settingValueEql(
            field_model.effectiveSettingValue(settingValue(pending, field)),
            field_model.effectiveSettingValue(settingValue(defaults, field)),
        );
        const owned = comptime ownedFieldFor(row.descriptor.key);
        // Typed text reaches the draft when the field loses focus. Until then
        // the field says what it holds: a blank default is differed from by
        // any text.
        if (self.owned_text_changed[@intFromEnum(owned)] and ownedSettingBlank(defaults, owned)) {
            if (self.ownedEdit(owned)) |edit| return editHoldsText(edit, if (owned == .font_family) " \t," else " \t");
        }
        return !ownedSettingEql(pending, defaults, owned);
    }

    /// Whether a reset of `row` would change what it shows: its draft
    /// differs from the default, or it holds text not staged yet (a number
    /// half typed, a font list being typed) that a reset throws away.
    fn rowNeedsReset(self: *const SettingsWindow, comptime row: field_model.FormField) bool {
        if (comptime !row.resettable()) return false;
        if (self.rowDiffersFromDefault(row)) return true;
        if (comptime row.field) |field| {
            inline for (comptime std.enums.values(RawScalarField)) |raw| {
                if (comptime raw.setting() == field) return self.raw_scalar_dirty[@intFromEnum(raw)];
            }
            return false;
        }
        return self.owned_text_changed[@intFromEnum(comptime ownedFieldFor(row.descriptor.key))];
    }

    /// What the file holds now (`current`, the last config read from it):
    /// what a reset is measured against.
    fn fileConfig(self: *const SettingsWindow) ?*const Config {
        return if (self.current) |*config| config else null;
    }

    /// Whether `row` has an edit to save.
    fn rowDirty(self: *const SettingsWindow, comptime row: field_model.FormField) bool {
        if (comptime row.field) |field| {
            const transaction = if (self.transaction) |*value| value else return false;
            return (transaction.entryConst(field) orelse return false).dirty;
        }
        return self.owned_dirty[@intFromEnum(comptime ownedFieldFor(row.descriptor.key))];
    }

    /// Bring every row's "differs from its default" cue up to date: the bar
    /// beside it, its Reset button and the field's UIA `ItemStatus`. Cheap and
    /// idempotent, and run with every change of state, like `syncMarkers`.
    fn syncDefaultMarks(self: *SettingsWindow) void {
        self.syncDefaultMarksShowing(true);
    }

    /// `syncDefaultMarks`. With `show_new` false (a page switch) the shown
    /// page's buttons are left hidden for `applySectionVisibility` to show
    /// once the layout has placed them.
    fn syncDefaultMarksShowing(self: *SettingsWindow, show_new: bool) void {
        // Between two drafts (a save starting over) nothing is compared, so a
        // focused Reset button is not hidden and shown again.
        if (self.pending == null or self.viewport == null) return;
        const active = self.activeFormRows();
        // Made once, when first needed, for what this pass annotates for
        // MSAA: the fields whose state changed and the buttons it hands out.
        var annotations: Annotations = .{ .fake = self.annotation_service };
        defer annotations.deinit();
        inline for (field_model.form_fields, 0..) |row, index| {
            const control = @field(self.fields, row.native.binding);
            const differs = control != null and self.rowDiffersFromDefault(row);
            if (differs != self.differs_from_default[index]) {
                self.differs_from_default[index] = differs;
                if (self.control_uia_providers[index]) |provider| provider.setChangedFromDefault(differs);
            }
            // An annotation can fail (low memory), so what MSAA says is
            // followed on its own and tried again until it takes.
            if (control) |field| {
                var description_buf: [OriginNote.capacity + 64]u8 = undefined;
                const description = self.fieldDescription(index, differs, &description_buf);
                const wanted = descriptionHash(description);
                if (self.described[index] != wanted) if (annotations.service()) |service| {
                    if (setFieldDescription(service, field, description)) self.described[index] = wanted;
                };
            }
            // Only the shown page's rows hold Reset buttons, so the window
            // has at most one page's worth (ten, on Appearance) however many
            // fields differ in all. Rows give theirs up before rows take one.
            if (!active.controls[index]) self.releaseResetButton(index);
        }
        // Every row first takes back the spare it last held, which keeps its
        // id and MSAA name; then the others share what is left.
        for ([_]bool{ true, false }) |own_only| for (0..form_field_count) |index| {
            if (active.controls[index] and self.differs_from_default[index] and self.reset_buttons[index] == null)
                self.takeResetButton(index, own_only, &annotations);
        };
        for (0..form_field_count) |index| if (active.controls[index]) if (self.reset_buttons[index]) |button| {
            const differs = self.differs_from_default[index];
            if (show_new or !differs) self.showResetButton(index, button, differs);
        };
        self.syncMarkerRects();
    }

    /// One `IAccPropServices`, made the first time a pass asks for it and
    /// never asked for again if that fails.
    const Annotations = struct {
        made: ?*IAccPropServices = null,
        tried: bool = false,
        /// `annotation_service`, for tests.
        fake: ?*IAccPropServices = null,

        fn service(self: *Annotations) ?*IAccPropServices {
            if (!self.tried) {
                self.tried = true;
                self.made = if (self.fake) |fake| fake.addRef() else createAccPropServices();
            }
            return self.made;
        }

        fn deinit(self: *Annotations) void {
            if (self.made) |made| made.release();
        }
    };

    /// Row `index` gives its Reset button up with its page: hidden and kept
    /// for another row (`reset_spares`). Focus on it (a page switch from the keyboard never
    /// leaves it there) goes to the shown page's rail button, checked first:
    /// an unchecked auto radio button that takes the focus clicks itself
    /// (inferred), which would start the page switch again from inside
    /// this one.
    fn releaseResetButton(self: *SettingsWindow, index: usize) void {
        const button = self.reset_buttons[index] orelse return;
        self.reset_buttons[index] = null;
        if (self.reset_uia_providers[index]) |provider| {
            self.reset_uia_providers[index] = null;
            provider.detach();
            self.deferProviderDisconnect(@ptrCast(provider), settingsControlDisconnect, settingsControlRelease);
        }
        if (GetFocus() == button) if (self.sectionButton(self.active_section)) |rail| {
            if (@as(usize, @bitCast(sys.SendMessageW(rail, BM_GETCHECK, 0, 0))) != BST_CHECKED) _ = sys.SendMessageW(rail, BM_SETCHECK, BST_CHECKED, 0);
            _ = SetFocus(rail);
        };
        // The button may serve another row next: focus to go back to (after
        // the close prompt, or when the window is active again) must not
        // find it there, nor may it keep the default border the dialog
        // manager gave it while it had focus.
        if (self.close_prior_focus == button) self.close_prior_focus = null;
        if (self.focus_before_deactivate == button) self.focus_before_deactivate = null;
        const style: u32 = @truncate(@as(usize, @bitCast(sys.GetWindowLongPtrW(button, GWL_STYLE))));
        if (style & BS_TYPEMASK == BS_DEFPUSHBUTTON) _ = sys.SendMessageW(button, BM_SETSTYLE, BS_PUSHBUTTON, 0);
        setChildShown(button, false);
        self.reset_spares[self.reset_spare_count] = button;
        self.reset_spare_count += 1;
    }

    /// The All settings page holds no Reset button, so the spares the form
    /// pages gave up go while it is shown. Kept, they sit hidden beside its
    /// list, which made the page with its menu open one USER object more than
    /// Appearance with its row menu, the busiest form page. The form page
    /// shown next makes what it needs again, about 0.6 ms a button.
    fn destroyResetSpares(self: *SettingsWindow) void {
        for (self.reset_spares[0..self.reset_spare_count]) |spare| _ = sys.DestroyWindow(spare);
        self.reset_spare_count = 0;
    }

    /// Give row `index` a Reset button, hidden: the spare that last served
    /// it, which keeps its id and MSAA name (all `own_only` takes), another
    /// row's spare, renamed, or a new one. It goes right after the control in
    /// z-order, which is the order Tab and the arrows take, and beside it at
    /// the right end of the row (`settingsFormItemRects` keeps the room). Its
    /// id says which row it resets.
    ///
    /// A button's MSAA name names the row its id resets, or is the bare
    /// "Reset" of a new button that could not be named: never another row's.
    /// So a spare takes this row's id only once it has this row's name; when
    /// renaming fails (`SetHwndPropStr` can, for lack of memory) the row
    /// goes without a button, and the next pass tries again.
    fn takeResetButton(self: *SettingsWindow, index: usize, own_only: bool, annotations: *Annotations) void {
        const viewport = self.viewport orelse return;
        const control = self.controlHwnd(index) orelse return;
        const id: LONG_PTR = @intCast(BTN_RESET_FIRST + index);
        const spares = self.reset_spares[0..self.reset_spare_count];
        const own: ?usize = for (spares, 0..) |spare, i| {
            if (sys.GetWindowLongPtrW(spare, GWLP_ID) == id) break i;
        } else null;
        if (own_only and own == null) return;
        // MSAA clients (NVDA reads a Win32 button there) hear which field it
        // resets; a spare that could not be renamed would say another's.
        const names = if (own == null) annotations.service() else null;
        const button = if (own) |i|
            self.takeSpare(i)
        else if (spares.len > 0 and names != null) renamed: {
            const spare = spares[spares.len - 1];
            if (!setAccessibleNameText(names.?, spare, reset_button_names[index])) return;
            _ = self.takeSpare(spares.len - 1);
            _ = sys.SetWindowLongPtrW(spare, GWLP_ID, id);
            break :renamed spare;
        } else made: {
            const made = self.finishChild(
                makePushButton(viewport, self.handle.hinstance, std.unicode.utf8ToUtf16LeStringLiteral("Reset"), BTN_RESET_FIRST + index, settings_reset_width, BS_NOTIFY),
                self.ui_font,
                .control,
            ) orelse return;
            if (names) |service| _ = setAccessibleNameText(service, made, reset_button_names[index]);
            break :made made;
        };
        // Past the row's last window, an up-down where it has one: an edit
        // shows the button at once, with no layout after it.
        _ = if (childRectIn(viewport, control)) |rect| placed: {
            const end = childRectIn(viewport, self.rowEnd(index) orelse control) orelse rect;
            break :placed SetWindowPos(button, control, end.right + self.px(settings_reset_gap), rect.top, self.px(settings_reset_width), self.px(settings_control_height), SWP_NOACTIVATE);
        } else SetWindowPos(button, control, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE);
        self.reset_buttons[index] = button;
        if (self.canInitializeCustomUiaProviders()) self.attachResetUiaProvider(index);
    }

    fn takeSpare(self: *SettingsWindow, i: usize) HWND {
        const spare = self.reset_spares[i];
        self.reset_spare_count -= 1;
        self.reset_spares[i] = self.reset_spares[self.reset_spare_count];
        return spare;
    }

    /// A click on row `index`'s Reset button, from the button the row holds
    /// and shows. A spare keeps the id of the row it last served, so a click
    /// that reaches it late (an MSAA client's default action on a button it
    /// found before the page changed) is not that row's.
    fn resetButtonClicked(self: *SettingsWindow, index: usize, source: LPARAM) void {
        const button = self.reset_buttons[index] orelse return;
        if (@intFromPtr(button) != @as(usize, @bitCast(source)) or sys.IsWindowVisible(button) == 0) return;
        self.resetRow(index);
    }

    fn showResetButton(self: *SettingsWindow, index: usize, button: HWND, shown: bool) void {
        // Hiding the focused button would strand the keyboard on it.
        if (!shown and GetFocus() == button) {
            if (self.controlHwnd(index)) |control| {
                if (self.focusTargetUsable(control)) _ = SetFocus(control) else self.focusAfterConflictResolution();
            }
        }
        setChildShown(button, shown);
    }

    fn resetButtonIndex(self: *const SettingsWindow, hwnd: HWND) ?usize {
        for (self.reset_buttons, 0..) |button, index| if (button == hwnd) return index;
        return null;
    }

    /// The UIA provider of row `index`'s Reset button, a new one for each row
    /// a button serves. The caller checks that custom providers are enabled.
    fn attachResetUiaProvider(self: *SettingsWindow, index: usize) void {
        const button = self.reset_buttons[index] orelse return;
        const subclassed = sys.GetWindowLongPtrW(button, GWLP_WNDPROC) == @as(LONG_PTR, @intCast(@intFromPtr(&settingsResetButtonProc)));
        // A spare's subclass passes on to the procedure recorded when it was
        // made; without that record it could not.
        if (subclassed and self.reset_uia_prev_proc == null) return;
        const provider = win32_uia.SettingsControlProvider.create(std.heap.page_allocator, button, .button, reset_button_names[index]) catch |err| {
            std.log.warn("settings reset UIA provider unavailable index={} err={}", .{ index, err });
            return;
        };
        provider.help_text = reset_button_help[index];
        if (subclassed) {
            self.reset_uia_providers[index] = provider;
            return;
        }
        const previous = sys.SetWindowLongPtrW(button, GWLP_WNDPROC, @as(LONG_PTR, @intCast(@intFromPtr(&settingsResetButtonProc))));
        if (previous == 0) {
            _ = win32_uia.SettingsControlProvider.Release(&provider.base);
            return;
        }
        const proc: *const anyopaque = @ptrFromInt(@as(usize, @intCast(previous)));
        if (self.reset_uia_prev_proc) |existing| {
            if (existing != proc) {
                _ = sys.SetWindowLongPtrW(button, GWLP_WNDPROC, previous);
                _ = win32_uia.SettingsControlProvider.Release(&provider.base);
                return;
            }
        } else self.reset_uia_prev_proc = proc;
        self.reset_uia_providers[index] = provider;
    }

    fn releaseResetUiaProviders(self: *SettingsWindow) void {
        for (&self.reset_uia_providers) |*slot| {
            const provider = slot.* orelse continue;
            slot.* = null;
            provider.detach();
            self.deferProviderDisconnect(@ptrCast(provider), settingsControlDisconnect, settingsControlRelease);
        }
        self.reset_uia_prev_proc = null;
    }

    /// Where row `index`'s marker goes (viewport client coordinates): a bar
    /// left of the row, as tall as a text field.
    fn markerRect(self: *const SettingsWindow, viewport: HWND, index: usize) ?RECT {
        const control = self.controlHwnd(index) orelse return null;
        const rect = childRectIn(viewport, control) orelse return null;
        const right = self.rowLeft(viewport, index, rect) - self.px(settings_marker_gap);
        return .{ .left = right - self.px(settings_marker_width), .top = rect.top, .right = right, .bottom = rect.top + self.px(settings_control_height) };
    }

    /// Repaint the markers that moved, came or went: where each was drawn
    /// and where it is drawn now.
    fn syncMarkerRects(self: *SettingsWindow) void {
        const viewport = self.viewport orelse return;
        const active = self.activeFormRows();
        for (0..form_field_count) |index| {
            const next: ?RECT = if (self.differs_from_default[index] and active.controls[index]) self.markerRect(viewport, index) else null;
            const previous = self.marker_rects[index];
            if (std.meta.eql(previous, next)) continue;
            if (previous) |rect| _ = InvalidateRect(viewport, &rect, 0);
            if (next) |rect| _ = InvalidateRect(viewport, &rect, 0);
            self.marker_rects[index] = next;
        }
    }

    /// The marker's colour: the accent, or in High Contrast the text colour,
    /// as the rail's marks are drawn.
    fn markerColor(self: *const SettingsWindow) COLORREF {
        const colors = self.theme_adapter.colors;
        return if (colors.high_contrast) colors.text else colors.accent;
    }

    /// The row `hwnd` belongs to: its control, its label, its Reset button,
    /// or its trackbar or up-down.
    fn rowOfWindow(self: *const SettingsWindow, hwnd: HWND) ?usize {
        if (self.resetButtonIndex(hwnd)) |index| return index;
        inline for (comptime std.enums.values(Companion)) |kind| {
            if (self.companions[@intFromEnum(kind)] == hwnd) return comptime kind.controlIndex();
        }
        for (self.formItems()) |item| {
            if (item.control_index >= form_field_count) continue;
            if (self.controlHwnd(item.control_index) == hwnd) return item.control_index;
            if (item.label_index) |label| if (self.field_labels[label] == hwnd) return item.control_index;
        }
        return null;
    }

    /// The window row `index` ends with: its up-down where it has one, else
    /// its control.
    fn rowEnd(self: *const SettingsWindow, index: usize) ?HWND {
        if (Companion.ofControl(index)) |kind| if (kind != .opacity_slider) {
            if (self.companions[@intFromEnum(kind)]) |spin| return spin;
        };
        return self.controlHwnd(index);
    }

    /// Row `index`'s trackbar or up-down, if it has one.
    fn companionOf(self: *const SettingsWindow, index: usize) ?HWND {
        const kind = Companion.ofControl(index) orelse return null;
        return self.companions[@intFromEnum(kind)];
    }

    /// Where row `index` starts (viewport client coordinates): at its
    /// trackbar, left of its field, where it has one; else at its control,
    /// whose rectangle is `control`.
    fn rowLeft(self: *const SettingsWindow, viewport: HWND, index: usize, control: RECT) i32 {
        if (Companion.ofControl(index) != .opacity_slider) return control.left;
        const slider = self.companions[@intFromEnum(Companion.opacity_slider)] orelse return control.left;
        const rect = childRectIn(viewport, slider) orelse return control.left;
        return @min(rect.left, control.left);
    }

    /// The row under `point` (viewport client coordinates): its label, its
    /// control, its Reset button, and the marker room left of them.
    fn rowAtPoint(self: *const SettingsWindow, point: POINT) ?usize {
        const viewport = self.viewport orelse return null;
        for (self.formItems()) |item| {
            if (item.control_index >= form_field_count) continue;
            const control = self.controlHwnd(item.control_index) orelse continue;
            var row = childRectIn(viewport, control) orelse continue;
            row.left = self.rowLeft(viewport, item.control_index, row);
            row.bottom = row.top + self.px(settings_control_height);
            if (item.label_index) |label| if (self.field_labels[label]) |text| if (childRectIn(viewport, text)) |label_rect| {
                row.top = @min(row.top, label_rect.top);
            };
            row.left -= self.px(settings_marker_gap + settings_marker_width);
            if (resettable_rows[item.control_index]) {
                const end = childRectIn(viewport, self.rowEnd(item.control_index) orelse control) orelse row;
                row.right = @max(row.right, end.right) + self.px(settings_reset_gap + settings_reset_width);
            }
            if (point.x >= row.left and point.x < row.right and point.y >= row.top and point.y < row.bottom) return item.control_index;
        }
        return null;
    }

    /// Put row `index` back to its default in the draft. It is an edit like
    /// any other: it previews where the row previews, is unsaved until Save,
    /// which writes the default as that key's line, and Discard takes it back.
    fn resetRow(self: *SettingsWindow, index: usize) void {
        inline for (field_model.form_fields, 0..) |row, i| if (i == index) {
            if (comptime !row.resettable()) return;
            return self.resetFormRow(row);
        };
    }

    fn resetFormRow(self: *SettingsWindow, comptime row: field_model.FormField) void {
        if (self.close_posted) return;
        const defaults = if (self.defaults) |*config| config else return;
        const pending = if (self.pending) |*config| config else return;
        if (!self.rowNeedsReset(row)) return self.setResetNote(row, .already_default);
        // The transaction takes no edit while a save is in progress, and the
        // draft must not change without it.
        if (self.transaction) |*transaction| if (transaction.pending_apply_id != null) return self.setResetNote(row, .reset_failed);
        // A reset is measured against what the file holds now. When the file
        // changed under an edit (a conflict), its value becomes the baseline
        // first, as Keep mine does: otherwise a default equal to the old
        // baseline reads as an edit given up, the field takes the file's
        // value back, and the note says it has the default.
        if (comptime row.field) |field| {
            // Nothing here can fail: the values are copied, not allocated.
            // A half-typed number goes with its error: the field shows the default.
            inline for (comptime std.enums.values(RawScalarField)) |raw| {
                if (comptime raw.setting() == field) if (self.raw_scalar_dirty[@intFromEnum(raw)]) self.finishRawScalarEdit(raw);
            }
            if (self.hasConflict(field)) self.resolveConflict(field, .keep_mine);
            setSettingValue(pending, resetSettingValue(self.fileConfig(), defaults, field));
            @field(field_adapters, row.native.binding).display(self);
            self.trackFieldEdit(field);
        } else {
            const owned = comptime ownedFieldFor(row.descriptor.key);
            const original = if (self.original) |*config| config else return;
            // Every copy the reset needs is made before anything changes, so
            // one that fails leaves the draft, its tracking and its conflict
            // as they were; then they are stored together.
            const prepared = prepareOwnedReset(pending, original, self.fileConfig(), defaults, owned) catch |err| {
                std.log.warn("settings: reset failed field={s} err={}", .{ @tagName(owned), err });
                return self.setResetNote(row, .reset_failed);
            };
            prepared.store(pending, original);
            self.owned_text_changed[@intFromEnum(owned)] = false;
            if (self.ownedEdit(owned)) |control| self.clearValidationError(control);
            self.refreshOwnedControl(owned);
            self.trackOwnedEdit(owned);
        }
        self.setResetNote(row, .field_reset);
    }

    /// Say what a reset did, naming the field and its default.
    fn setResetNote(self: *SettingsWindow, comptime row: field_model.FormField, note: StatusNote) void {
        var buf: [256]u8 = undefined;
        var writer: std.Io.Writer = .fixed(&buf);
        const label = comptime if (row.field) |field| field.label() else row.descriptor.label;
        const written = text: {
            if (note == .reset_failed) {
                writer.print("Could not reset {s}; it keeps its value.", .{label}) catch break :text false;
                break :text true;
            }
            writer.writeAll(label) catch break :text false;
            writer.writeAll(if (note == .field_reset) " is back to its default" else " already has its default") catch break :text false;
            if (self.defaults) |*defaults| writeDefaultSuffix(row, &writer, self.fileConfig(), defaults) catch break :text false;
            writer.writeByte('.') catch break :text false;
            if (note == .field_reset and self.rowDirty(row)) writer.writeAll(" Save to keep it.") catch break :text false;
            break :text true;
        };
        self.freeNoteText();
        if (written) self.note_text = self.handle.alloc.dupe(u8, writer.buffered()) catch null;
        self.status_note = note;
        self.setStatus(self.noteText());
    }

    /// The menu a row offers: its reset, with the default it puts back and
    /// the key that does the same. Unavailable while the row has its default.
    /// False when no row offers one, so the click stays the window's own (the
    /// viewport's scroll bar has a menu of its own).
    fn showRowMenu(self: *SettingsWindow, source: HWND, lParam: LPARAM) bool {
        const hwnd = self.hwnd orelse return false;
        const viewport = self.viewport orelse return false;
        // Without the defaults (they could not be made) there is nothing to reset to.
        const defaults = if (self.defaults) |*config| config else return false;
        const keyboard = @as(u32, @truncate(@as(usize, @bitCast(lParam)))) == 0xFFFF_FFFF;
        const index = (if (source != viewport) self.rowOfWindow(source) else null) orelse row: {
            if (keyboard) break :row if (GetFocus()) |focused| self.rowOfWindow(focused) else null;
            var point: POINT = .{ .x = lparamX(lParam), .y = lparamY(lParam) };
            if (ScreenToClient(viewport, &point) == 0) break :row null;
            break :row self.rowAtPoint(point);
        } orelse return false;
        var text_buf: [192]u8 = undefined;
        var text: std.Io.Writer = .fixed(&text_buf);
        var offered = false;
        var available = false;
        inline for (field_model.form_fields, 0..) |row, i| if (i == index) {
            if (comptime row.resettable()) {
                offered = true;
                available = self.rowNeedsReset(row);
                text.writeAll("&Reset to default") catch {};
                writeDefaultSuffix(row, &text, self.fileConfig(), defaults) catch {};
                text.writeAll("\t" ++ reset_shortcut_text) catch {};
            }
        };
        if (!offered) return false;
        const menu = sys.CreatePopupMenu() orelse return true;
        defer _ = sys.DestroyMenu(menu);
        var text_w: [192]u16 = undefined;
        if (sys.AppendMenuW(menu, if (available) MF_STRING else MF_GRAYED, row_menu_reset, utf8ToW(&text_w, text.buffered())) == 0) return true;
        // From the keyboard the menu opens below the control; from the mouse,
        // where it was clicked.
        var at: POINT = .{ .x = lparamX(lParam), .y = lparamY(lParam) };
        if (keyboard) if (self.controlHwnd(index)) |control| {
            var rect: RECT = undefined;
            if (GetWindowRect(control, &rect) != 0) at = .{ .x = rect.left, .y = rect.top + self.px(settings_control_height) };
        };
        const picked: usize = if (self.context_menu_pick) |pick|
            pick(menu)
        else
            @intCast(@max(0, sys.TrackPopupMenu(menu, TPM_RETURNCMD | TPM_RIGHTBUTTON, at.x, at.y, 0, hwnd, null)));
        if (picked == row_menu_reset) self.resetRow(index);
        return true;
    }

    fn surfaceNextValidation(self: *SettingsWindow, focus: bool) void {
        const visibility_changed = self.syncConflictControls();
        // Before the text: the status row is measured in the font it is drawn in.
        self.syncStatusFont();
        switch (self.nextStatus()) {
            .raw_validation => |field| {
                const destination = self.rawScalarDestination(field);
                self.active_raw_validation = field;
                self.validation_control = destination.hwnd;
                self.setErrorStatus(self.raw_scalar_error[@intFromEnum(field)].?);
                if (focus) if (destination.hwnd) |control| {
                    self.revealControl(destination.section, control);
                    _ = SetFocus(control);
                };
            },
            .owned_validation => |control| {
                self.active_raw_validation = null;
                self.validation_control = control;
                self.setErrorStatus(self.owned_validation_message orelse "A settings value is invalid.");
                if (focus) {
                    if (self.controlIndex(control)) |index| {
                        if (self.controlSection(index)) |section| self.revealControl(section, control);
                    }
                    self.ensureControlVisible(control);
                    _ = SetFocus(control);
                }
            },
            inline .conflict, .owned_conflict => |field| {
                self.active_raw_validation = null;
                self.validation_control = null;
                var buf: [256]u8 = undefined;
                self.setStatus(conflictStatusText(&buf, field.label()));
            },
            .none => {
                self.active_raw_validation = null;
                self.validation_control = null;
                self.setStatus(self.idleStatusText());
            },
        }
        if (visibility_changed) layoutChildren(self);
        self.updateSaveEnabled();
    }

    fn markOwnedTextChanged(self: *SettingsWindow, field: OwnedSettingField, control: HWND) void {
        if (self.suppress_edit_events) return;
        self.owned_text_changed[@intFromEnum(field)] = true;
        self.clearValidationError(control);
        // Font family, theme and default command are only read at save.
        self.status_note = .applies_on_save;
        self.updateSaveEnabled();
    }

    fn trackOwnedEdit(self: *SettingsWindow, field: OwnedSettingField) void {
        // The Profiles page marks the profile the draft's Default profile
        // names.
        if (field == .default_profile) self.profile_stale = true;
        const current = &(self.current orelse return);
        const original = &(self.original orelse return);
        const pending = &(self.pending orelse return);
        const index = @intFromEnum(field);
        self.owned_text_changed[index] = false;

        if (ownedSettingEql(pending, original, field)) {
            self.owned_dirty[index] = false;
            self.owned_conflict[index] = false;
            if (!ownedSettingEql(current, original, field)) {
                copyOwnedSetting(original, current, field) catch |err| {
                    std.log.warn("settings: owned baseline adoption failed field={s} err={}", .{ @tagName(field), err });
                    return;
                };
                copyOwnedSetting(pending, current, field) catch |err| {
                    std.log.warn("settings: owned draft adoption failed field={s} err={}", .{ @tagName(field), err });
                    return;
                };
                self.refreshOwnedControl(field);
            }
        } else if (ownedSettingEql(pending, current, field)) {
            copyOwnedSetting(original, current, field) catch |err| {
                std.log.warn("settings: owned baseline convergence failed field={s} err={}", .{ @tagName(field), err });
                return;
            };
            self.owned_dirty[index] = false;
            self.owned_conflict[index] = false;
        } else {
            self.owned_dirty[index] = true;
            self.owned_conflict[index] = !ownedSettingEql(current, original, field);
        }
        // Font family, theme and default command are only read at save.
        self.status_note = .applies_on_save;
        self.surfaceNextValidation(false);
        self.refreshNativeSectionText();
        self.updateSaveEnabled();
    }

    fn refreshOwnedControl(self: *SettingsWindow, field: OwnedSettingField) void {
        switch (field) {
            .font_family => self.displayFontFamilyInEdit(),
            .theme => self.displayThemeInEdit(),
            .command => self.displayCommandInEdit(),
            .default_profile => self.displayDefaultProfile(),
        }
    }

    fn syncOwnedControl(self: *SettingsWindow, field: OwnedSettingField) void {
        switch (field) {
            .font_family => self.syncFontFamilyFromEdit(),
            .theme => self.syncThemeFromEdit(),
            .command => self.syncCommandFromEdit(),
            // A choice is staged when it is made.
            .default_profile => {},
        }
    }

    /// Merge a newly-reloaded effective config into the open settings session.
    /// Disjoint disk changes advance both staged baselines; overlapping edits
    /// retain the user's draft and become explicit conflicts.
    pub fn externalConfigChanged(self: *SettingsWindow, config: *const Config, revision: u64) void {
        const transaction = &(self.transaction orelse return);
        for (std.enums.values(OwnedSettingField)) |field| {
            if (self.owned_text_changed[@intFromEnum(field)]) self.syncOwnedControl(field);
        }
        var replacement = config.clone(self.handle.alloc) catch |err| {
            std.log.warn("settings: external config snapshot failed revision={d} err={}", .{ revision, err });
            return;
        };
        var replacement_owned = true;
        defer if (replacement_owned) replacement.deinit();
        pane_launch.asWritten(&replacement);
        var changes: [setting_field_count]SettingsTransaction.FieldValue = undefined;
        for (std.enums.values(SettingField), 0..) |field, i| {
            changes[i] = .{ .field = field, .value = settingValue(&replacement, field) };
        }
        var effects: [setting_field_count]SettingsTransaction.Effect = undefined;
        const emitted = transaction.dispatch(.{ .external_update = .{
            .revision = revision,
            .changes = &changes,
        } }, &effects) catch |err| {
            if (err == error.ApplyAlreadyPending) return;
            std.log.warn("settings: external update rejected revision={d} err={}", .{ revision, err });
            return;
        };
        self.dispatchEffects(emitted);
        if (self.handle.configRevision == null) {
            self.local_revision = @max(self.local_revision, revision);
        }

        const previous_current = &(self.current orelse return);
        const original = &(self.original orelse return);
        const pending = &(self.pending orelse return);
        for (std.enums.values(OwnedSettingField)) |field| {
            if (ownedSettingEql(previous_current, &replacement, field)) continue;
            const index = @intFromEnum(field);
            if (self.owned_dirty[index] or self.owned_text_changed[index]) {
                self.owned_conflict[index] =
                    !ownedSettingEql(original, &replacement, field) and
                    !ownedSettingEql(pending, &replacement, field);
                if (ownedSettingEql(pending, &replacement, field)) {
                    copyOwnedSetting(original, &replacement, field) catch |err| {
                        std.log.warn("settings: failed to advance owned baseline field={s} err={}", .{ @tagName(field), err });
                        continue;
                    };
                    self.owned_dirty[index] = false;
                    self.owned_text_changed[index] = false;
                    self.owned_conflict[index] = false;
                }
            } else {
                copyOwnedSetting(original, &replacement, field) catch |err| {
                    std.log.warn("settings: failed to merge owned baseline field={s} err={}", .{ @tagName(field), err });
                    continue;
                };
                copyOwnedSetting(pending, &replacement, field) catch |err| {
                    std.log.warn("settings: failed to merge owned draft field={s} err={}", .{ @tagName(field), err });
                    continue;
                };
            }
        }

        // The profiles have no draft of their own until the page changes one:
        // until then they follow the file, as an unedited field does.
        settings_profiles.followFile(original, pending, &replacement) catch |err| {
            std.log.warn("settings: failed to merge the profiles err={}", .{err});
        };
        // A field open on a profile the file no longer has goes with it.
        if (self.profile_edit) |edit| switch (edit.kind) {
            .new_id, .new_command => {},
            else => if (pending.@"profile-command".get(edit.id()) == null) {
                self.cancelProfileEdit();
                self.setProfileNote(.said, "Profile {s} is no longer in the config file, so the change was not kept.", .{edit.id()});
            },
        };

        self.forgetTarget();
        if (self.current) |*old| old.deinit();
        self.current = replacement;
        replacement_owned = false;

        for (transaction.entries) |entry| {
            if (entry.dirty or entry.conflict) continue;
            setSettingValue(original, entry.current);
            setSettingValue(pending, entry.current);
        }
        // The reload replaced the live config, so the drafts are previewed
        // again, floored like the keystrokes that made them.
        self.previewDrafts();
        // A reset's "Save to keep it" may be about a field the file now has.
        if (self.status_note == .field_reset) {
            self.freeNoteText();
            self.status_note = .none;
        }
        self.refreshAllControls();
        self.surfaceNextValidation(false);
        self.updateSaveEnabled();
        self.referenceConfigChanged();
    }

    /// The unsaved drafts this window previews, as they are shown (with the
    /// opacity floor), copied into `buf`. The App shows them again over a
    /// config that replaced the one they were shown on
    /// (`App.restoreSettingsPreview`): whether a draft is previewed is this
    /// window's to say, not the App's, which cannot tell a draft from a config
    /// that happens to say the same for a while. None while a save is in
    /// flight: its reload shows what was saved.
    pub fn livePreviews(self: *const SettingsWindow, buf: *[setting_field_count]SettingValue) []const SettingValue {
        const transaction = &(self.transaction orelse return buf[0..0]);
        if (transaction.pending_apply_id != null) return buf[0..0];
        var count: usize = 0;
        for (transaction.entries) |entry| {
            if (!entry.dirty or !entry.previewed) continue;
            buf[count] = previewValue(transaction, entry.draft);
            count += 1;
        }
        return buf[0..count];
    }

    /// Hand every live preview to the App again. Showing a draft that is
    /// already shown changes nothing there.
    fn previewDrafts(self: *SettingsWindow) void {
        const preview = self.handle.previewField orelse return;
        var buf: [setting_field_count]SettingValue = undefined;
        for (self.livePreviews(&buf)) |value| preview(self.handle.ctx, std.meta.activeTag(value), value);
    }

    pub fn conflictCount(self: *const SettingsWindow) usize {
        const transaction = &(self.transaction orelse return 0);
        var count = transaction.conflictCount();
        for (self.owned_conflict) |conflict| count += @intFromBool(conflict);
        return count;
    }

    fn pendingDiffText(self: *const SettingsWindow, buf: []u8) []const u8 {
        const transaction = &(self.transaction orelse return no_pending_changes_text);
        // The tail of the buffer is kept for the "and more" line.
        var writer: std.Io.Writer = .fixed(buf[0 .. buf.len - more_changes_text.len]);
        var count: usize = 0;
        var truncated = false;
        for (transaction.entries) |entry| {
            if (!entry.dirty) continue;
            const line_start = writer.end;
            writeSettingDiffLine(&writer, entry.field, entry.baseline, entry.draft) catch {
                // A cut-off line may end inside a character, which would blank the page.
                writer.end = line_start;
                truncated = true;
                break;
            };
            count += 1;
        }
        if (!truncated) if (self.original) |*original| if (self.pending) |*pending| {
            const owned = writeOwnedSettingDiffs(
                &writer,
                original,
                pending,
                self.owned_dirty,
                self.owned_conflict,
            );
            count += owned.lines;
            truncated = owned.truncated;
        };
        // The profiles' changes, counted: their lines are on the Profiles page.
        const profile_changes = self.profileChangeCount();
        if (!truncated and profile_changes != 0) {
            const line_start = writer.end;
            writer.print("Profiles: {d} {s} changed\n", .{ profile_changes, if (profile_changes == 1) @as([]const u8, "field") else "fields" }) catch {
                writer.end = line_start;
                truncated = true;
            };
            if (!truncated) count += 1;
        }
        if (count == 0 and !truncated) return no_pending_changes_text;
        if (truncated) {
            const end = writer.end;
            @memcpy(buf[end..][0..more_changes_text.len], more_changes_text);
            return buf[0 .. end + more_changes_text.len];
        }
        return writer.buffered();
    }

    pub fn hasConflict(self: *const SettingsWindow, field: SettingField) bool {
        const transaction = &(self.transaction orelse return false);
        const entry = transaction.entryConst(field) orelse return false;
        return entry.conflict;
    }

    pub fn resolveConflict(
        self: *SettingsWindow,
        field: SettingField,
        resolution: ConflictResolution,
    ) void {
        const transaction = &(self.transaction orelse return);
        self.status_note = .none;
        var effects: [1]SettingsTransaction.Effect = undefined;
        const emitted = transaction.dispatch(.{ .resolve_conflict = .{
            .field = field,
            .resolution = resolution,
        } }, &effects) catch |err| {
            std.log.warn("settings: conflict resolution failed field={s} err={}", .{ @tagName(field), err });
            return;
        };
        self.dispatchEffects(emitted);
        const entry = transaction.entryConst(field).?;
        if (self.original) |*original| setSettingValue(original, entry.current);
        if (resolution == .use_disk) {
            if (self.pending) |*pending| setSettingValue(pending, entry.current);
            self.refreshAllControls();
        }
        self.updateSaveEnabled();
        self.surfaceNextValidation(false);
    }

    fn syncConflictControls(self: *SettingsWindow) bool {
        const transaction = &(self.transaction orelse return false);
        var next: ?SettingField = null;
        for (transaction.entries) |entry| if (entry.conflict) {
            next = entry.field;
            break;
        };
        self.active_conflict_field = next;
        var next_owned: ?OwnedSettingField = null;
        if (next == null) for (std.enums.values(OwnedSettingField)) |field| {
            if (self.owned_conflict[@intFromEnum(field)]) {
                next_owned = field;
                break;
            }
        };
        self.active_owned_conflict_field = next_owned;
        const focused = sys.GetFocus();
        const conflict_button_focused = focused != null and
            (focused == self.btn_conflict_keep or focused == self.btn_conflict_use_disk);
        const show: i32 = if (!self.close_prompt_visible and (next != null or next_owned != null)) SW_SHOWNORMAL else SW_HIDE;
        const visibility_changed = if (self.btn_conflict_keep) |button|
            (IsWindowVisible(button) != 0) != (show != SW_HIDE)
        else
            false;
        if (self.btn_conflict_keep) |button| _ = ShowWindow(button, show);
        if (self.btn_conflict_use_disk) |button| _ = ShowWindow(button, show);
        if (show == SW_HIDE and conflict_button_focused) self.focusAfterConflictResolution();
        // Discard takes the conflict buttons' place the rest of the time, and
        // is the prompt's own Discard while the prompt is up.
        const discard_hidden = show != SW_HIDE and !self.close_prompt_visible;
        if (self.btn_discard_changes) |button| {
            const was_focused = focused == button;
            _ = ShowWindow(button, if (discard_hidden) SW_HIDE else SW_SHOWNORMAL);
            if (discard_hidden and was_focused) self.focusAfterConflictResolution();
        }
        return visibility_changed;
    }

    fn focusAfterConflictResolution(self: *SettingsWindow) void {
        const validation = if (self.validation_control) |control|
            if (sys.IsWindowVisible(control) != 0 and sys.IsWindowEnabled(control) != 0) control else null
        else
            null;
        const save_hwnd = if (self.btn_save) |button|
            if (sys.IsWindowVisible(button) != 0 and sys.IsWindowEnabled(button) != 0) button else null
        else
            null;
        const section = self.sectionButton(self.active_section);
        const target = switch (conflictFocusTarget(validation != null, save_hwnd != null, section != null)) {
            .validation => validation,
            .save => save_hwnd,
            .section => section,
            .none => null,
        };
        if (target) |control| _ = sys.SetFocus(control);
    }

    fn resolveOwnedConflict(self: *SettingsWindow, field: OwnedSettingField, resolution: ConflictResolution) void {
        const index = @intFromEnum(field);
        self.status_note = .none;
        if (resolution == .keep_mine and self.owned_text_changed[index]) {
            self.syncOwnedControl(field);
            if (self.owned_text_changed[index]) return;
        }
        const current = &(self.current orelse return);
        const original = &(self.original orelse return);
        const pending = &(self.pending orelse return);
        copyOwnedSetting(original, current, field) catch |err| {
            std.log.warn("settings: conflict baseline copy failed field={s} err={}", .{ @tagName(field), err });
            self.setNote(.conflict_not_resolved);
            return;
        };
        if (resolution == .use_disk) {
            copyOwnedSetting(pending, current, field) catch |err| {
                std.log.warn("settings: conflict draft copy failed field={s} err={}", .{ @tagName(field), err });
                self.setNote(.disk_value_not_adopted);
                return;
            };
            self.refreshOwnedControl(field);
        }
        self.owned_text_changed[index] = false;
        self.owned_dirty[index] = !ownedSettingEql(pending, original, field);
        self.owned_conflict[index] = false;
        self.updateSaveEnabled();
        self.surfaceNextValidation(false);
    }

    /// Surface an external-edit conflict inline without stealing focus.
    pub fn promptConflict(self: *SettingsWindow, field: SettingField) void {
        self.active_conflict_field = field;
        self.surfaceNextValidation(false);
        self.updateSaveEnabled();
    }

    /// Null out child HWND references + drop pending. Called from
    /// both WM_CLOSE and WM_NCDESTROY so the next `open()` recreates
    /// fresh children and clones.
    fn clearChildRefs(self: *SettingsWindow) void {
        self.theme_adapter.deinit();
        self.releaseSectionUiaProviders();
        self.releaseTextUiaProviders();
        self.releaseControlUiaProviders();
        self.releaseResetUiaProviders();
        self.forgetDefaults();
        self.hwnd = null;
        self.forgetFormWindows();
        self.text_header = null;
        self.text_summary = null;
        self.text_status = null;
        self.text_help = null;
        self.forgetSearch();
        self.field_labels = [_]?HWND{null} ** settings_label_specs.len;
        self.deleteUiFont();
        self.btn_section_appearance = null;
        self.btn_section_terminal = null;
        self.btn_section_shell = null;
        self.btn_section_profiles = null;
        self.btn_section_privacy = null;
        self.btn_section_updates = null;
        self.btn_section_keybindings = null;
        self.btn_section_advanced = null;
        self.btn_section_reference = null;
        self.forgetReference();
        self.section_button_prev_proc = null;
        self.section_hovered = null;
        self.focus_input_mode = .pointer;
        self.focus_before_deactivate = null;
        self.btn_save = null;
        self.btn_discard_changes = null;
        self.btn_conflict_keep = null;
        self.btn_conflict_use_disk = null;
        self.btn_close_keep_editing = null;
        self.fields = std.mem.zeroes(FieldWindows);
        self.resetClosePromptState();
        self.clearPending();
    }

    fn releaseSectionUiaProviders(self: *SettingsWindow) void {
        const group = self.section_uia_group;
        self.section_uia_group = null;
        if (group) |provider| provider.detach();
        for (&self.section_uia_providers) |*slot| {
            const provider = slot.* orelse continue;
            slot.* = null;
            provider.detach();
            self.deferProviderDisconnect(
                @ptrCast(provider),
                settingsSectionDisconnect,
                settingsSectionRelease,
            );
        }
        if (group) |provider| {
            self.deferProviderDisconnect(
                @ptrCast(provider),
                settingsSectionGroupDisconnect,
                settingsSectionGroupRelease,
            );
        }
    }

    fn releaseTextUiaProviders(self: *SettingsWindow) void {
        for (&self.text_uia_providers) |*slot| {
            const provider = slot.* orelse continue;
            slot.* = null;
            provider.detach();
            self.deferProviderDisconnect(
                @ptrCast(provider),
                settingsControlDisconnect,
                settingsControlRelease,
            );
        }
    }

    fn textHwnd(self: *const SettingsWindow, index: usize) ?HWND {
        return switch (index) {
            text_header_index => self.text_header,
            text_summary_index => self.text_summary,
            text_status_index => self.text_status,
            text_help_index => self.text_help,
            else => if (index - text_first_label_index < self.field_labels.len) self.field_labels[index - text_first_label_index] else null,
        };
    }

    /// Announce new text in the status line or the close prompt, the two
    /// elements Narrator would otherwise never speak: the keyboard focus is
    /// elsewhere when they change. Without the custom providers the legacy
    /// name-change event is all a client has.
    fn announceText(self: *SettingsWindow, index: usize) void {
        const text = self.textHwnd(index) orelse return;
        if (self.text_uia_providers[index]) |provider| {
            // A reader drops a live region that is offscreen.
            if (sys.IsWindowVisible(text) != 0) provider.raiseLiveRegionChanged();
            return;
        }
        sys.NotifyWinEvent(EVENT_OBJECT_NAMECHANGE, text, @bitCast(OBJID_CLIENT), @bitCast(CHILDID_SELF));
    }

    fn textIndex(self: *const SettingsWindow, hwnd: HWND) ?usize {
        for (0..settings_text_count) |index| {
            if (self.textHwnd(index)) |text| {
                if (text == hwnd) return index;
            }
        }
        return null;
    }

    fn initializeTextUiaProviders(self: *SettingsWindow) void {
        self.releaseTextUiaProviders();
        self.text_uia_prev_proc = null;
        if (!self.canInitializeCustomUiaProviders()) return;
        for (0..settings_text_count) |index| self.attachTextUiaProvider(index);
    }

    /// The UIA provider of text `index`, if that text exists. The caller
    /// checks that custom providers are enabled.
    fn attachTextUiaProvider(self: *SettingsWindow, index: usize) void {
        const text = self.textHwnd(index) orelse return;
        const role: SettingsControlRole = switch (index) {
            // The status line, and the header's line, which says what a
            // search found.
            text_status_index, text_summary_index => .live_text,
            else => .text,
        };
        const provider = win32_uia.SettingsControlProvider.create(std.heap.page_allocator, text, role, null) catch |err| {
            std.log.warn("settings text UIA provider unavailable index={} err={}", .{ index, err });
            return;
        };
        const previous = sys.SetWindowLongPtrW(
            text,
            GWLP_WNDPROC,
            @as(LONG_PTR, @intCast(@intFromPtr(&settingsTextProc))),
        );
        if (previous == 0) {
            _ = win32_uia.SettingsControlProvider.Release(&provider.base);
            return;
        }
        const proc: *const anyopaque = @ptrFromInt(@as(usize, @intCast(previous)));
        if (self.text_uia_prev_proc) |existing| {
            if (existing != proc) {
                _ = sys.SetWindowLongPtrW(text, GWLP_WNDPROC, previous);
                _ = win32_uia.SettingsControlProvider.Release(&provider.base);
                return;
            }
        } else {
            self.text_uia_prev_proc = proc;
        }
        self.text_uia_providers[index] = provider;
    }

    fn releaseControlUiaProviders(self: *SettingsWindow) void {
        for (&self.control_uia_providers) |*slot| {
            const provider = slot.* orelse continue;
            slot.* = null;
            provider.detach();
            self.deferProviderDisconnect(
                @ptrCast(provider),
                settingsControlDisconnect,
                settingsControlRelease,
            );
        }
        self.control_uia_prev_procs = [_]?*const anyopaque{null} ** settings_control_count;
        if (self.viewport_uia_provider) |provider| {
            self.viewport_uia_provider = null;
            provider.detach();
            self.deferProviderDisconnect(@ptrCast(provider), settingsControlDisconnect, settingsControlRelease);
        }
    }

    /// The viewport and the state the layout and the field frames keep about
    /// it, for a window that is gone.
    fn forgetFormWindows(self: *SettingsWindow) void {
        self.fields = .{};
        self.materialized = .initEmpty();
        self.viewport = null;
        self.framed_invalid_field = null;
        self.help_shown = false;
        self.background_geometry = null;
        self.reset_buttons = @splat(null);
        self.companions = @splat(null);
        self.reset_spare_count = 0;
        self.differs_from_default = @splat(false);
        self.described = @splat(0);
        self.origin_notes = @splat(.{});
        self.marker_rects = @splat(null);
    }

    /// The search field and what it held, for a window that is gone: the next
    /// window opens with no search.
    fn forgetSearch(self: *SettingsWindow) void {
        self.edit_search = null;
        self.search_named = false;
        self.search_query = .{};
        self.search_found = @splat(false);
        self.search_counts = @splat(0);
        self.search_total = 0;
        self.search_item_count = 0;
    }

    fn forgetDefaults(self: *SettingsWindow) void {
        if (self.defaults) |*defaults| defaults.deinit();
        self.defaults = null;
    }

    fn deferProviderDisconnect(
        self: *SettingsWindow,
        provider_ctx: *anyopaque,
        disconnect: *const fn (*anyopaque) win32_uia.HRESULT,
        release: *const fn (*anyopaque) void,
    ) void {
        if (self.handle.deferUiaDisconnect) |defer_disconnect| {
            defer_disconnect(self.handle.ctx, provider_ctx, disconnect, release);
            return;
        }
        const hr = disconnect(provider_ctx);
        if (hr != win32_uia.S_OK) {
            std.log.warn("settings UIA immediate disconnect failed hr=0x{x}", .{@as(u32, @bitCast(hr))});
        }
        release(provider_ctx);
    }

    fn controlHwnd(self: *const SettingsWindow, index: usize) ?HWND {
        inline for (settings_control_specs, 0..) |spec, i| if (index == i) {
            return if (comptime i < settings_clipped_control_count) @field(self.fields, spec.binding) else @field(self, spec.binding);
        };
        return null;
    }

    fn controlIndex(self: *const SettingsWindow, hwnd: HWND) ?usize {
        for (0..settings_control_count) |index| {
            if (self.controlHwnd(index)) |control| {
                if (control == hwnd) return index;
            }
        }
        return null;
    }

    /// The rows the shown page shows: all of them, or while a search is typed
    /// only those it found. The others are hidden, which takes them out of
    /// the Tab order, the arrow-key groups and the UIA tree.
    fn formItems(self: *const SettingsWindow) []const FormItem {
        if (self.search_query.active()) return self.search_items[0..self.search_item_count];
        return formItemsForSection(self.active_section);
    }

    /// Whether form row `index` (`field_model.form_fields[index]`) differs
    /// from its default, as its marker says (`rowDiffersFromDefault`), for a
    /// row whose page may not have been made yet.
    fn rowDiffersAt(self: *const SettingsWindow, index: usize) bool {
        inline for (field_model.form_fields, 0..) |row, i| if (i == index) return self.rowDiffersFromDefault(row);
        return false;
    }

    /// Whether the search finds control `index`'s row: every word is in its
    /// text, and with `@modified` it differs from its default.
    fn searchFinds(self: *const SettingsWindow, index: usize) bool {
        if (!self.search_query.matchesText(settings_search_text[index])) return false;
        return !self.search_query.modified or self.rowDiffersAt(index);
    }

    /// Find the rows of every page the search holds, and count the settings
    /// they show. A setting is counted once: on its page, a key shown as two
    /// rows (`app-notifications`) once, and in all, as the All settings page
    /// counts it, since every key's row there is found by its fields' words as
    /// well (`reference_extra_search`), and with `@modified` by the same test
    /// (`referenceRowDiffers`). The other pages' rows that are no key (their
    /// "Open config" buttons) count one each, and so does each binding the
    /// Keybindings page's list finds: it is a `keybind` line of its own.
    fn findSearchRows(self: *SettingsWindow) void {
        self.search_counts = @splat(0);
        self.search_total = 0;
        if (!self.search_query.active()) return;
        const KeySet = std.StaticBitSet(settings_reference.key_count);
        var form_keys: KeySet = .initEmpty();
        var not_keys: usize = 0;
        for (std.enums.values(Section)) |section| {
            var page_keys: KeySet = .initEmpty();
            for (formItemsForSection(section)) |item| {
                const found = self.searchFinds(item.control_index);
                self.search_found[item.control_index] = found;
                if (!found) continue;
                if (item.control_index < form_field_count) {
                    const key = form_row_keys[item.control_index];
                    if (page_keys.isSet(key)) continue;
                    page_keys.set(key);
                    form_keys.set(key);
                } else not_keys += 1;
                self.search_counts[@intFromEnum(section)] += 1;
            }
        }
        // Each binding on the Keybindings page counts once more: it is a
        // `keybind` line of its own. So does each row of the Profiles page,
        // a profile or one of its fields.
        const bindings_found = self.findKeybindRows();
        self.search_counts[@intFromEnum(Section.keybindings)] += bindings_found;
        const profiles_found = self.findProfileRows();
        self.search_counts[@intFromEnum(Section.profiles)] += profiles_found;
        self.ensureReferenceModel();
        if (!self.reference_model.built()) {
            self.reference_found = @splat(false);
            self.search_total = form_keys.count() + not_keys + bindings_found + profiles_found;
            return;
        }
        var keys_found: u16 = 0;
        for (&self.reference_found, 0..) |*found, key| {
            found.* = self.referenceFinds(key);
            if (found.*) keys_found += 1;
        }
        self.search_counts[@intFromEnum(Section.reference)] = keys_found;
        self.search_total = keys_found + not_keys + bindings_found + profiles_found;
    }

    /// Which bindings the search finds on the Keybindings page
    /// (`keybind_found`), by their keys, actions and what the actions do; with
    /// `@modified`, only the ones the defaults lack. How many
    /// (`keybind_found_count`).
    fn findKeybindRows(self: *SettingsWindow) u16 {
        self.ensureKeybindModel();
        var found_count: u16 = 0;
        for (self.keybind_found, 0..) |*found, id| {
            const row = &self.keybind_model.rows[id];
            found.* = self.search_query.matchesText(row.search) and (!self.search_query.modified or row.differs);
            if (found.*) found_count +|= 1;
        }
        self.keybind_found_count = found_count;
        return found_count;
    }

    /// Whether the search finds config key `key` (an index into
    /// `settings_reference.keys`) on the All settings page.
    fn referenceFinds(self: *const SettingsWindow, key: usize) bool {
        if (!self.search_query.matchesText(self.reference_model.rows[key].search)) return false;
        return !self.search_query.modified or self.referenceRowDiffers(key);
    }

    /// Whether key `key` differs from its default: for a key with Settings
    /// controls, as their markers say (the draft); for any other, its value
    /// in effect (`settings_reference.Row.differs`).
    fn referenceRowDiffers(self: *const SettingsWindow, key: usize) bool {
        const rows = reference_form_rows[key];
        if (rows.len != 0) {
            for (rows) |row| if (self.rowDiffersAt(row)) return true;
            return false;
        }
        return self.reference_model.rows[key].differs;
    }

    /// Whether the shown page has anything the search found: rows of its
    /// form, or in its list, keys or bindings.
    fn pageFoundRows(self: *const SettingsWindow) bool {
        if (self.active_section == .reference) return self.reference_list.shown_count != 0;
        if (self.active_section == .profiles) return self.profile_list.shown_count != 0;
        if (self.active_section == .keybindings and self.keybind_list.shown_count != 0) return true;
        return self.search_item_count != 0;
    }

    /// The found rows of the shown page, in form order (`search_items`).
    fn filterShownPage(self: *SettingsWindow) void {
        var count: usize = 0;
        for (formItemsForSection(self.active_section)) |item| if (self.search_found[item.control_index]) {
            self.search_items[count] = item;
            count += 1;
        };
        self.search_item_count = count;
    }

    /// Run the search the field holds: find its rows, then show the page with
    /// only those, in one pass the way a page switch does, painted before
    /// this returns. The page's Reset buttons follow its shown rows. The
    /// viewport draws nothing while its rows are shown, hidden and moved
    /// (`suspendViewportRedraw`), and is painted once after.
    fn runSearch(self: *SettingsWindow, from_top: bool) void {
        const started = bench_trace.queryPerformanceCounter();
        self.findSearchRows();
        if (self.search_query.active()) self.filterShownPage();
        if (self.sectionList(self.active_section)) |list| self.refreshListShown(list, from_top);
        if (from_top) self.content_scroll_y = 0;
        self.refreshNativeSectionText();
        self.syncSearchCounts();
        self.keepFocusShown();
        {
            const suspended = self.suspendViewportRedraw();
            defer resumeViewportRedraw(suspended);
            self.syncDefaultMarksShowing(false);
            layoutChildren(self);
            self.applySectionVisibility();
        }
        const found = bench_trace.queryPerformanceCounter();
        if (self.hwnd) |hwnd| _ = RedrawWindow(hwnd, null, null, RDW_UPDATENOW | RDW_ALLCHILDREN);
        const painted = bench_trace.queryPerformanceCounter();
        const frequency = bench_trace.queryPerformanceFrequency();
        self.proof_search_filter_us = elapsedMicroseconds(started, found, frequency);
        self.proof_search_total_us = elapsedMicroseconds(started, painted, frequency);
    }

    /// Turn the form viewport's drawing off for a pass that shows, hides and
    /// moves many of its rows. With drawing on, each `ShowWindow` has the
    /// window manager rework the viewport's children, which at about 200 rows
    /// (450-600 windows) costs some 0.2 ms a window: a search that showed or
    /// hid most of a page spent up to 100 ms there. `WM_SETREDRAW` FALSE
    /// clears the viewport's `WS_VISIBLE` bit without hiding it, so the screen
    /// keeps its last picture, and until `resumeViewportRedraw` no window in
    /// the viewport counts as visible: nothing in between may decide anything
    /// on `IsWindowVisible`. Returns the viewport when its drawing was turned
    /// off; null when it was not shown (or is already suspended, by an outer
    /// pass), so that only the call that turned drawing off turns it on.
    fn suspendViewportRedraw(self: *SettingsWindow) ?HWND {
        const viewport = self.viewport orelse return null;
        const style: u32 = @truncate(@as(usize, @bitCast(sys.GetWindowLongPtrW(viewport, GWL_STYLE))));
        if (style & WS_VISIBLE == 0) return null;
        _ = sys.SendMessageW(viewport, WM_SETREDRAW, 0, 0);
        return viewport;
    }

    /// Drawing back on after `suspendViewportRedraw`, and the whole viewport
    /// invalidated, its frame (the scroll bar) and children included: a
    /// window hidden while drawing was off left its pixels behind, and a
    /// window shown was not invalidated. The caller paints (`RDW_UPDATENOW`).
    fn resumeViewportRedraw(suspended: ?HWND) void {
        const viewport = suspended orelse return;
        _ = sys.SendMessageW(viewport, WM_SETREDRAW, 1, 0);
        _ = RedrawWindow(viewport, null, null, RDW_INVALIDATE | RDW_ERASE | RDW_FRAME | RDW_ALLCHILDREN);
    }

    /// How many rows the search found on `section`'s page, or null with no
    /// search.
    fn searchCountOf(self: *const SettingsWindow, section: Section) ?u16 {
        if (!self.search_query.active()) return null;
        return self.search_counts[@intFromEnum(section)];
    }

    /// Tell each rail button how many rows the search found on its page, or
    /// that there is no search: the count is drawn on it and said as its
    /// `ItemStatus`.
    fn syncSearchCounts(self: *SettingsWindow) void {
        const active = self.search_query.active();
        for (std.enums.values(Section)) |section| {
            const count: ?u16 = if (active) self.search_counts[@intFromEnum(section)] else null;
            if (self.sectionProvider(section)) |provider| provider.setSearchCount(count);
            if (self.sectionButton(section)) |button| _ = InvalidateRect(button, null, 0);
        }
    }

    /// A focused row the search is about to hide gives the focus to the search
    /// field first, where the search was changed from. Hidden while focused,
    /// a field hands the focus to its parent, the viewport, where no key
    /// reaches it (measured: after a search hid the focused field, `GetFocus()`
    /// was the viewport). So this runs once the rows to show are known
    /// (`activeFormRows`) and before any is hidden, and asks those rows rather
    /// than `IsWindowVisible`, which the viewport's suspended drawing would
    /// answer false for every row.
    fn keepFocusShown(self: *SettingsWindow) void {
        const focused = GetFocus() orelse return;
        const viewport = self.viewport orelse return;
        if (IsChild(viewport, focused) == 0) return;
        const active = self.activeFormRows();
        // Field rows hold Reset buttons; the display rows after them do not.
        // The All settings list is hidden when the search finds no key.
        const stays = if (focused == self.reference_list.hwnd)
            self.referenceListShows()
        else if (focused == self.keybind_list.hwnd)
            self.keybindListShows()
        else if (focused == self.profile_list.hwnd)
            self.profileListShows()
        else for (0..settings_clipped_control_count) |index| {
            if (focused == self.controlHwnd(index) or focused == self.companionOf(index) or
                (index < form_field_count and focused == self.reset_buttons[index])) break active.controls[index];
        } else true;
        if (!stays) if (self.edit_search) |search| {
            _ = SetFocus(search);
        };
    }

    /// The search field's text changed: the user typed, pasted or deleted,
    /// or UIA set its value. A change that looks for the same rows (a space,
    /// a change of case) runs nothing again.
    fn searchTextChanged(self: *SettingsWindow) void {
        if (self.suppress_edit_events) return;
        const search = self.edit_search orelse return;
        var wide: [search_text_max_code_units + 1]u16 = undefined;
        const wide_len: usize = @intCast(@max(0, sys.GetWindowTextW(search, &wide, @intCast(wide.len))));
        var utf8: [SearchQuery.capacity]u8 = undefined;
        const text = utf16ToUtf8Lossy(&utf8, wide[0..wide_len]);
        const next = SearchQuery.parse(text);
        const same = next.sameSearch(&self.search_query);
        self.search_query = next;
        if (same) {
            // The message on a page with nothing found repeats what was typed,
            // which may now wrap differently.
            if (next.active() and !self.pageFoundRows()) {
                self.refreshNativeSectionText();
                layoutChildren(self);
            }
            return;
        }
        self.runSearch(true);
        self.armSearchAnnounce();
    }

    /// Empty the search field and show every row again. The field's own
    /// change notification is held back: the search runs here, once.
    fn clearSearch(self: *SettingsWindow) void {
        const was_active = self.search_query.active();
        self.dropSearch();
        if (was_active) self.runSearch(true);
    }

    /// Empty the search field and forget the search, with no pass of its own:
    /// for a caller that shows a page next (`setActiveSection`), which lays
    /// the page out and paints it once.
    fn dropSearch(self: *SettingsWindow) void {
        if (self.edit_search) |search| {
            const suppressed = self.suppress_edit_events;
            self.suppress_edit_events = true;
            _ = sys.SetWindowTextW(search, std.unicode.utf8ToUtf16LeStringLiteral(""));
            self.suppress_edit_events = suppressed;
        }
        self.search_query = .{};
        self.killSearchAnnounce();
        self.syncSearchCounts();
    }

    /// Show `section` with `control` on it and focus the control: the palette's
    /// jump to a field, and a field whose value Settings will not take. A search
    /// that would hide the control gives way first. Asked live, not from the
    /// last pass: with `@modified` a row that was reset since still shows, and
    /// the page switch runs the search again.
    fn revealControl(self: *SettingsWindow, section: Section, control: HWND) void {
        if (self.search_query.active()) if (self.controlIndex(control)) |index| {
            if (index < settings_clipped_control_count and !self.searchFinds(index)) self.dropSearch();
        };
        self.focusAhead(control);
        self.showSection(section, true);
        self.ensureControlVisible(control);
    }

    /// Give `control` the focus ahead of the page switch that shows it, so the
    /// focus moves once, the way `openSection` moves it to its rail button.
    /// The switch then hides the last page's rows with none of them holding
    /// the focus: a focused Reset button given up by its row would otherwise
    /// send it to the rail (`releaseResetButton`), and a focused field hidden
    /// would hand it to its parent, the viewport, before the control took it.
    /// The control may still be hidden. Its focus notification does not scroll
    /// the form (`restoring_focus`): the caller does, once the page is laid out.
    fn focusAhead(self: *SettingsWindow, control: HWND) void {
        self.restoring_focus = true;
        defer self.restoring_focus = false;
        _ = SetFocus(control);
    }

    /// `focusAhead` for `section`'s rail button, checked first, as
    /// `releaseResetButton` does, so taking the focus does not click it and
    /// start the switch again from inside this one.
    fn focusRailButtonAhead(self: *SettingsWindow, section: Section) void {
        const button = self.sectionButton(section) orelse return;
        if (@as(usize, @bitCast(sys.SendMessageW(button, BM_GETCHECK, 0, 0))) != BST_CHECKED) _ = sys.SendMessageW(button, BM_SETCHECK, BST_CHECKED, 0);
        self.focusAhead(button);
    }

    /// The UI state the dialog manager keeps hiding focus rectangles in
    /// until it sees Tab or an arrow key: a focus moved by Ctrl+F or Enter
    /// in the search field is a keyboard move, so the focused control shows it.
    fn showKeyboardCues(self: *SettingsWindow) void {
        self.focus_input_mode = .keyboard;
        const hwnd = self.hwnd orelse return;
        const UIS_CLEAR: usize = 2;
        const UISF_HIDEFOCUS: usize = 0x1;
        _ = sys.SendMessageW(hwnd, WM_CHANGEUISTATE, (UISF_HIDEFOCUS << 16) | UIS_CLEAR, 0);
    }

    /// Enter in the search field: focus the first setting found, on the shown
    /// page, or else on the first page (in rail order) that has one. A setting
    /// that cannot be changed (Windows does not support it) is passed over;
    /// with none to focus the page's rail button takes the focus. On the All
    /// settings page the list takes it, on the first key found, and on
    /// Keybindings it does when no row of the form was found.
    fn goToFirstMatch(self: *SettingsWindow) void {
        if (!self.search_query.active() or self.search_total == 0) return;
        // The field the focus lands on is spoken; the count would follow it.
        self.killSearchAnnounce();
        self.showKeyboardCues();
        if (self.search_counts[@intFromEnum(self.active_section)] == 0) {
            if (firstPageWithMatches(&self.search_counts)) |section| self.showSection(section, true);
            // With `@modified` the counts were the last pass's; the switch
            // found again, and the first page may have none now.
            if (!self.pageFoundRows()) if (firstPageWithMatches(&self.search_counts)) |section| {
                if (section != self.active_section) self.showSection(section, true);
            };
        }
        // Nothing found after all: the focus stays in the field.
        if (!self.pageFoundRows()) return;
        if (self.active_section == .reference or self.active_section == .profiles) {
            const state = self.sectionList(self.active_section).?;
            const list = state.hwnd orelse return;
            state.selectPosition(0);
            _ = SetFocus(list);
            return;
        }
        for (self.formItems()) |item| {
            const control = self.controlHwnd(item.control_index) orelse continue;
            if (sys.IsWindowEnabled(control) == 0) continue;
            self.ensureControlVisible(control);
            _ = SetFocus(control);
            return;
        }
        if (self.active_section == .keybindings and self.keybind_list.shown_count != 0) if (self.keybind_list.hwnd) |list| {
            self.keybind_list.selectPosition(0);
            _ = SetFocus(list);
            return;
        };
        if (self.sectionButton(self.active_section)) |button| _ = SetFocus(button);
    }

    /// The count is said once typing pauses (`search_announce_quiet_ms`).
    fn armSearchAnnounce(self: *SettingsWindow) void {
        const hwnd = self.hwnd orelse return;
        if (!self.search_query.active()) return self.killSearchAnnounce();
        _ = sys.SetTimer(hwnd, search_announce_timer_id, search_announce_quiet_ms, null);
    }

    fn killSearchAnnounce(self: *SettingsWindow) void {
        const hwnd = self.hwnd orelse return;
        _ = sys.KillTimer(hwnd, search_announce_timer_id);
    }

    /// Typing paused: say the count in the header (`searchSummaryText`), a
    /// polite live region.
    fn searchAnnounceElapsed(self: *SettingsWindow) void {
        self.killSearchAnnounce();
        if (self.search_query.active()) self.announceText(text_summary_index);
    }

    /// The control index of `field`'s row.
    fn settingControlIndex(field: SettingField) usize {
        inline for (field_model.form_fields, 0..) |row, index| if (row.field == field) return index;
        unreachable;
    }

    const ActiveFormRows = struct {
        controls: [settings_clipped_control_count]bool = @splat(false),
        labels: [settings_label_specs.len]bool = @splat(false),
    };

    /// Which controls and labels belong to the section on show.
    fn activeFormRows(self: *const SettingsWindow) ActiveFormRows {
        var rows: ActiveFormRows = .{};
        for (self.formItems()) |item| {
            rows.controls[item.control_index] = true;
            if (item.label_index) |index| rows.labels[index] = true;
        }
        return rows;
    }

    fn controlSection(self: *const SettingsWindow, control_index: usize) ?Section {
        _ = self;
        for (std.enums.values(Section)) |section| for (formItemsForSection(section)) |item| {
            if (item.control_index == control_index) return section;
        };
        return null;
    }

    fn initializeControlUiaProviders(self: *SettingsWindow) void {
        self.releaseControlUiaProviders();
        if (!self.canInitializeCustomUiaProviders()) return;
        if (self.viewport) |viewport| {
            // Answered from the viewport's own window procedure; no subclass.
            self.viewport_uia_provider = win32_uia.SettingsControlProvider.create(
                std.heap.page_allocator,
                viewport,
                .layout_pane,
                null,
            ) catch |err| blk: {
                std.log.warn("settings viewport UIA provider unavailable err={}", .{err});
                break :blk null;
            };
        }
        for (0..settings_control_count) |index| self.attachControlUiaProvider(index);
    }

    /// The UIA provider of control `index`, if that control exists. It
    /// subclasses the control, so a dropdown's or a text field's own subclass
    /// has to be installed first. The caller checks that custom providers are
    /// enabled.
    fn attachControlUiaProvider(self: *SettingsWindow, index: usize) void {
        const control = self.controlHwnd(index) orelse return;
        const spec = settings_control_specs[index];
        const provider = win32_uia.SettingsControlProvider.create(
            std.heap.page_allocator,
            control,
            spec.role,
            // Save's caption is its name, which the close prompt changes
            // (`placeSaveButton`).
            if (spec.id == BTN_SAVE) null else spec.name,
        ) catch |err| {
            std.log.warn("settings control UIA provider unavailable index={} err={}", .{ index, err });
            return;
        };
        const previous = sys.SetWindowLongPtrW(
            control,
            GWLP_WNDPROC,
            @as(LONG_PTR, @intCast(@intFromPtr(&settingsControlProc))),
        );
        if (previous == 0) {
            _ = win32_uia.SettingsControlProvider.Release(&provider.base);
            return;
        }
        provider.help_text = spec.help;
        if (index < form_field_count) provider.changed_from_default.store(self.differs_from_default[index], .release);
        self.control_uia_prev_procs[index] = @ptrFromInt(@as(usize, @intCast(previous)));
        self.control_uia_providers[index] = provider;
        if (spec.role == .combo_box) SettingsComboPopup.attach(control);
    }

    fn sectionButton(self: *const SettingsWindow, section: Section) ?HWND {
        return switch (section) {
            .appearance => self.btn_section_appearance,
            .terminal => self.btn_section_terminal,
            .shell => self.btn_section_shell,
            .profiles => self.btn_section_profiles,
            .privacy => self.btn_section_privacy,
            .updates => self.btn_section_updates,
            .keybindings => self.btn_section_keybindings,
            .advanced => self.btn_section_advanced,
            .reference => self.btn_section_reference,
        };
    }

    fn sectionProvider(self: *const SettingsWindow, section: Section) ?*win32_uia.SettingsSectionProvider {
        return self.section_uia_providers[@intFromEnum(section)];
    }

    fn sectionForButton(self: *const SettingsWindow, hwnd: HWND) ?Section {
        for (std.enums.values(Section)) |section| {
            if (self.sectionButton(section)) |button| {
                if (button == hwnd) return section;
            }
        }
        return null;
    }

    fn initializeSectionUiaProviders(self: *SettingsWindow) void {
        self.releaseSectionUiaProviders();
        if (!self.canInitializeCustomUiaProviders()) return;
        const parent = self.hwnd orelse return;
        const group = win32_uia.SettingsSectionGroupProvider.create(
            std.heap.page_allocator,
            parent,
        ) catch |err| {
            std.log.warn("settings section UIA group unavailable err={}", .{err});
            return;
        };
        self.section_uia_group = group;
        for (std.enums.values(Section)) |section| {
            const button = self.sectionButton(section) orelse continue;
            const provider = win32_uia.SettingsSectionProvider.create(
                std.heap.page_allocator,
                button,
                section.headerText(),
                @intFromEnum(section),
                group,
            ) catch |err| {
                std.log.warn("settings section UIA provider unavailable section={s} err={}", .{ section.headerText(), err });
                continue;
            };
            self.section_uia_providers[@intFromEnum(section)] = provider;
            group.setSection(@intFromEnum(section), provider);
        }
        group.setSelected(@intFromEnum(self.active_section));
    }

    fn subclassSectionButtons(self: *SettingsWindow) void {
        self.section_button_prev_proc = null;
        for (std.enums.values(Section)) |section| {
            const button = self.sectionButton(section) orelse continue;
            const previous = SetWindowLongPtrW(
                button,
                GWLP_WNDPROC,
                @as(LONG_PTR, @intCast(@intFromPtr(&settingsSectionButtonProc))),
            );
            if (previous == 0) continue;
            const proc: *const anyopaque = @ptrFromInt(@as(usize, @intCast(previous)));
            if (self.section_button_prev_proc) |existing| {
                if (existing != proc) {
                    _ = SetWindowLongPtrW(button, GWLP_WNDPROC, previous);
                    continue;
                }
            } else {
                self.section_button_prev_proc = proc;
            }
        }
    }

    /// Switch the form to `next`. The new section's fields are placed while
    /// they are still hidden, swapped in for the old ones, and painted before
    /// this returns, so no frame shows a field that has not drawn itself yet.
    /// Only the form and the header text repaint; the frame window does not.
    /// The first time a section is shown its rows are made here, hidden.
    fn setActiveSection(self: *SettingsWindow, next: Section) void {
        self.showSection(next, false);
    }

    /// `setActiveSection`. With `focus_follows` the caller has already given
    /// the focus to the page's control or rail button (`focusAhead`), so no
    /// row of the last page holds it and the search does not move it to the
    /// search field: one focus move, one announcement.
    fn showSection(self: *SettingsWindow, next: Section, focus_follows: bool) void {
        const changed = self.active_section != next;
        self.materializeSection(next);
        // A page's list exists only while its page is shown: it goes before
        // the next page's rows show, and comes, hidden, for the page.
        if (changed) if (self.sectionList(self.active_section)) |list| self.destroyList(list, next);
        self.active_section = next;
        // A search shows the found rows of the page. Found again: with
        // `@modified` what differs may have changed since it last ran.
        if (self.search_query.active()) {
            self.findSearchRows();
            self.filterShownPage();
            self.syncSearchCounts();
        }
        if (self.sectionList(next)) |list| {
            self.refreshListShown(list, false);
            self.createList(list);
        }
        // A row of this page the search no longer finds may hold the focus.
        if (self.search_query.active() and !focus_follows) self.keepFocusShown();
        // The page's Reset buttons, made hidden before the layout places
        // them; the last page's go.
        self.syncDefaultMarksShowing(false);
        // Neither list page holds a Reset button.
        if (next == .reference or next == .profiles) self.destroyResetSpares();
        if (self.section_uia_group) |group| group.setSelected(@intFromEnum(next));
        self.content_scroll_y = 0;
        self.refreshNativeSectionText();
        layoutChildren(self);
        self.applySectionVisibility();
        if (self.hwnd) |hwnd| _ = RedrawWindow(hwnd, null, null, RDW_UPDATENOW | RDW_ALLCHILDREN);
        if (changed) {
            if (self.sectionProvider(next)) |provider| provider.raiseSelected();
        }
    }

    /// Scroll the form to `next`. The viewport moves its pixels and its child
    /// windows together and repaints only the strip that comes into view; the
    /// header and the action bar are outside it and do not repaint at all.
    fn setContentScroll(self: *SettingsWindow, next: i32) void {
        const clamped = std.math.clamp(next, 0, self.content_scroll_max);
        if (clamped == self.content_scroll_y) return;
        const delta = self.content_scroll_y - clamped;
        self.content_scroll_y = clamped;
        const viewport = self.viewport orelse return;
        // The markers' pixels move with the rest of the viewport's.
        for (&self.marker_rects) |*marker| if (marker.*) |*rect| {
            rect.top += delta;
            rect.bottom += delta;
        };
        _ = ScrollWindowEx(viewport, 0, delta, null, null, null, null, SW_SCROLLCHILDREN | SW_INVALIDATE);
        _ = RedrawWindow(viewport, null, null, RDW_UPDATENOW | RDW_ALLCHILDREN);
        const position: SCROLLINFO = .{
            .cbSize = @sizeOf(SCROLLINFO),
            .fMask = SIF_POS,
            .nMin = 0,
            .nMax = 0,
            .nPage = 0,
            .nPos = clamped,
            .nTrackPos = 0,
        };
        _ = SetScrollInfo(viewport, SB_VERT, &position, 1);
        self.syncViewportClipFlags();
    }

    /// Height of one "page" of the form for Page Up/Down and page-scroll wheels.
    fn contentPage(self: *SettingsWindow) i32 {
        const viewport = self.viewport orelse return self.px(240);
        var client: RECT = undefined;
        if (GetClientRect(viewport, &client) == 0) return self.px(240);
        return @max(1, client.bottom - self.px(settings_control_height));
    }

    /// A `WM_VSCROLL` from the viewport's scroll bar.
    fn scrollByBar(self: *SettingsWindow, code: usize) void {
        const viewport = self.viewport orelse return;
        var tracking: SCROLLINFO = .{
            .cbSize = @sizeOf(SCROLLINFO),
            .fMask = SIF_TRACKPOS,
            .nMin = 0,
            .nMax = 0,
            .nPage = 0,
            .nPos = 0,
            .nTrackPos = self.content_scroll_y,
        };
        if (code == SB_THUMBPOSITION or code == SB_THUMBTRACK) _ = GetScrollInfo(viewport, SB_VERT, &tracking);
        const page = self.contentPage();
        self.setContentScroll(switch (code) {
            SB_LINEUP => self.content_scroll_y - self.px(32),
            SB_LINEDOWN => self.content_scroll_y + self.px(32),
            SB_PAGEUP => self.content_scroll_y - page,
            SB_PAGEDOWN => self.content_scroll_y + page,
            SB_THUMBPOSITION, SB_THUMBTRACK => tracking.nTrackPos,
            SB_TOP => 0,
            SB_BOTTOM => self.content_scroll_max,
            else => self.content_scroll_y,
        });
    }

    /// Tell each field's UIA provider whether the viewport hides it entirely;
    /// a field cut by an edge is still on screen.
    fn syncViewportClipFlags(self: *SettingsWindow) void {
        const viewport = self.viewport orelse return;
        var client: RECT = undefined;
        if (GetClientRect(viewport, &client) == 0) return;
        const active = self.activeFormRows();
        for (0..settings_clipped_control_count) |index| if (self.control_uia_providers[index]) |provider| {
            provider.setViewportFullyClipped(!active.controls[index] or
                viewportHidesChild(viewport, self.controlHwnd(index), client.bottom));
        };
        for (self.reset_uia_providers, self.reset_buttons, 0..) |slot, button, index| if (slot) |provider| {
            provider.setViewportFullyClipped(!active.controls[index] or viewportHidesChild(viewport, button, client.bottom));
        };
        if (self.text_uia_providers[text_help_index]) |provider| {
            provider.setViewportFullyClipped(!self.help_shown or viewportHidesChild(viewport, self.text_help, client.bottom));
        }
        for (self.field_labels, 0..) |label, index| if (self.text_uia_providers[text_first_label_index + index]) |provider| {
            provider.setViewportFullyClipped(!active.labels[index] or viewportHidesChild(viewport, label, client.bottom));
        };
    }

    /// Scroll the form by one wheel message. Notches and precision-touchpad
    /// deltas (a fraction of a notch each) take the same path: the movement is
    /// accumulated until it is a whole pixel, scaled by the user's "lines per
    /// notch" setting, so nothing is truncated to zero.
    fn scrollByWheel(self: *SettingsWindow, delta: i16) void {
        const lines = self.wheel_lines_override orelse systemWheelScrollLines();
        const notch_px: i32 = if (lines == WHEEL_PAGESCROLL)
            self.contentPage()
        else
            wheelNotchPixels(self.px(settings_wheel_notch_px), lines);
        const pixels = wheelScrollPixels(&self.wheel_remainder, delta, notch_px);
        if (pixels != 0) self.setContentScroll(self.content_scroll_y - pixels);
    }

    /// Enter on a focused push button presses it. A window class that is not
    /// a dialog has no default button for the dialog manager to ask about
    /// (`DM_GETDEFID`), so Enter would do nothing at all; answering it with the
    /// focused button instead would leave the manager stripping the default
    /// style from the previous answer. So the key is taken before the manager
    /// and the button is clicked directly. Returns whether the key was consumed;
    /// an auto-repeat is consumed without clicking again.
    fn pressFocusedButton(self: *SettingsWindow, repeat: bool) bool {
        const hwnd = self.hwnd orelse return false;
        const focused = GetFocus() orelse return false;
        if (IsChild(hwnd, focused) == 0 or sys.IsWindowEnabled(focused) == 0) return false;
        const code = SendMessageW(focused, WM_GETDLGCODE, 0, 0);
        if ((code & (DLGC_DEFPUSHBUTTON | DLGC_UNDEFPUSHBUTTON)) == 0) return false;
        if (!repeat) _ = SendMessageW(focused, BM_CLICK, 0, 0);
        return true;
    }

    /// A close request from the caption, Alt+F4 or Escape: close at once when
    /// clean, otherwise ask what to do with the unsaved changes.
    fn requestClose(self: *SettingsWindow, hwnd: HWND) void {
        // What a profile field holds counts as an edit, as when it loses the
        // focus. A value Settings refuses keeps the window open, with the
        // field and its reason, as it stops a save: Escape puts it back.
        if (self.profile_edit != null and !self.commitProfileEdit(.blur)) {
            if (self.profile_edit) |edit| if (edit.hwnd) |field| {
                _ = SetFocus(field);
            };
            return;
        }
        switch (closeRequestAction(self.hasPendingChanges(), self.close_prompt_visible, self.close_posted)) {
            .close_now => self.closeNow(hwnd),
            .show_prompt, .focus_prompt => self.showClosePrompt(),
            .ignore => {},
        }
    }

    /// Escape arrives as IDCANCEL. With the close prompt open it is the
    /// prompt's "Keep editing"; otherwise it is a close request.
    fn cancelRequested(self: *SettingsWindow, hwnd: HWND) void {
        if (self.close_prompt_visible) return self.cancelClosePrompt();
        self.requestClose(hwnd);
    }

    /// Whether `control` can take keyboard focus back: still a live, visible,
    /// enabled descendant of this window.
    fn focusTargetUsable(self: *const SettingsWindow, control: HWND) bool {
        const settings_hwnd = self.hwnd orelse return false;
        return control != settings_hwnd and
            sys.IsWindow(control) != 0 and
            IsChild(settings_hwnd, control) != 0 and
            sys.IsWindowVisible(control) != 0 and
            sys.IsWindowEnabled(control) != 0;
    }

    /// `WA_INACTIVE`: keep the focused child, the way `DefDlgProc` does.
    fn rememberFocus(self: *SettingsWindow) void {
        self.focus_before_deactivate = if (GetFocus()) |focused|
            (if (self.focusTargetUsable(focused)) focused else null)
        else
            null;
    }

    /// The frame itself received focus (`DefWindowProc` puts it there when the
    /// window is activated or restored from minimized): hand it to the child
    /// that had it, or to the section rail when that is gone. Done from
    /// `WM_SETFOCUS` rather than `WM_ACTIVATE` because restoring a minimized
    /// window sets frame focus without a second `WM_ACTIVATE`. Focusing the
    /// child must not scroll the form: after a click-activation the click has
    /// already been hit-tested against the controls where they are.
    fn forwardFrameFocus(self: *SettingsWindow) void {
        self.restoring_focus = true;
        defer self.restoring_focus = false;
        if (self.focus_before_deactivate) |control| {
            if (self.focusTargetUsable(control)) {
                _ = SetFocus(control);
                return;
            }
            self.focus_before_deactivate = null;
        }
        if (self.sectionButton(self.active_section)) |button| _ = SetFocus(button);
    }

    /// The header's title and line, and the help text. While a search is
    /// typed the line says what it found (`searchSummaryText`).
    fn refreshNativeSectionText(self: *SettingsWindow) void {
        setWindowTextUtf8(self.text_header, self.active_section.headerText());
        var summary_buf: [96]u8 = undefined;
        setWindowTextUtf8(self.text_summary, self.summaryText(&summary_buf));
        var help_buf: [help_text_bytes]u8 = undefined;
        setWindowTextUtf8(self.text_help, self.helpText(&help_buf));
    }

    fn summaryText(self: *const SettingsWindow, buf: []u8) []const u8 {
        if (!self.search_query.active()) return self.active_section.placeholderText();
        return searchSummaryText(buf, &self.search_counts, self.search_total, self.active_section);
    }

    /// Whether the page shows its help text: Keybindings and Advanced do, and
    /// so does a page with no row the search found, where it says so.
    fn showsHelp(self: *const SettingsWindow) bool {
        if (self.search_query.active() and !self.pageFoundRows()) return true;
        // Keybindings' help is about the page as a whole: a search that
        // found its row or bindings shows those alone.
        if (self.active_section == .keybindings) return !self.search_query.active();
        return self.active_section == .advanced;
    }

    /// A static text holds 2047 UTF-16 units, so the page is built in as many
    /// bytes.
    const help_text_bytes = 2047;
    /// The longest status line kept across the close prompt: the longest
    /// sentence names keys a later config layer overrides, which can be long.
    const status_line_capacity = 2048;

    /// The text above the form: Keybindings and Advanced have one, and a page
    /// the search found nothing on says what to do instead.
    fn helpText(self: *const SettingsWindow, buf: *[help_text_bytes]u8) []const u8 {
        if (self.search_query.active() and !self.pageFoundRows())
            return searchEmptyText(buf, &self.search_query, &self.search_counts, self.search_total);
        return switch (self.active_section) {
            .keybindings => keybindingsHelpText(),
            .advanced => self.advancedHelpText(buf),
            else => "",
        };
    }

    /// The app loaded the config again, so what the Advanced page lists as
    /// wrong with it may have changed.
    pub fn configProblemsChanged(self: *SettingsWindow) void {
        if (self.hwnd == null) return;
        self.refreshNativeSectionText();
        if (self.active_section == .advanced) layoutChildren(self);
    }

    /// The Advanced page: the file a save writes, what is wrong with the config
    /// as loaded, and the changes waiting to be saved. The first two are cut to
    /// their share of the room (whole entries, `config_problems`); what is
    /// left goes to the changes.
    fn advancedHelpText(self: *const SettingsWindow, buf: []u8) []const u8 {
        const head = buf[0..@min(buf.len, advanced_head_bytes)];
        var len: usize = 0;
        if (self.handle.saveTarget) |lend| {
            var path_buf: [advanced_target_bytes]u8 = undefined;
            if (lend(self.handle.ctx, &path_buf)) |path| {
                config_problems.appendWhole(head, &len, "Settings saves to ");
                config_problems.appendWhole(head, &len, path);
                config_problems.appendWhole(head, &len, "\n\n");
            }
        }
        if (self.handle.configProblems) |lend| {
            var problems_buf: [advanced_problems_bytes]u8 = undefined;
            config_problems.appendWhole(head, &len, lend(self.handle.ctx, &problems_buf));
            config_problems.appendWhole(head, &len, "\n");
        }
        const changes = self.pendingDiffText(buf[len..]);
        // Short answers are literals, longer ones were written into `buf`.
        if (changes.ptr != buf[len..].ptr) config_problems.appendWhole(buf, &len, changes) else len += changes.len;
        return buf[0..len];
    }

    fn setStatus(self: *SettingsWindow, text: []const u8) void {
        const status = self.text_status orelse return;
        self.rememberStatusLine(text);
        // The prompt's question holds the window; the line comes back with
        // everything that changed meanwhile when the prompt goes.
        if (self.close_prompt_visible) return;
        if (!setWindowTextUtf8IfChanged(status, text)) return;
        self.status_measure_width = -1;
        if (self.statusAnnounces()) self.announceText(text_status_index);
        // A message too long for the room beside the buttons gets a row of its
        // own, and a shorter one gives it back. The form loses or gains that much
        // height, so the field being typed in is kept in view.
        if (self.statusRowChanged()) {
            layoutChildren(self);
            if (GetFocus()) |focused| self.ensureControlVisible(focused);
        }
    }

    fn rememberStatusLine(self: *SettingsWindow, text: []const u8) void {
        var len = @min(text.len, self.status_line.len);
        // Never cut a UTF-8 sequence in two.
        while (len < text.len and len > 0 and (text[len] & 0xC0) == 0x80) len -= 1;
        @memcpy(self.status_line[0..len], text[0..len]);
        self.status_line_len = len;
    }

    /// Put the status line back in its window after the close prompt, in its
    /// own font.
    fn restoreStatusLine(self: *SettingsWindow) void {
        const status = self.text_status orelse return;
        self.syncStatusFont();
        setWindowTextUtf8(status, self.status_line[0..self.status_line_len]);
        self.status_measure_width = -1;
    }

    /// Whether the line now says something a screen reader should speak: an
    /// error, a conflict or the outcome of a save. The hint of what an edit
    /// does ("Applies when you save.") and the idle line change with nearly
    /// every edit and are read on request.
    fn statusAnnounces(self: *const SettingsWindow) bool {
        return switch (self.nextStatus()) {
            .none => switch (self.status_note) {
                .none, .previews_live, .applies_on_save, .profile_hint => false,
                else => true,
            },
            else => true,
        };
    }

    fn statusRowChanged(self: *SettingsWindow) bool {
        const hwnd = self.hwnd orelse return false;
        var rect: RECT = undefined;
        if (GetClientRect(hwnd, &rect) == 0) return false;
        const bar = closePromptLayoutGeometry(self, actionColumnWidth(self, rect), actionBarAvailableHeight(self, rect));
        return bar.status_separate != self.status_row_separate or bar.status_height != self.status_row_height;
    }

    /// Build the fonts for the current DPI and give them to every child: a DPI
    /// or theme change. A child `open` creates gets its font as it is made.
    fn recreateUiFont(self: *SettingsWindow) void {
        const replaced = self.buildUiFonts() orelse return;
        self.applyUiFonts();
        replaced.delete();
    }

    const UiFonts = struct {
        handles: [4]HGDIOBJ,

        fn delete(self: UiFonts) void {
            for (self.handles) |font| if (font) |handle| {
                _ = DeleteObject(handle);
            };
        }
    };

    /// The window's four fonts for `self.dpi`, and the line height the text
    /// fields centre on. Returns the fonts they replace, for the caller to
    /// delete once no child draws with them; null when a font could not be
    /// made, leaving the old ones in place.
    fn buildUiFonts(self: *SettingsWindow) ?UiFonts {
        const hwnd = self.hwnd orelse return null;
        const variable_face = std.unicode.utf8ToUtf16LeStringLiteral("Segoe UI Variable Text");
        const fallback_face = std.unicode.utf8ToUtf16LeStringLiteral("Segoe UI");
        const face = if (fontFaceAvailable(hwnd, variable_face)) variable_face else fallback_face;
        const next = createSettingsFont(self.dpi, 13, 400, face) orelse return null;
        const next_secondary = createSettingsFont(self.dpi, 12, 400, face) orelse {
            _ = DeleteObject(next);
            return null;
        };
        const next_emphasis = createSettingsFont(self.dpi, 13, 600, face) orelse {
            _ = DeleteObject(next_secondary);
            _ = DeleteObject(next);
            return null;
        };
        const next_header = createSettingsFont(self.dpi, 16, 600, face) orelse {
            _ = DeleteObject(next_emphasis);
            _ = DeleteObject(next_secondary);
            _ = DeleteObject(next);
            return null;
        };
        const replaced: UiFonts = .{ .handles = .{ self.ui_font, self.secondary_font, self.emphasis_font, self.header_font } };
        self.ui_font_dpi = self.dpi;
        self.ui_font = next;
        self.secondary_font = next_secondary;
        self.emphasis_font = next_emphasis;
        self.header_font = next_header;
        self.close_prompt_measure_width = -1;
        self.close_prompt_measure_height = 0;
        self.status_measure_width = -1;
        self.field_text_height = fontLineHeight(hwnd, next);
        self.font_builds +%= 1;
        return replaced;
    }

    fn applyUiFonts(self: *SettingsWindow) void {
        const hwnd = self.hwnd orelse return;
        _ = EnumChildWindows(hwnd, applyChildFont, @bitCast(@intFromPtr(self.ui_font)));
        if (self.text_header) |header| _ = SendMessageW(header, WM_SETFONT, @intFromPtr(self.header_font), 1);
        if (self.text_summary) |text| _ = SendMessageW(text, WM_SETFONT, @intFromPtr(self.secondary_font), 1);
        for (self.field_labels) |label| {
            if (label) |control| _ = SendMessageW(control, WM_SETFONT, @intFromPtr(self.secondary_font), 1);
        }
        for (0..settings_clipped_control_count) |index| if (controlIndexIsCheckbox(index)) {
            if (self.controlHwnd(index)) |control| _ = SendMessageW(control, WM_SETFONT, @intFromPtr(self.secondary_font), 1);
        };
        self.syncStatusFont();
        self.refreshFieldFrames();
        self.updateComboMetrics();
    }

    /// The text fields centre on the line height and their frame scales with
    /// the DPI (`settingsEditProc`): ask each one for its frame again.
    fn refreshFieldFrames(self: *SettingsWindow) void {
        for (self.editControls()) |edit| if (edit) |control| {
            _ = SetWindowPos(control, null, 0, 0, 0, 0, SWP_FRAMECHANGED | SWP_NOMOVE | SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE);
        };
    }

    /// What a child made during `open` needs before it is first drawn: its
    /// theme and its font, once each, and a dropdown's list item height after
    /// its font. A theme or DPI change later re-applies all of them to every
    /// window (`themeChanged`, `recreateUiFont`).
    fn finishChild(self: *SettingsWindow, child: ?HWND, font: HGDIOBJ, kind: enum { control, combo }) ?HWND {
        const control = child orelse return null;
        const colors = self.theme_adapter.colors;
        switch (kind) {
            .control => applyNativeControlTheme(control, colors),
            .combo => win32_theme.WindowThemeAdapter.applyNativeCombo(control, colors),
        }
        if (font) |value| _ = SendMessageW(control, WM_SETFONT, @intFromPtr(value), 0);
        if (kind == .combo) _ = SendMessageW(control, CB_SETITEMHEIGHT, 0, self.px(settings_combo_item_height));
        return control;
    }

    fn statusFont(self: *const SettingsWindow) HGDIOBJ {
        // The close prompt's question, in the window it shares with the line.
        if (self.close_prompt_visible) return self.emphasis_font;
        return switch (self.nextStatus()) {
            .conflict, .owned_conflict => self.emphasis_font,
            .raw_validation, .owned_validation, .none => self.secondary_font,
        };
    }

    fn syncStatusFont(self: *SettingsWindow) void {
        const status = self.text_status orelse return;
        if (self.statusFont()) |value| {
            const current: LRESULT = @bitCast(@intFromPtr(value));
            if (SendMessageW(status, WM_GETFONT, 0, 0) != current) {
                _ = SendMessageW(status, WM_SETFONT, @intFromPtr(value), 1);
                self.status_measure_width = -1;
            }
        }
    }

    fn controlsForRole(self: *const SettingsWindow, comptime role: SettingsControlRole) [controlCountForRole(role)]?HWND {
        var result: [controlCountForRole(role)]?HWND = undefined;
        var index: usize = 0;
        inline for (settings_control_specs, 0..) |spec, i| if (spec.role == role) {
            result[index] = self.controlHwnd(i);
            index += 1;
        };
        return result;
    }

    fn comboControls(self: *const SettingsWindow) [controlCountForRole(.combo_box)]?HWND {
        return self.controlsForRole(.combo_box);
    }

    fn editControls(self: *const SettingsWindow) [controlCountForRole(.edit)]?HWND {
        return self.controlsForRole(.edit);
    }

    fn isEditControl(self: *const SettingsWindow, hwnd: HWND) bool {
        for (self.editControls()) |edit| if (edit == hwnd) return true;
        return false;
    }

    /// Width of a text field's frame: the focus stroke, which the resting
    /// 1 DIP line sits inside, so focus does not move the text.
    fn fieldStroke(self: *const SettingsWindow) i32 {
        return @max(1, self.px(settings_metrics.stroke_focus));
    }

    /// Paint `edit`'s frame (see `settingsEditProc`). `focused` overrides
    /// `GetFocus` while focus is changing hands.
    fn paintFieldFrame(self: *SettingsWindow, edit: HWND, focused: ?bool) void {
        var window: RECT = undefined;
        var client: RECT = undefined;
        var client_origin: POINT = .{ .x = 0, .y = 0 };
        if (GetWindowRect(edit, &window) == 0 or
            GetClientRect(edit, &client) == 0 or
            sys.ClientToScreen(edit, &client_origin) == 0) return;
        const hdc = GetWindowDC(edit) orelse return;
        defer _ = ReleaseDC(edit, hdc);
        const left = client_origin.x - window.left;
        const top = client_origin.y - window.top;
        _ = ExcludeClipRect(hdc, left, top, left + client.right, top + client.bottom);

        const colors = self.theme_adapter.colors;
        const enabled = sys.IsWindowEnabled(edit) != 0;
        const state = fieldFrameState(focused orelse (GetFocus() == edit), enabled and self.validation_control == edit);
        const outer: RECT = .{ .left = 0, .top = 0, .right = window.right - window.left, .bottom = window.bottom - window.top };
        // A disabled EDIT asks for WM_CTLCOLORSTATIC and draws on the pane colour.
        fillSolid(hdc, outer, if (enabled) colors.edit_bg else colors.window_bg);
        const stroke: struct { color: COLORREF, width: i32 } = switch (state) {
            .rest => .{
                .color = if (enabled) colors.field_border else colors.disabled_text,
                .width = @max(1, self.px(settings_metrics.stroke_hairline)),
            },
            .focused => .{ .color = colors.accent, .width = self.fieldStroke() },
            .invalid => .{ .color = colors.error_text, .width = self.fieldStroke() },
        };
        strokeRect(hdc, outer, stroke.color, stroke.width);
    }

    /// Repaint the frames of the field that stops being invalid and of the
    /// one that starts (`fieldFrameState`).
    fn syncFieldFrames(self: *SettingsWindow) void {
        const next = self.validation_control;
        if (next == self.framed_invalid_field) return;
        const previous = self.framed_invalid_field;
        self.framed_invalid_field = next;
        for ([_]?HWND{ previous, next }) |field| if (field) |control| {
            if (self.isEditControl(control)) self.paintFieldFrame(control, null);
        };
    }

    fn updateComboMetrics(self: *SettingsWindow) void {
        const item_height: LPARAM = self.px(settings_combo_item_height);
        for (self.comboControls()) |combo| if (combo) |control| {
            win32_theme.WindowThemeAdapter.applyNativeCombo(control, self.theme_adapter.colors);
            _ = SendMessageW(control, CB_SETITEMHEIGHT, 0, item_height);
        };
        self.fitComboFields();
    }

    /// Make each closed dropdown exactly as tall as a text field. A dropdown
    /// that is resized, as every layout does (its height is that of the open
    /// list), puts its selection field back to the font's height, so the
    /// height set before the layout was lost: 35 px against 48 px text fields
    /// at 150%. This runs after the layout. The height asked for is the
    /// selection field's; the window adds a frame, which is measured.
    fn fitComboFields(self: *SettingsWindow) void {
        const target = self.px(settings_control_height);
        for (self.comboControls()) |combo| if (combo) |control| {
            var rect: RECT = undefined;
            if (GetWindowRect(control, &rect) == 0) continue;
            const current = SendMessageW(control, CB_GETITEMHEIGHT, std.math.maxInt(WPARAM), 0);
            if (current <= 0) continue;
            const next = comboSelectionHeight(rect.bottom - rect.top, @intCast(current), target);
            if (next != current) _ = SendMessageW(control, CB_SETITEMHEIGHT, std.math.maxInt(WPARAM), next);
        };
    }

    /// Feed an input message bound for this window or one of its children
    /// to the focus-cue tracker. The App pump calls this BEFORE
    /// `IsDialogMessageW`, because the dialog manager consumes Tab and the
    /// arrow keys itself and never dispatches them to the control that
    /// gains focus: a subclass on the rail buttons would see the click that
    /// focused one but never the key that did.
    pub fn noteInputMessage(self: *SettingsWindow, target: ?HWND, msg: UINT, wParam: WPARAM) void {
        const hwnd = self.hwnd orelse return;
        const control = target orelse return;
        if (control != hwnd and IsChild(hwnd, control) == 0) return;
        noteSettingsInput(self, msg, wParam);
    }

    /// Re-theme the window when something it was themed from has changed.
    /// WM_SETTINGCHANGE, WM_SYSCOLORCHANGE and WM_THEMECHANGED also arrive for
    /// settings that have nothing to do with it (Environment, taskbar, input),
    /// and every App-level theme rebuild calls this too, so the callers cannot
    /// tell. Doing the work anyway costs 80-200 ms of UI thread and blanks
    /// every control, which is why the work is keyed on what it reads: the
    /// resolved colors (High Contrast state included) and the DPI the fonts
    /// were built for. Do not filter by the broadcast's lParam instead; system
    /// font and High Contrast changes arrive under several names.
    pub fn themeChanged(self: *SettingsWindow) void {
        const hwnd = self.hwnd orelse return;
        // SetWindowTheme synchronously sends WM_THEMECHANGED while the adapter
        // is still applying. Its caller already follows that work with fonts
        // and layout; reentering here creates both a second time on each open,
        // before the initial font can satisfy themeInputsApplied.
        if (self.theme_adapter.applying) return;
        const colors = self.resolveThemeColors();
        if (self.themeInputsApplied(colors)) return;
        self.theme_applications +%= 1;
        self.theme_adapter.apply(hwnd, colors, .window);
        self.recreateUiFont();
        layoutChildren(self);
        _ = sys.InvalidateRect(hwnd, null, 1);
    }

    fn themeInputsApplied(self: *const SettingsWindow, colors: win32_theme.SettingsColors) bool {
        // `apply` creates the four brushes independently, so a shortage of GDI
        // objects can leave some of them null; any missing one retries.
        return self.theme_adapter.window_brush != null and
            self.theme_adapter.rail_brush != null and
            self.theme_adapter.edit_brush != null and
            self.theme_adapter.button_brush != null and
            self.ui_font != null and
            self.ui_font_dpi == self.dpi and
            std.meta.eql(self.theme_adapter.colors, colors);
    }

    fn resolveThemeColors(self: *const SettingsWindow) win32_theme.SettingsColors {
        var theme = if (self.handle.themeColors) |resolve|
            resolve(self.handle.ctx)
        else
            win32_theme.lightTheme();
        if (self.handle.themeColors == null) {
            theme.chrome_bg = self.handle.chromeBg(self.handle.ctx);
            theme.text_primary = self.handle.textPrimary(self.handle.ctx);
        }
        const high_contrast = if (self.handle.highContrast) |probe|
            probe(self.handle.ctx)
        else
            false;
        return win32_theme.settingsColors(
            theme,
            .{
                .window = GetSysColor(COLOR_WINDOW),
                .window_text = GetSysColor(COLOR_WINDOWTEXT),
                .button_face = GetSysColor(COLOR_BTNFACE),
                .button_text = GetSysColor(COLOR_BTNTEXT),
                .gray_text = GetSysColor(COLOR_GRAYTEXT),
                .highlight = GetSysColor(COLOR_HIGHLIGHT),
                .highlight_text = GetSysColor(COLOR_HIGHLIGHTTEXT),
            },
            high_contrast,
        );
    }

    fn ensureControlVisible(self: *SettingsWindow, control: HWND) void {
        // The Keybindings page's list scrolls with the page's rows when the
        // page is too short for it.
        var is_form_control = (self.keybind_list.hwnd != null and control == self.keybind_list.hwnd.?) or
            self.companions[@intFromEnum(Companion.opacity_slider)] == control;
        for (self.formItems()) |item| {
            const reset = if (item.control_index < form_field_count) self.reset_buttons[item.control_index] else null;
            if (self.controlHwnd(item.control_index) == control or reset == control) {
                is_form_control = true;
                break;
            }
        }
        if (!is_form_control) return;
        const viewport = self.viewport orelse return;
        var child_rect: RECT = undefined;
        var client_rect: RECT = undefined;
        if (sys.GetWindowRect(control, &child_rect) == 0 or
            sys.GetClientRect(viewport, &client_rect) == 0) return;
        var child_origin: POINT = .{ .x = child_rect.left, .y = child_rect.top };
        if (sys.ScreenToClient(viewport, &child_origin) == 0) return;
        const top = child_origin.y;
        const bottom = top + child_rect.bottom - child_rect.top;
        if (top < 0) {
            self.setContentScroll(self.content_scroll_y + top);
        } else if (bottom > client_rect.bottom) {
            // Its bottom into view, but never its top out of it (a list taller
            // than the viewport).
            self.setContentScroll(self.content_scroll_y + @min(bottom - client_rect.bottom, top));
        }
    }

    /// Show the active section's fields and labels and hide the rest. A
    /// window already in the wanted state is left alone, so it does not
    /// repaint.
    fn applySectionVisibility(self: *SettingsWindow) void {
        for (std.enums.values(Section)) |section| {
            if (self.sectionButton(section)) |button| {
                const check: usize = if (section == self.active_section) BST_CHECKED else BST_UNCHECKED;
                if (@as(usize, @bitCast(sys.SendMessageW(button, BM_GETCHECK, 0, 0))) != check) {
                    _ = sys.SendMessageW(button, BM_SETCHECK, check, 0);
                }
                const style: u32 = @truncate(@as(usize, @bitCast(sys.GetWindowLongPtrW(button, GWL_STYLE))));
                const next_style = if (section == self.active_section) style | WS_TABSTOP else style & ~WS_TABSTOP;
                if (next_style != style) _ = sys.SetWindowLongPtrW(button, GWL_STYLE, @intCast(next_style));
            }
        }
        const active = self.activeFormRows();
        for (0..settings_clipped_control_count) |index| if (self.controlHwnd(index)) |control| {
            setChildShown(control, active.controls[index]);
        };
        for (self.field_labels, 0..) |label, index| if (label) |control| {
            setChildShown(control, active.labels[index]);
        };
        for (self.reset_buttons, 0..) |button, index| if (button) |control| {
            setChildShown(control, active.controls[index] and self.differs_from_default[index]);
        };
        inline for (comptime std.enums.values(Companion)) |kind| if (self.companions[@intFromEnum(kind)]) |control| {
            setChildShown(control, active.controls[comptime kind.controlIndex()]);
        };
        if (self.reference_list.hwnd) |list| setChildShown(list, self.referenceListShows());
        if (self.keybind_list.hwnd) |list| setChildShown(list, self.keybindListShows());
        if (self.profile_list.hwnd) |list| setChildShown(list, self.profileListShows());
    }

    /// Whether the All settings list is on screen: its page is shown, and a
    /// search found keys there (with none, the help text says so instead).
    fn referenceListShows(self: *const SettingsWindow) bool {
        return self.active_section == .reference and !(self.search_query.active() and self.reference_list.shown_count == 0);
    }

    /// Whether the Keybindings page's list is on screen: as the All settings
    /// list, for bindings.
    fn keybindListShows(self: *const SettingsWindow) bool {
        return self.active_section == .keybindings and !(self.search_query.active() and self.keybind_list.shown_count == 0);
    }

    /// Whether the Profiles page's list is on screen: as the All settings
    /// list, for profiles.
    fn profileListShows(self: *const SettingsWindow) bool {
        return self.active_section == .profiles and !(self.search_query.active() and self.profile_list.shown_count == 0);
    }

    /// Parse a number field's text (scrollback, font size, opacity) into the
    /// draft. Called from EN_CHANGE. Text that does not parse keeps the field
    /// raw (`markRawScalarEdit`) and records its message; the draft keeps the
    /// last valid value.
    fn syncNumberFromEdit(self: *SettingsWindow, comptime field: RawScalarField) void {
        const setting = comptime field.setting();
        const label = comptime field_model.descriptor(setting).label;
        if (self.suppress_edit_events) return;
        const p = &(self.pending orelse return);
        const edit = self.rawScalarEdit(field) orelse return;
        self.markRawScalarEdit(field);
        // All of what the field holds (up to its limit, which a value set
        // through UIA is cut to as well): a prefix that parsed would let a
        // field showing text that does not parse save a value it does not show.
        var utf8_buf: [edit_text_max_utf8]u8 = undefined;
        const utf8 = readEditUtf8(edit, &utf8_buf) orelse
            return self.setRawScalarValidationError(field, edit, label ++ " contains invalid text.");
        if (utf8.len == 0) return self.setRawScalarValidationError(field, edit, label ++ " is required.");
        const trimmed = std.mem.trim(u8, utf8, " \t");
        if (trimmed.len == 0) return self.setRawScalarValidationError(field, edit, label ++ " is required.");
        const parsed = field_model.parseScalar(setting, trimmed) catch |err|
            return self.setRawScalarValidationError(field, edit, switch (comptime field_model.descriptor(setting).validation) {
                .unsigned_integer => label ++ " must be a non-negative whole number.",
                else => field_model.scalarValidationMessage(setting, err == error.OutOfRange),
            });
        self.finishRawScalarEdit(field);
        setSettingValue(p, @unionInit(SettingValue, @tagName(setting), parsed));
        self.trackFieldEdit(setting);
        self.syncCompanion(field);
    }

    fn displayNumberInEdit(self: *SettingsWindow, comptime field: RawScalarField) void {
        if (!self.shouldRefreshRawScalar(field)) return;
        const edit = self.rawScalarEdit(field) orelse return;
        const p = self.pending orelse return;
        var buf: [32]u8 = undefined;
        const text = std.fmt.bufPrintZ(&buf, "{d}", .{fieldValue(&p, field.setting())}) catch return;
        setEditText(edit, text, &self.suppress_edit_events);
        self.syncCompanion(field);
    }

    /// Make `kind`'s window in the form, themed, its range set; hidden or
    /// shown as its section (`shown`). Each starts a group of its own: the
    /// arrow keys step a trackbar and are its own, and an up-down is no tab
    /// stop and takes no focus, so no arrow-key run may land on one (the row
    /// after an up-down has a label, which starts the next group). The
    /// trackbar comes before its field in z-order, as it sits left of it; an
    /// up-down after its field and the field's Reset button.
    fn makeCompanion(self: *SettingsWindow, form: HWND, comptime kind: Companion, shown: u32) void {
        // The classes, in whichever comctl32 the thread's activation context
        // names (version 6 in the app, through its manifest).
        _ = InitCommonControlsEx(&.{ .classes = 0x0004 | 0x0010 }); // ICC_BAR_CLASSES | ICC_UPDOWN_CLASS
        const hinstance = self.handle.hinstance;
        const window = switch (kind) {
            .opacity_slider => sys.CreateWindowExW(0, std.unicode.utf8ToUtf16LeStringLiteral("msctls_trackbar32"), std.unicode.utf8ToUtf16LeStringLiteral(""), WS_CHILD | WS_GROUP | WS_TABSTOP | TBS_NOTICKS | TBS_FIXEDLENGTH | shown, 0, 0, 1, 1, form, null, hinstance, null),
            else => sys.CreateWindowExW(0, std.unicode.utf8ToUtf16LeStringLiteral("msctls_updown32"), std.unicode.utf8ToUtf16LeStringLiteral(""), WS_CHILD | WS_GROUP | UDS_ARROWKEYS | UDS_HOTTRACK | UDS_NOTHOUSANDS | shown, 0, 0, 1, 1, form, null, hinstance, null),
        };
        const control = self.finishChild(window, null, .control) orelse return;
        self.companions[@intFromEnum(kind)] = control;
        if (kind == .opacity_slider) subclassKeepingPrevious(control, &settingsSliderProc);
        switch (kind) {
            .opacity_slider => {
                _ = SendMessageW(control, TBM_SETRANGEMIN, 0, 0);
                _ = SendMessageW(control, TBM_SETRANGEMAX, 1, 100);
                _ = SendMessageW(control, TBM_SETLINESIZE, 0, 1);
                _ = SendMessageW(control, TBM_SETPAGESIZE, 0, 10);
            },
            .font_size_spin, .scrollback_spin => {
                // Its arrows step the field (`UDS_ARROWKEYS` on the buddy).
                if (self.rawScalarEdit(kind.field())) |edit| _ = SendMessageW(control, UDM_SETBUDDY, @intFromPtr(edit), 0);
                const range = spinRange(kind);
                _ = SendMessageW(control, UDM_SETRANGE32, @bitCast(@as(isize, range.min)), range.max);
            },
        }
    }

    /// The range an up-down reports, as a screen reader reads its value: the
    /// font size's own; the scrollback limit's in bytes, to what 32 bits hold.
    fn spinRange(kind: Companion) struct { min: i32, max: i32 } {
        return switch (kind) {
            .font_size_spin => font_size: {
                const range = comptime field_model.descriptor(Companion.font_size_spin.field().setting()).validation.finite_range;
                break :font_size .{ .min = @intFromFloat(range.min), .max = @intFromFloat(range.max) };
            },
            else => .{ .min = 0, .max = std.math.maxInt(i32) },
        };
    }

    /// Put `field`'s companion where the draft's value is: the trackbar at
    /// its percentage, an up-down at the value (rounded, and held to its
    /// range). Setting either sends nothing back.
    fn syncCompanion(self: *SettingsWindow, comptime field: RawScalarField) void {
        const kind = comptime Companion.of(field) orelse return;
        const control = self.companions[@intFromEnum(kind)] orelse return;
        const p = self.pending orelse return;
        const value = numberAsF64(fieldValue(&p, field.setting()));
        switch (kind) {
            .opacity_slider => _ = SendMessageW(control, TBM_SETPOS, 1, @bitCast(@as(isize, sliderPosition(value)))),
            else => {
                const range = spinRange(kind);
                const position: i32 = @intFromFloat(std.math.clamp(@round(value), @as(f64, @floatFromInt(range.min)), @as(f64, @floatFromInt(range.max))));
                _ = SendMessageW(control, UDM_SETPOS32, 0, @bitCast(@as(isize, position)));
            },
        }
    }

    fn sliderPosition(opacity: f64) i32 {
        return @intFromFloat(std.math.clamp(@round(opacity * 100), 0, 100));
    }

    /// The field's value as its text now parses, if it does.
    fn typedValue(self: *const SettingsWindow, comptime field: RawScalarField) ?f64 {
        const edit = self.rawScalarEdit(field) orelse return null;
        var utf8_buf: [edit_text_max_utf8]u8 = undefined;
        const utf8 = readEditUtf8(edit, &utf8_buf) orelse return null;
        const parsed = field_model.parseScalar(comptime field.setting(), utf8) catch return null;
        return numberAsF64(parsed);
    }

    /// The trackbar's channel and thumb in the theme's colours: the stock
    /// channel is a light two-tone line, light in dark mode and under 1.4:1
    /// on the light pane. Each is drawn inside the rectangle the trackbar
    /// gives it, so what the trackbar hit-tests and repaints is what shows.
    /// High Contrast keeps the stock trackbar, in system colours.
    fn sliderCustomDraw(self: *SettingsWindow, draw: *const NMCUSTOMDRAW) LRESULT {
        const colors = self.theme_adapter.colors;
        if (colors.high_contrast) return CDRF_DODEFAULT;
        switch (draw.stage) {
            CDDS_PREPAINT => return CDRF_NOTIFYITEMDRAW,
            CDDS_ITEMPREPAINT => {
                const color: COLORREF = switch (draw.item) {
                    TBCD_CHANNEL => colors.slider_rail,
                    TBCD_THUMB => colors.slider_thumb,
                    else => return CDRF_DODEFAULT,
                };
                const hdc = draw.hdc orelse return CDRF_DODEFAULT;
                const rect = draw.rc;
                const brush = CreateSolidBrush(color) orelse return CDRF_DODEFAULT;
                defer _ = DeleteObject(brush);
                const previous_brush = SelectObject(hdc, brush);
                defer _ = SelectObject(hdc, previous_brush);
                const previous_pen = SelectObject(hdc, GetStockObject(NULL_PEN));
                defer _ = SelectObject(hdc, previous_pen);
                // Rounded at the narrow ends: a rail, and a pill of a thumb.
                const round = @min(rect.right - rect.left, rect.bottom - rect.top);
                // The null pen leaves the right and bottom edges out.
                _ = sys.RoundRect(hdc, rect.left, rect.top, rect.right + 1, rect.bottom + 1, round, round);
                return CDRF_SKIPDEFAULT;
            },
            else => return CDRF_DODEFAULT,
        }
    }

    /// The trackbar moved (`WM_HSCROLL`): its percentage goes into the
    /// opacity field as if typed (`EN_CHANGE` then takes it into the draft
    /// and the preview, with the preview's floor), unless the field already
    /// says that, as "0.875" at 88 does.
    fn sliderMoved(self: *SettingsWindow) void {
        const slider = self.companions[@intFromEnum(Companion.opacity_slider)] orelse return;
        const edit = self.rawScalarEdit(.background_opacity) orelse return;
        const position: i32 = @intCast(SendMessageW(slider, TBM_GETPOS, 0, 0));
        if (self.typedValue(.background_opacity)) |value| if (sliderPosition(value) == position) return;
        var buf: [16]u8 = undefined;
        const text = std.fmt.bufPrint(&buf, "{d}", .{@as(f64, @floatFromInt(position)) / 100}) catch return;
        setWindowTextUtf8(edit, text);
    }

    /// An up-down asks to step (`UDN_DELTAPOS`): its field steps from the
    /// value it now shows, or the draft's when its text does not parse, held
    /// to the field's range, and the text goes in as if typed. The up-down's
    /// own position follows from the field (`syncCompanion`), so its own
    /// change is refused. Returns the answer to the notification.
    fn spinStep(self: *SettingsWindow, comptime kind: Companion, delta: i32) LRESULT {
        const field = comptime kind.field();
        const edit = self.rawScalarEdit(field) orelse return 1;
        const p = self.pending orelse return 1;
        var buf: [32]u8 = undefined;
        const text = switch (kind) {
            .font_size_spin => text: {
                const current = self.typedValue(field) orelse numberAsF64(fieldValue(&p, field.setting()));
                const stepped = current + @as(f64, @floatFromInt(delta)) * kind.step();
                const range = comptime field_model.descriptor(field.setting()).validation.finite_range;
                break :text std.fmt.bufPrint(&buf, "{d}", .{@as(f32, @floatCast(std.math.clamp(stepped, range.min, range.max)))}) catch return 1;
            },
            // In whole bytes, held to what the limit holds: a value typed
            // near the top stays exact, and a step cannot overflow it.
            .scrollback_spin => text: {
                var utf8_buf: [edit_text_max_utf8]u8 = undefined;
                const typed = if (readEditUtf8(edit, &utf8_buf)) |utf8| field_model.parseScalar(comptime field.setting(), utf8) catch null else null;
                const current = typed orelse fieldValue(&p, field.setting());
                const step: @TypeOf(current) = @as(@TypeOf(current), @intFromFloat(kind.step())) * @abs(delta);
                break :text std.fmt.bufPrint(&buf, "{d}", .{if (delta > 0) current +| step else current -| step}) catch return 1;
            },
            .opacity_slider => return 1,
        };
        setWindowTextUtf8(edit, text);
        return 1;
    }

    /// A notification from a form child (`WM_NOTIFY` to the viewport), if it
    /// is an up-down's step or the trackbar's custom draw; null for anything
    /// else.
    fn companionNotify(self: *SettingsWindow, lParam: LPARAM) ?LRESULT {
        if (lParam == 0) return null;
        const header: *const NMHDR = @ptrFromInt(@as(usize, @bitCast(lParam)));
        const from = header.hwndFrom orelse return null;
        if (@as(i32, @bitCast(header.code)) == NM_CUSTOMDRAW) {
            if (self.companions[@intFromEnum(Companion.opacity_slider)] != from) return null;
            return self.sliderCustomDraw(@ptrFromInt(@as(usize, @bitCast(lParam))));
        }
        if (@as(i32, @bitCast(header.code)) != UDN_DELTAPOS) return null;
        const change: *const NMUPDOWN = @ptrFromInt(@as(usize, @bitCast(lParam)));
        inline for (.{ Companion.font_size_spin, Companion.scrollback_spin }) |kind| {
            if (self.companions[@intFromEnum(kind)] == from) return self.spinStep(kind, change.delta);
        }
        return null;
    }

    fn syncFontFamilyFromEdit(self: *SettingsWindow) void {
        if (self.suppress_edit_events or !self.owned_text_changed[@intFromEnum(OwnedSettingField.font_family)]) return;
        const p = &(self.pending orelse return);
        const arena = p.*._arena.?.allocator();
        const edit = self.fields.edit_font_family orelse return;
        var text_buf: [edit_text_max_utf8]u8 = undefined;
        const text = readEditUtf8(edit, &text_buf) orelse
            return self.setValidationError(edit, "Font family text could not be read.");
        p.*.@"font-family" = parseFontFamilyEditText(arena, text) catch
            return self.setValidationError(edit, "Font family list is invalid.");
        self.clearValidationError(edit);
        self.trackOwnedEdit(.font_family);
    }

    fn displayFontFamilyInEdit(self: *SettingsWindow) void {
        const edit = self.fields.edit_font_family orelse return;
        const p = self.pending orelse return;
        var buf: [edit_text_max_utf8]u8 = undefined;
        var writer: std.Io.Writer = .fixed(&buf);
        for (p.@"font-family".list.items, 0..) |family, i| {
            if (i != 0) writer.writeAll(", ") catch break;
            writer.writeAll(family) catch break;
        }
        setEditText(edit, writer.buffered(), &self.suppress_edit_events);
    }

    fn syncThemeFromEdit(self: *SettingsWindow) void {
        if (self.suppress_edit_events or !self.owned_text_changed[@intFromEnum(OwnedSettingField.theme)]) return;
        const p = &(self.pending orelse return);
        const arena = p.*._arena.?.allocator();
        const edit = self.fields.edit_theme orelse return;
        var text_buf: [edit_text_max_utf8]u8 = undefined;
        const text = readEditUtf8(edit, &text_buf) orelse return;
        const trimmed = std.mem.trim(u8, text, " \t");
        if (trimmed.len == 0) {
            p.*.theme = null;
            self.clearValidationError(edit);
            self.trackOwnedEdit(.theme);
            return;
        }
        var theme: Config.Theme = undefined;
        theme.parseCLI(arena, trimmed) catch
            return self.setValidationError(edit, "Terminal theme must be a valid name, path, or light/dark pair.");
        p.*.theme = theme;
        self.clearValidationError(edit);
        self.trackOwnedEdit(.theme);
    }

    fn displayThemeInEdit(self: *SettingsWindow) void {
        const edit = self.fields.edit_theme orelse return;
        const p = self.pending orelse return;
        var buf: [edit_text_max_utf8]u8 = undefined;
        var writer: std.Io.Writer = .fixed(&buf);
        if (p.theme) |theme| {
            theme.formatValue(&writer) catch {};
        }
        setEditText(edit, writer.buffered(), &self.suppress_edit_events);
    }

    fn syncCommandFromEdit(self: *SettingsWindow) void {
        if (self.suppress_edit_events or !self.owned_text_changed[@intFromEnum(OwnedSettingField.command)]) return;
        const p = &(self.pending orelse return);
        const arena = p.*._arena.?.allocator();
        const edit = self.fields.edit_command orelse return;
        var text_buf: [edit_text_max_utf8]u8 = undefined;
        const text = readEditUtf8(edit, &text_buf) orelse return;
        const trimmed = std.mem.trim(u8, text, " \t");
        if (trimmed.len == 0) {
            p.*.command = null;
            self.clearValidationError(edit);
            self.trackOwnedEdit(.command);
            return;
        }
        var command: Config.Command = undefined;
        command.parseCLI(arena, trimmed) catch
            return self.setValidationError(edit, "Default command syntax is invalid.");
        p.*.command = command;
        self.clearValidationError(edit);
        self.trackOwnedEdit(.command);
    }

    fn displayCommandInEdit(self: *SettingsWindow) void {
        const edit = self.fields.edit_command orelse return;
        const p = self.pending orelse return;
        var buf: [edit_text_max_utf8]u8 = undefined;
        var writer: std.Io.Writer = .fixed(&buf);
        if (p.command) |command| writeCommandForEdit(&writer, command) catch {};
        setEditText(edit, writer.buffered(), &self.suppress_edit_events);
    }

    /// Fill the Default profile dropdown from the app's profiles, the saved
    /// `default-profile` and the draft's, asking the app for a list when no
    /// window has one, and select the draft's row.
    fn displayDefaultProfile(self: *SettingsWindow) void {
        self.fillDefaultProfile(true);
    }

    fn fillDefaultProfile(self: *SettingsWindow, ask_now: bool) void {
        const combo = self.fields.combo_default_profile orelse return;
        // An open list keeps the rows the user is looking at, whatever asked
        // for the refill (a discovery, a config reload); `CBN_CLOSEUP` refills
        // it once it closes.
        if (self.profileListOpen()) {
            self.profile_rows_stale = true;
            self.profile_rows_ask = self.profile_rows_ask or ask_now;
            return;
        }
        // Taken before asking: a discovery that fails on the UI thread calls
        // `profilesChanged` from inside `profileChoices`, and that refill must
        // not ask again.
        const ask = ask_now or self.profile_rows_ask;
        self.profile_rows_ask = false;
        const p = self.pending orelse return;
        const o = self.original orelse return;
        const alloc = self.handle.alloc;
        const saved: ?[]const u8 = if (o.@"default-profile") |text| text else null;
        const draft: ?[]const u8 = if (p.@"default-profile") |text| text else null;
        var choices: ProfileChoices = if (self.handle.profileChoices) |get|
            get(self.handle.ctx, alloc, saved, draft, ask) catch |err| blk: {
                std.log.warn("settings: could not list profiles err={}", .{err});
                break :blk .{};
            }
        else
            .{};
        var rows = ProfileRows.build(alloc, &choices, saved, draft) catch {
            choices.deinit(alloc);
            std.log.warn("settings: could not list profiles err=OutOfMemory", .{});
            return;
        };
        const saved_copy = if (saved) |text| alloc.dupe(u8, text) catch null else null;
        const draft_copy = if (draft) |text| alloc.dupe(u8, text) catch null else null;
        if ((saved != null and saved_copy == null) or (draft != null and draft_copy == null)) {
            if (saved_copy) |text| alloc.free(text);
            if (draft_copy) |text| alloc.free(text);
            rows.deinit(alloc);
            choices.deinit(alloc);
            std.log.warn("settings: could not keep the default profile values", .{});
            return;
        }
        self.forgetProfileRows();
        self.profile_choices = choices;
        self.profile_saved_value = saved_copy;
        self.profile_draft_value = draft_copy;
        self.profile_rows = rows;

        self.suppress_edit_events = true;
        defer self.suppress_edit_events = false;
        var before_w: [combo_text_max]u16 = undefined;
        const before = comboSelectionText(combo, &before_w);
        _ = sys.SendMessageW(combo, CB_RESETCONTENT, 0, 0);
        for (self.profile_rows.slice()) |row| {
            var text: [512]u8 = undefined;
            var text_w: [512]u16 = undefined;
            const w = utf8ToW(&text_w, profileRowText(&text, row, &self.profile_choices, saved, draft));
            _ = sys.SendMessageW(combo, CB_ADDSTRING, 0, @bitCast(@intFromPtr(w)));
        }
        const row = self.profile_rows.rowFor(&self.profile_choices, saved, draft);
        _ = sys.SendMessageW(combo, CB_SETCURSEL, row, 0);
        // A new row is announced by the provider (`syncNativeState`, on
        // `CB_SETCURSEL`), which compares indexes only. The same row with
        // other text (a relabelled profile, "(not found)" once the list is
        // complete) is announced here.
        if (before) |old| if (old.index == row) {
            var after_w: [combo_text_max]u16 = undefined;
            const same = if (comboSelectionText(combo, &after_w)) |now| std.mem.eql(u16, old.text, now.text) else false;
            if (!same) if (self.controlIndex(combo)) |index| if (self.control_uia_providers[index]) |provider| provider.valueTextChanged();
        };
    }

    /// Stage the chosen row: Automatic clears `default-profile`, a profile
    /// saves its key, and the saved value's row keeps it as written.
    fn syncDefaultProfileFromCombo(self: *SettingsWindow) void {
        if (self.suppress_edit_events) return;
        const p = &(self.pending orelse return);
        const combo = self.fields.combo_default_profile orelse return;
        const index = sys.SendMessageW(combo, CB_GETCURSEL, 0, 0);
        if (index < 0 or index >= self.profile_rows.len) return;
        const next = self.profile_rows.valueFor(&self.profile_choices, self.profile_saved_value, self.profile_draft_value, @intCast(index));
        const arena = p.*._arena.?.allocator();
        p.*.@"default-profile" = if (next) |text| arena.dupeZ(u8, text) catch {
            std.log.warn("settings: could not stage the default profile", .{});
            return;
        } else null;
        self.trackOwnedEdit(.default_profile);
    }

    /// The app's profile list changed (a discovery finished or failed):
    /// refill the Default profile dropdown from what the windows have, or,
    /// while its list is open, once it closes. Never asks for a list itself.
    pub fn profilesChanged(self: *SettingsWindow) void {
        self.fillDefaultProfile(false);
    }

    fn syncPaddingFromEdit(self: *SettingsWindow, comptime field: RawScalarField) void {
        const setting = comptime field.setting();
        if (self.suppress_edit_events) return;
        const p = &(self.pending orelse return);
        const edit = self.rawScalarEdit(field) orelse return;
        self.markRawScalarEdit(field);
        var text_buf: [64]u8 = undefined;
        const text = readEditUtf8(edit, &text_buf) orelse
            return self.setRawScalarValidationError(field, edit, comptime field_model.descriptor(setting).label ++ " could not be read.");
        const parsed = field_model.parseScalar(setting, text) catch |err|
            return self.setRawScalarValidationError(field, edit, field_model.scalarValidationMessage(setting, err == error.OutOfRange));
        self.finishRawScalarEdit(field);
        setSettingValue(p, @unionInit(SettingValue, @tagName(setting), parsed));
        self.trackFieldEdit(setting);
    }

    fn displayPaddingInEdit(self: *SettingsWindow, comptime field: RawScalarField) void {
        if (!self.shouldRefreshRawScalar(field)) return;
        const edit = self.rawScalarEdit(field) orelse return;
        const p = self.pending orelse return;
        const padding = fieldValue(&p, field.setting());
        var buf: [64]u8 = undefined;
        const text = if (padding.top_left == padding.bottom_right)
            std.fmt.bufPrint(&buf, "{d}", .{padding.top_left}) catch return
        else
            std.fmt.bufPrint(&buf, "{d},{d}", .{ padding.top_left, padding.bottom_right }) catch return;
        setEditText(edit, text, &self.suppress_edit_events);
    }

    /// A checkbox for a bool field, or for one of `app-notifications`' bool
    /// projections, which writes only its own member.
    fn syncCheckbox(self: *SettingsWindow, comptime field: SettingField) void {
        if (self.suppress_edit_events) return;
        const p = &(self.pending orelse return);
        const chk = self.fieldControl(field) orelse return;
        const checked = sys.SendMessageW(chk, BM_GETCHECK, 0, 0) == BST_CHECKED;
        setSettingValue(p, @unionInit(SettingValue, @tagName(field), checked));
        self.trackFieldEdit(field);
    }

    fn displayCheckbox(self: *SettingsWindow, comptime field: SettingField) void {
        const chk = self.fieldControl(field) orelse return;
        const p = self.pending orelse return;
        self.showChecked(chk, fieldValue(&p, field));
    }

    fn showChecked(self: *SettingsWindow, chk: HWND, checked: bool) void {
        self.suppress_edit_events = true;
        _ = sys.SendMessageW(chk, BM_SETCHECK, if (checked) BST_CHECKED else BST_UNCHECKED, 0);
        self.suppress_edit_events = false;
    }

    /// A dropdown. Its item positions are the field's `Combo` options, which
    /// map an index to the config value and back.
    fn syncCombo(self: *SettingsWindow, comptime field: SettingField) void {
        if (self.suppress_edit_events) return;
        const p = &(self.pending orelse return);
        const combo = self.fieldControl(field) orelse return;
        const idx = sys.SendMessageW(combo, CB_GETCURSEL, 0, 0);
        if (idx < 0) return;
        const value = field_model.Combo(field).fromIndex(idx) orelse return;
        setSettingValue(p, @unionInit(SettingValue, @tagName(field), value));
        self.trackFieldEdit(field);
    }

    fn displayCombo(self: *SettingsWindow, comptime field: SettingField) void {
        const combo = self.fieldControl(field) orelse return;
        const p = self.pending orelse return;
        const idx = field_model.Combo(field).toIndex(fieldValue(&p, field));
        self.suppress_edit_events = true;
        _ = sys.SendMessageW(combo, CB_SETCURSEL, idx, 0);
        self.suppress_edit_events = false;
    }

    /// background-blur is a union (false / true / { radius: u8 }). The
    /// GUI exposes only the boolean path, so keep an existing numeric
    /// radius intact while the checkbox remains enabled.
    fn syncBgBlurFromCheckbox(self: *SettingsWindow) void {
        if (self.suppress_edit_events) return;
        const p = &(self.pending orelse return);
        const chk = self.fields.chk_bg_blur orelse return;
        const state = sys.SendMessageW(chk, BM_GETCHECK, 0, 0);
        p.*.@"background-blur" = backgroundBlurFromCheckbox(
            p.*.@"background-blur",
            state == BST_CHECKED,
        );
        self.trackFieldEdit(.background_blur);
    }

    fn displayBgBlurInCheckbox(self: *SettingsWindow) void {
        const chk = self.fields.chk_bg_blur orelse return;
        const p = self.pending orelse return;
        self.showChecked(chk, p.@"background-blur".win32BlurRequested());
    }

    /// Refresh every control from the pending draft. Called after
    /// `adoptCurrentConfig` and after a successful save.
    fn refreshAllControls(self: *SettingsWindow) void {
        // Typed display adapters retain raw owned edits and never grant ownership.
        inline for (field_model.form_fields) |row| {
            @field(field_adapters, row.native.binding).display(self);
        }
        self.updateSaveEnabled();
    }

    fn save(self: *SettingsWindow) void {
        // A profile field being typed into is kept first; one Settings
        // refuses stops the save, and says why.
        if (self.profile_edit != null and !self.commitProfileEdit(.stay)) return;
        // Scalar EN_CHANGE already validates and stages every typed value.
        // Only owned text waiting for EN_KILLFOCUS needs a save-time parse.
        for (std.enums.values(OwnedSettingField)) |field| {
            if (self.owned_text_changed[@intFromEnum(field)]) self.syncOwnedControl(field);
        }
        // A close prompt's "Save and close" gets here with a field still inside
        // its quiet period.
        self.showRawScalarErrors(null);
        if (self.validation_control) |control| {
            // Save and close shows the field once its prompt has gone
            // (`surfaceNextValidation`); otherwise a field another page or the
            // search hides is shown before it takes the focus.
            if (!self.close_prompt_visible) {
                if (sys.IsWindowVisible(control) == 0) if (self.controlIndex(control)) |index| {
                    if (self.controlSection(index)) |section| self.revealControl(section, control);
                };
                _ = sys.SetFocus(control);
                self.ensureControlVisible(control);
            }
            return;
        }
        // The check may merge a changed file into this window, so it runs on
        // the window's own configs, and nothing below uses a copy made before
        // it. A conflict it finds is shown the way one that was already open is.
        if (self.conflictCount() == 0) if (self.handle.reconcileDisk) |reconcile| {
            if (self.pending) |*draft| if (self.original) |*baseline| reconcile(self.handle.ctx, draft, baseline) catch |err| {
                std.log.warn("settings: could not check the config file before saving err={}; draft preserved", .{err});
                self.setSaveFailureNote(err);
                self.updateSaveEnabled();
                return;
            };
            self.refreshProfileChanges();
        };
        if (self.conflictCount() != 0) {
            self.surfaceNextValidation(false);
            return;
        }
        const p = self.pending orelse return;
        const o = self.original orelse return;

        var apply_id: ?ApplyId = null;
        if (self.transaction) |*transaction| {
            var effects: [setting_field_count + 1]SettingsTransaction.Effect = undefined;
            const emitted = transaction.dispatch(.apply, &effects) catch |err| {
                std.log.warn("settings: save transaction rejected err={}; draft preserved", .{err});
                self.setNote(.resolve_first);
                return;
            };
            for (emitted) |effect| switch (effect) {
                .apply_requested => |request| apply_id = request.apply_id,
                .set_preview, .conflict_detected, .persist_field => {},
            };
        }

        switch (saveReloadOutcome(self.handle.saveAndReload(self.handle.ctx, &p, &o))) {
            .completed => self.completeSynchronousSave(apply_id, false),
            .completed_masked => {
                // Persisted bytes are correct but a later config
                // layer is masking one or more edits. Same baseline
                // refresh as success since the file IS written.
                // The toast copy tells the user the bytes made it
                // to disk but the effective value differs.
                self.completeSynchronousSave(apply_id, true);
            },
            .failed => |err| {
                // Write failed. DO NOT discard `pending` — the user's
                // edits are still in memory; losing them on every
                // transient disk error (permission denied, sharing
                // violation when another editor has the file open)
                // would be destructive. Leave `pending` alone so
                // the user can retry Save once the underlying issue
                // is fixed, or close the window to discard.
                if (apply_id) |id| if (!self.failApply(id)) return;
                // A reload that applied before the save failed showed no
                // preview (`livePreviews` is empty while a save is in
                // flight); the draft stays, and so does its preview.
                self.previewDrafts();
                std.log.warn("settings: save failed err={}; draft preserved", .{err});
                self.setSaveFailureNote(err);
                self.updateSaveEnabled();
            },
        }
    }

    fn resetClosePromptState(self: *SettingsWindow) void {
        self.close_prompt_visible = false;
        self.discard_prompt = false;
        self.close_after_save = false;
        self.close_posted = false;
        self.close_prior_focus = null;
    }

    fn updateClosePromptActions(self: *SettingsWindow) void {
        if (self.discard_prompt and !self.hasPendingChanges()) {
            // A field can become clean while it is still being edited. Keep
            // typing there; restore focus only when the prompt owned it.
            const focused = sys.GetFocus();
            const restore_focus = focused != null and (focused == self.btn_save or
                focused == self.btn_discard_changes or focused == self.btn_close_keep_editing);
            self.dismissPrompt(false, restore_focus);
            return;
        }
        const actions = closePromptActions(self.close_prompt_visible, self.close_posted);
        if (self.close_prompt_visible) if (self.btn_save) |button| {
            _ = sys.EnableWindow(button, @intFromBool(actions.save and !self.discard_prompt));
        };
        // The bar's Discard is the prompt's while the prompt is up; the rest of
        // the time `updateSaveEnabled` decides it.
        if (self.close_prompt_visible) if (self.btn_discard_changes) |button| {
            _ = sys.EnableWindow(button, @intFromBool(actions.discard));
        };
        if (self.btn_close_keep_editing) |button| {
            _ = sys.EnableWindow(button, @intFromBool(actions.keep_editing));
        }
        if (self.discard_prompt and self.pendingFieldCount() != self.discard_prompt_count) {
            self.syncClosePromptText(false);
            layoutChildren(self);
        }
    }

    fn promptText(self: *const SettingsWindow, buffer: []u8) []const u8 {
        if (!self.discard_prompt) return closePromptText(self.quit_after_close);
        const count = self.pendingFieldCount();
        return std.fmt.bufPrint(buffer, "Discard unsaved changes to {d} {s}?", .{
            count, if (count == 1) @as([]const u8, "field") else "fields",
        }) catch "Discard unsaved changes?";
    }

    fn syncClosePromptText(self: *SettingsWindow, announce: bool) void {
        const text = self.text_status orelse return;
        var buffer: [128]u8 = undefined;
        self.syncStatusFont();
        setWindowTextUtf8(text, self.promptText(&buffer));
        self.discard_prompt_count = self.pendingFieldCount();
        self.close_prompt_measure_height = 0;
        if (announce) self.announceText(text_status_index);
    }

    /// Where the one "Discard changes" button sits in z-order, which is the
    /// order Tab and the arrows take: after "Use disk" in the bar, after
    /// "Save and close" in the prompt.
    fn placeDiscardButton(self: *SettingsWindow) void {
        const button = self.btn_discard_changes orelse return;
        _ = sys.SetWindowLongPtrW(button, -12, @intCast(if (self.close_prompt_visible) BTN_CLOSE_DISCARD else BTN_DISCARD_CHANGES)); // GWLP_ID
        const after = (if (self.close_prompt_visible) self.btn_save else self.btn_conflict_use_disk) orelse return;
        _ = SetWindowPos(button, after, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE);
    }

    /// The one Save button is the bar's "Save", or while the close prompt is
    /// up the prompt's "Save and close": its caption, which is its name for
    /// MSAA and UIA alike (`attachControlUiaProvider`), and its id, which UIA
    /// Invoke posts with (as Discard's, `placeDiscardButton`). Two buttons
    /// that are never shown together are one window, so the Profiles page's
    /// rail button costs none.
    fn placeSaveButton(self: *SettingsWindow) void {
        const button = self.btn_save orelse return;
        const prompt = self.close_prompt_visible;
        _ = sys.SetWindowLongPtrW(button, -12, @intCast(if (prompt) BTN_CLOSE_SAVE else BTN_SAVE)); // GWLP_ID
        const caption = if (prompt) std.unicode.utf8ToUtf16LeStringLiteral("Save and close") else std.unicode.utf8ToUtf16LeStringLiteral("Save");
        _ = sys.SetWindowTextW(button, caption);
        if (self.controlIndex(button)) |index| if (self.control_uia_providers[index]) |provider| {
            win32_uia.events.raiseNameChanged(&provider.base);
        };
    }

    fn showClosePrompt(self: *SettingsWindow) void {
        self.showPrompt(false);
    }

    fn showPrompt(self: *SettingsWindow, discard: bool) void {
        if (self.close_prompt_visible and self.discard_prompt == discard) {
            if (self.btn_close_keep_editing) |button| _ = sys.SetFocus(button);
            return;
        }
        if (!self.close_prompt_visible) self.close_prior_focus = sys.GetFocus();
        self.close_prompt_visible = true;
        self.discard_prompt = discard;
        if (self.btn_conflict_keep) |button| _ = sys.ShowWindow(button, SW_HIDE);
        if (self.btn_conflict_use_disk) |button| _ = sys.ShowWindow(button, SW_HIDE);
        self.placeSaveButton();
        if (self.btn_save) |button| _ = sys.ShowWindow(button, if (discard) SW_HIDE else SW_SHOWNORMAL);
        self.placeDiscardButton();
        if (self.btn_discard_changes) |button| _ = sys.ShowWindow(button, SW_SHOWNORMAL);
        if (self.btn_close_keep_editing) |button| _ = sys.ShowWindow(button, SW_SHOWNORMAL);
        self.syncClosePromptText(true);
        self.updateClosePromptActions();
        layoutChildren(self);
        // Conservative default: closing must never be the result of an
        // accidental Enter after the window-close gesture.
        if (self.btn_close_keep_editing) |button| _ = sys.SetFocus(button);
    }

    /// The app's quit asks here first. With unsaved changes, raise the window
    /// with its close prompt and hold the quit: Save or Discard closes the
    /// window and `onClosed` resumes the quit (`takeQuitAfterClose`), while
    /// Keep editing, or a save that fails, drops it. Returns whether the
    /// quit has to wait.
    pub fn holdQuitForUnsavedChanges(self: *SettingsWindow) bool {
        const hwnd = self.hwnd orelse return false;
        // What a profile field holds counts as an edit (`requestClose`); a
        // refused one goes with the app.
        if (self.profile_edit != null) _ = self.commitProfileEdit(.closing);
        if (self.close_posted or !self.hasPendingChanges()) return false;
        if (sys.IsIconic(hwnd) != 0) _ = sys.ShowWindow(hwnd, SW_RESTORE);
        _ = SetForegroundWindow(hwnd);
        self.quit_after_close = true;
        // An open prompt still says "closing"; say "quitting" instead.
        if (self.close_prompt_visible and !self.discard_prompt) {
            self.syncClosePromptText(true);
            layoutChildren(self);
        }
        self.showClosePrompt();
        return true;
    }

    pub fn takeQuitAfterClose(self: *SettingsWindow) bool {
        defer self.quit_after_close = false;
        return self.quit_after_close;
    }

    fn cancelClosePrompt(self: *SettingsWindow) void {
        self.dismissPrompt(true, true);
    }

    fn dismissPrompt(self: *SettingsWindow, announce_status: bool, restore_focus: bool) void {
        if (!closePromptCanCancel(self.close_prompt_visible, self.close_posted)) return;
        const prior_focus = self.close_prior_focus;
        self.quit_after_close = false;
        self.close_prompt_visible = false;
        self.discard_prompt = false;
        self.close_after_save = false;
        self.close_prior_focus = null;
        if (self.btn_close_keep_editing) |button| _ = ShowWindow(button, SW_HIDE);
        self.placeSaveButton();
        self.placeDiscardButton();
        self.restoreStatusLine();
        if (self.btn_save) |button| _ = ShowWindow(button, SW_SHOWNORMAL);
        _ = self.syncConflictControls();
        self.updateSaveEnabled();
        layoutChildren(self);
        // What came up while the prompt hid the line (an error, or the failure
        // of a Save and close) was not spoken.
        if (announce_status and self.statusAnnounces()) self.announceText(text_status_index);

        if (!restore_focus) return;
        if (prior_focus) |control| {
            const belongs_to_settings = if (self.hwnd) |settings_hwnd|
                control == settings_hwnd or sys.IsChild(settings_hwnd, control) != 0
            else
                false;
            if (belongs_to_settings and sys.IsWindow(control) != 0 and sys.IsWindowVisible(control) != 0 and sys.IsWindowEnabled(control) != 0) {
                _ = sys.SetFocus(control);
                return;
            }
        }
        if (self.sectionButton(self.active_section)) |button| _ = sys.SetFocus(button);
    }

    fn saveAndClose(self: *SettingsWindow) void {
        if (!self.close_prompt_visible or self.close_posted or self.discard_prompt) return;
        self.close_after_save = true;
        self.save();
        if (self.close_posted) {
            self.updateClosePromptActions();
            return;
        }
        if (!self.hasPendingChanges()) {
            self.postCloseNow();
            return;
        }
        // Validation, a conflict, or synchronous persistence failure needs
        // the normal inline status and its owning control to be visible.
        self.cancelClosePrompt();
        if (self.validation_control != null or self.conflictCount() != 0) {
            self.surfaceNextValidation(true);
        }
    }

    fn discardAndClose(self: *SettingsWindow) void {
        if (!self.close_prompt_visible or self.close_posted) return;
        if (self.discard_prompt) {
            self.dismissPrompt(false, true);
            self.discardChangesNow();
            return;
        }
        self.close_after_save = false;
        self.postCloseNow();
    }

    fn discardChanges(self: *SettingsWindow) void {
        const button = self.btn_discard_changes orelse return;
        if (sys.IsWindowVisible(button) == 0 or self.close_posted or !self.hasPendingChanges()) return;
        self.showPrompt(true);
    }

    /// After confirmation, throw the draft away and show what is saved, with
    /// the window still open: `adoptConfig` from this window's own snapshot of
    /// the saved config, which rolls every live preview back on the way.
    fn discardChangesNow(self: *SettingsWindow) void {
        // The request validates the visible button before asking. Once the
        // user confirms, a new external conflict must not cancel the discard.
        if (self.close_posted or !self.hasPendingChanges()) return;
        const saved = &(self.current orelse return);
        self.freeNoteText();
        // From this window's own snapshot of what is saved, which does not
        // depend on an App keeping its previews out of `currentConfig`. The
        // copies come first, then the previews are rolled back
        // (`clearPending`), so a failure to copy leaves the draft whole.
        self.adoptConfig(saved) catch |err| {
            std.log.warn("settings: discarding the draft failed err={}", .{err});
            self.setNote(.discard_failed);
            return;
        };
        self.refreshAllControls();
        // A conflict may have arrived while confirmation was open. The clean
        // draft must restore the ordinary actions after its conflict is gone.
        self.surfaceNextValidation(false);
        // The Advanced page lists the pending changes.
        self.refreshNativeSectionText();
        if (self.active_section == .advanced) layoutChildren(self);
        self.setNote(.discarded);
    }

    fn postCloseNow(self: *SettingsWindow) void {
        if (self.close_posted or self.close_notified) return;
        const hwnd = self.hwnd orelse return;
        self.close_posted = true;
        self.updateClosePromptActions();
        if (sys.PostMessageW(hwnd, WM_SETTINGS_CLOSE_NOW, 0, 0) == 0) {
            self.close_posted = false;
            self.updateClosePromptActions();
            self.setNote(.close_failed);
            self.cancelClosePrompt();
        }
    }

    fn closeNow(self: *SettingsWindow, hwnd: HWND) void {
        if (self.close_notified) return;
        self.close_notified = true;
        _ = sys.ShowWindow(hwnd, SW_HIDE);
        if (sys.DestroyWindow(hwnd) == 0) {
            self.close_notified = false;
            self.close_posted = false;
            _ = sys.ShowWindow(hwnd, SW_SHOWNORMAL);
            self.updateClosePromptActions();
            self.setNote(.close_failed);
            self.cancelClosePrompt();
            return;
        }
        self.handle.onClosed(self.handle.ctx);
    }

    fn nextSuccessfulRevision(self: *SettingsWindow) u64 {
        if (self.handle.configRevision) |get_revision| {
            return get_revision(self.handle.ctx);
        }
        self.local_revision +%= 1;
        return self.local_revision;
    }

    fn succeedApply(self: *SettingsWindow, apply_id: ApplyId, revision: u64) bool {
        const transaction = &(self.transaction orelse return false);
        _ = transaction.dispatch(.{ .apply_succeeded = .{
            .apply_id = apply_id,
            .revision = revision,
        } }, &.{}) catch |err| {
            std.log.err("settings: save completion rejected apply_id={d} err={}", .{ apply_id, err });
            return false;
        };
        return true;
    }

    fn failApply(self: *SettingsWindow, apply_id: ApplyId) bool {
        const transaction = &(self.transaction orelse return false);
        _ = transaction.dispatch(.{ .apply_failed = .{ .apply_id = apply_id } }, &.{}) catch |err| {
            std.log.err("settings: save failure completion rejected apply_id={d} err={}", .{ apply_id, err });
            return false;
        };
        return true;
    }

    fn finishSuccessfulSave(self: *SettingsWindow, masked: bool) void {
        const should_close = self.close_after_save;
        // Before anything repaints the status: the note outlives the reset.
        self.freeNoteText();
        self.status_note = if (masked) .saved_overridden else .saved;
        // The settings the save wrote that something later overrides, by the
        // names a config file knows them by, and where the value that wins
        // is set, read from the config the save reloaded.
        const masked_keys: ?[]const u8 = if (masked)
            if (self.handle.maskedKeys) |lend| lend(self.handle.ctx) else null
        else
            null;
        const adopted = if (self.adoptCurrentConfig()) |_| true else |err| failed: {
            std.log.err("settings: failed to refresh saved config snapshot err={}", .{err});
            break :failed false;
        };
        var masked_detail: ?[]u8 = null;
        defer if (masked_detail) |detail| self.handle.alloc.free(detail);
        if (masked_keys) |keys| {
            masked_detail = if (adopted) self.maskedDetail(keys) catch null else null;
            self.note_text = StatusNote.saved_overridden.textWithDetail(self.handle.alloc, masked_detail orelse keys) catch null;
        }
        if (!adopted) {
            if (should_close) self.cancelClosePrompt();
            return;
        }
        self.refreshAllControls();
        self.updateSaveEnabled();
        if (masked) {
            var body_buf: [1024]u8 = undefined;
            const body = maskedNotificationBody(&body_buf, masked_detail, masked_keys);
            self.handle.notifySuccess(
                self.handle.ctx,
                "Settings saved, but some values are overridden",
                body,
            );
        } else {
            self.handle.notifySuccess(self.handle.ctx, "Settings saved", "");
        }
        if (should_close and self.close_after_save) {
            self.postCloseNow();
        } else if (self.close_prompt_visible and !self.hasPendingChanges()) {
            self.cancelClosePrompt();
        }
    }

    /// The masked keys `keys` names (comma separated, as the App lends them),
    /// each with where the value that overrides it is set in `current`:
    /// "font-size (line 2 of included.conf)". That is the value in effect
    /// (`config.origin.of`), not the files' value a row shows
    /// (`settings_reference.savedOrigin`): a command line's `default-profile`
    /// masks a saved one, and is what is named. Owned by the caller.
    fn maskedDetail(self: *const SettingsWindow, keys: []const u8) ![]u8 {
        const current = if (self.current) |*config| config else return error.NoConfig;
        var out: std.Io.Writer.Allocating = .init(self.handle.alloc);
        errdefer out.deinit();
        // A profile field is named "key id" or "profile-env id NAME"
        // (`settings_patch.writeEditName`); its line comes from the index.
        var profile_index: ?config_origin.Index = null;
        defer if (profile_index) |*index| index.deinit(self.handle.alloc);
        var names = std.mem.splitSequence(u8, keys, ", ");
        var first = true;
        while (names.next()) |name| {
            if (!first) try out.writer.writeAll(", ");
            first = false;
            try out.writer.writeAll(name);
            var parts = std.mem.splitScalar(u8, name, ' ');
            const key = std.meta.stringToEnum(Config.Key, parts.first()) orelse continue;
            const winner = if (parts.next()) |id| profile: {
                if (profile_index == null) profile_index = try config_origin.Index.init(self.handle.alloc, current);
                break :profile profile_index.?.ofProfile(key, id, parts.next());
            } else config_origin.of(current, key, null);
            switch (winner) {
                .file => |file| try out.writer.print(" (line {d} of {s})", .{ file.line, std.fs.path.basename(file.path) }),
                .cli => try out.writer.writeAll(" (the command line)"),
                .default, .derived, .unplaced => {},
            }
        }
        return out.toOwnedSlice();
    }

    fn completeSynchronousSave(self: *SettingsWindow, apply_id: ?ApplyId, masked: bool) void {
        const revision = self.nextSuccessfulRevision();
        if (apply_id) |id| {
            if (!self.succeedApply(id, revision)) return;
        }
        self.finishSuccessfulSave(masked);
    }

    fn adoptCurrentConfig(self: *SettingsWindow) !void {
        return self.adoptConfig(self.handle.currentConfig(self.handle.ctx));
    }

    /// Start the draft over from `current`. Nothing is touched until every copy
    /// is made, so a failure leaves the draft, its tracking and its previews as
    /// they were. `current` may be this window's own snapshot, which is freed
    /// only after the copies exist.
    fn adoptConfig(self: *SettingsWindow, current: *const Config) !void {
        // The draft starts over, and a profile field being typed into with it.
        self.cancelProfileEdit();
        var original = try current.clone(self.handle.alloc);
        errdefer original.deinit();
        var current_snapshot = try current.clone(self.handle.alloc);
        errdefer current_snapshot.deinit();
        var pending = try current.clone(self.handle.alloc);
        errdefer pending.deinit();
        for ([_]*Config{ &original, &current_snapshot, &pending }) |copy| pane_launch.asWritten(copy);

        self.clearPending();
        self.original = original;
        self.current = current_snapshot;
        self.pending = pending;
        self.initTransaction();
        self.referenceConfigChanged();
    }

    /// The section and the native control that own `field`.
    fn settingDestination(self: *const SettingsWindow, field: SettingField) struct { section: Section, hwnd: ?HWND } {
        inline for (field_model.form_fields) |row| if (row.field == field) {
            return .{ .section = nativeSection(row.descriptor.section), .hwnd = @field(self.fields, row.native.binding) };
        };
        unreachable;
    }

    /// Open settings at the exact native control that owns `field`.
    pub fn openField(self: *SettingsWindow, field: SettingField) !void {
        try self.open();
        self.showField(field);
    }

    /// Show `field`'s page with the focus on its control, in a window that is
    /// open: the palette's jump after `open`, and the All settings page's Edit,
    /// which is inside the window already and so leaves its placement (a
    /// snapped window stays snapped) and a close prompt that is up alone.
    fn showField(self: *SettingsWindow, field: SettingField) void {
        // A search that hides the field gives way to it (asked live, as
        // `revealControl` does), with no pass of its own: the page switch
        // below lays out and paints once.
        if (self.search_query.active() and !self.searchFinds(settingControlIndex(field))) self.dropSearch();
        const section = self.settingDestination(field).section;
        // The page's rows first, so the control exists to take the focus
        // before the switch (`focusAhead`): the focus moves once.
        self.materializeSection(section);
        const control = self.settingDestination(field).hwnd;
        if (control) |target| {
            // Unsupported controls are disabled: the focus goes to the page.
            if (sys.IsWindowEnabled(target) != 0) self.focusAhead(target) else self.focusRailButtonAhead(section);
        }
        self.showSection(section, true);
        if (control) |target| self.ensureControlVisible(target);
    }

    /// Open Settings on `section`, with focus on its rail button. The caller
    /// asked for the page itself (the palette's Config problems asks for
    /// Advanced, whose help text lists them), so a search gives way whether or
    /// not it finds rows there: a page cut down by an earlier search, or one
    /// that only says nothing on it matches, is not the page asked for. The
    /// focus moves once, straight to the rail button, before the switch hides
    /// the last page's rows (`focusRailButtonAhead`): a focused row hidden
    /// first would hand the focus to the viewport, and with a search,
    /// `keepFocusShown` to the search field.
    pub fn openSection(self: *SettingsWindow, section: Section) !void {
        try self.open();
        if (self.search_query.active()) self.dropSearch();
        self.focusRailButtonAhead(section);
        self.showSection(section, true);
    }

    /// Bring the settings window up. Idempotent: a subsequent open
    /// with a live HWND brings the existing window to the foreground
    /// instead of duplicating it.
    pub fn open(self: *SettingsWindow) !void {
        // The stamps describe this call alone: a raise leaves none, so an
        // earlier creation's stamps never read as this one's.
        const stamps = &self.creation_stamps;
        stamps.len = 0;
        if (self.hwnd) |h| {
            if (sys.IsWindow(h) != 0) {
                switch (pendingCloseReopenAction(self.close_posted, self.close_after_save)) {
                    .none => {},
                    .cancel_saved_close => {
                        self.close_posted = false;
                        self.close_after_save = false;
                    },
                    .cancel_discard_close => {
                        // The user already chose Discard. A reopen that wins
                        // the posted-close race must not resurrect that draft.
                        self.status_note = .none;
                        try self.adoptCurrentConfig();
                        self.refreshAllControls();
                        self.close_posted = false;
                        self.close_after_save = false;
                    },
                }
                self.cancelClosePrompt();
                if (sys.IsIconic(h) != 0) _ = sys.ShowWindow(h, SW_RESTORE) else _ = sys.ShowWindow(h, SW_SHOWNORMAL);
                _ = sys.SetForegroundWindow(h);
                return;
            }
            self.hwnd = null;
        }
        stamps.mark(.create_begin);
        self.resetClosePromptState();
        self.close_notified = false;
        self.focus_before_deactivate = null;
        self.wheel_remainder = 0;

        // Fresh owned snapshots of the live config. Discarded on close
        // or atomically refreshed after a successful save.
        self.status_note = .none;
        try self.adoptCurrentConfig();
        // What each row is compared with for its marker and its reset. Without
        // it the window still works, with no row marked and none to reset.
        if (self.defaults == null) self.defaults = Config.default(self.handle.alloc) catch |err| blk: {
            std.log.warn("settings: defaults unavailable err={}; no field can be reset", .{err});
            break :blk null;
        };
        stamps.mark(.create_config);

        if (self.class_atom == 0) {
            const wc: WNDCLASSEXW = .{
                .cbSize = @sizeOf(WNDCLASSEXW),
                .style = CS_HREDRAW | CS_VREDRAW,
                .lpfnWndProc = &wndProc,
                .cbClsExtra = 0,
                .cbWndExtra = 0,
                .hInstance = self.handle.hinstance,
                .hIcon = self.appIcon(false),
                .hCursor = sys.LoadCursorW(null, @ptrFromInt(IDC_ARROW)),
                .hbrBackground = null,
                .lpszMenuName = null,
                .lpszClassName = class_name,
                .hIconSm = self.appIcon(true),
            };
            self.class_atom = sys.RegisterClassExW(&wc);
            if (self.class_atom == 0) {
                return windows.unexpectedError(windows.kernel32.GetLastError());
            }
        }
        if (self.viewport_class_atom == 0) {
            const wc: WNDCLASSEXW = .{
                .cbSize = @sizeOf(WNDCLASSEXW),
                .style = 0,
                .lpfnWndProc = &viewportProc,
                .cbClsExtra = 0,
                .cbWndExtra = 0,
                .hInstance = self.handle.hinstance,
                .hIcon = null,
                .hCursor = sys.LoadCursorW(null, @ptrFromInt(IDC_ARROW)),
                .hbrBackground = null,
                .lpszMenuName = null,
                .lpszClassName = viewport_class_name,
                .hIconSm = null,
            };
            self.viewport_class_atom = sys.RegisterClassExW(&wc);
            if (self.viewport_class_atom == 0) {
                return windows.unexpectedError(windows.kernel32.GetLastError());
            }
        }

        const title = window_title;
        // WS_CLIPCHILDREN: painting the frame never paints over a child, so a
        // relayout, a section switch or a theme refresh no longer blanks the
        // form until every control has repainted. The scroll bar belongs to
        // the viewport, not to the window.
        const window_style = (WS_OVERLAPPEDWINDOW & ~WS_MAXIMIZEBOX) | WS_CLIPCHILDREN;
        const initial_outer = settingsOuterSizeForClient(960, 640, 96, window_style, WS_EX_APPWINDOW);
        const owner_hwnd = if (self.handle.ownerWindow) |get_owner| get_owner(self.handle.ctx) else null;
        const hwnd = sys.CreateWindowExW(
            WS_EX_APPWINDOW,
            class_name,
            title,
            window_style,
            CW_USEDEFAULT,
            CW_USEDEFAULT,
            initial_outer.x,
            initial_outer.y,
            // Keep settings independent from terminal lifetime. The owner HWND
            // is used only to choose/center on the originating monitor below;
            // an owned top-level window is destroyed when its owner dies and
            // would bypass dirty-close confirmation.
            null,
            null,
            self.handle.hinstance,
            self,
        ) orelse return windows.unexpectedError(windows.kernel32.GetLastError());
        self.hwnd = hwnd;
        self.dpi = normalizedDpi(sys.GetDpiForWindow(hwnd));
        // The class icon is what Alt+Tab shows; the caption and taskbar sizes
        // are set on the window itself, as the terminal windows do.
        if (self.appIcon(false)) |icon| _ = sys.SendMessageW(hwnd, WM_SETICON, ICON_BIG, @bitCast(@intFromPtr(icon)));
        if (self.appIcon(true)) |icon| _ = sys.SendMessageW(hwnd, WM_SETICON, ICON_SMALL, @bitCast(@intFromPtr(icon)));

        // PerMonitorV2 coordinates are physical pixels. Start at the intended
        // logical size, capped to the current work area, so a high-DPI monitor
        // does not receive a tiny and immediately overlapping first frame.
        var work_area: RECT = undefined;
        var have_work_area = false;
        if (owner_hwnd) |owner| if (sys.MonitorFromWindow(owner, MONITOR_DEFAULTTONEAREST)) |monitor| {
            var info: MONITORINFO = .{
                .cbSize = @sizeOf(MONITORINFO),
                .rcMonitor = undefined,
                .rcWork = undefined,
                .dwFlags = 0,
            };
            if (sys.GetMonitorInfoW(monitor, &info) != 0) {
                work_area = info.rcWork;
                have_work_area = true;
            }
        };
        if (!have_work_area) have_work_area = sys.SystemParametersInfoW(SPI_GETWORKAREA, 0, &work_area, 0) != 0;
        if (have_work_area) {
            const work_width = work_area.right - work_area.left;
            const work_height = work_area.bottom - work_area.top;
            const intended = settingsOuterSizeForClient(960, 640, self.dpi, window_style, WS_EX_APPWINDOW);
            const width = @min(intended.x, work_width);
            const height = @min(intended.y, work_height);
            _ = SetWindowPos(
                hwnd,
                null,
                work_area.left + @divTrunc(work_width - width, 2),
                work_area.top + @divTrunc(work_height - height, 2),
                width,
                height,
                SWP_NOZORDER | SWP_NOACTIVATE,
            );
        }
        stamps.mark(.create_frame);

        // Each window is created once, in its final form: where Tab reaches
        // it (z-order is creation order), with its final group, tab stop and
        // visibility, then given its theme and its font (`finishChild`).
        // Nothing reorders, restyles, re-themes or re-fonts every window
        // afterwards, so what the colours, brushes and fonts are comes first.
        // A `WM_DPICHANGED` from the move above already built the fonts for
        // the new DPI. Fonts before any child: a text field's frame centres on
        // their line height.
        self.theme_adapter.apply(hwnd, self.resolveThemeColors(), .frame);
        stamps.mark(.create_theme);
        if (self.ui_font == null or self.ui_font_dpi != self.dpi) {
            if (self.buildUiFonts()) |replaced| replaced.delete();
        }
        stamps.mark(.create_fonts);

        const hinstance = self.handle.hinstance;
        const btn_class = std.unicode.utf8ToUtf16LeStringLiteral("BUTTON");
        const status_text = switch (self.nextStatus()) {
            .none => self.idleStatusText(),
            else => "",
        };
        // The first child starts a group of its own. The dialog manager walks
        // a group round the end of the child list, so this is what ends the
        // action bar's run (the last in z-order) and lets the arrows wrap
        // within the bar instead of reaching these statics.
        self.text_header = self.finishChild(makeStatic(hwnd, hinstance, self.active_section.headerText(), WS_VISIBLE | WS_GROUP), self.header_font, .control);
        self.text_summary = self.finishChild(makeStatic(hwnd, hinstance, self.active_section.placeholderText(), WS_VISIBLE), self.secondary_font, .control);
        self.text_status = self.finishChild(makeStatic(hwnd, hinstance, status_text, WS_VISIBLE), self.statusFont(), .control);
        self.rememberStatusLine(status_text);
        // The search field: first in the Tab order, a group of its own (the
        // rail's first button starts the next), framed like the form's text
        // fields, whose subclass it takes before its UIA provider's.
        self.edit_search = self.finishChild(makeEdit(hwnd, hinstance, EDIT_SEARCH, WS_VISIBLE | WS_GROUP), self.ui_font, .control);
        if (self.edit_search) |search| {
            _ = sys.SendMessageW(search, EM_LIMITTEXT, search_text_max_code_units, 0);
            // Shown while the field is focused and empty, too: Ctrl+F lands
            // in it with nothing typed.
            _ = sys.SendMessageW(search, EM_SETCUEBANNER, 1, @bitCast(@intFromPtr(search_field_cue)));
            subclassKeepingPrevious(search, &settingsEditProc);
            _ = SetWindowPos(search, null, 0, 0, 0, 0, SWP_FRAMECHANGED | SWP_NOMOVE | SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE);
        }

        // Left-rail section buttons. Clicks arrive via WM_COMMAND on
        // the parent; the id maps back to a `Section` via
        // `Section.fromButtonId`.
        const selected = self.active_section;
        self.btn_section_appearance = self.finishChild(makeSectionButton(hwnd, hinstance, btn_class, .appearance, selected), self.ui_font, .control);
        self.btn_section_terminal = self.finishChild(makeSectionButton(hwnd, hinstance, btn_class, .terminal, selected), self.ui_font, .control);
        self.btn_section_shell = self.finishChild(makeSectionButton(hwnd, hinstance, btn_class, .shell, selected), self.ui_font, .control);
        self.btn_section_profiles = self.finishChild(makeSectionButton(hwnd, hinstance, btn_class, .profiles, selected), self.ui_font, .control);
        self.btn_section_privacy = self.finishChild(makeSectionButton(hwnd, hinstance, btn_class, .privacy, selected), self.ui_font, .control);
        self.btn_section_updates = self.finishChild(makeSectionButton(hwnd, hinstance, btn_class, .updates, selected), self.ui_font, .control);
        self.btn_section_keybindings = self.finishChild(makeSectionButton(hwnd, hinstance, btn_class, .keybindings, selected), self.ui_font, .control);
        self.btn_section_advanced = self.finishChild(makeSectionButton(hwnd, hinstance, btn_class, .advanced, selected), self.ui_font, .control);
        self.btn_section_reference = self.finishChild(makeSectionButton(hwnd, hinstance, btn_class, .reference, selected), self.ui_font, .control);
        if (self.sectionButton(selected)) |button| _ = sys.SendMessageW(button, BM_SETCHECK, BST_CHECKED, 0);
        self.subclassSectionButtons();
        self.initializeSectionUiaProviders();
        stamps.mark(.create_rail);

        // The form: every field, its label and the help text live in the
        // viewport, after the rail in z-order so Tab goes rail, fields, action
        // bar. WS_EX_CONTROLPARENT lets the dialog manager walk into it.
        // WM_COMMAND and WM_CTLCOLOR* from the fields are forwarded here.
        // No scroll bar yet: the layout gives it one when the form overflows
        // (`SetScrollInfo`, `ShowScrollBar`).
        const form = sys.CreateWindowExW(
            WS_EX_CONTROLPARENT,
            viewport_class_name,
            std.unicode.utf8ToUtf16LeStringLiteral(""),
            WS_CHILD | WS_VISIBLE | WS_CLIPCHILDREN | WS_CLIPSIBLINGS,
            0,
            0,
            1,
            1,
            hwnd,
            null,
            hinstance,
            self,
        ) orelse {
            const err = windows.kernel32.GetLastError();
            _ = sys.DestroyWindow(hwnd);
            return windows.unexpectedError(err);
        };
        // Its scroll bar takes the theme; it draws no text.
        self.viewport = self.finishChild(form, null, .control);
        // The arrow keys walk a group from window to window and step into the
        // viewport, ignoring a group style on the viewport itself: its first
        // child has to end the rail's group, or Down from the last section
        // would run on into the labels. The layout shows it on the pages that
        // have help.
        var help_buf: [help_text_bytes]u8 = undefined;
        self.text_help = self.finishChild(makeStatic(form, hinstance, self.helpText(&help_buf), WS_GROUP), self.ui_font, .control);
        // Only the selected section's rows: the others are made the first
        // time they are shown (`materializeSection`).
        self.createSectionRows(selected, true);
        self.initializeTextUiaProviders();
        stamps.mark(.create_form);

        // The action bar, in the order Tab reaches it: the conflict choices
        // and Discard sit left of Save (never together), and the close
        // prompt's three replace them all: Save becomes its "Save and close"
        // and Discard its Discard (`placeSaveButton`, `placeDiscardButton`).
        // The first starts the bar's group and the header, the first child,
        // ends its run at the wrap. All five exist from the start: Escape
        // reaches the close path only through the enabled "Keep editing"
        // button, which owns IDCANCEL.
        // "Save" writes `pending` to disk and fires a hard reload; save
        // errors are logged and the draft remains in memory for retry.
        const discard_label = std.unicode.utf8ToUtf16LeStringLiteral("Discard changes");
        self.btn_conflict_keep = self.finishChild(makePushButton(hwnd, hinstance, std.unicode.utf8ToUtf16LeStringLiteral("Keep mine"), BTN_CONFLICT_KEEP, 112, WS_GROUP), self.ui_font, .control);
        self.btn_conflict_use_disk = self.finishChild(makePushButton(hwnd, hinstance, std.unicode.utf8ToUtf16LeStringLiteral("Use disk"), BTN_CONFLICT_USE_DISK, 112, 0), self.ui_font, .control);
        self.btn_discard_changes = self.finishChild(makePushButton(hwnd, hinstance, discard_label, BTN_DISCARD_CHANGES, 128, WS_VISIBLE), self.ui_font, .control);
        self.btn_save = self.finishChild(makePushButton(hwnd, hinstance, std.unicode.utf8ToUtf16LeStringLiteral("Save"), BTN_SAVE, 96, WS_VISIBLE), self.ui_font, .control);
        self.btn_close_keep_editing = self.finishChild(makePushButton(hwnd, hinstance, std.unicode.utf8ToUtf16LeStringLiteral("Keep editing"), BTN_CLOSE_KEEP_EDITING, 112, 0), self.ui_font, .control);
        stamps.mark(.create_actions);

        self.prepareSectionRows(selected);
        stamps.mark(.create_annotate);
        // Establish native values before providers cache their initial state.
        self.refreshAllControls();
        self.initializeControlUiaProviders();
        if (self.sectionList(selected)) |list| {
            self.ensureListModel(list);
            self.refreshListShown(list, true);
            self.createList(list);
        }
        stamps.mark(.create_refresh);

        layoutChildren(self);
        if (self.reference_list.hwnd) |list| setChildShown(list, self.referenceListShows());
        if (self.keybind_list.hwnd) |list| setChildShown(list, self.keybindListShows());
        if (self.profile_list.hwnd) |list| setChildShown(list, self.profileListShows());
        stamps.mark(.create_layout);
        _ = sys.ShowWindow(hwnd, SW_SHOWNORMAL);
        stamps.mark(.create_show);
        _ = sys.SetForegroundWindow(hwnd);
        if (self.sectionButton(selected)) |button| _ = sys.SetFocus(button);
        stamps.mark(.create_end);
    }

    /// Make `section`'s rows the first time it is shown, hidden: the caller
    /// lays them out and shows them with the rest of the section
    /// (`setActiveSection`). Each row gets what `open` gives the selected
    /// section's rows, from the window's current draft, theme, fonts and DPI,
    /// so a section first shown late ends up as one made at open would.
    fn materializeSection(self: *SettingsWindow, section: Section) void {
        // The All settings page has no rows of its own: its list is made with
        // the page (`createList`), from the model made here. The Keybindings
        // page's list is too, besides its row.
        if (section == .reference) return self.ensureReferenceModel();
        if (section == .profiles) return self.ensureProfileModel();
        if (section == .keybindings) self.ensureKeybindModel();
        if (self.materialized.contains(section) or self.viewport == null) return;
        self.createSectionRows(section, false);
        const providers = self.canInitializeCustomUiaProviders();
        if (providers) for (formItemsForSection(section)) |item| {
            if (item.label_index) |index| self.attachTextUiaProvider(text_first_label_index + index);
        };
        self.prepareSectionRows(section);
        // Values before the providers, which cache their initial state, and
        // whether each differs from its default too.
        self.displaySectionRows(section);
        self.syncDefaultMarks();
        if (providers) for (formItemsForSection(section)) |item| self.attachControlUiaProvider(item.control_index);
    }

    /// Make `section`'s labels and controls in the viewport, each in its final
    /// form (`finishChild`), in the order they are laid out: a label right
    /// before its control. A section's first row, a label and its control, and
    /// a row next to text start an arrow-key group, so the arrows never run
    /// from one section into the next or onto a static row.
    ///
    /// Tab and the arrow keys follow z-order, and a new window goes to the
    /// bottom of it. So when a later section's rows already exist, each new
    /// row is moved in behind the one before it, starting after the rows of
    /// the nearest earlier section: in whatever order the sections are first
    /// shown, the viewport ends up as if they had all been made in order.
    fn createSectionRows(self: *SettingsWindow, section: Section, visible: bool) void {
        const form = self.viewport orelse return;
        const hinstance = self.handle.hinstance;
        const shown: u32 = if (visible) WS_VISIBLE else 0;
        var order: RowOrder = if (self.laterSectionMaterialized(section))
            .{ .insert = true, .after = self.lastFormWindowBefore(section) }
        else
            .{ .insert = false, .after = null };
        var previous_text = false;
        switch (section) {
            inline else => |made| inline for (comptime formItemsForSection(made), 0..) |item, index| {
                const spec = comptime settings_control_specs[item.control_index];
                const text = comptime spec.role == .text;
                var group = formGroupStarts(index, previous_text, text);
                if (comptime item.control_index < form_field_count) _ = self.refreshOriginNote(item.control_index);
                if (item.label_index) |i| {
                    // Drawn by the viewport (`paintFieldLabel`), with the
                    // row's origin note on the right.
                    self.field_labels[i] = self.finishChild(makeStatic(form, hinstance, spec.label.?, shown | WS_GROUP | SS_OWNERDRAW), self.secondary_font, .control);
                    order.place(self.field_labels[i]);
                    if (self.field_labels[i] != null) group = true;
                }
                const style: u32 = shown | if (group) WS_GROUP else 0;
                if (comptime Companion.ofControl(item.control_index) == .opacity_slider) {
                    self.makeCompanion(form, .opacity_slider, shown);
                    order.place(self.companions[@intFromEnum(Companion.opacity_slider)]);
                }
                if (comptime item.control_index < field_model.form_fields.len) {
                    const row = comptime field_model.form_fields[item.control_index];
                    @field(self.fields, spec.binding) = switch (comptime row.kind()) {
                        .choice => makeCombo(form, hinstance, spec.id, settings_combo_popup_height, &field_model.Combo(row.field.?).labels, style),
                        // Its items come from the app's profiles when it is shown.
                        .profile => makeCombo(form, hinstance, spec.id, settings_combo_popup_height, &.{}, style),
                        .boolean, .blur => makeCheckbox(form, hinstance, spec.id, std.unicode.utf8ToUtf16LeStringLiteral(spec.caption.?), style),
                        else => makeEdit(form, hinstance, spec.id, style | if (row.kind() == .integer) ES_NUMBER else 0),
                    };
                    if (@field(self.fields, spec.binding)) |control| {
                        if (row.descriptor.support != .available) _ = sys.EnableWindow(control, 0);
                        if (spec.role == .edit and row.descriptor.placeholder.len != 0)
                            _ = sys.SendMessageW(control, 0x1501, 0, @bitCast(@intFromPtr(std.unicode.utf8ToUtf16LeStringLiteral(row.descriptor.placeholder)))); // EM_SETCUEBANNER
                    }
                } else {
                    @field(self.fields, spec.binding) = makeDisplayControl(form, hinstance, spec, style);
                }
                const font = if (comptime spec.role == .check_box) self.secondary_font else self.ui_font;
                if (self.finishChild(@field(self.fields, spec.binding), font, if (comptime spec.role == .combo_box) .combo else .control)) |control| {
                    order.place(control);
                    previous_text = text;
                }
                if (comptime Companion.ofControl(item.control_index)) |kind| if (comptime kind != .opacity_slider) {
                    self.makeCompanion(form, kind, shown);
                    order.place(self.companions[@intFromEnum(kind)]);
                };
            },
        }
        self.materialized.insert(section);
    }

    /// Where the next row goes in the viewport's z-order.
    const RowOrder = struct {
        /// Rows are moved only when a later section's rows exist; otherwise a
        /// new window already lands where it belongs, at the bottom.
        insert: bool,
        /// The window the next row goes behind.
        after: ?HWND,

        fn place(self: *RowOrder, window: ?HWND) void {
            const row = window orelse return;
            if (!self.insert) return;
            _ = SetWindowPos(row, self.after, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE);
            self.after = row;
        }
    };

    fn laterSectionMaterialized(self: *const SettingsWindow, section: Section) bool {
        for (std.enums.values(Section)) |other| {
            if (@intFromEnum(other) > @intFromEnum(section) and self.materialized.contains(other)) return true;
        }
        return false;
    }

    /// The viewport window that `section`'s rows follow: the last row of the
    /// nearest earlier section that has rows, or else the help text, the
    /// viewport's first window.
    fn lastFormWindowBefore(self: *const SettingsWindow, section: Section) ?HWND {
        var earlier = @intFromEnum(section);
        while (earlier > 0) {
            earlier -= 1;
            if (!self.materialized.contains(@enumFromInt(earlier))) continue;
            const items = formItemsForSection(@enumFromInt(earlier));
            var index = items.len;
            while (index > 0) {
                index -= 1;
                if (self.controlHwnd(items[index].control_index)) |control| return control;
                if (items[index].label_index) |label| if (self.field_labels[label]) |window| return window;
            }
        }
        return self.text_help;
    }

    /// What a section's rows need once they exist: the names MSAA clients
    /// read for its text fields and dropdowns, then their subclasses, then
    /// each text field's frame. The subclasses come before the UIA providers,
    /// which subclass the same windows and call down to whatever procedure is
    /// installed when they arrive; and the stock EDIT answered the frame
    /// request at creation, which its subclass owns now.
    fn prepareSectionRows(self: *SettingsWindow, section: Section) void {
        annotateAccessibleControls(self, section);
        const items = formItemsForSection(section);
        for (items) |item| if (settings_control_specs[item.control_index].role == .combo_box) {
            if (self.controlHwnd(item.control_index)) |control| subclassKeepingPrevious(control, &settingsComboProc);
        };
        for (items) |item| if (settings_control_specs[item.control_index].role == .edit) {
            if (self.controlHwnd(item.control_index)) |control| subclassKeepingPrevious(control, &settingsEditProc);
        };
        for (items) |item| if (settings_control_specs[item.control_index].role == .check_box) {
            if (self.controlHwnd(item.control_index)) |control| subclassKeepingPrevious(control, &settingsToggleProc);
        };
        for (items) |item| if (settings_control_specs[item.control_index].role == .edit) {
            if (self.controlHwnd(item.control_index)) |control|
                _ = SetWindowPos(control, null, 0, 0, 0, 0, SWP_FRAMECHANGED | SWP_NOMOVE | SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE);
        };
    }

    /// Show the draft's values in `section`'s controls.
    fn displaySectionRows(self: *SettingsWindow, section: Section) void {
        inline for (field_model.form_fields) |row| {
            if (nativeSection(row.descriptor.section) == section) @field(field_adapters, row.native.binding).display(self);
        }
    }

    /// Build the All settings model when there is none, or the config changed
    /// since it was built (`reference_stale`): from `current` (the config in
    /// effect), the defaults, and the config file Settings saves to, read for
    /// the lines that set each key when it can be shown to be local
    /// (`AppHandle.configSource`). Without a config there is nothing to build,
    /// and the page lists nothing.
    fn ensureReferenceModel(self: *SettingsWindow) void {
        if (!self.reference_stale and self.reference_model.built()) return;
        const current = if (self.current) |*config| config else return;
        const defaults: ?*const Config = if (self.defaults) |*config| config else null;
        var source: settings_reference.ConfigSource = if (self.handle.configSource) |read| read(self.handle.ctx, self.handle.alloc) else .{};
        defer source.deinit(self.handle.alloc);
        self.reference_list.forgetOpenText(self.handle.alloc);
        self.reference_generation +%= 1;
        self.reference_model.build(self.handle.alloc, current, defaults, source.path, source.file, &reference_extra_search) catch |err| {
            std.log.warn("settings: the All settings page could not be built err={}", .{err});
            self.reference_model.deinit();
            return;
        };
        self.reference_stale = false;
    }

    /// Build the Keybindings page's model when there is none, or the config
    /// changed since it was built: every binding of `current`, each marked
    /// by whether the defaults have it.
    fn ensureKeybindModel(self: *SettingsWindow) void {
        if (!self.keybind_stale) return;
        const current = if (self.current) |*config| config else return;
        const defaults: ?*const Config.Keybinds = if (self.defaults) |*config| &config.keybind else null;
        const alloc = self.handle.alloc;
        const list = &self.keybind_list;
        // The selection is a row of the old model: it follows its binding,
        // which keeps its id (`keybind_model.Row.id`). Not its text, which
        // two bindings may share.
        const was_selected: ?u64 = if (list.selected) |id| (if (id < self.keybind_model.rows.len) self.keybind_model.rows[id].id else null) else null;
        list.selected = null;
        list.forgetOpenText(alloc);
        self.keybind_generation +%= 1;
        // Tried once per config: a failure is not tried again on every keystroke.
        self.keybind_stale = false;
        self.keybind_model.build(alloc, &current.keybind, defaults) catch |err| {
            std.log.warn("settings: the key binding list could not be built err={}", .{err});
            self.keybind_model.deinit();
        };
        // The found rows were the old model's.
        alloc.free(self.keybind_found);
        self.keybind_found = &.{};
        if (!self.keybind_model.built()) return;
        self.keybind_found = alloc.alloc(bool, self.keybind_model.rows.len) catch &.{};
        @memset(self.keybind_found, false);
        if (was_selected) |selected| for (self.keybind_model.rows, 0..) |row, id| {
            if (row.id == selected) list.selected = @intCast(id);
        };
    }

    /// Build the Profiles page's model when there is none, or the draft
    /// changed since it was built: the draft's user profiles
    /// (`settings_profiles.Model`), each field marked when the draft changed
    /// it. The selection follows its row (`Row.identity`).
    fn ensureProfileModel(self: *SettingsWindow) void {
        if (!self.profile_stale) return;
        const pending = if (self.pending) |*config| config else return;
        const original: ?*const Config = if (self.original) |*config| config else null;
        const alloc = self.handle.alloc;
        const list = &self.profile_list;
        const was_selected: ?u64 = if (list.selected) |id| (if (id < self.profile_model.rows.len) self.profile_model.rows[id].identity else null) else null;
        list.selected = null;
        list.forgetOpenText(alloc);
        self.profile_generation +%= 1;
        // Tried once per draft: a failure is not tried again on every key.
        self.profile_stale = false;
        self.profile_model.build(alloc, pending, original) catch |err| {
            std.log.warn("settings: the profile list could not be built err={}", .{err});
            self.profile_model.deinit();
        };
        alloc.free(self.profile_found);
        self.profile_found = &.{};
        if (!self.profile_model.built()) return;
        self.profile_found = alloc.alloc(bool, self.profile_model.rows.len) catch &.{};
        @memset(self.profile_found, false);
        if (was_selected) |identity| list.selected = self.profile_model.find(identity);
    }

    /// Which profile rows the search finds (`profile_found`): by the profile's
    /// label and id, the field's name and its value; with `@modified`, every
    /// profile and field (a user profile is never a default). How many.
    fn findProfileRows(self: *SettingsWindow) u16 {
        self.ensureProfileModel();
        var found_count: u16 = 0;
        for (self.profile_found, 0..) |*found, id| {
            const row = self.profile_model.rows[id];
            found.* = self.search_query.matchesText(row.search) and (!self.search_query.modified or row.kind != .new_profile);
            if (found.*) found_count +|= 1;
        }
        self.profile_found_count = found_count;
        return found_count;
    }

    /// The rows the search found in a page's list, as last counted.
    fn listFoundCount(self: *const SettingsWindow, kind: ListKind) u16 {
        return switch (kind) {
            .reference => 0,
            .keybindings => self.keybind_found_count,
            .profiles => self.profile_found_count,
        };
    }

    /// Find a page's list's rows again (`findKeybindRows`, `findProfileRows`).
    fn findListRows(self: *SettingsWindow, kind: ListKind) u16 {
        return switch (kind) {
            .reference => 0,
            .keybindings => self.findKeybindRows(),
            .profiles => self.findProfileRows(),
        };
    }

    /// Whether the draft's profiles differ from the ones it started with.
    fn profileDraftDiffers(self: *const SettingsWindow) bool {
        return self.profile_changes != 0;
    }

    /// How many profile fields the draft changed (`profile_changes`).
    fn profileChangeCount(self: *const SettingsWindow) usize {
        return self.profile_changes;
    }

    /// Count the draft's profile changes again (`changedFieldCount`): after
    /// the page changed the draft, and whenever the draft or its baseline
    /// was replaced or merged (`referenceConfigChanged`, a save's disk
    /// check). The count is read on every edit anywhere in the window
    /// (`hasPendingChanges`), so it is not worked out there.
    fn refreshProfileChanges(self: *SettingsWindow) void {
        const original = if (self.original) |*config| config else {
            self.profile_changes = 0;
            return;
        };
        const pending = if (self.pending) |*config| config else {
            self.profile_changes = 0;
            return;
        };
        self.profile_changes = settings_profiles.changedFieldCount(original, pending);
    }

    /// Where the config in effect sets the field `row` shows
    /// (`config_origin.Index.ofProfile`), in the words the form's rows use,
    /// with the round-9 note when that line of the file Settings saves to
    /// has changed since. Nothing for a field no line set, or that the draft
    /// added.
    fn writeProfileOrigin(self: *SettingsWindow, row: settings_profiles.Row, writer: *std.Io.Writer) std.Io.Writer.Error!void {
        const profile = self.profile_model.profileOf(row) orelse return;
        const problems = self.originIndex() orelse return;
        const key: Config.Key, const name: ?[]const u8 = switch (row.kind) {
            .profile, .command => .{ .@"profile-command", null },
            .name => .{ .@"profile-name", null },
            .folder => .{ .@"profile-working-directory", null },
            .variable => .{ .@"profile-env", profile.variables[row.variable].name },
            .new_profile, .add_variable => return,
        };
        const found = problems.ofProfile(key, profile.id, name);
        const changed = switch (found) {
            .file => |file| self.originLineChanged(file),
            else => false,
        };
        try writeOriginNote(writer, found, changed);
    }

    /// The labels of what Enter and Delete do on a row of the Profiles page,
    /// which its open row shows and its menu offers. None for a profile from
    /// noctty's command line, which Settings does not change.
    pub const ProfileActions = struct { enter: ?[]const u8 = null, delete: ?[]const u8 = null };

    fn profileActions(self: *const SettingsWindow, row: settings_profiles.Row) ProfileActions {
        if (self.profile_model.profileOf(row)) |profile| if (profile.read_only) return .{};
        return switch (row.kind) {
            .new_profile => .{ .enter = "New profile (Enter)" },
            .profile => .{
                .enter = "Edit command line (Enter)",
                .delete = if (self.profile_remove_armed == row.identity) "Remove: press Delete again" else "Remove profile (Delete)",
            },
            .command => .{ .enter = "Edit (Enter)" },
            .name, .folder => .{ .enter = "Edit (Enter)", .delete = if (self.profile_model.emptyValue(row)) null else "Take out (Delete)" },
            .variable => .{ .enter = "Edit value (Enter)", .delete = "Take out (Delete)" },
            .add_variable => .{ .enter = "Add variable (Enter)" },
        };
    }

    /// The Profiles page's selected row, if one is selected and shown.
    fn selectedProfileRow(self: *const SettingsWindow) ?settings_profiles.Row {
        const list = &self.profile_list;
        if (list.selectedPosition() == null or !self.profile_model.built()) return null;
        const id = list.selected.?;
        if (id >= self.profile_model.rows.len) return null;
        return self.profile_model.rows[id];
    }

    /// Say `text` on the status line about the Profiles page: what a key
    /// did, or (`refused`) why Settings did not take a value. Never a value.
    fn setProfileNote(self: *SettingsWindow, comptime kind: enum { said, hint, refused }, comptime format: []const u8, args: anytype) void {
        self.freeNoteText();
        self.status_note = switch (kind) {
            .said => .profile_said,
            .hint => .profile_hint,
            .refused => .profile_refused,
        };
        self.note_text = std.fmt.allocPrint(self.handle.alloc, format, args) catch null;
        self.setStatus(self.noteText());
    }

    /// Enter, F2, a double click or UIA's Invoke on the Profiles page's
    /// selected row: type into its field, or start a profile or a variable.
    fn profileInvoke(self: *SettingsWindow) void {
        if (!self.profileEditDone()) return;
        const row = self.selectedProfileRow() orelse return;
        if (self.profile_model.profileOf(row)) |profile| if (profile.read_only) {
            return self.setProfileNote(.said, "Profile {s} comes from noctty's command line, so Settings does not change it.", .{profile.id});
        };
        self.beginProfileEdit(switch (row.kind) {
            .new_profile => .new_id,
            .profile, .command => .command,
            .name => .name,
            .folder => .folder,
            .variable => .variable,
            .add_variable => .new_variable,
        }, row, null);
    }

    /// Insert or Ctrl+N: a new profile, typed into the "New profile" row.
    fn profileNew(self: *SettingsWindow) void {
        if (!self.profileEditDone()) return;
        if (self.search_query.active()) self.clearSearch();
        const list = &self.profile_list;
        if (list.shown_count == 0) return;
        list.selectPosition(0);
        self.profileInvoke();
    }

    /// Delete on the Profiles page's selected row: a label, a starting folder
    /// or a variable goes at once (Discard brings it back); a profile goes on
    /// a second Delete, after the status line has said what removing it does.
    fn profileDelete(self: *SettingsWindow) void {
        if (!self.profileEditDone()) return;
        const row = self.selectedProfileRow() orelse return;
        const profile = self.profile_model.profileOf(row) orelse return;
        if (profile.read_only) {
            return self.setProfileNote(.said, "Profile {s} comes from noctty's command line, so Settings does not change it.", .{profile.id});
        }
        const pending = if (self.pending) |*config| config else return;
        var id_buf: [profile_map.max_id_len]u8 = undefined;
        const id = id_buf[0..profile.id.len];
        @memcpy(id, profile.id);
        switch (row.kind) {
            .new_profile, .add_variable => return,
            .command => return self.setProfileNote(.said, "A profile needs a command line. Delete on the profile's row removes profile {s}.", .{id}),
            .name, .folder => {
                if (self.profile_model.emptyValue(row)) return;
                settings_profiles.setField(pending, if (row.kind == .name) .name else .folder, id, "") catch return self.profileChangeFailed();
                self.profileDraftChanged(row.identity);
            },
            .variable => {
                const name = self.handle.alloc.dupe(u8, profile.variables[row.variable].name) catch return self.profileChangeFailed();
                defer self.handle.alloc.free(name);
                settings_profiles.removeVariable(pending, id, name) catch return self.profileChangeFailed();
                // The selection goes to what took the variable's place.
                self.profileDraftChanged(row.identity);
                if (self.profile_list.selected == null) self.selectProfileRow(settings_profiles.identity(.add_variable, id, null));
            },
            .profile => {
                if (self.profile_remove_armed != row.identity) {
                    self.profile_remove_armed = row.identity;
                    self.profile_list.metrics = null;
                    if (self.profile_list.hwnd) |list| _ = InvalidateRect(list, null, 0);
                    if (profile.default) return self.setProfileNote(
                        .said,
                        "Press Delete again to remove profile {s}. Default profile names it, so new tabs will open the automatic shell; Save writes the change.",
                        .{id},
                    );
                    return self.setProfileNote(.said, "Press Delete again to remove profile {s}. Save writes the change.", .{id});
                }
                self.profile_remove_armed = null;
                const original = if (self.original) |*config| config else return;
                settings_profiles.removeProfile(original, pending, id) catch return self.profileChangeFailed();
                // The rows after it move up: the selection takes the next
                // profile, or the one before, or New profile.
                const position = self.profile_list.selectedPosition() orelse 0;
                self.profileDraftChanged(null);
                const list = &self.profile_list;
                if (list.shown_count != 0) {
                    var at = @min(position, list.shown_count - 1);
                    while (at > 0 and self.profile_model.rows[list.shown[at]].kind.isField()) at -= 1;
                    list.selectPosition(at);
                }
                self.setProfileNote(.said, "Removed profile {s}. Save writes the change; Discard changes brings it back.", .{id});
            },
        }
    }

    /// Whether no field of the Profiles page is open, once an open one has
    /// kept what it holds (`.blur`): a click or a key elsewhere on the page
    /// acts only then, not on top of a value Settings refused, and never
    /// throws typed text away.
    fn profileEditDone(self: *SettingsWindow) bool {
        if (self.profile_edit == null) return true;
        return self.commitProfileEdit(.blur);
    }

    /// The first Delete on a profile asked for a second; anything else lets
    /// go of that.
    fn disarmProfileRemoval(self: *SettingsWindow) void {
        if (self.profile_remove_armed == null) return;
        self.profile_remove_armed = null;
        self.profile_list.metrics = null;
        if (self.profile_list.hwnd) |list| _ = InvalidateRect(list, null, 0);
        self.forgetProfileNote();
    }

    fn profileChangeFailed(self: *SettingsWindow) void {
        self.setProfileNote(.refused, "Error: the profile could not be changed. The draft keeps what it had.", .{});
    }

    fn selectProfileRow(self: *SettingsWindow, identity: u64) void {
        const id = self.profile_model.find(identity) orelse return;
        const list = &self.profile_list;
        for (list.shown[0..list.shown_count], 0..) |shown, position| if (shown == id) return list.selectPosition(position);
    }

    /// The draft's profiles changed: the page shows them again, the
    /// selection on `select` (a row's identity) or on the row it was on, and
    /// Save, the rail's marker and the title follow.
    fn profileDraftChanged(self: *SettingsWindow, select: ?u64) void {
        self.refreshProfileChanges();
        self.profile_stale = true;
        self.ensureProfileModel();
        if (select) |identity| self.profile_list.selected = self.profile_model.find(identity);
        if (self.search_query.active()) {
            const was = self.profile_found_count;
            const now = self.findProfileRows();
            const counts = &self.search_counts[@intFromEnum(Section.profiles)];
            counts.* = counts.* - was + now;
            self.search_total = self.search_total - was + now;
            self.syncSearchCounts();
        }
        self.refreshListShown(&self.profile_list, false);
        self.profile_list.revealSelected(.unless_shown);
        self.freeNoteText();
        self.status_note = .applies_on_save;
        self.updateSaveEnabled();
    }

    /// Start typing into a field of the Profiles page: a text field over the
    /// open row (`placeProfileEdit`), holding the field's value, named for
    /// UIA after the field and its profile. `id` is the new profile's, for
    /// `.new_command`.
    fn beginProfileEdit(self: *SettingsWindow, kind: ProfileEdit.Kind, row: settings_profiles.Row, new_id: ?[]const u8) void {
        self.disarmProfileRemoval();
        self.cancelProfileEdit();
        const list = self.profile_list.hwnd orelse return;
        const alloc = self.handle.alloc;
        var edit: ProfileEdit = .{ .kind = kind, .row = row.identity };
        const profile = self.profile_model.profileOf(row);
        if (new_id orelse if (profile) |p| p.id else null) |id| edit.setId(id);
        if (kind == .variable) edit.name = alloc.dupe(u8, profile.?.variables[row.variable].name) catch return;
        const initial: []const u8 = switch (kind) {
            .new_id, .new_command, .new_variable => "",
            .command => profile.?.command,
            .name => profile.?.label orelse "",
            .folder => profile.?.folder orelse "",
            .variable => profile.?.variables[row.variable].value,
        };
        const wide = std.unicode.utf8ToUtf16LeAllocZ(alloc, initial) catch {
            if (edit.name) |name| alloc.free(name);
            return;
        };
        defer alloc.free(wide);
        const hwnd = sys.CreateWindowExW(
            0,
            std.unicode.utf8ToUtf16LeStringLiteral("EDIT"),
            wide.ptr,
            WS_CHILD | WS_BORDER | ES_AUTOHSCROLL,
            0,
            0,
            1,
            1,
            list,
            @ptrFromInt(PROFILE_EDIT),
            self.handle.hinstance,
            null,
        ) orelse {
            if (edit.name) |name| alloc.free(name);
            return;
        };
        _ = self.finishChild(hwnd, self.ui_font, .control);
        // A line of the config file holds at most this much.
        _ = sys.SendMessageW(hwnd, EM_LIMITTEXT, LineIterator.max_line_len, 0);
        subclassKeepingPrevious(hwnd, &profileEditProc);
        edit.hwnd = hwnd;
        edit.writeLabel();
        self.profile_edit = edit;
        const stored = &self.profile_edit.?;
        if (self.canInitializeCustomUiaProviders()) {
            stored.provider = win32_uia.SettingsControlProvider.create(std.heap.page_allocator, hwnd, .edit, stored.label()) catch |err| blk: {
                std.log.warn("settings: profile field UIA provider unavailable err={}", .{err});
                break :blk null;
            };
            if (stored.provider) |provider| provider.help_text = profile_edit_help;
        }
        // The open row makes room for the field.
        self.profile_list.metrics = null;
        self.profile_list.revealSelected(.whole);
        if (self.profile_list.hwnd) |list_hwnd| _ = InvalidateRect(list_hwnd, null, 0);
        self.placeProfileEdit();
        _ = sys.SendMessageW(hwnd, EM_SETSEL, 0, -1);
        _ = SetFocus(hwnd);
        switch (kind) {
            .new_id => self.setProfileNote(.hint, "Type the new profile's id, then press Enter. Escape cancels.", .{}),
            .new_command => self.setProfileNote(.hint, "Type the command line of profile {s}, then press Enter. Escape cancels.", .{stored.id()}),
            .new_variable => self.setProfileNote(.hint, "Type the variable as NAME=VALUE, then press Enter. Escape cancels.", .{}),
            else => self.setProfileNote(.hint, "Enter keeps the change and Escape cancels it.", .{}),
        }
    }

    /// Put the field being typed into over its row, below the row's title, or
    /// hide it while the row is not in the list's view.
    fn placeProfileEdit(self: *SettingsWindow) void {
        const edit = self.profile_edit orelse return;
        const hwnd = edit.hwnd orelse return;
        const list = &self.profile_list;
        const metrics = list.ensureMetrics() orelse return;
        const position = list.selectedPosition() orelse {
            _ = ShowWindow(hwnd, SW_HIDE);
            return;
        };
        const top = ReferenceList.rowTop(metrics, position, position) - list.scroll_y + 2 * metrics.pad_y + metrics.title + metrics.gap;
        const left = metrics.pad_x + metrics.bar + list.indentOf(metrics, list.shown[position]);
        const width = @max(1, metrics.width - left - metrics.pad_x);
        _ = SetWindowPos(hwnd, null, left, top, width, @max(1, metrics.field - metrics.gap), SWP_NOZORDER | SWP_NOACTIVATE);
        _ = ShowWindow(hwnd, SW_SHOWNA);
    }

    /// The text of the field being typed into changed (`EN_CHANGE`): Save is
    /// enabled for it from the first key, as for a form field.
    fn profileEditTyped(self: *SettingsWindow) void {
        const field = if (self.profile_edit) |*edit| edit else return;
        if (field.typed) return;
        field.typed = true;
        self.updateSaveEnabled();
    }

    /// Whether a field of the Profiles page is open with text typed into it.
    fn profileEditTypedInto(self: *const SettingsWindow) bool {
        const edit = self.profile_edit orelse return false;
        return edit.typed;
    }

    /// The field being typed into lost the focus (posted, so the focus has
    /// landed): what it holds is kept, as a form field's is.
    fn profileEditBlurred(self: *SettingsWindow) void {
        const edit = self.profile_edit orelse return;
        const focused = GetFocus() orelse return;
        if (focused == edit.hwnd) return;
        // Another window took the focus (Alt+Tab, Win+V): the field stays,
        // and gets the focus back with the window (`rememberFocus`).
        const window = self.hwnd orelse return;
        if (focused != window and IsChild(window, focused) == 0) return;
        _ = self.commitProfileEdit(.blur);
    }

    /// Keep what the field being typed into holds, trimmed, as its change to
    /// the draft. A value Settings refuses keeps the field open, its reason on
    /// the status line, whether the focus is in it (`.stay`: Enter, Tab,
    /// Save) or went elsewhere in the window (`.blur`), so a save started
    /// with the mouse stops at it too. When the field has to go (`.closing`:
    /// its page goes, or the window or the app closes), a refused value is
    /// dropped and the status line says so. A new profile or variable left
    /// empty by a blur or a close is just let go. Returns whether no field is
    /// open any more.
    fn commitProfileEdit(self: *SettingsWindow, how: enum { stay, blur, closing }) bool {
        const edit = &(self.profile_edit orelse return true);
        const hwnd = edit.hwnd orelse return true;
        const alloc = self.handle.alloc;
        const pending = if (self.pending) |*config| config else {
            self.cancelProfileEdit();
            return true;
        };
        const text_w_len: usize = @intCast(@max(0, sys.GetWindowTextLengthW(hwnd)));
        const text_w = alloc.allocSentinel(u16, text_w_len, 0) catch return false;
        defer alloc.free(text_w);
        const copied: usize = @intCast(@max(0, sys.GetWindowTextW(hwnd, text_w.ptr, @intCast(text_w_len + 1))));
        const raw = std.unicode.utf16LeToUtf8Alloc(alloc, text_w[0..copied]) catch {
            return self.refuseProfileEdit(how, "That text cannot be saved.");
        };
        defer alloc.free(raw);
        const text = std.mem.trim(u8, raw, &std.ascii.whitespace);
        var id_buf: [profile_map.max_id_len]u8 = undefined;
        const id = id_buf[0..edit.id_len];
        @memcpy(id, edit.id());
        const new_kind = switch (edit.kind) {
            .new_id, .new_command, .new_variable => true,
            else => false,
        };
        if (how != .stay and new_kind and text.len == 0) {
            self.cancelProfileEdit();
            return true;
        }
        const select: u64 = switch (edit.kind) {
            .new_id => {
                if (settings_profiles.checkNewId(pending, text)) |message| return self.refuseProfileEdit(how, message);
                // The id is taken; the command line comes next, in its own
                // field, on the same row. A field that lost the focus keeps
                // nothing: a profile needs both.
                if (how != .stay) {
                    self.cancelProfileEdit();
                    self.setProfileNote(.said, "No profile was added: a profile needs an id and a command line.", .{});
                    return true;
                }
                const row = self.selectedProfileRow() orelse return true;
                self.beginProfileEdit(.new_command, row, text);
                return false;
            },
            .new_command, .command => blk: {
                if (settings_profiles.checkCommand(id, text)) |message| return self.refuseProfileEdit(how, message);
                // The file may have defined the id since it was typed (an
                // external reload).
                if (edit.kind == .new_command) if (settings_profiles.checkNewId(pending, id)) |message| return self.refuseProfileEdit(how, message);
                if (edit.kind == .command) if (self.profile_model.find(edit.row)) |row_id| {
                    const profile = self.profile_model.profileOf(self.profile_model.rows[row_id]).?;
                    if (std.mem.eql(u8, profile.command, text)) {
                        self.cancelProfileEdit();
                        return true;
                    }
                };
                settings_profiles.setCommand(pending, id, text) catch return self.refuseProfileEdit(how, "The profile could not be changed.");
                break :blk settings_profiles.identity(if (edit.kind == .new_command) .profile else .command, id, null);
            },
            .name, .folder => blk: {
                const refused = if (edit.kind == .name) settings_profiles.checkText(.name, id, text) else settings_profiles.checkText(.text, id, text);
                if (refused) |message| return self.refuseProfileEdit(how, message);
                settings_profiles.setField(pending, if (edit.kind == .name) .name else .folder, id, text) catch
                    return self.refuseProfileEdit(how, "The profile could not be changed.");
                break :blk edit.row;
            },
            .variable => blk: {
                const name = edit.name.?;
                if (settings_profiles.checkVariableValue(id, name, text)) |message| return self.refuseProfileEdit(how, message);
                settings_profiles.setVariable(pending, id, name, text) catch return self.refuseProfileEdit(how, "The profile could not be changed.");
                break :blk edit.row;
            },
            .new_variable => blk: {
                const variable = switch (settings_profiles.checkNewVariable(id, text)) {
                    .refused => |message| return self.refuseProfileEdit(how, message),
                    .ok => |value| value,
                };
                settings_profiles.setVariable(pending, id, variable.name, variable.value) catch return self.refuseProfileEdit(how, "The profile could not be changed.");
                break :blk settings_profiles.identity(.variable, id, variable.name);
            },
        };
        self.endProfileEdit();
        self.profileDraftChanged(select);
        return true;
    }

    /// A value Settings will not take (`message` names the field, never the
    /// value). Returns whether the field went (`.blur`).
    fn refuseProfileEdit(self: *SettingsWindow, how: anytype, message: []const u8) bool {
        if (how == .closing) {
            self.cancelProfileEdit();
            self.setProfileNote(.refused, "Error: the change was not kept. {s}", .{message});
            return true;
        }
        self.setProfileNote(.refused, "Error: {s}", .{message});
        return false;
    }

    /// Escape, or a page or a draft that starts over: the field goes and the
    /// draft keeps what it had.
    fn cancelProfileEdit(self: *SettingsWindow) void {
        if (self.profile_edit == null) return;
        self.endProfileEdit();
        self.forgetProfileNote();
    }

    /// What the status line said about the Profiles page's field, or about a
    /// removal waiting for its second Delete, is over: the line says what it
    /// says when idle. A save's or a reset's outcome stays.
    fn forgetProfileNote(self: *SettingsWindow) void {
        switch (self.status_note) {
            .profile_said, .profile_hint, .profile_refused => {},
            else => return,
        }
        self.freeNoteText();
        self.status_note = .none;
        self.syncIdleStatus();
    }

    /// The field being typed into goes: the focus back to its list first, so
    /// the focus leaving it finds no field to keep (`profileEditBlurred`).
    fn endProfileEdit(self: *SettingsWindow) void {
        var edit = self.profile_edit orelse return;
        self.profile_edit = null;
        if (edit.hwnd) |hwnd| {
            if (GetFocus() == hwnd) if (self.profile_list.hwnd) |list| {
                _ = SetFocus(list);
            };
            self.releaseProfileEditProvider(&edit);
            _ = sys.DestroyWindow(hwnd);
        }
        if (edit.name) |name| self.handle.alloc.free(name);
        self.profile_list.metrics = null;
        if (self.profile_list.hwnd) |list| _ = InvalidateRect(list, null, 0);
        // Typed text was an edit Save and Discard were enabled for
        // (`profileEditTyped`); a field that goes without changing the
        // draft takes that back.
        if (edit.typed) self.updateSaveEnabled();
    }

    fn releaseProfileEditProvider(self: *SettingsWindow, edit: *ProfileEdit) void {
        const provider = edit.provider orelse return;
        edit.provider = null;
        provider.detach();
        self.deferProviderDisconnect(@ptrCast(provider), settingsControlDisconnect, settingsControlRelease);
    }

    /// The field's window is going without `endProfileEdit` (its list or the
    /// window went first): let go of what it held.
    fn profileEditDestroyed(self: *SettingsWindow, hwnd: HWND) void {
        const edit = &(self.profile_edit orelse return);
        if (edit.hwnd != hwnd) return;
        self.releaseProfileEditProvider(edit);
        if (edit.name) |name| self.handle.alloc.free(name);
        self.profile_edit = null;
    }

    /// The Profiles list's menu (Shift+F10, the menu key, a right click): what
    /// Enter and Delete do on the row, a new profile, and the config file.
    fn showProfileMenu(self: *SettingsWindow, menu: HMENU, at: POINT, frame: HWND) void {
        const row = self.selectedProfileRow() orelse return;
        const actions = self.profileActions(row);
        var item_w: [96]u16 = undefined;
        var item_buf: [96]u8 = undefined;
        if (actions.enter) |label| _ = sys.AppendMenuW(menu, MF_STRING, reference_menu_edit, utf8ToW(&item_w, profileMenuLabel(&item_buf, label)));
        if (actions.delete) |label| _ = sys.AppendMenuW(menu, MF_STRING, reference_menu_copy, utf8ToW(&item_w, profileMenuLabel(&item_buf, label)));
        if (row.kind != .new_profile) _ = sys.AppendMenuW(menu, MF_STRING, profile_menu_new, std.unicode.utf8ToUtf16LeStringLiteral("&New profile\tInsert"));
        _ = sys.AppendMenuW(menu, MF_STRING, reference_menu_open, std.unicode.utf8ToUtf16LeStringLiteral("&Open config file"));
        const picked: usize = if (self.context_menu_pick) |pick|
            pick(menu)
        else
            @intCast(@max(0, sys.TrackPopupMenu(menu, TPM_RETURNCMD | TPM_RIGHTBUTTON, at.x, at.y, 0, frame, null)));
        switch (picked) {
            reference_menu_edit => self.profileInvoke(),
            reference_menu_copy => self.profileDelete(),
            profile_menu_new => self.profileNew(),
            reference_menu_open => self.handle.openInEditor(self.handle.ctx),
            else => {},
        }
    }

    /// The list for `section`, if the page has one.
    fn sectionList(self: *SettingsWindow, section: Section) ?*ReferenceList {
        return switch (section) {
            .reference => &self.reference_list,
            .keybindings => &self.keybind_list,
            .profiles => &self.profile_list,
            else => null,
        };
    }

    fn ensureListModel(self: *SettingsWindow, list: *const ReferenceList) void {
        switch (list.kind) {
            .reference => self.ensureReferenceModel(),
            .keybindings => self.ensureKeybindModel(),
            .profiles => self.ensureProfileModel(),
        }
    }

    /// The All settings list's rows (`refreshListShown`).
    fn refreshReferenceShown(self: *SettingsWindow, from_top: bool) void {
        self.refreshListShown(&self.reference_list, from_top);
    }

    /// The rows `list` shows: every row of its model, or with a search the
    /// ones it found (`reference_found`, `keybind_found`), in the model's
    /// order. The selection stays with its row, hidden while the search hides
    /// it. `from_top` scrolls the list back to its first row.
    fn refreshListShown(self: *SettingsWindow, list: *ReferenceList, from_top: bool) void {
        const alloc = self.handle.alloc;
        const filtering = self.search_query.active();
        const total: usize = if (!list.modelBuilt()) 0 else switch (list.kind) {
            .reference => settings_reference.key_count,
            .keybindings => self.keybind_model.rows.len,
            .profiles => self.profile_model.rows.len,
        };
        if (list.shown.len < total) {
            alloc.free(list.shown);
            list.shown = alloc.alloc(u16, total) catch &.{};
        }
        var count: usize = 0;
        for (0..@min(total, list.shown.len)) |id| {
            const found = switch (list.kind) {
                .reference => self.reference_found[id],
                .keybindings => id < self.keybind_found.len and self.keybind_found[id],
                .profiles => id < self.profile_found.len and self.profile_found[id],
            };
            if (filtering and !found) continue;
            list.shown[count] = @intCast(id);
            count += 1;
        }
        list.shown_count = count;
        if (from_top) list.scroll_y = 0;
        list.contentChanged();
        // A reader that holds the rows asks for them again, as the palette's do.
        if (list.provider) |provider| win32_uia.events.raiseStructureChanged(&provider.base, .children_invalidated, null);
    }

    /// Work out row `index`'s origin note from `current`; whether it changed.
    fn refreshOriginNote(self: *SettingsWindow, index: usize) bool {
        var note: OriginNote = .{};
        if (self.current) |*current| {
            self.proof_origin_lookups +%= 1;
            const key = field_model.form_fields[index].descriptor.key;
            const found = if (self.originIndex()) |problems|
                settings_reference.savedOriginIn(problems, key, null)
            else
                settings_reference.savedOrigin(current, key, null);
            const changed = switch (found) {
                .file => |file| self.originLineChanged(file),
                else => false,
            };
            var writer: std.Io.Writer = .fixed(&note.buf);
            writeOriginNote(&writer, found, changed) catch {
                // A file name too long for the label: the line alone.
                writer = .fixed(&note.buf);
                if (found == .file) {
                    writer.print("Set in a file, line {d}", .{found.file.line}) catch {};
                    if (changed) writer.writeAll(origin_changed_note) catch {};
                }
            };
            note.len = @intCast(writer.buffered().len);
        }
        const old = &self.origin_notes[index];
        if (std.mem.eql(u8, old.text(), note.text())) return false;
        old.* = note;
        return true;
    }

    /// Whether `file`, the line a row's value came from, is a line of the file
    /// Settings saves to that no longer holds what the loader took there
    /// (`settings_reference.TargetLines.holds`). Not known, and so not said,
    /// for any other file, which Settings does not read.
    fn originLineChanged(self: *SettingsWindow, file: config_origin.Origin.File) bool {
        const now = self.targetNow() orelse return false;
        return settings_reference.samePath(file.path, now.path) and !now.lines.holds(file.line);
    }

    /// The file Settings saves to as it is now (`target_now`), read the first
    /// time it is asked for after the config changed.
    fn targetNow(self: *SettingsWindow) ?*const TargetNow {
        if (!self.target_read) {
            self.target_read = true;
            self.target_now = self.readTargetNow();
        }
        return if (self.target_now) |*now| now else null;
    }

    /// `origin_index`, made the first time it is asked for after `current`
    /// changed; null when it cannot be made (the rows then look up without
    /// it).
    fn originIndex(self: *SettingsWindow) ?*const config_origin.Index {
        if (self.origin_index == null) {
            const current = if (self.current) |*config| config else return null;
            self.origin_index = config_origin.Index.init(self.handle.alloc, current) catch return null;
        }
        return &self.origin_index.?;
    }

    fn readTargetNow(self: *SettingsWindow) ?TargetNow {
        const read = self.handle.configSource orelse return null;
        const problems = self.originIndex() orelse return null;
        const alloc = self.handle.alloc;
        var source = read(self.handle.ctx, alloc);
        defer source.deinit(alloc);
        const path = source.path orelse return null;
        var arena: std.heap.ArenaAllocator = .init(alloc);
        defer arena.deinit();
        const text: []const u8 = switch (source.file) {
            .missing => "",
            .bytes => |bytes| (settings_reference.decodeConfigText(arena.allocator(), bytes) catch return null) orelse return null,
            .none, .unavailable => return null,
        };
        var lines = settings_reference.TargetLines.init(alloc, problems, path, text) catch return null;
        const owned = alloc.dupe(u8, path) catch {
            lines.deinit(alloc);
            return null;
        };
        return .{ .path = owned, .lines = lines };
    }

    /// Drop what was worked out from `current` (`target_now`,
    /// `origin_index`): before `current` is replaced or freed, which the
    /// index borrows, and when it changed.
    fn forgetTarget(self: *SettingsWindow) void {
        if (self.target_now) |*now| now.deinit(self.handle.alloc);
        self.target_now = null;
        self.target_read = false;
        if (self.origin_index) |*problems| problems.deinit(self.handle.alloc);
        self.origin_index = null;
    }

    /// `current` changed: every made row's origin note again, on every page,
    /// its label repainted and its description renewed when the note changed.
    fn syncOriginNotes(self: *SettingsWindow) void {
        var changed = false;
        for (std.enums.values(Section)) |section| for (formItemsForSection(section)) |item| {
            if (item.control_index >= form_field_count) continue;
            if (self.controlHwnd(item.control_index) == null) continue;
            if (!self.refreshOriginNote(item.control_index)) continue;
            changed = true;
            if (item.label_index) |label_index| if (self.field_labels[label_index]) |label| {
                _ = InvalidateRect(label, null, 0);
            };
        };
        if (changed and self.pending != null) self.syncDefaultMarks();
    }

    /// The origin note of the row `label` names, when it has one.
    fn labelOriginNote(self: *const SettingsWindow, label: HWND) ?[]const u8 {
        for (std.enums.values(Section)) |section| for (formItemsForSection(section)) |item| {
            if (item.control_index >= form_field_count) continue;
            const label_index = item.label_index orelse continue;
            if (self.field_labels[label_index] != label) continue;
            const note = self.origin_notes[item.control_index].text();
            return if (note.len == 0) null else note;
        };
        return null;
    }

    /// A field's MSAA description: that it differs from its default, and
    /// where its saved value comes from, written to `buf`. Empty for neither.
    fn fieldDescription(self: *const SettingsWindow, index: usize, differs: bool, buf: []u8) []const u8 {
        const note = self.origin_notes[index].text();
        const changed = win32_uia.SettingsControlProvider.changed_from_default_status;
        return if (differs and note.len != 0)
            std.fmt.bufPrint(buf, "{s}. {s}.", .{ changed, note }) catch changed
        else if (differs)
            changed
        else if (note.len != 0)
            std.fmt.bufPrint(buf, "{s}.", .{note}) catch ""
        else
            "";
    }

    /// A form row's label, drawn by the viewport (`SS_OWNERDRAW`): the label
    /// on the left, in the colours a label takes, and its origin note on the
    /// right in the same. When the line is too narrow for both, the label is
    /// shortened, not the note.
    fn paintFieldLabel(self: *SettingsWindow, draw: *const sys.DRAWITEMSTRUCT) void {
        const colors = self.theme_adapter.colors;
        const hdc = draw.hDC;
        const rect = draw.rcItem;
        fillSolid(hdc, rect, colors.window_bg);
        const font: HGDIOBJ = @ptrFromInt(@as(usize, @bitCast(SendMessageW(draw.hwndItem, WM_GETFONT, 0, 0))));
        const previous_font = if (font) |value| SelectObject(hdc, value) else null;
        defer {
            if (previous_font) |value| _ = SelectObject(hdc, value);
        }
        _ = sys.SetBkMode(hdc, TRANSPARENT);
        _ = SetTextColor(hdc, if (sys.IsWindowEnabled(draw.hwndItem) == 0) colors.disabled_text else colors.secondary_text);
        var label: [256:0]u16 = undefined;
        const length = GetWindowTextW(draw.hwndItem, &label, @intCast(label.len));
        var label_right = rect.right;
        if (self.labelOriginNote(draw.hwndItem)) |note| {
            // The label keeps its width, up to half the line; the note takes
            // what is left, its file name shortened in the middle so that the
            // line number stays (the MSAA description has it whole).
            const gap = self.px(settings_metrics.space_4);
            var label_size: RECT = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
            if (length > 0) _ = DrawTextW(hdc, &label, length, &label_size, DT_SINGLELINE | DT_NOPREFIX | DT_CALCRECT);
            const keep = @min(label_size.right - label_size.left, @divTrunc(rect.right - rect.left - gap, 2));
            const room = rect.right - rect.left - gap - keep;
            var note_w: [OriginNote.capacity + 1:0]u16 = undefined;
            const wide = utf8ToW(&note_w, note);
            var measured: RECT = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
            _ = DrawTextW(hdc, wide, -1, &measured, DT_SINGLELINE | DT_NOPREFIX | DT_CALCRECT);
            if (room > 0) {
                var note_rect = rect;
                note_rect.left = rect.right - @min(measured.right - measured.left, room);
                _ = DrawTextW(hdc, wide, -1, &note_rect, DT_SINGLELINE | DT_NOPREFIX | DT_RIGHT | DT_PATH_ELLIPSIS);
                label_right = note_rect.left - gap;
            }
        }
        if (length > 0) {
            var label_rect = rect;
            label_rect.right = label_right;
            _ = DrawTextW(hdc, &label, length, &label_rect, DT_SINGLELINE | DT_NOPREFIX | DT_END_ELLIPSIS);
        }
    }

    /// The config the lists show changed (a reload, a save, a discard, the
    /// window opening): their models are built again when next needed, at
    /// once for a list that is shown. A search keeps the rows it found until
    /// it runs again, as the other pages keep theirs. The form's origin notes
    /// are worked out again at once.
    fn referenceConfigChanged(self: *SettingsWindow) void {
        self.reference_stale = true;
        self.keybind_stale = true;
        self.profile_stale = true;
        self.refreshProfileChanges();
        self.forgetTarget();
        self.syncOriginNotes();
        if (self.hwnd == null) return;
        const list = self.sectionList(self.active_section) orelse return;
        self.ensureListModel(list);
        // A rebuilt binding model has no rows found: its bindings are found
        // again, and the page's count, help and layout follow. The rest of the
        // search keeps what it found, as on any page.
        if (list.kind != .reference and self.search_query.active()) {
            const was = self.listFoundCount(list.kind);
            const now = self.findListRows(list.kind);
            const counts = &self.search_counts[@intFromEnum(self.active_section)];
            counts.* = counts.* - was + now;
            self.search_total = self.search_total - was + now;
            self.refreshListShown(list, false);
            self.syncSearchCounts();
            self.refreshNativeSectionText();
            // A list that held the focus and now shows nothing gives it to
            // the search field, as a search does, before it leaves the screen.
            self.keepFocusShown();
            layoutChildren(self);
            self.applySectionVisibility();
            return;
        }
        self.refreshListShown(list, false);
    }

    /// Make `list`, hidden, for its page: the layout places it and
    /// `applySectionVisibility` shows it. One window, so the page costs one
    /// window while it is shown and none otherwise.
    fn createList(self: *SettingsWindow, list_state: *ReferenceList) void {
        if (list_state.hwnd != null) return;
        const viewport = self.viewport orelse return;
        if (self.reference_list_class_atom == 0) {
            const wc: WNDCLASSEXW = .{
                .cbSize = @sizeOf(WNDCLASSEXW),
                .style = CS_DBLCLKS,
                .lpfnWndProc = &referenceListProc,
                .cbClsExtra = 0,
                .cbWndExtra = 0,
                .hInstance = self.handle.hinstance,
                .hIcon = null,
                .hCursor = sys.LoadCursorW(null, @ptrFromInt(IDC_ARROW)),
                .hbrBackground = null,
                .lpszMenuName = null,
                .lpszClassName = reference_list_class_name,
                .hIconSm = null,
            };
            self.reference_list_class_atom = sys.RegisterClassExW(&wc);
            if (self.reference_list_class_atom == 0) {
                std.log.warn("settings: the All settings list class could not be registered", .{});
                return;
            }
        }
        const list = sys.CreateWindowExW(
            0,
            reference_list_class_name,
            switch (list_state.kind) {
                .reference => std.unicode.utf8ToUtf16LeStringLiteral("All settings"),
                .keybindings => std.unicode.utf8ToUtf16LeStringLiteral("Key bindings"),
                .profiles => std.unicode.utf8ToUtf16LeStringLiteral("Profiles"),
            },
            // The Profiles list holds the field being typed into.
            WS_CHILD | WS_TABSTOP | WS_GROUP | WS_VSCROLL | if (list_state.kind == .profiles) WS_CLIPCHILDREN else 0,
            0,
            0,
            1,
            1,
            viewport,
            @ptrFromInt(switch (list_state.kind) {
                .reference => REFERENCE_LIST,
                .keybindings => KEYBIND_LIST,
                .profiles => PROFILE_LIST,
            }),
            self.handle.hinstance,
            list_state,
        ) orelse {
            std.log.warn("settings: a settings list could not be made kind={t}", .{list_state.kind});
            return;
        };
        // Its scroll bar takes the theme; it draws its own text.
        list_state.hwnd = self.finishChild(list, null, .control);
        list_state.metrics = null;
        list_state.wheel_remainder = 0;
        if (self.canInitializeCustomUiaProviders()) {
            list_state.provider = win32_uia.PaletteListProvider.create(
                std.heap.page_allocator,
                list,
                referenceListUiaState(list_state),
            ) catch |err| blk: {
                std.log.warn("settings: settings list UIA provider unavailable kind={t} err={}", .{ list_state.kind, err });
                break :blk null;
            };
        }
        list_state.contentChanged();
    }

    /// `list`'s page goes: the list with it. A list that holds the focus
    /// gives it to `next`'s rail button first, which takes it ahead of the
    /// switch (`focusRailButtonAhead`), as the switch's own focus moves do.
    fn destroyList(self: *SettingsWindow, list_state: *ReferenceList, next: Section) void {
        const list = list_state.hwnd orelse return;
        // A field being typed into goes with the page, kept as when it loses
        // the focus.
        if (list_state.kind == .profiles) _ = self.commitProfileEdit(.closing);
        if (GetFocus() == list) self.focusRailButtonAhead(next);
        if (list_state.provider) |provider| provider.raiseTeardown();
        _ = sys.DestroyWindow(list);
    }

    /// A list window is gone (`WM_NCDESTROY`): its provider is let go, and
    /// what was drawn from the model with it.
    fn listDestroyed(self: *SettingsWindow, list: *ReferenceList) void {
        list.hwnd = null;
        list.metrics = null;
        if (list.provider) |provider| {
            list.provider = null;
            provider.detach();
            self.deferProviderDisconnect(@ptrCast(provider), referenceListDisconnect, referenceListRelease);
        }
    }

    /// Everything the All settings and Keybindings pages hold, for a window
    /// that is gone: the models are built again from the config the next
    /// window opens with.
    fn forgetReference(self: *SettingsWindow) void {
        const alloc = self.handle.alloc;
        self.forgetTarget();
        for ([_]*ReferenceList{ &self.reference_list, &self.keybind_list, &self.profile_list }) |list| {
            list.forgetOpenText(alloc);
            list.forgetRows(alloc);
        }
        alloc.free(self.profile_found);
        self.profile_found = &.{};
        self.profile_found_count = 0;
        self.profile_model.deinit();
        self.profile_stale = true;
        self.profile_remove_armed = null;
        self.reference_found = @splat(false);
        self.reference_model.deinit();
        self.reference_stale = true;
        alloc.free(self.keybind_found);
        self.keybind_found = &.{};
        self.keybind_found_count = 0;
        self.keybind_model.deinit();
        self.keybind_stale = true;
    }

    /// Copy binding `id` (a row of `keybind_model`) as config lines through
    /// the app's clipboard, and say so on the status line.
    fn copyKeybind(self: *SettingsWindow, id: usize) void {
        const copy = self.handle.copyText orelse return;
        if (id >= self.keybind_model.rows.len) return;
        const row = &self.keybind_model.rows[id];
        const copied = copy(self.handle.ctx, row.entry);
        const note: StatusNote = if (copied) .key_copied else .key_copy_failed;
        self.freeNoteText();
        self.status_note = note;
        var detail_buf: [256]u8 = undefined;
        const detail = std.fmt.bufPrint(&detail_buf, "the binding for {s}", .{row.trigger}) catch "the binding";
        self.note_text = note.textWithDetail(self.handle.alloc, detail) catch null;
        self.setStatus(self.noteText());
    }

    /// Copy key `key`'s name (an index into `settings_reference.keys`) through the
    /// app's clipboard, and say so on the status line.
    fn copyReferenceKey(self: *SettingsWindow, key: usize) void {
        const copy = self.handle.copyText orelse return;
        const name = @tagName(settings_reference.keys[key]);
        const copied = copy(self.handle.ctx, name);
        const note: StatusNote = if (copied) .key_copied else .key_copy_failed;
        self.freeNoteText();
        self.status_note = note;
        self.note_text = note.textWithDetail(self.handle.alloc, name) catch null;
        self.setStatus(self.noteText());
    }

    /// Whether key `key` has an edit in this window that is not saved yet: the
    /// value the All settings page shows is the one in effect.
    fn referenceKeyDirty(self: *const SettingsWindow, key: usize) bool {
        for (reference_form_rows[key]) |row| if (self.rowDirtyAt(row)) return true;
        return false;
    }

    /// `rowDirty` for form row `index`.
    fn rowDirtyAt(self: *const SettingsWindow, index: usize) bool {
        inline for (field_model.form_fields, 0..) |row, i| if (i == index) return self.rowDirty(row);
        return false;
    }
};

const IAccPropServicesVtbl = extern struct {
    QueryInterface: *const fn (*anyopaque, *const GUID, *?*anyopaque) callconv(.winapi) HRESULT,
    AddRef: *const fn (*anyopaque) callconv(.winapi) u32,
    Release: *const fn (*anyopaque) callconv(.winapi) u32,
    SetPropValue: *const anyopaque,
    SetPropServer: *const anyopaque,
    ClearProps: *const anyopaque,
    SetHwndProp: *const anyopaque,
    SetHwndPropStr: *const fn (
        *anyopaque,
        HWND,
        u32,
        u32,
        GUID,
        LPCWSTR,
    ) callconv(.winapi) HRESULT,
    SetHwndPropServer: *const anyopaque,
    ClearHwndProps: *const fn (
        *anyopaque,
        HWND,
        u32,
        u32,
        [*]const GUID,
        c_int,
    ) callconv(.winapi) HRESULT,
};

const IAccPropServices = extern struct {
    vtbl: *const IAccPropServicesVtbl,

    fn asRaw(self: *IAccPropServices) *anyopaque {
        return @ptrCast(self);
    }

    fn release(self: *IAccPropServices) void {
        _ = self.vtbl.Release(self.asRaw());
    }

    fn addRef(self: *IAccPropServices) *IAccPropServices {
        _ = self.vtbl.AddRef(self.asRaw());
        return self;
    }

    fn setName(self: *IAccPropServices, hwnd: HWND, comptime name: []const u8) HRESULT {
        return self.vtbl.SetHwndPropStr(
            self.asRaw(),
            hwnd,
            OBJID_CLIENT,
            CHILDID_SELF,
            PROPID_ACC_NAME,
            std.unicode.utf8ToUtf16LeStringLiteral(name),
        );
    }
};

fn createAccPropServices() ?*IAccPropServices {
    var raw: ?*anyopaque = null;
    const hr = sys.CoCreateInstance(
        &CLSID_ACC_PROP_SERVICES,
        null,
        CLSCTX_INPROC_SERVER,
        &IID_IACC_PROP_SERVICES,
        &raw,
    );
    if (hr < 0 or raw == null) return null;
    return @ptrCast(@alignCast(raw.?));
}

fn setAccessibleName(service: *IAccPropServices, hwnd_opt: ?HWND, comptime name: []const u8) void {
    const hwnd = hwnd_opt orelse return;
    const hr = service.setName(hwnd, name);
    if (hr < 0) {
        std.log.warn("settings: failed to set accessible name '{s}' hr=0x{x}", .{
            name,
            @as(u32, @bitCast(hr)),
        });
    }
}

/// `setAccessibleName` for a name made at run time. Whether it took.
fn setAccessibleNameText(service: *IAccPropServices, hwnd: HWND, name: []const u8) bool {
    var name_w: [128]u16 = undefined;
    const hr = service.vtbl.SetHwndPropStr(service.asRaw(), hwnd, OBJID_CLIENT, CHILDID_SELF, PROPID_ACC_NAME, utf8ToW(&name_w, name));
    if (hr < 0) std.log.warn("settings: failed to set accessible name '{s}' hr=0x{x}", .{ name, @as(u32, @bitCast(hr)) });
    return hr >= 0;
}

/// Set a field's MSAA description to `text` (`SettingsWindow.fieldDescription`:
/// that it differs from its default, and where its saved value comes from),
/// or clear it for none. The field's UIA `ItemStatus` says the first; this is
/// for a reader that takes a standard Edit, Button or ComboBox through MSAA,
/// as NVDA does.
fn setFieldDescription(service: *IAccPropServices, hwnd: HWND, text: []const u8) bool {
    var wide: [OriginNote.capacity + 64:0]u16 = undefined;
    const hr = if (text.len != 0)
        service.vtbl.SetHwndPropStr(service.asRaw(), hwnd, OBJID_CLIENT, CHILDID_SELF, PROPID_ACC_DESCRIPTION, utf8ToW(&wide, text))
    else
        service.vtbl.ClearHwndProps(service.asRaw(), hwnd, OBJID_CLIENT, CHILDID_SELF, &.{PROPID_ACC_DESCRIPTION}, 1);
    if (hr < 0) std.log.warn("settings: failed to annotate a field's description hr=0x{x}", .{@as(u32, @bitCast(hr))});
    return hr >= 0;
}

/// A description's hash for `SettingsWindow.described`: 0 for none.
fn descriptionHash(text: []const u8) u64 {
    if (text.len == 0) return 0;
    return std.hash.Wyhash.hash(0, text) | 1;
}

/// Where a form row's saved value comes from, as its label shows it on the
/// right: a line of a file, named by the file's name, or the command line
/// (`writeOriginNote`). Empty for a default, or a value noctty worked out.
const OriginNote = struct {
    /// A file name of 255 UTF-16 units is at most 765 bytes of UTF-8, and
    /// "Set by the theme " and ", line " with the number take under 64, and
    /// `origin_changed_note` under 32 more.
    const capacity = 255 * 3 + 96;
    len: u16 = 0,
    buf: [capacity]u8 = undefined,

    fn text(self: *const OriginNote) []const u8 {
        return self.buf[0..self.len];
    }
};

/// The file Settings saves to as it is now (`SettingsWindow.target_now`).
const TargetNow = struct {
    path: []const u8,
    lines: settings_reference.TargetLines,

    fn deinit(self: *TargetNow, alloc: std.mem.Allocator) void {
        alloc.free(self.path);
        self.lines.deinit(alloc);
    }
};

/// What a form row's note adds when the line it names has changed since the
/// file was read (`SettingsWindow.originLineChanged`).
const origin_changed_note = "; the file has changed since";

/// Write what a form row's label says about `found` (`config.origin`).
/// `changed`: the line named no longer holds what the loader took there.
fn writeOriginNote(writer: *std.Io.Writer, found: config_origin.Origin, changed: bool) std.Io.Writer.Error!void {
    switch (found) {
        .file => |file| {
            const name = std.fs.path.basename(file.path);
            if (file.kind == .theme)
                try writer.print("Set by the theme {s}, line {d}", .{ name, file.line })
            else
                try writer.print("Set in {s}, line {d}", .{ name, file.line });
            if (changed) try writer.writeAll(origin_changed_note);
        },
        .cli => try writer.writeAll("Set on the command line"),
        .default, .derived, .unplaced => {},
    }
}

/// `child`'s window rect in `parent`'s client coordinates.
fn childRectIn(parent: HWND, child: HWND) ?RECT {
    var rect: RECT = undefined;
    if (GetWindowRect(child, &rect) == 0) return null;
    var top_left: POINT = .{ .x = rect.left, .y = rect.top };
    var bottom_right: POINT = .{ .x = rect.right, .y = rect.bottom };
    if (ScreenToClient(parent, &top_left) == 0 or ScreenToClient(parent, &bottom_right) == 0) return null;
    return .{ .left = top_left.x, .top = top_left.y, .right = bottom_right.x, .bottom = bottom_right.y };
}

/// The signed coordinates a mouse message packs into `lParam`.
fn lparamX(lParam: LPARAM) i32 {
    return @as(i16, @bitCast(@as(u16, @truncate(@as(usize, @bitCast(lParam))))));
}
fn lparamY(lParam: LPARAM) i32 {
    return @as(i16, @bitCast(@as(u16, @truncate(@as(usize, @bitCast(lParam)) >> 16))));
}

/// Put `row`'s value in `pending` back to its default (`resetSettingValue`):
/// what a reset stages, and so what a save of it writes (the default as that
/// key's line, or for Default profile, no line).
pub fn resetDraftRow(pending: *Config, saved: ?*const Config, defaults: *const Config, comptime row: field_model.FormField) std.mem.Allocator.Error!void {
    if (comptime row.field) |field| return setSettingValue(pending, resetSettingValue(saved, defaults, field));
    const owned = comptime ownedFieldFor(row.descriptor.key);
    const default = try cloneOwnedSetting(pending, defaults, owned);
    storeOwnedReset(pending, default);
}

/// What an owned field's reset stores, copied but not stored yet: the
/// default for the draft, and for the baseline the file's value when it
/// differs from it (a conflict, `resetFormRow`).
const PreparedOwnedReset = struct {
    default: OwnedSettingValue,
    baseline: ?OwnedSettingValue,

    fn store(self: PreparedOwnedReset, pending: *Config, original: *Config) void {
        storeOwnedReset(pending, self.default);
        if (self.baseline) |value| storeOwnedSetting(original, value);
    }
};

/// The copies an owned field's reset needs, each in the arena of the config
/// it goes to. A failure stores nothing; a copy made before it stays unused
/// in its arena, freed with the config.
fn prepareOwnedReset(
    pending: *Config,
    original: *Config,
    file: ?*const Config,
    defaults: *const Config,
    field: OwnedSettingField,
) std.mem.Allocator.Error!PreparedOwnedReset {
    const default = try cloneOwnedSetting(pending, defaults, field);
    const baseline: ?OwnedSettingValue = if (file) |current|
        if (!ownedSettingEql(current, original, field)) try cloneOwnedSetting(original, current, field) else null
    else
        null;
    return .{ .default = default, .baseline = baseline };
}

fn storeOwnedReset(pending: *Config, default: OwnedSettingValue) void {
    storeOwnedSetting(pending, default);
}

/// What a reset of `field` puts back: its default, unless the saved value
/// already counts as the default, which it keeps, so a reset that undoes an
/// edit leaves nothing to save. The saved copy is of a finalized config,
/// where an unset Auto-update channel holds this build's channel and a
/// Window theme of auto with a light/dark pair holds system
/// (`effectiveSettingValue`).
fn resetSettingValue(saved: ?*const Config, defaults: *const Config, field: SettingField) SettingValue {
    const default = settingValue(defaults, field);
    const kept = settingValue(saved orelse return default, field);
    return if (settingValueEql(field_model.effectiveSettingValue(kept), field_model.effectiveSettingValue(default))) kept else default;
}

fn ownedFieldFor(comptime key: Config.Key) OwnedSettingField {
    for (std.enums.values(OwnedSettingField)) |owned| if (owned.descriptor().key == key) return owned;
    @compileError("Not an owned Settings key: " ++ @tagName(key));
}

/// " (12 pt)": the default a reset of `row` puts back, as the form shows it,
/// or " (automatic)". Nothing for a text field that is blank by default.
fn writeDefaultSuffix(comptime row: field_model.FormField, writer: *std.Io.Writer, saved: ?*const Config, defaults: *const Config) !void {
    if (comptime row.field == null and row.descriptor.default_display == .inherited) return;
    var buf: [128]u8 = undefined;
    var value: std.Io.Writer = .fixed(&buf);
    if (comptime row.field) |field|
        try field_model.writeSettingValue(&value, resetSettingValue(saved, defaults, field))
    else
        try row.writeDefault(&value, defaults);
    // An owned field writes its default as a placeholder in parentheses.
    const text = if (comptime row.field == null) std.mem.trim(u8, value.buffered(), "()") else value.buffered();
    try writer.print(" ({s})", .{text});
}

/// Painted field labels keep the native dark visual treatment, while MSAA
/// annotations give `section`'s EDIT and COMBOBOX windows stable names through
/// the UI Automation bridge. Values remain owned by the native controls and
/// are not conflated with their accessible names.
fn annotateAccessibleControls(self: *SettingsWindow, section: Section) void {
    // The names the custom UIA providers serve, so a client that falls back to
    // MSAA (`customUiaProvidersEnabled` false) hears the same ones. Only for
    // the fields and dropdowns, whose captions are separate labels. A checkbox
    // or button already speaks its own caption, and a name that leaves the
    // caption out breaks voice control ("click Discard changes").
    // The search field is named with the first section's fields, in the same
    // pass, rather than in a pass of its own when the window opens.
    const name_search = !self.search_named and self.edit_search != null;
    const named = for (formItemsForSection(section)) |item| {
        const role = settings_control_specs[item.control_index].role;
        if (role == .edit or role == .combo_box) break true;
    } else name_search;
    if (!named) return;
    // The test's service (`annotation_service`) where there is one.
    var annotations: SettingsWindow.Annotations = .{ .fake = self.annotation_service };
    defer annotations.deinit();
    const service = annotations.service() orelse {
        std.log.warn("settings: accessibility annotation service unavailable", .{});
        return;
    };
    inline for (settings_control_specs, 0..) |spec, index| {
        if ((spec.role == .edit or spec.role == .combo_box) and spec.section == section)
            setAccessibleName(service, self.controlHwnd(index), spec.name);
    }
    // A field's trackbar or up-down, by the field's name; its role (slider,
    // spin button) and value are the stock control's.
    inline for (comptime std.enums.values(Companion)) |kind| {
        const spec = comptime settings_control_specs[kind.controlIndex()];
        if (spec.section == section) setAccessibleName(service, self.companions[@intFromEnum(kind)], spec.name);
    }
    // A name that did not take is tried again with the next section made.
    if (name_search) self.search_named = setAccessibleNameText(service, self.edit_search.?, search_field_name);
}

fn populateCombo(combo_opt: ?HWND, items: []const []const u8) void {
    const combo = combo_opt orelse return;
    _ = sys.SendMessageW(combo, CB_RESETCONTENT, 0, 0);
    for (items) |item| {
        var buf_w: [64]u16 = undefined;
        const w = utf8ToW(&buf_w, item);
        _ = sys.SendMessageW(combo, CB_ADDSTRING, 0, @bitCast(@intFromPtr(w)));
    }
}

/// `style` adds the window's final visibility and group (`WS_VISIBLE`, `WS_GROUP`).
fn makeStatic(parent: HWND, hinstance: HINSTANCE, text: []const u8, style: u32) ?HWND {
    var text_w: [2048]u16 = undefined;
    return sys.CreateWindowExW(
        0,
        std.unicode.utf8ToUtf16LeStringLiteral("STATIC"),
        utf8ToW(&text_w, text),
        WS_CHILD | SS_LEFT | SS_NOPREFIX | style,
        0,
        0,
        1,
        1,
        parent,
        null,
        hinstance,
        null,
    );
}

fn setWindowTextUtf8(hwnd_opt: ?HWND, text: []const u8) void {
    const hwnd = hwnd_opt orelse return;
    var text_w: [2048]u16 = undefined;
    _ = sys.SendMessageW(hwnd, WM_SETTEXT, 0, @bitCast(@intFromPtr(utf8ToW(&text_w, text))));
}

fn setWindowTextUtf8IfChanged(hwnd: HWND, text: []const u8) bool {
    var current: [2048]u16 = undefined;
    const current_len: usize = @intCast(@max(0, sys.GetWindowTextW(hwnd, &current, @intCast(current.len))));
    var desired: [2048]u16 = undefined;
    const desired_z = utf8ToW(&desired, text);
    const desired_slice = std.mem.span(desired_z);
    if (std.mem.eql(u16, current[0..current_len], desired_slice)) return false;
    _ = sys.SendMessageW(hwnd, WM_SETTEXT, 0, @bitCast(@intFromPtr(desired_z)));
    return true;
}

fn applyChildFont(hwnd: HWND, lParam: LPARAM) callconv(.winapi) BOOL {
    _ = sys.SendMessageW(hwnd, WM_SETFONT, @as(WPARAM, @bitCast(lParam)), 1);
    return 1;
}

fn fontProbeCallback(_: *const LOGFONTW, _: ?*const anyopaque, _: u32, lParam: LPARAM) callconv(.winapi) c_int {
    const found: *bool = @ptrFromInt(@as(usize, @bitCast(lParam)));
    found.* = true;
    return 0;
}

fn fontFaceAvailable(hwnd: HWND, face: [*:0]const u16) bool {
    const hdc = GetDC(hwnd) orelse return false;
    defer _ = ReleaseDC(hwnd, hdc);
    var query: LOGFONTW = .{};
    const name = std.mem.span(face);
    const copy_len = @min(name.len, query.lfFaceName.len - 1);
    @memcpy(query.lfFaceName[0..copy_len], name[0..copy_len]);
    var found = false;
    _ = EnumFontFamiliesExW(
        hdc,
        &query,
        &fontProbeCallback,
        @bitCast(@intFromPtr(&found)),
        0,
    );
    return found;
}

fn createSettingsFont(dpi: u32, logical_height: i32, weight: i32, face: [*:0]const u16) HGDIOBJ {
    return CreateFontW(
        -scaleForDpi(logical_height, dpi),
        0,
        0,
        0,
        weight,
        0,
        0,
        0,
        1,
        0,
        0,
        5,
        0,
        face,
    );
}

/// `style` adds the edit styles and the window's final visibility and group.
fn makeEdit(
    parent: HWND,
    hinstance: HINSTANCE,
    id: usize,
    style: u32,
) ?HWND {
    const edit_class = std.unicode.utf8ToUtf16LeStringLiteral("EDIT");
    // No border style: the field draws its own frame (`settingsEditProc`).
    // `WS_EX_CLIENTEDGE` is the classic sunken 3-D frame and ignores the dark
    // theme; a themed `WS_BORDER` has no focused state, and the themed EDIT
    // drew it a second time inside the text area once the frame was ours.
    const edit = CreateWindowExW(
        0,
        edit_class,
        std.unicode.utf8ToUtf16LeStringLiteral(""),
        WS_CHILD | WS_TABSTOP | ES_AUTOHSCROLL | style,
        0,
        0,
        settings_field_max_width,
        settings_control_height,
        parent,
        @ptrFromInt(id),
        hinstance,
        null,
    );
    if (edit) |e| _ = sys.SendMessageW(e, EM_LIMITTEXT, edit_text_max_code_units - 1, 0);
    return edit;
}

/// `style` adds the window's final visibility and group.
fn makeCheckbox(
    parent: HWND,
    hinstance: HINSTANCE,
    id: usize,
    label: LPCWSTR,
    style: u32,
) ?HWND {
    const btn_class = std.unicode.utf8ToUtf16LeStringLiteral("BUTTON");
    return sys.CreateWindowExW(
        0,
        btn_class,
        label,
        WS_CHILD | WS_TABSTOP | BS_AUTOCHECKBOX | style,
        0,
        0,
        settings_field_max_width,
        settings_control_height,
        parent,
        @ptrFromInt(id),
        hinstance,
        null,
    );
}

/// `style` adds the window's final visibility and group.
fn makeCombo(
    parent: HWND,
    hinstance: HINSTANCE,
    id: usize,
    height: i32,
    items: []const []const u8,
    style: u32,
) ?HWND {
    const combo_class = std.unicode.utf8ToUtf16LeStringLiteral("COMBOBOX");
    const combo = sys.CreateWindowExW(
        0,
        combo_class,
        std.unicode.utf8ToUtf16LeStringLiteral(""),
        WS_CHILD | WS_TABSTOP | CBS_DROPDOWNLIST | CBS_HASSTRINGS | style,
        0,
        0,
        settings_field_max_width,
        height,
        parent,
        @ptrFromInt(id),
        hinstance,
        null,
    );
    populateCombo(combo, items);
    return combo;
}

/// `style` adds the window's final visibility and group.
fn makePushButton(parent: HWND, hinstance: HINSTANCE, label: LPCWSTR, id: usize, width: i32, style: u32) ?HWND {
    return sys.CreateWindowExW(
        0,
        std.unicode.utf8ToUtf16LeStringLiteral("BUTTON"),
        label,
        WS_CHILD | WS_TABSTOP | BS_PUSHBUTTON | style,
        0,
        0,
        width,
        32,
        parent,
        @ptrFromInt(id),
        hinstance,
        null,
    );
}

/// The rail is one arrow-key group, which the first button starts, and the
/// selected section's button is its tab stop (`applySectionVisibility` moves
/// it on a switch).
fn makeSectionButton(
    parent: HWND,
    hinstance: HINSTANCE,
    class: LPCWSTR,
    section: Section,
    selected: Section,
) ?HWND {
    const id: usize = switch (section) {
        .appearance => BTN_SECTION_APPEARANCE,
        .terminal => BTN_SECTION_TERMINAL,
        .shell => BTN_SECTION_SHELL,
        .profiles => BTN_SECTION_PROFILES,
        .privacy => BTN_SECTION_PRIVACY,
        .updates => BTN_SECTION_UPDATES,
        .keybindings => BTN_SECTION_KEYBINDINGS,
        .advanced => BTN_SECTION_ADVANCED,
        .reference => BTN_SECTION_REFERENCE,
    };
    const group_style: u32 = if (section == .appearance) WS_GROUP else 0;
    const tab_style: u32 = if (section == selected) WS_TABSTOP else 0;
    return sys.CreateWindowExW(
        0,
        class,
        section.label(),
        WS_CHILD | WS_VISIBLE | group_style | tab_style | BS_AUTORADIOBUTTON | BS_PUSHLIKE,
        0,
        0,
        100,
        settings_rail_item_height,
        parent,
        @ptrFromInt(id),
        hinstance,
        null,
    );
}

const settings_metrics: win32_theme.ThemeMetrics = .{};
const settings_rail_width: i32 = 184;
const settings_rail_padding_x: i32 = settings_metrics.space_4;
const settings_rail_top_padding: i32 = settings_metrics.space_6;
const settings_rail_item_height: i32 = settings_metrics.space_9;
const settings_rail_item_gap: i32 = settings_metrics.space_2;
const compact_section_btn_height: i32 = 28;
const compact_section_btn_top_pad: i32 = settings_metrics.space_4;
const compact_section_btn_gap: i32 = settings_metrics.space_1;
const settings_pane_padding: i32 = settings_metrics.space_6;
const settings_header_title_height: i32 = settings_metrics.space_8;
const settings_header_summary_top: i32 = settings_header_title_height + settings_metrics.space_2;
const settings_header_summary_height: i32 = 36;
const settings_header_separator_y: i32 = settings_header_summary_top + settings_header_summary_height + settings_metrics.space_5;
const settings_form_viewport_top: i32 = settings_header_separator_y + settings_metrics.space_4;
const settings_prose_max_width: i32 = 560;
const settings_search_min_width: i32 = 160;
const settings_search_max_width: i32 = 280;
const settings_action_bar_height: i32 = 64;
const settings_action_padding: i32 = settings_metrics.space_6;
const settings_action_gap: i32 = settings_metrics.space_4;
const settings_field_label_height: i32 = settings_metrics.space_6;
const settings_label_control_gap: i32 = settings_metrics.space_2;
const settings_field_label_offset: i32 = settings_metrics.space_7;
const settings_control_height: i32 = settings_metrics.space_9;
const settings_combo_item_height: i32 = settings_metrics.space_9;
const settings_field_group_gap: i32 = settings_metrics.space_5;
const settings_field_row_pitch: i32 = 64;
/// The least height the Keybindings page gives its list, about four bindings
/// with one open: below it the page scrolls to the list.
const settings_keybind_list_min_height: i32 = 240;
/// What one wheel notch scrolls at the default of three lines per notch.
const settings_wheel_notch_px: i32 = 64;
const settings_column_gap: i32 = settings_metrics.space_8;
const settings_column_min_width: i32 = 320;
const settings_two_column_min_width: i32 = 664;
const settings_field_max_width: i32 = 360;
/// The opacity field's box at the end of its trackbar's lane.
const settings_slider_field_width: i32 = 72;
/// The trackbar's thumb, top to bottom.
const settings_slider_thumb_length: i32 = 20;
/// An up-down beside its field.
const settings_spin_width: i32 = 20;
const settings_combo_popup_height: i32 = 160;
const settings_content_bottom_padding: i32 = settings_metrics.space_6;
/// The Reset button at the right end of an editable row. Every editable row
/// keeps its room, so a control does not move or narrow when its button comes.
const settings_reset_width: i32 = 64;
const settings_reset_gap: i32 = settings_metrics.space_4;
/// The bar left of a control whose value differs from the default: the
/// viewport reaches this far left of the form, so the bar beside the first
/// lane has room without moving the form.
const settings_marker_gutter: i32 = settings_metrics.space_4;
const settings_marker_width: i32 = 3;
const settings_marker_gap: i32 = settings_metrics.space_2;

const RailGeometry = struct {
    top_pad: i32,
    button_height: i32,
    gap: i32,
};

fn sectionRailGeometry(client_height: i32, dpi: u32) RailGeometry {
    const regular: RailGeometry = .{
        .top_pad = scaleForDpi(settings_rail_top_padding, dpi),
        .button_height = scaleForDpi(settings_rail_item_height, dpi),
        .gap = scaleForDpi(settings_rail_item_gap, dpi),
    };
    const button_count: i32 = @intCast(section_count);
    const regular_bottom = regular.top_pad + button_count * regular.button_height + (button_count - 1) * regular.gap;
    if (regular_bottom <= client_height) return regular;
    const compact: RailGeometry = .{
        .top_pad = scaleForDpi(compact_section_btn_top_pad, dpi),
        .button_height = scaleForDpi(compact_section_btn_height, dpi),
        .gap = scaleForDpi(compact_section_btn_gap, dpi),
    };
    const compact_bottom = compact.top_pad + button_count * compact.button_height + (button_count - 1) * compact.gap;
    if (compact_bottom <= client_height) return compact;

    // Work areas can be shorter than the nominal minimum at large DPI. Keep
    // every navigation target reachable rather than placing the last buttons
    // below the client edge. This only compresses below the compact geometry.
    const bounded_height = @max(button_count, client_height);
    const top_pad = @min(compact.top_pad, @max(0, bounded_height - button_count));
    const remaining = bounded_height - top_pad;
    const gap = @min(
        compact.gap,
        @max(0, @divTrunc(remaining - button_count, @max(1, button_count - 1))),
    );
    return .{
        .top_pad = top_pad,
        .button_height = @max(1, @divTrunc(remaining - (button_count - 1) * gap, button_count)),
        .gap = gap,
    };
}

const ActionRowGeometry = struct {
    first_x: i32,
    first_width: i32,
    second_x: i32,
    second_y: i32,
    second_width: i32,
    third_x: i32,
    third_y: i32,
    third_width: i32,
    button_height: i32,
    stacked: bool,
};

fn closeActionRowGeometry(available_width: i32, available_height: i32, dpi: u32) ActionRowGeometry {
    return promptActionRowGeometry(available_width, available_height, dpi, false);
}

fn promptActionRowGeometry(available_width: i32, available_height: i32, dpi: u32, discard: bool) ActionRowGeometry {
    const gap = scaleForDpi(settings_action_gap, dpi);
    const preferred_first = if (discard) 0 else scaleForDpi(120, dpi);
    const preferred_second = scaleForDpi(128, dpi);
    const preferred_third = scaleForDpi(112, dpi);
    const preferred_height = scaleForDpi(settings_control_height, dpi);
    const button_count: i32 = if (discard) 2 else 3;
    const preferred_total = preferred_first + preferred_second + preferred_third + (button_count - 1) * gap;
    if (available_width >= preferred_total) return .{
        .first_x = available_width - preferred_total,
        .first_width = preferred_first,
        .second_x = available_width - preferred_total + if (discard) @as(i32, 0) else preferred_first + gap,
        .second_y = 0,
        .second_width = preferred_second,
        .third_x = available_width - preferred_third,
        .third_y = 0,
        .third_width = preferred_third,
        .button_height = @min(preferred_height, @max(0, available_height)),
        .stacked = false,
    };

    // Typed: `@max(0, x)` alone is a u31, and `height - 3` below wraps when the
    // pane is shorter than 3 px (the closed prompt asks with a height of 0).
    const width: i32 = @max(0, available_width);
    const height: i32 = @max(0, available_height);
    const vertical_gap = @min(scaleForDpi(6, dpi), @divTrunc(@max(0, height - button_count), button_count - 1));
    const button_height = @min(preferred_height, @divTrunc(@max(0, height - (button_count - 1) * vertical_gap), button_count));
    return .{
        .first_x = 0,
        .first_width = if (discard) 0 else width,
        .second_x = 0,
        .second_y = if (discard) 0 else button_height + vertical_gap,
        .second_width = width,
        .third_x = 0,
        .third_y = (button_count - 1) * (button_height + vertical_gap),
        .third_width = width,
        .button_height = button_height,
        .stacked = true,
    };
}

const NormalActionRowGeometry = struct {
    status_right: i32,
    /// "Discard changes" beside Save. Zero wide while a conflict owns the row
    /// (its choices are the way out), or when the pane has no room for it.
    discard_x: i32 = 0,
    discard_width: i32 = 0,
    keep_mine_x: i32,
    keep_mine_y: i32,
    keep_mine_width: i32,
    use_disk_x: i32,
    use_disk_y: i32,
    use_disk_width: i32,
    save_x: i32,
    save_y: i32,
    save_width: i32,
    button_height: i32,
    stacked: bool,
};

fn normalActionRowGeometry(pane_width: i32, available_height: i32, conflict: bool, dpi: u32) NormalActionRowGeometry {
    const gap = scaleForDpi(settings_action_gap, dpi);
    const preferred_save_width = scaleForDpi(96, dpi);
    const preferred_conflict_width = scaleForDpi(112, dpi);
    const preferred_height = scaleForDpi(settings_control_height, dpi);
    const width: i32 = @max(0, pane_width);
    const height: i32 = @max(0, available_height);
    if (!conflict) {
        const save_width = @min(preferred_save_width, width);
        const save_x = width - save_width;
        const discard_width = std.math.clamp(save_x - gap, 0, scaleForDpi(128, dpi));
        const discard_x = if (discard_width > 0) save_x - gap - discard_width else 0;
        return .{
            .discard_x = discard_x,
            .discard_width = discard_width,
            .status_right = @max(0, (if (discard_width > 0) discard_x else save_x) - gap),
            .keep_mine_x = 0,
            .keep_mine_y = 0,
            .keep_mine_width = 0,
            .use_disk_x = 0,
            .use_disk_y = 0,
            .use_disk_width = 0,
            .save_x = save_x,
            .save_y = 0,
            .save_width = save_width,
            .button_height = @min(preferred_height, height),
            .stacked = false,
        };
    }

    const preferred_total = preferred_save_width + 2 * preferred_conflict_width + 2 * gap;
    if (width >= preferred_total) {
        const save_x = width - preferred_save_width;
        const use_disk_x = save_x - gap - preferred_conflict_width;
        const keep_mine_x = use_disk_x - gap - preferred_conflict_width;
        return .{
            .status_right = @max(0, keep_mine_x - gap),
            .keep_mine_x = keep_mine_x,
            .keep_mine_y = 0,
            .keep_mine_width = preferred_conflict_width,
            .use_disk_x = use_disk_x,
            .use_disk_y = 0,
            .use_disk_width = preferred_conflict_width,
            .save_x = save_x,
            .save_y = 0,
            .save_width = preferred_save_width,
            .button_height = @min(preferred_height, height),
            .stacked = false,
        };
    }

    const vertical_gap = @min(scaleForDpi(6, dpi), @divTrunc(@max(0, height - 3), 2));
    const button_height = @min(preferred_height, @divTrunc(@max(0, height - 2 * vertical_gap), 3));
    return .{
        .status_right = 0,
        .keep_mine_x = 0,
        .keep_mine_y = 0,
        .keep_mine_width = width,
        .use_disk_x = 0,
        .use_disk_y = button_height + vertical_gap,
        .use_disk_width = width,
        .save_x = 0,
        .save_y = 2 * (button_height + vertical_gap),
        .save_width = width,
        .button_height = button_height,
        .stacked = true,
    };
}

const ConflictFocusTarget = enum { validation, save, section, none };

fn conflictFocusTarget(has_validation: bool, save_enabled: bool, has_section: bool) ConflictFocusTarget {
    if (has_validation) return .validation;
    if (save_enabled) return .save;
    if (has_section) return .section;
    return .none;
}

const CloseRequestAction = enum { close_now, show_prompt, focus_prompt, ignore };
const PendingCloseReopenAction = enum { none, cancel_saved_close, cancel_discard_close };
const ClosePromptActions = struct {
    save: bool,
    discard: bool,
    keep_editing: bool,
};

fn closeRequestAction(has_pending: bool, prompt_visible: bool, close_posted: bool) CloseRequestAction {
    if (close_posted) return .ignore;
    if (!has_pending) return .close_now;
    if (prompt_visible) return .focus_prompt;
    return .show_prompt;
}

fn closePromptActions(visible: bool, close_posted: bool) ClosePromptActions {
    const can_choose = visible and !close_posted;
    return .{
        .save = can_choose,
        .discard = can_choose,
        // The button that owns IDCANCEL stays enabled while it is hidden:
        // `IsDialogMessageW` does not send Escape to a disabled cancel button,
        // and Escape without the prompt is a close request.
        .keep_editing = !close_posted,
    };
}

fn closePromptCanCancel(visible: bool, close_posted: bool) bool {
    return visible and !close_posted;
}

fn closePromptText(quitting: bool) []const u8 {
    return if (quitting) "Save changes before quitting?" else "Save changes before closing?";
}

fn pendingCloseReopenAction(close_posted: bool, close_after_save: bool) PendingCloseReopenAction {
    if (!close_posted) return .none;
    return if (close_after_save) .cancel_saved_close else .cancel_discard_close;
}

fn isSaveShortcut(vk: u32, ctrl: bool, alt: bool, shift: bool) bool {
    return vk == 'S' and ctrl and !alt and !shift;
}

/// Ctrl+F alone: Ctrl+Shift+F and AltGr (Ctrl+Alt) chords type into a field.
fn isFindShortcut(ctrl: bool, alt: bool, shift: bool) bool {
    return ctrl and !alt and !shift;
}

/// The header's line while a search is typed: how many settings it found, and
/// how many of them the shown page has, or where the first are when it has
/// none. This is what a reader announces.
fn searchSummaryText(buf: []u8, counts: *const [section_count]u16, total: usize, shown: Section) []const u8 {
    if (total == 0) return "No settings match.";
    const noun = if (total == 1) "setting matches" else "settings match";
    const here = counts[@intFromEnum(shown)];
    if (here != 0) return std.fmt.bufPrint(buf, "{d} {s}: {d} on this page.", .{ total, noun, here }) catch "";
    const first = firstPageWithMatches(counts).?;
    return std.fmt.bufPrint(buf, "{d} {s}: none on this page, {d} on {s}.", .{ total, noun, counts[@intFromEnum(first)], first.headerText() }) catch "";
}

/// The first page in rail order with a row the search found.
fn firstPageWithMatches(counts: *const [section_count]u16) ?Section {
    for (std.enums.values(Section)) |section| if (counts[@intFromEnum(section)] != 0) return section;
    return null;
}

/// What a page with no row the search found shows in place of its rows: what
/// was looked for, and where it was found, or else what the search looks in.
fn searchEmptyText(buf: []u8, query: *const SearchQuery, counts: *const [section_count]u16, total: usize) []const u8 {
    var writer: std.Io.Writer = .fixed(buf);
    writeSearchEmptyText(&writer, query, counts, total) catch {};
    return writer.buffered();
}

fn writeSearchEmptyText(writer: *std.Io.Writer, query: *const SearchQuery, counts: *const [section_count]u16, total: usize) !void {
    if (query.word_count != 0) {
        try writer.print("Nothing on this page matches \u{201C}{s}\u{201D}.", .{query.typedText()});
    } else {
        try writer.writeAll("Nothing on this page differs from its default.");
    }
    if (total == 0) {
        try writer.writeAll(" Nor does anything on the other pages. The search looks in each setting's name, " ++
            "description and keywords, and @modified finds the settings that differ from their defaults. " ++
            "Escape in the search field clears it.");
        return;
    }
    try writer.writeAll(" Found on ");
    var listed: usize = 0;
    for (std.enums.values(Section)) |section| {
        const count = counts[@intFromEnum(section)];
        if (count == 0) continue;
        if (listed != 0) try writer.writeAll(", ");
        try writer.print("{s} ({d})", .{ section.headerText(), count });
        listed += 1;
    }
    try writer.writeAll(". Enter in the search field goes to the first, or choose a page on the left.");
}

fn saveCommandCanDispatch(
    prompt_visible: bool,
    close_posted: bool,
    button_enabled: bool,
    button_visible: bool,
) bool {
    return !prompt_visible and !close_posted and button_enabled and button_visible;
}

