test "settings action bar pins normal conflict prompt and stacked actions" {
    for ([_]u32{ 96, 120, 144, 168, 192, 288 }) |dpi| {
        const pane_width = scaleForDpi(560, dpi);
        const action_height = scaleForDpi(settings_control_height, dpi);
        const stack_height = scaleForDpi(3 * settings_control_height + 2 * 6, dpi);
        const normal = normalActionRowGeometry(pane_width, action_height, false, dpi);
        const conflict = normalActionRowGeometry(pane_width, action_height, true, dpi);
        try std.testing.expectEqual(pane_width, normal.save_x + scaleForDpi(96, dpi));
        try std.testing.expect(conflict.keep_mine_x >= 0);
        try std.testing.expect(conflict.keep_mine_x + scaleForDpi(112, dpi) + scaleForDpi(settings_action_gap, dpi) <= conflict.use_disk_x);
        try std.testing.expect(conflict.use_disk_x + scaleForDpi(112, dpi) + scaleForDpi(settings_action_gap, dpi) <= conflict.save_x);

        const narrow_width = scaleForDpi(320, dpi);
        const narrow = normalActionRowGeometry(narrow_width, stack_height, true, dpi);
        try std.testing.expect(narrow.stacked);
        try std.testing.expect(narrow.keep_mine_x >= 0);
        try std.testing.expect(narrow.use_disk_x >= 0);
        try std.testing.expect(narrow.save_x >= 0);
        try std.testing.expect(narrow.keep_mine_x + narrow.keep_mine_width <= narrow_width);
        try std.testing.expect(narrow.use_disk_x + narrow.use_disk_width <= narrow_width);
        try std.testing.expect(narrow.save_x + narrow.save_width <= narrow_width);

        const tiny_normal = normalActionRowGeometry(1, action_height, false, dpi);
        try std.testing.expect(tiny_normal.save_x >= 0);
        try std.testing.expect(tiny_normal.save_x + tiny_normal.save_width <= 1);

        var settings: SettingsWindow = .{ .handle = undefined, .dpi = dpi };
        const client_height = scaleForDpi(520, dpi);
        const normal_bar = closePromptLayoutGeometry(&settings, pane_width, client_height);
        try std.testing.expectEqual(scaleForDpi(settings_action_bar_height, dpi), normal_bar.bar_height);
        settings.close_prompt_visible = true;
        const prompt_bar = closePromptLayoutGeometry(&settings, pane_width, client_height);
        try std.testing.expect(!prompt_bar.actions.stacked);
        try std.testing.expect(prompt_bar.bar_height >= normal_bar.bar_height);
        const stacked = closePromptLayoutGeometry(&settings, scaleForDpi(320, dpi), client_height);
        try std.testing.expect(stacked.actions.stacked);
        try std.testing.expect(stacked.bar_height > prompt_bar.bar_height);
        try std.testing.expect(stacked.actions_top + stacked.actions.third_y + stacked.actions.button_height <= stacked.bar_height);

        const short_height = scaleForDpi(100, dpi);
        const short = closePromptLayoutGeometry(&settings, scaleForDpi(320, dpi), short_height);
        try std.testing.expect(short.bar_height <= short_height);
        try std.testing.expect(short.actions_top + short.actions.third_y + short.actions.button_height <= short.bar_height);
    }

    // The real minimum client size is DPI-scaled: `WM_GETMINMAXINFO` sets
    // `ptMinTrackSize` from `px(720)` / `px(520)`. Assert a *positive* form
    // viewport at that actual floor for every DPI — `top <= bottom` alone is
    // satisfied by an empty viewport, which would clip every control to an
    // empty region.
    for ([_]u32{ 96, 120, 144, 168, 192, 288 }) |dpi| {
        var floor: SettingsWindow = .{
            .handle = undefined,
            .dpi = dpi,
            .close_prompt_visible = true,
        };
        const enforced: RECT = .{
            .left = 0,
            .top = 0,
            .right = scaleForDpi(720, dpi),
            .bottom = scaleForDpi(520, dpi),
        };
        try std.testing.expect(
            settingsContentViewportTop(&floor, enforced) <
                settingsContentViewportBottom(&floor, enforced),
        );
    }

    // `cappedMinimum` clamps the DPI-scaled minimum down to the monitor work
    // area, which is how a client shorter than the scaled fixed bands is
    // actually reached -- a 1366x768 work area at 288 DPI used to produce a
    // viewport of exactly zero height, blanking the whole form. Assert a form
    // viewport of at least one control row for every work area a real display
    // or Remote Desktop session can present, with the dirty-close prompt open,
    // and assert the action bar still has room for its first button row.
    for ([_]struct { w: i32, h: i32, dpi: u32 }{
        .{ .w = 1920, .h = 1080, .dpi = 96 },
        .{ .w = 2560, .h = 1440, .dpi = 144 },
        .{ .w = 1366, .h = 768, .dpi = 192 },
        .{ .w = 1920, .h = 1080, .dpi = 288 },
        .{ .w = 1366, .h = 768, .dpi = 288 },
        .{ .w = 1280, .h = 720, .dpi = 288 },
        .{ .w = 1024, .h = 640, .dpi = 288 },
        .{ .w = 800, .h = 600, .dpi = 288 },
    }) |work| {
        var capped: SettingsWindow = .{
            .handle = undefined,
            .dpi = work.dpi,
            .close_prompt_visible = true,
        };
        const client: RECT = .{
            .left = 0,
            .top = 0,
            .right = cappedMinimum(720, work.dpi, work.w),
            .bottom = cappedMinimum(520, work.dpi, work.h),
        };
        const viewport_top = settingsContentViewportTop(&capped, client);
        const viewport_bottom = settingsContentViewportBottom(&capped, client);
        try std.testing.expect(
            viewport_bottom - viewport_top >= capped.px(settings_control_height),
        );

        const bar = closePromptLayoutGeometry(
            &capped,
            paneBounds(&capped, client).width,
            actionBarAvailableHeight(&capped, client),
        );
        try std.testing.expect(bar.bar_height > 0);
        try std.testing.expect(bar.actions_top + bar.actions.button_height <= bar.bar_height);
        try std.testing.expectEqual(client.bottom - bar.bar_height - capped.px(settings_pane_padding), viewport_bottom);
    }

    // Degenerate probe: a client smaller than anything `cappedMinimum` can
    // produce must still not invert the viewport.
    var minimum: SettingsWindow = .{ .handle = undefined, .dpi = 288, .close_prompt_visible = true };
    const client: RECT = .{ .left = 0, .top = 0, .right = 720, .bottom = 520 };
    const pane = paneBounds(&minimum, client);
    try std.testing.expect(closePromptLayoutGeometry(&minimum, pane.width, client.bottom).actions.stacked);
    try std.testing.expect(settingsContentViewportTop(&minimum, client) <= settingsContentViewportBottom(&minimum, client));
}

test "settings checkbox and label classification agrees with form model" {
    var controls = [_]bool{false} ** settings_clipped_control_count;
    var labels = [_]bool{false} ** settings_label_specs.len;
    for (std.enums.values(Section)) |section| for (formItemsForSection(section)) |item| {
        try std.testing.expect(!controls[item.control_index]);
        controls[item.control_index] = true;
        try std.testing.expectEqual(settings_control_specs[item.control_index].role == .check_box, item.checkbox);
        if (item.label_index) |index| {
            try std.testing.expect(!labels[index]);
            labels[index] = true;
            try std.testing.expectEqual(item.checkbox, labelIndexIsCheckbox(index));
        }
    };
    for (controls) |seen| try std.testing.expect(seen);
    for (labels) |seen| try std.testing.expect(seen);
}

/// A row's label and control, and for an editable row the room at the right
/// end of its lane that its Reset button takes when the row differs from its
/// default.
const SettingsFieldRects = struct { label: RECT, control: RECT, reset: ?RECT = null };

/// Narrow `rects.control` by the room of a Reset button and put the button
/// there, at the end of the lane.
fn withResetRoom(rects: *SettingsFieldRects, dpi: u32) void {
    const width = scaleForDpi(settings_reset_width, dpi);
    const lane_right = rects.control.right;
    rects.control.right = @max(rects.control.left, lane_right - width - scaleForDpi(settings_reset_gap, dpi));
    rects.reset = .{ .left = lane_right - width, .top = rects.control.top, .right = lane_right, .bottom = rects.control.bottom };
}

fn settingsFieldRects(index: usize, pane_width: i32, dpi: u32) SettingsFieldRects {
    const columns = settingsColumnCount(pane_width, dpi);
    const gap = scaleForDpi(settings_column_gap, dpi);
    const available_lane_width = @divTrunc(pane_width - (if (columns == 2) gap else 0), @as(i32, @intCast(columns)));
    const lane_width = @min(available_lane_width, scaleForDpi(settings_field_max_width, dpi));
    const column: i32 = @intCast(index % columns);
    const row: i32 = @intCast(index / columns);
    const left = column * (lane_width + gap);
    const label_top = row * scaleForDpi(settings_field_row_pitch, dpi);
    const control_top = label_top + scaleForDpi(settings_field_label_offset, dpi);
    return .{
        .label = .{
            .left = left,
            .top = label_top,
            .right = left + lane_width,
            .bottom = label_top + scaleForDpi(settings_field_label_height, dpi),
        },
        .control = .{
            .left = left,
            .top = control_top,
            .right = left + lane_width,
            .bottom = control_top + scaleForDpi(settings_control_height, dpi),
        },
    };
}

fn settingsFormItemRects(items: []const FormItem, pane_width: i32, dpi: u32, output: []SettingsFieldRects) void {
    std.debug.assert(output.len >= items.len);
    const columns = settingsColumnCount(pane_width, dpi);
    const row_pitch = scaleForDpi(settings_field_row_pitch, dpi);
    const control_height = scaleForDpi(settings_control_height, dpi);
    const checkbox_pitch = control_height + scaleForDpi(settings_metrics.space_2, dpi);
    const group_gap = scaleForDpi(settings_field_group_gap, dpi);
    var top: i32 = 0;
    var start: usize = 0;
    while (start < items.len) {
        var end = start + 1;
        // A later labeled checkbox starts a new run so its label has its own
        // space above the control, rather than sharing the first row's label.
        while (end < items.len and items[end].checkbox == items[start].checkbox and
            !(items[end].checkbox and items[end].label_index != null)) : (end += 1)
        {}
        if (items[start].checkbox) {
            const lane = settingsFieldRects(0, pane_width, dpi);
            const control_top = top + if (items[start].label_index != null) scaleForDpi(settings_field_label_offset, dpi) else 0;
            for (start..end) |index| {
                const item_top = control_top + @as(i32, @intCast(index - start)) * checkbox_pitch;
                output[index] = .{
                    .label = .{ .left = lane.label.left, .top = top, .right = lane.label.right, .bottom = top + scaleForDpi(settings_field_label_height, dpi) },
                    .control = .{ .left = lane.control.left, .top = item_top, .right = lane.control.right, .bottom = item_top + control_height },
                };
            }
            top = control_top + @as(i32, @intCast(end - start - 1)) * checkbox_pitch + control_height + group_gap;
        } else {
            for (start..end) |index| {
                output[index] = settingsFieldRects(index - start, pane_width, dpi);
                output[index].label.top += top;
                output[index].label.bottom += top;
                output[index].control.top += top;
                output[index].control.bottom += top;
            }
            top += @as(i32, @intCast((end - start + columns - 1) / columns)) * row_pitch;
        }
        start = end;
    }
    // Every row that can be reset keeps the room, so a control never moves or
    // narrows when its Reset button comes or goes. A field Windows does not
    // support never has one, and keeps the lane for its caption.
    for (items, output[0..items.len]) |item, *rects| {
        if (item.control_index < form_field_count and resettable_rows[item.control_index]) withResetRoom(rects, dpi);
    }
}

/// Whether form row `i` (`field_model.form_fields[i]`) can be reset.
const resettable_rows = rows: {
    var result: [form_field_count]bool = undefined;
    for (field_model.form_fields, 0..) |row, i| result[i] = row.resettable();
    break :rows result;
};

fn settingsContentExtent(rects: []const RECT, bottom_padding: i32) i32 {
    var bottom: i32 = 0;
    for (rects) |rect| bottom = @max(bottom, rect.bottom);
    return bottom + @max(0, bottom_padding);
}

const SettingsScrollGeometry = struct {
    max_position: i32,
    page: u32,
    nmax: i32,
};

fn settingsScrollGeometry(content_extent: i32, viewport_height: i32) SettingsScrollGeometry {
    const extent = @max(0, content_extent);
    const viewport = @max(1, viewport_height);
    const page_i32 = @min(viewport, @max(1, extent));
    return .{
        .max_position = if (extent > viewport) extent - viewport else 0,
        .page = @intCast(page_i32),
        .nmax = if (extent > 0) extent - 1 else 0,
    };
}

/// Whether a child spanning `top`..`bottom` (viewport client coordinates) is
/// entirely outside a viewport `height` tall. One cut by an edge is on screen.
fn viewportHidesSpan(top: i32, bottom: i32, height: i32) bool {
    return height <= 0 or bottom <= top or bottom <= 0 or top >= height;
}

fn viewportHidesChild(viewport: HWND, child: ?HWND, height: i32) bool {
    const hwnd = child orelse return true;
    var rect: RECT = undefined;
    if (sys.GetWindowRect(hwnd, &rect) == 0) return true;
    var origin: POINT = .{ .x = rect.left, .y = rect.top };
    if (sys.ScreenToClient(viewport, &origin) == 0) return true;
    return viewportHidesSpan(origin.y, origin.y + (rect.bottom - rect.top), height);
}

test "settings viewport exposes partially clipped controls as onscreen" {
    try std.testing.expect(viewportHidesSpan(-40, 0, 300));
    try std.testing.expect(viewportHidesSpan(300, 340, 300));
    try std.testing.expect(viewportHidesSpan(20, 20, 300));
    try std.testing.expect(viewportHidesSpan(0, 40, 0));
    try std.testing.expect(!viewportHidesSpan(-39, 1, 300));
    try std.testing.expect(!viewportHidesSpan(299, 339, 300));
    try std.testing.expect(!viewportHidesSpan(0, 40, 300));
}

test "settings scrollbar thumb and maximum cover real extents" {
    const rects = [_]RECT{
        .{ .left = 0, .top = 0, .right = 320, .bottom = 16 },
        .{ .left = 0, .top = 20, .right = 320, .bottom = 52 },
        .{ .left = 0, .top = 84, .right = 320, .bottom = 244 },
    };
    const extent = settingsContentExtent(&rects, settings_content_bottom_padding);
    try std.testing.expectEqual(@as(i32, 260), extent);
    for ([_]i32{ 0, 1, 64, extent, 1024 }) |content| for ([_]i32{ 1, 32, 128, 512, 2048 }) |viewport| {
        const scroll = settingsScrollGeometry(content, viewport);
        const page: i32 = @intCast(scroll.page);
        try std.testing.expectEqual(@max(0, content - 1), scroll.nmax);
        try std.testing.expectEqual(@min(viewport, @max(1, content)), page);
        try std.testing.expectEqual(@max(0, content - viewport), scroll.max_position);
        try std.testing.expect(scroll.max_position + page >= content);
    };
}

fn closePromptMeasuredHeight(self: *SettingsWindow, pane_width: i32) i32 {
    const minimum = self.px(20);
    if (!self.close_prompt_visible) return minimum;
    if (self.close_prompt_measure_width == pane_width and
        self.close_prompt_measure_dpi == self.dpi and
        self.close_prompt_measure_quitting == self.quit_after_close and
        self.close_prompt_measure_height > 0)
    {
        return self.close_prompt_measure_height;
    }
    const hwnd = self.hwnd orelse return minimum;
    const hdc = GetDC(hwnd) orelse return minimum;
    defer _ = ReleaseDC(hwnd, hdc);
    const previous_font = if (self.emphasis_font) |font| SelectObject(hdc, font) else null;
    defer {
        if (previous_font) |font| _ = sys.SelectObject(hdc, font);
    }

    var text_w: [256]u16 = undefined;
    var text_buf: [128]u8 = undefined;
    const text = std.mem.span(utf8ToW(&text_w, self.promptText(&text_buf)));
    var measure = RECT{
        .left = 0,
        .top = 0,
        .right = @max(1, pane_width),
        .bottom = 0,
    };
    _ = sys.DrawTextW(
        hdc,
        text.ptr,
        @intCast(text.len),
        &measure,
        DT_CALCRECT | DT_WORDBREAK | DT_NOPREFIX,
    );
    const height = @max(minimum, measure.bottom - measure.top);
    self.close_prompt_measure_width = pane_width;
    self.close_prompt_measure_dpi = self.dpi;
    self.close_prompt_measure_quitting = self.quit_after_close;
    self.close_prompt_measure_height = height;
    return height;
}

const ClosePromptLayoutGeometry = struct {
    actions: ActionRowGeometry,
    normal_actions: NormalActionRowGeometry,
    prompt_height: i32,
    bar_height: i32,
    prompt_top: i32,
    actions_top: i32,
    /// A status message that does not fit on one line beside the buttons sits in
    /// a row of its own above them, across the whole pane, wrapped. Otherwise
    /// `status_separate` is false and the message shares the buttons' row.
    status_separate: bool = false,
    status_top: i32 = 0,
    status_height: i32 = 0,
};

/// The status text measured in the font it is drawn in: its width on one line,
/// and its height wrapped to `full_width`. Zero while there is no text, no
/// window to measure in, or the close prompt owns the bar.
fn statusMeasure(self: *SettingsWindow, full_width: i32) struct { single_line: i32, wrapped: i32 } {
    if (self.status_measure_width == full_width and self.status_measure_dpi == self.dpi) {
        return .{ .single_line = self.status_measure_single_line, .wrapped = self.status_measure_wrapped };
    }
    const status = self.text_status orelse return .{ .single_line = 0, .wrapped = 0 };
    const parent = self.hwnd orelse return .{ .single_line = 0, .wrapped = 0 };
    var buffer: [2048:0]u16 = undefined;
    const length = GetWindowTextW(status, &buffer, @intCast(buffer.len));
    var single_line: i32 = 0;
    var wrapped: i32 = 0;
    if (length > 0) if (GetDC(parent)) |hdc| {
        defer _ = ReleaseDC(parent, hdc);
        const raw_font: usize = @bitCast(SendMessageW(status, WM_GETFONT, 0, 0));
        const font: HGDIOBJ = if (raw_font != 0) @ptrFromInt(raw_font) else self.secondary_font;
        const previous = if (font) |value| SelectObject(hdc, value) else null;
        defer {
            if (previous) |value| _ = SelectObject(hdc, value);
        }
        var one_line: RECT = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
        _ = DrawTextW(hdc, &buffer, length, &one_line, DT_CALCRECT | DT_SINGLELINE | DT_NOPREFIX);
        single_line = one_line.right - one_line.left;
        var wrap: RECT = .{ .left = 0, .top = 0, .right = @max(1, full_width), .bottom = 0 };
        _ = DrawTextW(hdc, &buffer, length, &wrap, DT_CALCRECT | DT_WORDBREAK | DT_NOPREFIX);
        wrapped = wrap.bottom - wrap.top;
    };
    self.status_measure_width = full_width;
    self.status_measure_dpi = self.dpi;
    self.status_measure_single_line = single_line;
    self.status_measure_wrapped = wrapped;
    return .{ .single_line = single_line, .wrapped = wrapped };
}

/// Whether the status message needs a row of its own and how tall that row is.
/// `inline_width` is the room beside the buttons.
fn statusRowGeometry(self: *SettingsWindow, full_width: i32, inline_width: i32) struct { separate: bool, height: i32 } {
    const measure = statusMeasure(self, full_width);
    if (measure.single_line <= 0) return .{ .separate = false, .height = 0 };
    if (measure.single_line <= inline_width) return .{ .separate = false, .height = 0 };
    return .{ .separate = true, .height = @max(self.px(20), measure.wrapped) };
}

/// Height the fixed action bar is allowed to occupy, leaving at least one
/// control row of form viewport above it.
///
/// `cappedMinimum` clamps the DPI-scaled minimum window size down to the
/// monitor work area, so a short work area at a high scale can produce a
/// client that the scaled header plus a stacked dirty-close bar would consume
/// entirely: a 1366x768 work area at 288 DPI gives a viewport of exactly zero
/// height, i.e. a blank form. The viewport is reserved first and
/// the action bar gives way, which it already handles because it clamps its
/// own contents to whatever height it is given.
fn actionBarAvailableHeight(self: *SettingsWindow, client_rect: RECT) i32 {
    const client_height = @max(0, client_rect.bottom - client_rect.top);
    const reserved = settingsContentViewportTop(self, client_rect) +
        self.px(settings_control_height) +
        self.px(settings_pane_padding);
    return @max(0, client_height - reserved);
}

fn closePromptLayoutGeometry(self: *SettingsWindow, pane_width: i32, client_height: i32) ClosePromptLayoutGeometry {
    const available_height: i32 = @max(0, client_height);
    const desired_padding = self.px(settings_action_padding);
    if (!self.close_prompt_visible) {
        const conflict_visible = self.active_conflict_field != null or self.active_owned_conflict_field != null;
        const preferred_actions = normalActionRowGeometry(
            pane_width,
            self.px(3 * settings_control_height + 2 * 6),
            conflict_visible,
            self.dpi,
        );
        const preferred_span = preferred_actions.save_y + preferred_actions.button_height;
        const status = statusRowGeometry(self, pane_width, preferred_actions.status_right);
        const status_gap = self.px(6);
        const wanted_block = if (status.separate) status.height + status_gap else 0;
        const bar_height = @min(
            available_height,
            @max(self.px(settings_action_bar_height), 2 * desired_padding + wanted_block + preferred_span),
        );
        const padding = @min(desired_padding, @divTrunc(bar_height, 4));
        // The buttons come first: the status row gets what is left, clipped.
        const room = @max(0, bar_height - 2 * padding);
        const status_block = @min(wanted_block, @max(0, room - preferred_span));
        const status_height = if (status_block > status_gap) status_block - status_gap else 0;
        const normal_actions = normalActionRowGeometry(
            pane_width,
            @max(0, room - status_block),
            conflict_visible,
            self.dpi,
        );
        return .{
            .actions = closeActionRowGeometry(pane_width, 0, self.dpi),
            .normal_actions = normal_actions,
            .prompt_height = 0,
            .bar_height = bar_height,
            .prompt_top = padding,
            .actions_top = padding + status_block,
            .status_separate = status_height > 0,
            .status_top = padding,
            .status_height = status_height,
        };
    }

    const padding = @min(desired_padding, @divTrunc(available_height, 4));
    const actions = promptActionRowGeometry(
        pane_width,
        @max(0, available_height - 2 * padding),
        self.dpi,
        self.discard_prompt,
    );
    const action_span = if (actions.stacked)
        actions.third_y + actions.button_height
    else
        actions.button_height;
    const prompt_width = if (actions.stacked)
        pane_width
    else
        @max(1, actions.first_x - self.px(settings_action_gap));
    const measured_prompt_height = closePromptMeasuredHeight(self, prompt_width);
    if (actions.stacked) {
        const remaining = @max(0, available_height - 2 * padding - action_span);
        const prompt_height = @min(measured_prompt_height, @max(0, remaining - self.px(settings_action_gap)));
        const prompt_gap = if (prompt_height > 0) @min(self.px(settings_action_gap), remaining - prompt_height) else 0;
        const actions_top = padding + prompt_height + prompt_gap;
        return .{
            .actions = actions,
            .normal_actions = normalActionRowGeometry(pane_width, 0, false, self.dpi),
            .prompt_height = prompt_height,
            .bar_height = actions_top + action_span + padding,
            .prompt_top = padding,
            .actions_top = actions_top,
        };
    }
    const prompt_height = @min(measured_prompt_height, @max(0, available_height - 2 * padding));
    const row_height = @max(actions.button_height, prompt_height);
    return .{
        .actions = actions,
        .normal_actions = normalActionRowGeometry(pane_width, 0, false, self.dpi),
        .prompt_height = prompt_height,
        .bar_height = @min(available_height, 2 * padding + row_height),
        .prompt_top = padding + @divTrunc(row_height - prompt_height, 2),
        .actions_top = padding + @divTrunc(row_height - actions.button_height, 2),
    };
}

fn settingsContentViewportTop(self: *SettingsWindow, client_rect: RECT) i32 {
    const rail = sectionRailGeometry(client_rect.bottom - client_rect.top, self.dpi);
    return rail.top_pad + self.px(settings_form_viewport_top);
}

const PaneBounds = struct { left: i32, right: i32, width: i32 };

fn paneBounds(self: *const SettingsWindow, client_rect: RECT) PaneBounds {
    const client_width = @max(0, client_rect.right - client_rect.left);
    const padding = self.px(settings_pane_padding);
    const left = @min(self.px(settings_rail_width) + padding, client_width);
    const right = @max(left, client_width - @min(padding, client_width));
    return .{ .left = left, .right = right, .width = right - left };
}

fn settingsContentViewportBottom(self: *SettingsWindow, client_rect: RECT) i32 {
    const action_bar = closePromptLayoutGeometry(self, actionColumnWidth(self, client_rect), actionBarAvailableHeight(self, client_rect));
    return @max(settingsContentViewportTop(self, client_rect), client_rect.bottom - action_bar.bar_height - self.px(settings_pane_padding));
}

/// The width the form is laid out in. The viewport runs from the pane's left
/// edge to the window's right edge, so its scroll bar normally sits in the
/// pane's right padding; whatever part of the bar reaches into the pane is
/// left out, shown or not, so the fields never sit under it and never move
/// when it appears.
fn formPaneWidth(self: *const SettingsWindow, client_rect: RECT) i32 {
    const pane = paneBounds(self, client_rect);
    const scrollbar = @max(0, GetSystemMetricsForDpi(SM_CXVSCROLL, normalizedDpi(self.dpi)));
    return @max(0, @min(pane.width, client_rect.right - pane.left - scrollbar));
}

/// How wide the laid-out form is: one lane, or two lanes and the gap.
fn settingsFormColumnWidth(form_pane_width: i32, dpi: u32) i32 {
    const lane = settingsFieldRects(0, form_pane_width, dpi).control;
    const lane_width = lane.right - lane.left;
    if (settingsColumnCount(form_pane_width, dpi) < 2) return lane_width;
    return 2 * lane_width + scaleForDpi(settings_column_gap, dpi);
}

/// The width of the action bar and of the separators. Once the form has two
/// lanes it is the form's own width, so Save stays at the form's right edge
/// however wide the window gets (it drifted to the far right before). A
/// one-lane form keeps the whole pane: the action rows need more than one
/// lane to stand side by side.
fn settingsActionColumnWidth(pane_width: i32, form_pane_width: i32, dpi: u32) i32 {
    if (settingsColumnCount(form_pane_width, dpi) < 2) return pane_width;
    return @min(pane_width, settingsFormColumnWidth(form_pane_width, dpi));
}

fn actionColumnWidth(self: *const SettingsWindow, client_rect: RECT) i32 {
    return settingsActionColumnWidth(paneBounds(self, client_rect).width, formPaneWidth(self, client_rect), self.dpi);
}

test "settings action bar follows the form's column once it has two lanes" {
    for ([_]u32{ 96, 144, 192, 288 }) |dpi| {
        // One lane: the whole pane, so the close prompt's three buttons fit.
        const narrow = scaleForDpi(500, dpi);
        try std.testing.expectEqual(narrow, settingsActionColumnWidth(narrow, narrow, dpi));
        // Two lanes in a wide pane: two full lanes and the gap, not the pane.
        const wide = scaleForDpi(1600, dpi);
        const column = settingsActionColumnWidth(wide, wide, dpi);
        try std.testing.expectEqual(2 * scaleForDpi(settings_field_max_width, dpi) + scaleForDpi(settings_column_gap, dpi), column);
        // Just wide enough for two lanes: the form fills the pane.
        const tight = scaleForDpi(settings_two_column_min_width, dpi);
        try std.testing.expect(settingsActionColumnWidth(tight, tight, dpi) <= tight);
        try std.testing.expect(settingsActionColumnWidth(tight, tight, dpi) >= tight - 1);
        // The right lane ends where the column ends: its control, then the
        // room of its Reset button.
        var rects: [2]SettingsFieldRects = undefined;
        settingsFormItemRects(formItemsForSection(.appearance)[0..2], wide, dpi, &rects);
        try std.testing.expectEqual(column, rects[1].reset.?.right);
        try std.testing.expectEqual(rects[1].reset.?.left - scaleForDpi(settings_reset_gap, dpi), rects[1].control.right);
    }
}

fn measureStaticTextHeight(self: *SettingsWindow, text_opt: ?HWND, width: i32) i32 {
    const text = text_opt orelse return 0;
    var buffer: [2048:0]u16 = undefined;
    const length = GetWindowTextW(text, &buffer, @intCast(buffer.len));
    if (length <= 0) return 0;
    const parent = self.hwnd orelse return 0;
    const hdc = GetDC(parent) orelse return 0;
    defer _ = ReleaseDC(parent, hdc);
    const previous = if (self.ui_font) |font| SelectObject(hdc, font) else null;
    defer {
        if (previous) |font| _ = SelectObject(hdc, font);
    }
    var measure: RECT = .{ .left = 0, .top = 0, .right = @max(1, width), .bottom = 0 };
    _ = DrawTextW(hdc, &buffer, length, &measure, DT_CALCRECT | DT_WORDBREAK | DT_NOPREFIX);
    return @max(self.px(20), measure.bottom - measure.top);
}

fn isComboControl(self: *const SettingsWindow, hwnd: HWND) bool {
    for (self.comboControls()) |combo| if (combo == hwnd) return true;
    return false;
}

/// Child windows to place at once. One `DeferWindowPos` batch moves them all
/// before anything repaints, and Windows invalidates only what moved or was
/// uncovered. If the batch cannot be built, each window is moved on its own.
/// All windows in one batch must share a parent.
fn ChildPlacements(comptime capacity: usize) type {
    return struct {
        windows: [capacity]HWND = undefined,
        rects: [capacity]RECT = undefined,
        flags: [capacity]UINT = undefined,
        len: usize = 0,

        fn add(self: *@This(), hwnd: ?HWND, x: i32, y: i32, width: i32, height: i32) void {
            self.put(hwnd, x, y, width, height, false);
        }

        /// A static whose text wraps to its width. Moving a window keeps
        /// what it showed, and the Static class does not ask to be drawn
        /// again when its size changes (no `CS_HREDRAW`). A resize of the
        /// Settings window repaints every child anyway (its class has
        /// `CS_HREDRAW | CS_VREDRAW`), but a static can change size while the
        /// window keeps its own: a status message that needs a row of its
        /// own, or a DPI change on a window already at its capped minimum,
        /// where `WM_SETFONT` has just drawn the text in the new font at the
        /// old size. Such a static would keep its old picture, so a resized
        /// one is drawn again whole.
        fn addText(self: *@This(), hwnd: ?HWND, x: i32, y: i32, width: i32, height: i32) void {
            self.put(hwnd, x, y, width, height, true);
        }

        fn put(self: *@This(), hwnd: ?HWND, x: i32, y: i32, width: i32, height: i32, wraps: bool) void {
            const window = hwnd orelse return;
            std.debug.assert(self.len < capacity);
            const r: RECT = .{ .left = x, .top = y, .right = x + @max(0, width), .bottom = y + @max(0, height) };
            var flags: UINT = SWP_NOZORDER | SWP_NOACTIVATE;
            if (wraps) {
                var current: RECT = undefined;
                const resized = GetWindowRect(window, &current) == 0 or
                    current.right - current.left != r.right - r.left or
                    current.bottom - current.top != r.bottom - r.top;
                if (resized) flags |= SWP_NOCOPYBITS;
            }
            self.windows[self.len] = window;
            self.rects[self.len] = r;
            self.flags[self.len] = flags;
            self.len += 1;
        }

        fn apply(self: *const @This()) bool {
            if (self.len == 0) return true;
            if (BeginDeferWindowPos(@intCast(self.len))) |first| {
                var batch: ?*anyopaque = first;
                for (self.windows[0..self.len], self.rects[0..self.len], self.flags[0..self.len]) |window, r, flags| {
                    // A failed call has already discarded the batch.
                    batch = DeferWindowPos(batch.?, window, null, r.left, r.top, r.right - r.left, r.bottom - r.top, flags);
                    if (batch == null) break;
                }
                if (batch) |complete| if (EndDeferWindowPos(complete) != 0) return true;
            }
            for (self.windows[0..self.len], self.rects[0..self.len], self.flags[0..self.len]) |window, r, flags| {
                _ = SetWindowPos(window, null, r.left, r.top, r.right - r.left, r.bottom - r.top, flags);
            }
            return false;
        }
    };
}

/// Rail buttons, header, search field, summary, viewport, status, five action
/// buttons.
const settings_frame_child_count = section_count + 10;

const SearchGeometry = struct {
    width: i32,
    height: i32,
    /// From the top of the title's row.
    top: i32,
    /// Between the title and the field.
    gap: i32,
};

/// The search field at the right end of the title's row: a third of the
/// column, from 160 to 280 DIP, never more than half of it. As tall as a text
/// field, centred on the title, so it ends where the line below starts.
fn settingsSearchGeometry(column_width: i32, dpi: u32) SearchGeometry {
    const width = std.math.clamp(@divTrunc(column_width, 3), scaleForDpi(settings_search_min_width, dpi), scaleForDpi(settings_search_max_width, dpi));
    const height = scaleForDpi(settings_control_height, dpi);
    const title = scaleForDpi(settings_header_title_height, dpi);
    return .{
        .width = @max(0, @min(width, @divTrunc(column_width, 2))),
        .height = height,
        .top = @min(@divTrunc(title - height, 2), scaleForDpi(settings_header_summary_top, dpi) - height),
        .gap = scaleForDpi(settings_metrics.space_6, dpi),
    };
}
/// Every label, field and Reset button of the largest section, and the help text.
const settings_form_child_count = settings_max_form_items * 3 + 1 + Companion.count;

/// What the frame window paints besides its background colour.
const BackgroundGeometry = struct {
    rail: RECT,
    rail_separator: RECT,
    header_separator: RECT,
    action_separator: RECT,
};

fn backgroundGeometry(self: *SettingsWindow, client_rect: RECT) BackgroundGeometry {
    const separator_width = @max(1, self.px(settings_metrics.stroke_hairline));
    const rail_right = self.px(settings_rail_width);
    const pane = paneBounds(self, client_rect);
    const column = actionColumnWidth(self, client_rect);
    const rail_geometry = sectionRailGeometry(client_rect.bottom - client_rect.top, self.dpi);
    const header_y = rail_geometry.top_pad + self.px(settings_header_separator_y);
    const action_bar = closePromptLayoutGeometry(self, column, actionBarAvailableHeight(self, client_rect));
    const action_y = client_rect.bottom - action_bar.bar_height;
    return .{
        .rail = .{ .left = client_rect.left, .top = client_rect.top, .right = rail_right, .bottom = client_rect.bottom },
        .rail_separator = .{ .left = rail_right - separator_width, .top = client_rect.top, .right = rail_right, .bottom = client_rect.bottom },
        .header_separator = .{ .left = pane.left, .top = header_y, .right = pane.left + column, .bottom = header_y + separator_width },
        .action_separator = .{ .left = pane.left, .top = action_y, .right = pane.left + column, .bottom = action_y + separator_width },
    };
}

fn layoutChildren(self: *SettingsWindow) void {
    const hwnd = self.hwnd orelse return;
    var rect: RECT = undefined;
    if (GetClientRect(hwnd, &rect) == 0) return;

    var frame: ChildPlacements(settings_frame_child_count) = .{};
    const rail_width = self.px(settings_rail_width);
    const rail_padding = self.px(settings_rail_padding_x);
    const pane_padding = self.px(settings_pane_padding);
    const rail_geometry = sectionRailGeometry(rect.bottom - rect.top, self.dpi);
    var rail_y = rail_geometry.top_pad;
    for (std.enums.values(Section)) |section| {
        frame.add(self.sectionButton(section), rail_padding, rail_y, rail_width - 2 * rail_padding, rail_geometry.button_height);
        rail_y += rail_geometry.button_height + rail_geometry.gap;
    }

    const pane = paneBounds(self, rect);
    const pane_left = pane.left;
    const form_width = formPaneWidth(self, rect);
    const column_width = settingsActionColumnWidth(pane.width, form_width, self.dpi);
    const pane_top = rail_geometry.top_pad;
    const action_bar = closePromptLayoutGeometry(self, column_width, actionBarAvailableHeight(self, rect));
    const action_bar_top = rect.bottom - action_bar.bar_height;
    const viewport_top = pane_top + self.px(settings_form_viewport_top);
    const viewport_bottom = @max(viewport_top, action_bar_top - pane_padding);
    self.proof_viewport_top = viewport_top;
    self.proof_viewport_bottom = viewport_bottom;
    const viewport_height = @max(0, viewport_bottom - viewport_top);

    const prose_width = @min(pane.width, self.px(settings_prose_max_width));
    // The search field ends the title's row at the column's right edge,
    // centred on the title and clear of the line below it.
    const search = settingsSearchGeometry(column_width, self.dpi);
    const title_width = @max(0, @min(prose_width, column_width - search.width - search.gap));
    frame.addText(self.text_header, pane_left, pane_top, title_width, self.px(settings_header_title_height));
    frame.add(self.edit_search, pane_left + column_width - search.width, pane_top + search.top, search.width, search.height);
    frame.addText(self.text_summary, pane_left, pane_top + self.px(settings_header_summary_top), prose_width, self.px(settings_header_summary_height));
    // To the window's right edge, so its scroll bar sits at the edge of the
    // window but only beside the form; and a gutter left of the form's first
    // lane, in the pane's padding, for the markers drawn beside its controls.
    const gutter = self.px(settings_marker_gutter);
    frame.add(self.viewport, pane_left - gutter, viewport_top, rect.right - pane_left + gutter, viewport_height);

    // The form, in viewport coordinates.
    const form_items = self.formItems();
    var item_rects: [settings_max_form_items]SettingsFieldRects = undefined;
    var extent_rects: [settings_max_form_items * 2 + 2]RECT = undefined;
    var extent_count: usize = 0;
    settingsFormItemRects(form_items, form_width, self.dpi, item_rects[0..form_items.len]);
    for (form_items, 0..) |item, index| {
        if (self.controlHwnd(item.control_index) == null) continue;
        if (item.label_index != null) {
            extent_rects[extent_count] = item_rects[index].label;
            extent_count += 1;
        }
        extent_rects[extent_count] = item_rects[index].control;
        extent_count += 1;
    }

    var help_rect: ?RECT = null;
    if (self.showsHelp()) {
        // Below the page's one row, or at the top when none is shown.
        const help_top = if (form_items.len == 0) 0 else self.px(settings_field_row_pitch);
        const help_width = @min(form_width, self.px(settings_prose_max_width));
        const help_height = measureStaticTextHeight(self, self.text_help, help_width);
        if (help_height > 0) {
            help_rect = .{ .left = 0, .top = help_top, .right = help_width, .bottom = help_top + help_height };
            extent_rects[extent_count] = help_rect.?;
            extent_count += 1;
        }
    }
    // The Keybindings page's list: below the page's row and help, to the
    // viewport's bottom, as wide as the column, and scrolling itself, so the
    // page has nothing more to scroll. Where that would leave it shorter than
    // a few rows it keeps that height, and the page scrolls to it
    // (`ensureControlVisible` when it takes the focus).
    var keybind_rect: ?RECT = null;
    if (self.keybind_list.hwnd != null and self.keybindListShows()) {
        var top: i32 = 0;
        for (extent_rects[0..extent_count]) |extent| top = @max(top, extent.bottom);
        if (top > 0) top += self.px(settings_field_row_pitch) - self.px(settings_control_height);
        const min_height = self.px(settings_keybind_list_min_height);
        keybind_rect = .{ .left = 0, .top = top, .right = column_width, .bottom = top + @max(min_height, viewport_height - top) };
        if (viewport_height - top < min_height) {
            extent_rects[extent_count] = keybind_rect.?;
            extent_count += 1;
        }
    }
    const content_extent = settingsContentExtent(extent_rects[0..extent_count], self.px(settings_content_bottom_padding));
    const scroll_geometry = settingsScrollGeometry(content_extent, viewport_height);
    self.content_scroll_max = scroll_geometry.max_position;
    self.content_scroll_y = std.math.clamp(self.content_scroll_y, 0, self.content_scroll_max);
    const scroll_y = self.content_scroll_y;

    var form: ChildPlacements(settings_form_child_count) = .{};
    for (form_items, 0..) |item, index| {
        const control = self.controlHwnd(item.control_index) orelse continue;
        const geometry = item_rects[index];
        if (item.label_index) |label_index| {
            const label = geometry.label;
            form.addText(self.field_labels[label_index], gutter + label.left, label.top - scroll_y, label.right - label.left, label.bottom - label.top);
        }
        // A dropdown's height is that of its open list; its closed height is
        // set afterwards (`fitComboFields`).
        const height = if (isComboControl(self, control)) self.px(settings_combo_popup_height) else self.px(settings_control_height);
        var field_left = geometry.control.left;
        var field_right = geometry.control.right;
        // A trackbar takes the lane and leaves its field a narrow box at the
        // end; an up-down sits at the end, beside its narrowed field.
        if (Companion.ofControl(item.control_index)) |kind| if (self.companions[@intFromEnum(kind)]) |companion| switch (kind) {
            .opacity_slider => {
                const box = @min(self.px(settings_slider_field_width), @divTrunc(field_right - field_left, 2));
                field_left = field_right - box;
                // A thumb of a fixed length, scaled: left to itself the
                // trackbar shortens it in a short window (it is 1 x 1 when
                // made). It sits a fixed way below the trackbar's top, so
                // the trackbar is moved down until the thumb's middle meets
                // the field's.
                const length = self.px(settings_slider_thumb_length);
                if (SendMessageW(companion, TBM_GETTHUMBLENGTH, 0, 0) != length) _ = SendMessageW(companion, TBM_SETTHUMBLENGTH, @intCast(length), 0);
                var thumb: RECT = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
                _ = SendMessageW(companion, TBM_GETTHUMBRECT, 0, @bitCast(@intFromPtr(&thumb)));
                const drop = std.math.clamp(@divTrunc(height, 2) - @divTrunc(thumb.top + thumb.bottom, 2), 0, @divTrunc(height, 2));
                form.add(companion, gutter + geometry.control.left, geometry.control.top - scroll_y + drop, @max(0, field_left - self.px(settings_metrics.space_4) - geometry.control.left), height - drop);
            },
            else => {
                const spin = self.px(settings_spin_width);
                field_right = @max(field_left, field_right - spin - self.px(settings_metrics.space_1));
                form.add(companion, gutter + field_right + self.px(settings_metrics.space_1), geometry.control.top - scroll_y, spin, height);
            },
        };
        form.add(control, gutter + field_left, geometry.control.top - scroll_y, field_right - field_left, height);
        if (geometry.reset) |reset| if (self.reset_buttons[item.control_index]) |button| {
            form.add(button, gutter + reset.left, reset.top - scroll_y, reset.right - reset.left, reset.bottom - reset.top);
        };
    }
    if (help_rect) |help| form.addText(self.text_help, gutter + help.left, help.top - scroll_y, help.right - help.left, help.bottom - help.top);
    // The All settings list fills the viewport as wide as the column and
    // scrolls itself, so the viewport has nothing to scroll on that page.
    if (self.reference_list.hwnd) |list| if (self.referenceListShows()) {
        form.add(list, gutter, 0, column_width, viewport_height);
    };
    if (self.profile_list.hwnd) |list| if (self.profileListShows()) {
        form.add(list, gutter, 0, column_width, viewport_height);
    };
    if (keybind_rect) |placed| form.add(self.keybind_list.hwnd.?, gutter + placed.left, placed.top - scroll_y, placed.right - placed.left, placed.bottom - placed.top);

    const row_top = action_bar_top + action_bar.actions_top;
    const action_gap = self.px(settings_action_gap);
    const normal_actions = action_bar.normal_actions;
    if (!self.close_prompt_visible) frame.add(self.btn_save, pane_left + normal_actions.save_x, row_top + normal_actions.save_y, normal_actions.save_width, normal_actions.button_height);
    frame.add(self.btn_conflict_keep, pane_left + normal_actions.keep_mine_x, row_top + normal_actions.keep_mine_y, normal_actions.keep_mine_width, normal_actions.button_height);
    frame.add(self.btn_conflict_use_disk, pane_left + normal_actions.use_disk_x, row_top + normal_actions.use_disk_y, normal_actions.use_disk_width, normal_actions.button_height);
    const close_actions = action_bar.actions;
    const close_top = action_bar_top + action_bar.actions_top;
    if (self.close_prompt_visible) {
        // The prompt's question, in the status line's window.
        const prompt_width = if (close_actions.stacked) column_width else @max(0, close_actions.first_x - action_gap);
        frame.addText(self.text_status, pane_left, action_bar_top + action_bar.prompt_top, prompt_width, action_bar.prompt_height);
        frame.add(self.btn_discard_changes, pane_left + close_actions.second_x, close_top + close_actions.second_y, close_actions.second_width, close_actions.button_height);
    } else {
        if (action_bar.status_separate) {
            frame.addText(self.text_status, pane_left, action_bar_top + action_bar.status_top, column_width, action_bar.status_height);
        } else {
            frame.addText(self.text_status, pane_left, row_top + self.px(6), @max(0, normal_actions.status_right), self.px(20));
        }
        frame.add(self.btn_discard_changes, pane_left + normal_actions.discard_x, row_top + normal_actions.save_y, normal_actions.discard_width, normal_actions.button_height);
    }
    self.status_row_separate = action_bar.status_separate;
    self.status_row_height = action_bar.status_height;
    if (self.close_prompt_visible) frame.add(self.btn_save, pane_left + close_actions.first_x, close_top, close_actions.first_width, close_actions.button_height);
    frame.add(self.btn_close_keep_editing, pane_left + close_actions.third_x, close_top + close_actions.third_y, close_actions.third_width, close_actions.button_height);

    const frame_batched = frame.apply();
    if (self.viewport) |viewport| {
        const scroll_info: SCROLLINFO = .{
            .cbSize = @sizeOf(SCROLLINFO),
            .fMask = SIF_RANGE | SIF_PAGE | SIF_POS,
            .nMin = 0,
            .nMax = scroll_geometry.nmax,
            .nPage = scroll_geometry.page,
            .nPos = scroll_y,
            .nTrackPos = 0,
        };
        _ = SetScrollInfo(viewport, SB_VERT, &scroll_info, 1);
        _ = ShowScrollBar(viewport, SB_VERT, @intFromBool(self.content_scroll_max > 0));
    }
    const form_batched = form.apply();
    self.fitComboFields();
    self.help_shown = help_rect != null;
    if (self.text_help) |text| setChildShown(text, self.help_shown);
    self.proof_layout_batched = frame_batched and form_batched;
    self.syncViewportClipFlags();
    // The markers are the viewport's own pixels, which moving its children
    // does not repaint.
    self.syncMarkerRects();

    // Moving children repaints them and whatever they uncovered. The frame's
    // own lines move only with the action bar or the column, which a window
    // that keeps its size does not repaint on its own: repaint where each one
    // was and where it is now.
    const background = backgroundGeometry(self, rect);
    if (self.background_geometry) |previous| {
        inline for (std.meta.fields(BackgroundGeometry)) |field| {
            const old_rect = @field(previous, field.name);
            const new_rect = @field(background, field.name);
            if (!std.meta.eql(old_rect, new_rect)) {
                _ = InvalidateRect(hwnd, &old_rect, 0);
                _ = InvalidateRect(hwnd, &new_rect, 0);
            }
        }
    }
    self.background_geometry = background;
}

/// Dialog-semantics tests drive a real Settings window. They run on a desktop
/// of their own (the window is shown, and `SetThreadDesktop` fails on a thread
/// that already owns one), so nothing reaches or takes focus from the user's.
const dialog_test = struct {
    extern "user32" fn CreateDesktopW(
        name: [*:0]const u16,
        device: ?*anyopaque,
        mode: ?*anyopaque,
        flags: u32,
        access: u32,
        attributes: ?*anyopaque,
    ) callconv(.winapi) ?*anyopaque;
    extern "user32" fn SetThreadDesktop(desktop: *anyopaque) callconv(.winapi) BOOL;
    extern "user32" fn CloseDesktop(desktop: *anyopaque) callconv(.winapi) BOOL;
    extern "user32" fn GetClassLongPtrW(hwnd: HWND, index: i32) callconv(.winapi) usize;
    extern "user32" fn LoadIconW(instance: ?HINSTANCE, name: ?*anyopaque) callconv(.winapi) HICON;
    extern "user32" fn GetNextDlgTabItem(dialog: HWND, control: ?HWND, previous: BOOL) callconv(.winapi) ?HWND;
    extern "user32" fn GetKeyboardState(keys: *[256]u8) callconv(.winapi) BOOL;
    extern "user32" fn SetKeyboardState(keys: *const [256]u8) callconv(.winapi) BOOL;

    /// Make exactly these modifiers the ones the calling thread sees held, and
    /// no other key. The whole 256-entry table is replaced, then read back
    /// through `GetKeyState`, which is what the code under test reads: a
    /// table the system refreshed from the real keyboard in between fails here
    /// with the key that leaked, not later in an unrelated assertion.
    fn holdKeys(held: struct { ctrl: bool = false, alt: bool = false, shift: bool = false }) !void {
        var keys: [256]u8 = @splat(0);
        const down: u8 = 0x80;
        if (held.ctrl) keys[VK_CONTROL] = down;
        if (held.alt) keys[VK_MENU] = down;
        if (held.shift) keys[VK_SHIFT] = down;
        try std.testing.expect(SetKeyboardState(&keys) != 0);
        try std.testing.expectEqual(held.ctrl, win32_input.keyPressed(VK_CONTROL));
        try std.testing.expectEqual(held.alt, win32_input.keyPressed(VK_MENU));
        try std.testing.expectEqual(held.shift, win32_input.keyPressed(VK_SHIFT));
    }
    extern "user32" fn GetNextDlgGroupItem(dialog: HWND, control: ?HWND, previous: BOOL) callconv(.winapi) ?HWND;
    extern "gdi32" fn BitBlt(dst: HDC, x: i32, y: i32, width: i32, height: i32, src: HDC, src_x: i32, src_y: i32, rop: u32) callconv(.winapi) BOOL;
    extern "user32" fn HideCaret(hwnd: ?HWND) callconv(.winapi) BOOL;
    extern "user32" fn GetClassNameW(hwnd: HWND, name: [*]u16, count: c_int) callconv(.winapi) c_int;
    extern "user32" fn MapWindowPoints(from: ?HWND, to: ?HWND, points: [*]POINT, count: UINT) callconv(.winapi) c_int;
    extern "gdi32" fn CreateDIBSection(hdc: HDC, info: *const BITMAPINFO, usage: UINT, bits: *?*anyopaque, section: ?*anyopaque, offset: u32) callconv(.winapi) HGDIOBJ;
    extern "gdi32" fn GdiFlush() callconv(.winapi) BOOL;

    const BITMAPINFO = extern struct {
        biSize: u32 = @sizeOf(BITMAPINFO) - 4,
        biWidth: i32,
        biHeight: i32,
        biPlanes: u16 = 1,
        biBitCount: u16 = 32,
        biCompression: u32 = 0,
        biSizeImage: u32 = 0,
        biXPelsPerMeter: i32 = 0,
        biYPelsPerMeter: i32 = 0,
        biClrUsed: u32 = 0,
        biClrImportant: u32 = 0,
        colors: [1]u32 = .{0},
    };

    /// The client area of `hwnd` as its surface holds it now, children
    /// included, top row first: a BitBlt from the window DC, which shows a
    /// missing repaint (a hidden desktop cannot be screen-captured, and
    /// `PrintWindow` repaints everything first).
    const Capture = struct {
        pixels: []u32,
        width: usize,
        height: usize,

        fn take(hwnd: HWND) !Capture {
            var rect: RECT = undefined;
            if (GetClientRect(hwnd, &rect) == 0 or rect.right <= 0 or rect.bottom <= 0) return error.NoClientArea;
            const memory = sys.CreateCompatibleDC(null) orelse return error.NoDC;
            defer _ = sys.DeleteDC(memory);
            const info: BITMAPINFO = .{ .biWidth = rect.right, .biHeight = -rect.bottom };
            var bits: ?*anyopaque = null;
            const bitmap = CreateDIBSection(memory, &info, 0, &bits, null, 0) orelse return error.NoBitmap;
            defer _ = DeleteObject(bitmap);
            const previous = SelectObject(memory, bitmap);
            defer _ = SelectObject(memory, previous);
            const source_dc = GetDC(hwnd) orelse return error.NoDC;
            defer _ = ReleaseDC(hwnd, source_dc);
            const srccopy: u32 = 0x00CC0020;
            if (BitBlt(memory, 0, 0, rect.right, rect.bottom, source_dc, 0, 0, srccopy) == 0) return error.BitBltFailed;
            _ = GdiFlush();
            const width: usize = @intCast(rect.right);
            const height: usize = @intCast(rect.bottom);
            const source: [*]const u32 = @ptrCast(@alignCast(bits.?));
            return .{ .pixels = try std.testing.allocator.dupe(u32, source[0 .. width * height]), .width = width, .height = height };
        }

        fn deinit(self: Capture) void {
            std.testing.allocator.free(self.pixels);
        }

        /// The highest contrast any pixel inside `rect` has against
        /// `against` (a COLORREF).
        fn bestContrast(self: Capture, rect: RECT, against: COLORREF) f64 {
            const RGB = @import("../terminal/color.zig").RGB;
            const base: RGB = .{ .r = @truncate(against), .g = @truncate(against >> 8), .b = @truncate(against >> 16) };
            var best: f64 = 0;
            var y = @max(0, rect.top);
            while (y < @min(rect.bottom, @as(i32, @intCast(self.height)))) : (y += 1) {
                var x = @max(0, rect.left);
                while (x < @min(rect.right, @as(i32, @intCast(self.width)))) : (x += 1) {
                    const pixel = self.pixels[@as(usize, @intCast(y)) * self.width + @as(usize, @intCast(x))];
                    const color: RGB = .{ .r = @truncate(pixel >> 16), .g = @truncate(pixel >> 8), .b = @truncate(pixel) };
                    best = @max(best, color.contrast(base));
                }
            }
            return best;
        }

        /// The pixels inside the circle inscribed in `rect`, `inset` pixels
        /// in from its edge (so none of the corners outside it): how many
        /// there are, how many are `fill` exactly (a COLORREF), and the
        /// highest contrast any of the others has against `fill`.
        const DiscPixels = struct { total: usize, fill: usize, best: f64 };

        fn inDisc(self: Capture, rect: RECT, inset: i32, fill: COLORREF) DiscPixels {
            const RGB = @import("../terminal/color.zig").RGB;
            const base: RGB = .{ .r = @truncate(fill), .g = @truncate(fill >> 8), .b = @truncate(fill >> 16) };
            // In half pixels, so a pixel's centre is a whole number.
            const center_x: i64 = rect.left + rect.right;
            const center_y: i64 = rect.top + rect.bottom;
            const radius: i64 = @divTrunc(@min(rect.right - rect.left, rect.bottom - rect.top), 2) - inset;
            var result: DiscPixels = .{ .total = 0, .fill = 0, .best = 0 };
            if (radius <= 0) return result;
            var y = @max(0, rect.top);
            while (y < @min(rect.bottom, @as(i32, @intCast(self.height)))) : (y += 1) {
                var x = @max(0, rect.left);
                while (x < @min(rect.right, @as(i32, @intCast(self.width)))) : (x += 1) {
                    const dx: i64 = 2 * @as(i64, x) + 1 - center_x;
                    const dy: i64 = 2 * @as(i64, y) + 1 - center_y;
                    if (dx * dx + dy * dy > 4 * radius * radius) continue;
                    result.total += 1;
                    const pixel = self.pixels[@as(usize, @intCast(y)) * self.width + @as(usize, @intCast(x))];
                    const color: RGB = .{ .r = @truncate(pixel >> 16), .g = @truncate(pixel >> 8), .b = @truncate(pixel) };
                    if (color.r == base.r and color.g == base.g and color.b == base.b) {
                        result.fill += 1;
                    } else {
                        result.best = @max(result.best, color.contrast(base));
                    }
                }
            }
            return result;
        }

        fn rows(self: Capture, top: i32, bottom: i32) []const u32 {
            const first: usize = @intCast(std.math.clamp(top, 0, @as(i32, @intCast(self.height))));
            const last: usize = @intCast(std.math.clamp(bottom, top, @as(i32, @intCast(self.height))));
            return self.pixels[first * self.width .. last * self.width];
        }

        /// Pixels inside `rect` (client coordinates) that differ from `other`,
        /// skipping the columns `skip_left`..`skip_right`.
        fn countDifferent(self: Capture, other: Capture, rect: RECT, skip_left: i32, skip_right: i32) usize {
            var count: usize = 0;
            var y = @max(0, rect.top);
            while (y < @min(rect.bottom, @as(i32, @intCast(self.height)))) : (y += 1) {
                var x = @max(0, rect.left);
                while (x < @min(rect.right, @as(i32, @intCast(self.width)))) : (x += 1) {
                    if (x >= skip_left and x < skip_right) continue;
                    const index = @as(usize, @intCast(y)) * self.width + @as(usize, @intCast(x));
                    if (self.pixels[index] != other.pixels[index]) count += 1;
                }
            }
            return count;
        }
    };

    extern "user32" fn PrintWindow(hwnd: HWND, hdc: HDC, flags: UINT) callconv(.winapi) BOOL;

    /// What `draw(context, hdc, clip)` draws into a memory DC the size of
    /// `client`: a paint function's own output, nothing of the screen's.
    fn paintInto(client: RECT, context: anytype, comptime draw: anytype) !Capture {
        if (client.right <= 0 or client.bottom <= 0) return error.NoClientArea;
        const memory = sys.CreateCompatibleDC(null) orelse return error.NoDC;
        defer _ = sys.DeleteDC(memory);
        const info: BITMAPINFO = .{ .biWidth = client.right, .biHeight = -client.bottom };
        var bits: ?*anyopaque = null;
        const bitmap = CreateDIBSection(memory, &info, 0, &bits, null, 0) orelse return error.NoBitmap;
        defer _ = DeleteObject(bitmap);
        const previous = SelectObject(memory, bitmap);
        defer _ = SelectObject(memory, previous);
        draw(context, memory, client);
        _ = GdiFlush();
        const width: usize = @intCast(client.right);
        const height: usize = @intCast(client.bottom);
        const source: [*]const u32 = @ptrCast(@alignCast(bits.?));
        return .{ .pixels = try std.testing.allocator.dupe(u32, source[0 .. width * height]), .width = width, .height = height };
    }

    /// The client area of `hwnd` as `PrintWindow` gives it: the window
    /// repainted (one `WM_PAINT`) and each child's pixels as they stand, so
    /// a child left stale shows as the screen shows it. Only this window's
    /// pixels: `Capture.take` reads the desktop's screen surface, and on a
    /// hidden desktop the parts of a large window (2144 x 1353 at 288 DPI)
    /// read the interactive desktop's pixels instead. So a capture that is
    /// kept, or of a window that may outgrow the screen, goes through here.
    ///
    /// Every part is read while it lies on the window's monitor. A window
    /// partly on its monitor, with a child in the gap below that monitor
    /// (beside a taller one), has now and then had that child come back black
    /// from `PrintWindow` in runs beside other test runs, while the child drew
    /// its own colours when asked directly (`WM_PRINTCLIENT`). That strongly
    /// suggests an artifact of capturing off the monitor; the mechanism inside
    /// Windows is not established. So a client area that is not wholly on its
    /// monitor is moved there a monitor-sized piece at a time, each piece read
    /// in turn, and the window put back where it was.
    fn printClient(hwnd: HWND) !Capture {
        return printClientInPieces(hwnd, null);
    }

    /// How many pieces the last `printClient` read with the window moved:
    /// none for a client area read where it is.
    var moved_pieces: usize = 0;

    /// `printClient`, in pieces no larger than `most` when it is given, even
    /// for a window wholly on its monitor.
    fn printClientInPieces(hwnd: HWND, most: ?POINT) !Capture {
        moved_pieces = 0;
        if (most) |size| if (size.x <= 0 or size.y <= 0) return error.EmptyPiece;
        var rect: RECT = undefined;
        if (GetClientRect(hwnd, &rect) == 0 or rect.right <= 0 or rect.bottom <= 0) return error.NoClientArea;
        const monitor = monitorOf(hwnd) orelse return error.NoMonitor;
        var window: RECT = undefined;
        if (GetWindowRect(hwnd, &window) == 0) return error.NoWindowRect;
        var origin: POINT = .{ .x = 0, .y = 0 };
        if (sys.ClientToScreen(hwnd, &origin) == 0) return error.NoClientOrigin;
        const width: usize = @intCast(rect.right);
        const height: usize = @intCast(rect.bottom);
        const pixels = try std.testing.allocator.alloc(u32, width * height);
        errdefer std.testing.allocator.free(pixels);
        if (most == null and origin.x >= monitor.left and origin.y >= monitor.top and
            origin.x + rect.right <= monitor.right and origin.y + rect.bottom <= monitor.bottom)
        {
            try printClientPiece(hwnd, rect, rect, pixels);
            return .{ .pixels = pixels, .width = width, .height = height };
        }
        errdefer _ = sys.SetWindowPos(hwnd, null, window.left, window.top, 0, 0, SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE);
        const piece_width = @min(monitor.right - monitor.left, if (most) |size| size.x else std.math.maxInt(i32));
        const piece_height = @min(monitor.bottom - monitor.top, if (most) |size| size.y else std.math.maxInt(i32));
        var top: i32 = 0;
        while (top < rect.bottom) : (top += piece_height) {
            var left: i32 = 0;
            while (left < rect.right) : (left += piece_width) {
                // The piece's top left corner on the monitor's.
                const x = monitor.left - left - (origin.x - window.left);
                const y = monitor.top - top - (origin.y - window.top);
                if (sys.SetWindowPos(hwnd, null, x, y, 0, 0, SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE) == 0) return error.MoveFailed;
                // What the move left to paint, painted as the screen would.
                if (RedrawWindow(hwnd, null, null, RDW_UPDATENOW | RDW_ALLCHILDREN) == 0) return error.RedrawFailed;
                const piece: RECT = .{
                    .left = left,
                    .top = top,
                    .right = @min(rect.right, left + piece_width),
                    .bottom = @min(rect.bottom, top + piece_height),
                };
                // The move kept the window's size (no DPI change resized it)
                // and put the piece on the monitor.
                var moved: RECT = undefined;
                var at: POINT = .{ .x = piece.left, .y = piece.top };
                if (GetClientRect(hwnd, &moved) == 0 or moved.right != rect.right or moved.bottom != rect.bottom) return error.CaptureResized;
                if (sys.ClientToScreen(hwnd, &at) == 0 or at.x < monitor.left or at.y < monitor.top or
                    at.x + (piece.right - piece.left) > monitor.right or at.y + (piece.bottom - piece.top) > monitor.bottom) return error.PieceOffMonitor;
                try printClientPiece(hwnd, rect, piece, pixels);
                moved_pieces += 1;
            }
        }
        if (sys.SetWindowPos(hwnd, null, window.left, window.top, 0, 0, SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE) == 0) return error.RestoreFailed;
        return .{ .pixels = pixels, .width = width, .height = height };
    }

    /// `PrintWindow` of `hwnd`'s client area `client`, the pixels inside
    /// `piece` copied into `pixels` (the whole client area's, top row first).
    fn printClientPiece(hwnd: HWND, client: RECT, piece: RECT, pixels: []u32) !void {
        const memory = sys.CreateCompatibleDC(null) orelse return error.NoDC;
        defer _ = sys.DeleteDC(memory);
        const info: BITMAPINFO = .{ .biWidth = client.right, .biHeight = -client.bottom };
        var bits: ?*anyopaque = null;
        const bitmap = CreateDIBSection(memory, &info, 0, &bits, null, 0) orelse return error.NoBitmap;
        defer _ = DeleteObject(bitmap);
        const previous = SelectObject(memory, bitmap);
        defer _ = SelectObject(memory, previous);
        // `PW_RENDERFULLCONTENT` is left out: it asks the compositor, which
        // a hidden desktop does not have.
        const PW_CLIENTONLY: UINT = 1;
        if (PrintWindow(hwnd, memory, PW_CLIENTONLY) == 0) return error.PrintWindowFailed;
        _ = GdiFlush();
        const width: usize = @intCast(client.right);
        const source: [*]const u32 = @ptrCast(@alignCast(bits.?));
        const left: usize = @intCast(piece.left);
        const right: usize = @intCast(piece.right);
        for (@as(usize, @intCast(piece.top))..@as(usize, @intCast(piece.bottom))) |row| {
            @memcpy(pixels[row * width + left .. row * width + right], source[row * width + left .. row * width + right]);
        }
    }

    /// The rect of the monitor `hwnd` is on, or the nearest one.
    fn monitorOf(hwnd: HWND) ?RECT {
        const monitor = sys.MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST) orelse return null;
        var info: MONITORINFO = .{ .cbSize = @sizeOf(MONITORINFO), .rcMonitor = undefined, .rcWork = undefined, .dwFlags = 0 };
        if (sys.GetMonitorInfoW(monitor, &info) == 0) return null;
        return info.rcMonitor;
    }

    /// Write `capture` as a 32-bit BMP named `name` into the directory
    /// `NOCTTY_SETTINGS_CAPTURE_DIR` names, when it is set: evidence for a
    /// reviewer, never read back.
    fn saveCapture(capture: Capture, name: []const u8) !void {
        const dir_path = std.process.getEnvVarOwned(std.testing.allocator, "NOCTTY_SETTINGS_CAPTURE_DIR") catch return;
        defer std.testing.allocator.free(dir_path);
        var dir = try std.fs.openDirAbsolute(dir_path, .{});
        defer dir.close();
        const file = try dir.createFile(name, .{});
        defer file.close();
        const width: u32 = @intCast(capture.width);
        const height: u32 = @intCast(capture.height);
        var header: [54]u8 = @splat(0);
        header[0] = 'B';
        header[1] = 'M';
        std.mem.writeInt(u32, header[2..6], 54 + width * height * 4, .little);
        std.mem.writeInt(u32, header[10..14], 54, .little);
        std.mem.writeInt(u32, header[14..18], 40, .little);
        std.mem.writeInt(i32, header[18..22], @intCast(width), .little);
        std.mem.writeInt(i32, header[22..26], -@as(i32, @intCast(height)), .little);
        std.mem.writeInt(u16, header[26..28], 1, .little);
        std.mem.writeInt(u16, header[28..30], 32, .little);
        try file.writeAll(&header);
        try file.writeAll(std.mem.sliceAsBytes(capture.pixels));
    }

    /// comctl32 6 active on this thread while it lasts. The app's manifest
    /// asks for it and the test binary has none, so without this a window
    /// made in a test is a classic, unthemed control, which no user sees.
    const CommonControls6 = struct {
        context: windows.HANDLE,
        cookie: usize,

        const ACTCTXW = extern struct {
            cbSize: u32 = @sizeOf(ACTCTXW),
            dwFlags: u32 = 0,
            lpSource: [*:0]const u16,
            wProcessorArchitecture: u16 = 0,
            wLangId: u16 = 0,
            lpAssemblyDirectory: ?[*:0]const u16 = null,
            lpResourceName: ?[*:0]const u16 = null,
            lpApplicationName: ?[*:0]const u16 = null,
            hModule: ?*anyopaque = null,
        };
        extern "kernel32" fn CreateActCtxW(*const ACTCTXW) callconv(.winapi) windows.HANDLE;
        extern "kernel32" fn ActivateActCtx(windows.HANDLE, *usize) callconv(.winapi) BOOL;
        extern "kernel32" fn DeactivateActCtx(u32, usize) callconv(.winapi) BOOL;
        extern "kernel32" fn ReleaseActCtx(windows.HANDLE) callconv(.winapi) void;

        fn activate() !CommonControls6 {
            var tmp = std.testing.tmpDir(.{});
            defer tmp.cleanup();
            // The dependency the app's manifest (`dist/windows/noctty.manifest`) declares.
            const manifest =
                \\<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
                \\<assembly xmlns="urn:schemas-microsoft-com:asm.v1" manifestVersion="1.0">
                \\  <dependency><dependentAssembly>
                \\    <assemblyIdentity type="win32" name="Microsoft.Windows.Common-Controls" version="6.0.0.0" processorArchitecture="*" publicKeyToken="6595b64144ccf1df" language="*" />
                \\  </dependentAssembly></dependency>
                \\</assembly>
            ;
            try tmp.dir.writeFile(.{ .sub_path = "comctl6.manifest", .data = manifest });
            const path = try tmp.dir.realpathAlloc(std.testing.allocator, "comctl6.manifest");
            defer std.testing.allocator.free(path);
            const path_w = try std.unicode.utf8ToUtf16LeAllocZ(std.testing.allocator, path);
            defer std.testing.allocator.free(path_w);
            // The context reads the file here, so it may go with the directory.
            const context = CreateActCtxW(&.{ .lpSource = path_w });
            if (context == windows.INVALID_HANDLE_VALUE) return error.ActivationContextUnavailable;
            var cookie: usize = 0;
            if (ActivateActCtx(context, &cookie) == 0) {
                ReleaseActCtx(context);
                return error.ActivationContextUnavailable;
            }
            return .{ .context = context, .cookie = cookie };
        }

        fn deactivate(self: CommonControls6) void {
            _ = DeactivateActCtx(0, self.cookie);
            ReleaseActCtx(self.context);
        }
    };

    /// The colour most of `rect`'s pixels have (0x00RRGGBB).
    fn dominantColor(capture: Capture, rect: RECT) ?u32 {
        var counts = std.AutoHashMap(u32, u32).init(std.testing.allocator);
        defer counts.deinit();
        var best: ?u32 = null;
        var best_count: u32 = 0;
        var y = @max(0, rect.top);
        while (y < @min(rect.bottom, @as(i32, @intCast(capture.height)))) : (y += 1) {
            var x = @max(0, rect.left);
            while (x < @min(rect.right, @as(i32, @intCast(capture.width)))) : (x += 1) {
                const pixel = capture.pixels[@as(usize, @intCast(y)) * capture.width + @as(usize, @intCast(x))] & 0xFFFFFF;
                const entry = counts.getOrPut(pixel) catch return null;
                if (!entry.found_existing) entry.value_ptr.* = 0;
                entry.value_ptr.* += 1;
                if (entry.value_ptr.* > best_count) {
                    best_count = entry.value_ptr.*;
                    best = pixel;
                }
            }
        }
        return best;
    }

    /// WCAG relative luminance of a 0x00RRGGBB pixel.
    fn luminanceOf(pixel: u32) f64 {
        const RGB = @import("../terminal/color.zig").RGB;
        return (RGB{ .r = @truncate(pixel >> 16), .g = @truncate(pixel >> 8), .b = @truncate(pixel) }).luminance();
    }

    /// Lay the window out as on a monitor at `dpi`, the way `WM_DPICHANGED`
    /// does (fonts, metrics, layout), without moving it to such a monitor.
    fn simulateDpi(hwnd: HWND, dpi: u32) void {
        var rect: RECT = undefined;
        _ = GetWindowRect(hwnd, &rect);
        _ = SendMessageW(hwnd, WM_DPICHANGED, (@as(usize, dpi) << 16) | dpi, @bitCast(@intFromPtr(&rect)));
    }

    /// Make every section's rows, as if each had been shown once, for a test
    /// that reaches into sections it does not show.
    fn makeAllSections(settings: *SettingsWindow) void {
        for (std.enums.values(Section)) |section| settings.materializeSection(section);
    }

    /// Dispatch the messages that are queued for this thread: posted ones and
    /// a timer that has come due.
    fn pump() void {
        var msg: sys.MSG = undefined;
        while (sys.PeekMessageW(&msg, null, 0, 0, 1) != 0) {
            _ = sys.TranslateMessage(&msg);
            _ = sys.DispatchMessageW(&msg);
        }
    }

    /// Paint everything that is waiting to be painted, children included.
    fn flushPaint(hwnd: HWND) void {
        _ = RedrawWindow(hwnd, null, null, RDW_UPDATENOW | RDW_ALLCHILDREN);
    }

    /// Every window that gets the focus between `start` and `stop`, in order:
    /// `WM_SETFOCUS` as user32 delivers it on this thread (a thread-local
    /// `WH_CALLWNDPROC` hook), which is what a screen reader hears as a focus
    /// move.
    const FocusTrace = struct {
        var focused: [16]HWND = undefined;
        var len: usize = 0;
        var hook: ?*anyopaque = null;

        fn sent(code: c_int, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
            if (code >= 0) {
                const message: *const OpenWork.CWPSTRUCT = @ptrFromInt(@as(usize, @bitCast(lParam)));
                if (message.message == WM_SETFOCUS and len < focused.len) {
                    focused[len] = message.hwnd;
                    len += 1;
                }
            }
            return OpenWork.CallNextHookEx(null, code, wParam, lParam);
        }

        fn start() !void {
            len = 0;
            hook = OpenWork.SetWindowsHookExW(OpenWork.WH_CALLWNDPROC, &sent, null, sys.GetCurrentThreadId()) orelse return error.HookUnavailable;
        }

        fn stop() []const HWND {
            if (hook) |installed| _ = OpenWork.UnhookWindowsHookEx(installed);
            hook = null;
            return focused[0..len];
        }
    };

    /// What the window shows now equals a full repaint of it: nothing was left
    /// unpainted or stale by whatever ran before. The caret is hidden.
    fn expectNothingStale(hwnd: HWND) !void {
        _ = HideCaret(null);
        flushPaint(hwnd);
        const shown = try Capture.take(hwnd);
        defer shown.deinit();
        const rdw_frame: UINT = 0x0400;
        _ = RedrawWindow(hwnd, null, null, RDW_INVALIDATE | rdw_frame | RDW_ALLCHILDREN | RDW_UPDATENOW);
        const repainted = try Capture.take(hwnd);
        defer repainted.deinit();
        const all: RECT = .{ .left = 0, .top = 0, .right = @intCast(shown.width), .bottom = @intCast(shown.height) };
        const stale = shown.countDifferent(repainted, all, 0, 0);
        if (stale != 0) {
            var box: RECT = .{ .left = std.math.maxInt(i32), .top = std.math.maxInt(i32), .right = -1, .bottom = -1 };
            for (shown.pixels, repainted.pixels, 0..) |a, b, index| if (a != b) {
                const x: i32 = @intCast(index % shown.width);
                const y: i32 = @intCast(index / shown.width);
                box = .{ .left = @min(box.left, x), .top = @min(box.top, y), .right = @max(box.right, x + 1), .bottom = @max(box.bottom, y + 1) };
            };
            std.debug.print("stale pixels {d} in ({d},{d})-({d},{d}) of a {d}x{d} client\n", .{ stale, box.left, box.top, box.right, box.bottom, shown.width, shown.height });
            // The first rows' runs of stale pixels, with both colours.
            var y: usize = @intCast(box.top);
            while (y < @min(@as(usize, @intCast(box.bottom)), @as(usize, @intCast(box.top)) + 16)) : (y += 1) {
                var x: usize = 0;
                var runs: usize = 0;
                while (x < shown.width and runs < 4) : (x += 1) {
                    const index = y * shown.width + x;
                    if (shown.pixels[index] == repainted.pixels[index]) continue;
                    const start = x;
                    while (x < shown.width and shown.pixels[y * shown.width + x] != repainted.pixels[y * shown.width + x]) x += 1;
                    std.debug.print("  y={d} x={d}..{d} shown=0x{x:0>6} repainted=0x{x:0>6}\n", .{ y, start, x, shown.pixels[index] & 0xFFFFFF, repainted.pixels[index] & 0xFFFFFF });
                    runs += 1;
                }
            }
            // The visible windows that cover them. A point lookup would not
            // do: a static answers `HTTRANSPARENT`, so it reports the parent.
            const Overlapping = struct {
                var root: HWND = undefined;
                var area: RECT = undefined;
                fn each(child: HWND, _: LPARAM) callconv(.winapi) BOOL {
                    if (sys.IsWindowVisible(child) == 0) return 1;
                    const r = rectIn(root, child);
                    if (r.right <= area.left or r.left >= area.right or r.bottom <= area.top or r.top >= area.bottom) return 1;
                    var class_w: [64]u16 = undefined;
                    const length = GetClassNameW(child, &class_w, class_w.len);
                    std.debug.print("  under them: {f} ({d},{d})-({d},{d}), a direct child: {}\n", .{
                        std.unicode.fmtUtf16Le(class_w[0..@intCast(@max(0, length))]),
                        r.left,
                        r.top,
                        r.right,
                        r.bottom,
                        sys.GetParent(child) == root,
                    });
                    return 1;
                }
            };
            Overlapping.root = hwnd;
            Overlapping.area = box;
            _ = sys.EnumChildWindows(hwnd, Overlapping.each, 0);
        }
        try std.testing.expectEqual(@as(usize, 0), stale);
    }

    /// `child`'s window rect in `parent`'s client coordinates.
    fn rectIn(parent: HWND, child: HWND) RECT {
        var rect: RECT = undefined;
        _ = GetWindowRect(child, &rect);
        var corners = [_]POINT{ .{ .x = rect.left, .y = rect.top }, .{ .x = rect.right, .y = rect.bottom } };
        _ = MapWindowPoints(null, parent, &corners, 2);
        return .{ .left = corners[0].x, .top = corners[0].y, .right = corners[1].x, .bottom = corners[1].y };
    }

    const GCLP_HICON: i32 = -14;
    const GCLP_HICONSM: i32 = -34;
    const WM_GETICON: UINT = 0x007F;
    const IDI_APPLICATION: usize = 32512;
    const WA_ACTIVE: usize = 1;

    fn run(desktop: *anyopaque, result: *anyerror!void, body: *const fn () anyerror!void) void {
        if (SetThreadDesktop(desktop) == 0) {
            result.* = error.SkipZigTest;
            return;
        }
        body() catch |err| {
            if (@errorReturnTrace()) |trace| std.debug.dumpStackTrace(trace.*);
            result.* = err;
        };
    }

    fn onHiddenDesktop(body: *const fn () anyerror!void) !void {
        // One desktop per test process. Two test runs at once (parallel
        // worktrees) shared one named desktop, and the Ctrl+S test failed in a
        // run that overlapped another one while passing on its own.
        var name_utf8: [64]u8 = undefined;
        const name = try std.fmt.bufPrint(&name_utf8, "noctty-test-settings-dialog-{d}", .{windows.GetCurrentProcessId()});
        var name_w: [64:0]u16 = undefined;
        const desktop = CreateDesktopW(
            utf8ToW(&name_w, name),
            null,
            null,
            0,
            0x10000000, // GENERIC_ALL
            null,
        ) orelse return error.SkipZigTest;
        defer _ = CloseDesktop(desktop);
        var result: anyerror!void = {};
        const thread = try std.Thread.spawn(.{}, run, .{ desktop, &result, body });
        thread.join();
        try result;
    }

    /// A Settings window opened over stub callbacks that count what reaches the App.
    const Fixture = struct {
        config: Config,
        settings: SettingsWindow,
        icon: HICON,
        closed: u32 = 0,
        editor_opened: u32 = 0,
        saved: u32 = 0,
        custom_uia: bool = false,
        /// Whether a live preview writes into `config`, which is what
        /// `currentConfig` hands back. The App keeps its previews out of that
        /// config (`App.settings_preview`); one that wrote them in, as it once
        /// did, is the harder case for Discard, which then has to take them
        /// back before it reads it.
        live_previews: bool = false,
        /// How many live previews reached the App.
        previews: u32 = 0,
        /// A save writes, its reload applies, and then it fails.
        reload_then_fail: bool = false,
        /// What the window's High Contrast probe answers.
        high_contrast: bool = false,
        /// A save writes this config file the way the App's does
        /// (`persistSettings`), patching only the keys edited.
        save_path: ?[]const u8 = null,
        /// After writing `save_path`, the save reads it again, with the files
        /// it includes, into `config`, and reports the edited keys whose
        /// value something read later overrides, as the App does
        /// (`settingsMaskedKeyNames`, `SaveError.SavedButMasked`).
        reload_from_disk: bool = false,
        /// The command line that reload reads after `save_path`, with its
        /// places, as `Config.load` reads noctty's.
        reload_args: []const []const u8 = &.{},
        /// The file `AppHandle.configSource` reads, as the App's does; none
        /// when null.
        source_path: ?[]const u8 = null,
        /// What the save's reload found masked: keys, then profile fields.
        masked: [1024]u8 = undefined,
        masked_len: usize = 0,
        /// What the All settings page's "Copy name" handed the App last, and
        /// how many times: a recorder, so no test reaches the clipboard.
        copied: [128]u8 = undefined,
        copied_len: usize = 0,
        copies: u32 = 0,
        /// The recorder answers as a clipboard that would not take the text.
        copy_fails: bool = false,
        /// What the Default profile dropdown is offered: `test_profiles`,
        /// whole or not yet.
        profiles_complete: bool = true,
        profile_lists: u32 = 0,
        /// The lists asked with `ask` false (refills that must not ask).
        profile_refills: u32 = 0,
        /// Leave `user:py312` out of the list, as a reload that removed it.
        drop_py312: bool = false,
        /// Show `user:py312` with this label, as a reload that relabelled it.
        relabel_py312: ?[]const u8 = null,
        /// Refill the dropdown from inside a list that asks, as a discovery
        /// that fails on the UI thread does (`profilesChanged`), up to 3 deep.
        refill_when_asked: bool = false,
        nested_refills: u32 = 0,
        /// The label of the profile the loaded config resolved an unlisted
        /// saved value to, as the App answers for an `ssh:` alias outside
        /// the SSH config.
        resolved_label: ?[]const u8 = null,

        /// The fixture's profiles, as `AppHandle.profileChoices` lists them:
        /// shown ones first, then the hidden tail.
        const test_profiles = [_]ProfileChoice{
            .{ .key = "pwsh.exe", .label = "PowerShell" },
            .{ .key = "cmd.exe", .label = "Command Prompt" },
            .{ .key = "user:py312", .label = "Python 3.12" },
            .{ .key = "wsl:docker-desktop", .label = "WSL: docker-desktop", .hidden = true },
        };

        fn start() !*Fixture {
            return startWith(false);
        }

        fn startWith(custom_uia: bool) !*Fixture {
            const self = try prepare(custom_uia);
            errdefer self.finish();
            try self.settings.open();
            return self;
        }

        /// The fixture over a config in which every editable row differs
        /// from its default (`field_model.round_trip_config`), opened.
        fn startChanged(custom_uia: bool) !*Fixture {
            const self = try prepareChanged(custom_uia);
            errdefer self.finish();
            try self.settings.open();
            return self;
        }

        /// `startChanged`, not opened yet.
        fn prepareChanged(custom_uia: bool) !*Fixture {
            const self = try prepare(custom_uia);
            errdefer self.finish();
            var tmp = std.testing.tmpDir(.{});
            defer tmp.cleanup();
            try tmp.dir.writeFile(.{ .sub_path = "changed.ghostty", .data = field_model.round_trip_config });
            const path = try tmp.dir.realpathAlloc(std.testing.allocator, "changed.ghostty");
            defer std.testing.allocator.free(path);
            try self.config.loadFile(std.testing.allocator, path);
            try std.testing.expect(self.config._diagnostics.empty());
            // The fixture's `tip` is this build's own channel on a tip build,
            // which is the default there (`effectiveSettingValue`).
            const release_channel = @import("../build_config.zig").release_channel;
            self.config.@"auto-update-channel" = if (release_channel == .stable) .tip else .stable;
            return self;
        }

        /// The fixture with its window not opened yet.
        fn prepare(custom_uia: bool) !*Fixture {
            const self = try std.testing.allocator.create(Fixture);
            errdefer std.testing.allocator.destroy(self);
            self.* = .{
                .config = try Config.default(std.testing.allocator),
                .settings = undefined,
                .icon = LoadIconW(null, @ptrFromInt(IDI_APPLICATION)),
                .custom_uia = custom_uia,
            };
            errdefer self.config.deinit();
            self.settings = SettingsWindow.init(.{
                .ctx = self,
                .alloc = std.testing.allocator,
                .hinstance = sys.GetModuleHandleW(null),
                .appIcon = &appIcon,
                .chromeBg = &stubChromeBg,
                .textPrimary = &stubTextPrimary,
                .openInEditor = &openInEditor,
                .copyText = &copyText,
                .currentConfig = &currentConfig,
                .saveAndReload = &saveAndReload,
                .notifySuccess = &notifySuccess,
                .customUiaProvidersEnabled = &customUia,
                .previewField = &previewField,
                .highContrast = &highContrast,
                .profileChoices = &profileChoices,
                .maskedKeys = &maskedKeys,
                .onClosed = &onClosed,
                .configSource = &configSource,
            });
            self.settings.wheel_lines_override = 3;
            return self;
        }

        fn copyText(ctx: *anyopaque, text: []const u8) bool {
            const self: *Fixture = @ptrCast(@alignCast(ctx));
            self.copies += 1;
            self.copied_len = @min(text.len, self.copied.len);
            @memcpy(self.copied[0..self.copied_len], text[0..self.copied_len]);
            return !self.copy_fails;
        }

        fn copiedText(self: *const Fixture) []const u8 {
            return self.copied[0..self.copied_len];
        }

        fn maskedKeys(ctx: *anyopaque) ?[]const u8 {
            const self: *Fixture = @ptrCast(@alignCast(ctx));
            return if (self.masked_len == 0) null else self.masked[0..self.masked_len];
        }

        fn configSource(ctx: *anyopaque, alloc: std.mem.Allocator) settings_reference.ConfigSource {
            const self: *Fixture = @ptrCast(@alignCast(ctx));
            const path = self.source_path orelse return .{};
            return readConfigSource(alloc, path);
        }

        fn finish(self: *Fixture) void {
            self.settings.deinit();
            _ = sys.UnregisterClassW(class_name, self.settings.handle.hinstance);
            _ = sys.UnregisterClassW(viewport_class_name, self.settings.handle.hinstance);
            _ = sys.UnregisterClassW(reference_list_class_name, self.settings.handle.hinstance);
            self.config.deinit();
            std.testing.allocator.destroy(self);
        }

        fn hwnd(self: *const Fixture) HWND {
            return self.settings.hwnd.?;
        }

        fn appIcon(ctx: *anyopaque, _: bool) HICON {
            const self: *Fixture = @ptrCast(@alignCast(ctx));
            return self.icon;
        }

        fn openInEditor(ctx: *anyopaque) void {
            const self: *Fixture = @ptrCast(@alignCast(ctx));
            self.editor_opened += 1;
        }

        fn currentConfig(ctx: *anyopaque) *const Config {
            const self: *Fixture = @ptrCast(@alignCast(ctx));
            return &self.config;
        }

        fn saveAndReload(ctx: *anyopaque, pending: *const Config, original: *const Config) SaveError!void {
            const self: *Fixture = @ptrCast(@alignCast(ctx));
            self.saved += 1;
            if (self.save_path) |path| {
                const app = @import("win32.zig");
                const settings_patch = @import("win32/settings_patch.zig");
                const edited = app.settingsUserEditedKeys(original, pending);
                // The profile editor's changes, as the App works them out.
                var profile_arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
                defer profile_arena.deinit();
                const profile_edits = settings_patch.editsForSave(profile_arena.allocator(), std.testing.allocator, &self.config, original, pending, path, &settings_reference.samePath) catch
                    return error.OutOfMemory;
                try app.persistSettings(std.testing.allocator, path, pending, edited, profile_edits, null);
                if (self.reload_from_disk) {
                    var reloaded = Config.default(std.testing.allocator) catch return error.ReloadFailed;
                    read: {
                        reloaded.loadFile(std.testing.allocator, path) catch break :read;
                        const cli_args = @import("../cli/args.zig");
                        var args: cli_args.ArgsIterator(cli_args.SliceIterator) = .{ .iterator = cli_args.sliceIterator(self.reload_args) };
                        reloaded.loadIter(std.testing.allocator, &args) catch break :read;
                        reloaded.loadRecursiveFiles(std.testing.allocator) catch break :read;
                        var keys: [app.settings_masked_keys_capacity]u8 = undefined;
                        var masked: std.Io.Writer = .fixed(&self.masked);
                        masked.writeAll(app.settingsMaskedKeyNames(&keys, edited, pending, &reloaded)) catch {};
                        _ = settings_patch.writeMasked(&masked, profile_edits, &reloaded, masked.end > 0) catch {};
                        self.masked_len = masked.end;
                        self.config.deinit();
                        self.config = reloaded;
                        if (self.masked_len != 0) return error.SavedButMasked;
                        return;
                    }
                    reloaded.deinit();
                    return error.ReloadFailed;
                }
            }
            if (self.reload_then_fail) {
                // The App's reload during a save shows no preview.
                self.config.@"background-opacity" = 1;
                return error.ReloadFailed;
            }
        }

        fn previewField(ctx: *anyopaque, _: SettingField, value: SettingValue) void {
            const self: *Fixture = @ptrCast(@alignCast(ctx));
            self.previews += 1;
            if (self.live_previews) setSettingValue(&self.config, value);
        }

        fn customUia(ctx: *anyopaque) bool {
            const self: *Fixture = @ptrCast(@alignCast(ctx));
            return self.custom_uia;
        }

        fn highContrast(ctx: *anyopaque) bool {
            const self: *Fixture = @ptrCast(@alignCast(ctx));
            return self.high_contrast;
        }

        /// The App resolves a reference by the picker's rules; here a key in
        /// any case, `pwsh`, or a bare user id.
        fn profileChoices(ctx: *anyopaque, alloc: std.mem.Allocator, reference: ?[]const u8, draft: ?[]const u8, ask: bool) std.mem.Allocator.Error!ProfileChoices {
            const self: *Fixture = @ptrCast(@alignCast(ctx));
            // The fixture's drafts are its own keys, which no label stands
            // in for (`settingsDraftProfileLabel` is tested in win32/app.zig).
            _ = draft;
            self.profile_lists += 1;
            if (!ask) self.profile_refills += 1;
            if (ask and self.refill_when_asked and self.nested_refills < 3) {
                self.nested_refills += 1;
                self.settings.profilesChanged();
            }
            var kept: [test_profiles.len]ProfileChoice = undefined;
            var kept_len: usize = 0;
            for (if (self.profiles_complete) test_profiles[0..] else test_profiles[0..1]) |source| {
                if (self.drop_py312 and std.mem.eql(u8, source.key, "user:py312")) continue;
                kept[kept_len] = source;
                kept_len += 1;
            }
            const listed = kept[0..kept_len];
            const items = try alloc.alloc(ProfileChoice, listed.len);
            var made: usize = 0;
            errdefer {
                for (items[0..made]) |item| {
                    alloc.free(item.key);
                    alloc.free(item.label);
                }
                alloc.free(items);
            }
            for (listed, items) |source, *item| {
                const key = try alloc.dupe(u8, source.key);
                const shown = if (self.relabel_py312 != null and std.mem.eql(u8, source.key, "user:py312")) self.relabel_py312.? else source.label;
                const label = alloc.dupe(u8, shown) catch |err| {
                    alloc.free(key);
                    return err;
                };
                item.* = .{ .key = key, .label = label, .hidden = source.hidden };
                made += 1;
            }
            var selected: ?usize = null;
            if (reference) |value| for (listed, 0..) |source, index| {
                const user_id = std.mem.startsWith(u8, source.key, "user:") and std.ascii.eqlIgnoreCase(source.key["user:".len..], value);
                if (std.ascii.eqlIgnoreCase(source.key, value) or user_id or
                    (index == 0 and std.ascii.eqlIgnoreCase(value, "pwsh"))) selected = index;
            };
            var result: ProfileChoices = .{
                .items = items,
                .selected = selected,
                .complete = self.profiles_complete,
                .saved_not_found = self.profiles_complete and selected == null and self.resolved_label == null,
            };
            if (reference != null and selected == null) if (self.resolved_label) |label| {
                result.saved_label = alloc.dupe(u8, label) catch |err| {
                    result.deinit(alloc);
                    return err;
                };
            };
            return result;
        }

        fn notifySuccess(_: *anyopaque, _: []const u8, _: []const u8) void {}

        fn onClosed(ctx: *anyopaque) void {
            const self: *Fixture = @ptrCast(@alignCast(ctx));
            self.closed += 1;
        }

        /// Hand a key down to Settings the way the App pump does: the
        /// accelerators first, then the dialog manager.
        fn pumpKey(self: *Fixture, vk: u32) bool {
            return self.pumpKeyRepeat(vk, false);
        }

        fn pumpKeyRepeat(self: *Fixture, vk: u32, repeat: bool) bool {
            const target = sys.GetFocus() orelse self.hwnd();
            var msg: sys.MSG = .{
                .hwnd = target,
                .message = WM_KEYDOWN,
                .wParam = vk,
                .lParam = if (repeat) 1 << 30 else 0,
                .time = 0,
                .pt = .{ .x = 0, .y = 0 },
                .lPrivate = 0,
            };
            if (self.settings.handleAccelerator(msg.hwnd, msg.message, msg.wParam, msg.lParam)) return true;
            return sys.IsDialogMessageW(self.hwnd(), &msg) != 0;
        }

        fn wheel(target: HWND, delta: i16) void {
            const high: usize = @as(u16, @bitCast(delta));
            _ = sys.SendMessageW(target, WM_MOUSEWHEEL, high << 16, 0);
        }

        /// Shrink to the minimum size, where a single column of Appearance
        /// fields no longer fits and the form scrolls, at the work area's
        /// corner. On a screen smaller than that size (a CI runner's is
        /// 1024x768) the minimum is the work area, so the window keeps one
        /// size across DPI changes: see "settings text resized inside a
        /// window of one size is drawn again".
        fn makeFormScrollable(self: *Fixture) !void {
            var work: RECT = .{ .left = 0, .top = 0, .right = 1024, .bottom = 728 };
            _ = windowWorkArea(self.hwnd(), &work);
            const width = @min(self.settings.px(720), work.right - work.left);
            const height = @min(self.settings.px(520), work.bottom - work.top);
            _ = SetWindowPos(self.hwnd(), null, work.left, work.top, width, height, SWP_NOZORDER | SWP_NOACTIVATE);
            try std.testing.expect(self.settings.content_scroll_max > 0);
        }
    };
    /// What one `open` does to each window, counted from the messages user32
    /// delivers on this thread (thread-local `WH_CBT` and `WH_CALLWNDPROC`
    /// hooks): what each window was actually sent, not what the code meant to
    /// send. `SetWindowTheme` shows as the `WM_THEMECHANGED` it sends.
    const OpenWork = struct {
        const WH_CALLWNDPROC: c_int = 4;
        const WH_CBT: c_int = 5;
        const HCBT_CREATEWND: c_int = 3;
        const WM_SHOWWINDOW: UINT = 0x0018;
        const WM_STYLECHANGING: UINT = 0x007C;
        const WM_WINDOWPOSCHANGING: UINT = 0x0046;
        const HookProc = *const fn (c_int, WPARAM, LPARAM) callconv(.winapi) LRESULT;
        const CWPSTRUCT = extern struct { lParam: LPARAM, wParam: WPARAM, message: UINT, hwnd: HWND };
        extern "user32" fn SetWindowsHookExW(id: c_int, proc: HookProc, module: ?HINSTANCE, thread: u32) callconv(.winapi) ?*anyopaque;
        extern "user32" fn UnhookWindowsHookEx(hook: *anyopaque) callconv(.winapi) BOOL;
        extern "user32" fn CallNextHookEx(hook: ?*anyopaque, code: c_int, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT;

        const Counts = struct {
            hwnd: HWND,
            created: u16 = 0,
            fonts: u16 = 0,
            themes: u16 = 0,
            shown: u16 = 0,
            hidden: u16 = 0,
            z_moves: u16 = 0,
            style_rewrites: u16 = 0,
            frame_changes: u16 = 0,
            messages: u32 = 0,
        };

        // The hooks run on the test's own thread, one at a time.
        var seen: [256]Counts = undefined;
        var seen_len: usize = 0;
        var overflowed = false;

        fn at(hwnd: HWND) ?*Counts {
            for (seen[0..seen_len]) |*counts| if (counts.hwnd == hwnd) return counts;
            if (seen_len == seen.len) {
                overflowed = true;
                return null;
            }
            seen[seen_len] = .{ .hwnd = hwnd };
            seen_len += 1;
            return &seen[seen_len - 1];
        }

        fn of(hwnd: HWND) Counts {
            for (seen[0..seen_len]) |counts| if (counts.hwnd == hwnd) return counts;
            return .{ .hwnd = hwnd };
        }

        fn cbt(code: c_int, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
            if (code == HCBT_CREATEWND) if (at(@ptrFromInt(wParam))) |counts| {
                counts.created += 1;
            };
            return CallNextHookEx(null, code, wParam, lParam);
        }

        fn sent(code: c_int, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
            if (code >= 0) {
                const message: *const CWPSTRUCT = @ptrFromInt(@as(usize, @bitCast(lParam)));
                if (at(message.hwnd)) |counts| {
                    counts.messages += 1;
                    switch (message.message) {
                        WM_SETFONT => counts.fonts += 1,
                        WM_THEMECHANGED => counts.themes += 1,
                        WM_SHOWWINDOW => if (message.wParam != 0) {
                            counts.shown += 1;
                        } else {
                            counts.hidden += 1;
                        },
                        WM_STYLECHANGING => if (message.wParam == @as(WPARAM, @bitCast(@as(isize, GWL_STYLE)))) {
                            counts.style_rewrites += 1;
                        },
                        WM_WINDOWPOSCHANGING => {
                            const pos: *const sys.WINDOWPOS = @ptrFromInt(@as(usize, @bitCast(message.lParam)));
                            if (pos.flags & SWP_NOZORDER == 0) counts.z_moves += 1;
                            if (pos.flags & SWP_FRAMECHANGED != 0) counts.frame_changes += 1;
                        },
                        else => {},
                    }
                }
            }
            return CallNextHookEx(null, code, wParam, lParam);
        }

        /// Open `settings` with the hooks installed.
        fn measure(settings: *SettingsWindow) !void {
            try measureStep(settings, .open);
        }

        const Step = union(enum) { open, show: Section };

        /// Run `step` with the hooks installed, counting from zero.
        fn measureStep(settings: *SettingsWindow, step: Step) !void {
            seen_len = 0;
            overflowed = false;
            const thread = sys.GetCurrentThreadId();
            const creation_hook = SetWindowsHookExW(WH_CBT, &cbt, null, thread) orelse return error.HookUnavailable;
            defer _ = UnhookWindowsHookEx(creation_hook);
            const message_hook = SetWindowsHookExW(WH_CALLWNDPROC, &sent, null, thread) orelse return error.HookUnavailable;
            defer _ = UnhookWindowsHookEx(message_hook);
            switch (step) {
                .open => try settings.open(),
                .show => |section| settings.setActiveSection(section),
            }
        }

        /// The windows the last measured step created.
        fn created() []const Counts {
            const Storage = struct {
                var windows: [256]Counts = undefined;
            };
            var len: usize = 0;
            for (seen[0..seen_len]) |counts| if (counts.created != 0) {
                Storage.windows[len] = counts;
                len += 1;
            };
            return Storage.windows[0..len];
        }

        /// The window's tree: the window itself first, then its descendants.
        const Tree = struct {
            windows: [128]HWND = undefined,
            len: usize = 0,

            fn of(root: HWND) Tree {
                var tree: Tree = .{};
                tree.windows[0] = root;
                tree.len = 1;
                _ = sys.EnumChildWindows(root, collect, @bitCast(@intFromPtr(&tree)));
                return tree;
            }

            fn collect(child: HWND, data: LPARAM) callconv(.winapi) BOOL {
                const tree: *Tree = @ptrFromInt(@as(usize, @bitCast(data)));
                if (tree.len == tree.windows.len) return 0;
                tree.windows[tree.len] = child;
                tree.len += 1;
                return 1;
            }

            fn slice(self: *const Tree) []const HWND {
                return self.windows[0..self.len];
            }
        };

        fn print(tree: *const Tree) void {
            for (tree.slice()) |hwnd| {
                const counts = of(hwnd);
                var class_w: [64]u16 = undefined;
                const length = GetClassNameW(hwnd, &class_w, class_w.len);
                std.debug.print("  {f} id={d} created={d} fonts={d} themes={d} shown={d} hidden={d} z={d} style={d} frame={d} messages={d}\n", .{
                    std.unicode.fmtUtf16Le(class_w[0..@intCast(@max(0, length))]),
                    sys.GetDlgCtrlID(hwnd),
                    counts.created,
                    counts.fonts,
                    counts.themes,
                    counts.shown,
                    counts.hidden,
                    counts.z_moves,
                    counts.style_rewrites,
                    counts.frame_changes,
                    counts.messages,
                });
            }
        }
    };

    /// What each window of an open Settings window shows and how the keyboard
    /// reaches it: the state `open` decides at creation and a section switch
    /// or a DPI change decides again (`setActiveSection`, `recreateUiFont`).
    /// A font is recorded by its role, since a rebuild makes new handles.
    /// Neither path writes `WS_GROUP` or `WS_DISABLED`, so for those bits
    /// the comparison shows only that nothing changed them; "settings
    /// arrow-key groups stop at the rail and the action bar" pins the groups.
    const OpenState = struct {
        const WS_DISABLED: u32 = 0x08000000;
        const kept_styles = WS_VISIBLE | WS_TABSTOP | WS_GROUP | WS_DISABLED | WS_VSCROLL;
        const Font = enum { none, ui, secondary, emphasis, header, other };

        const Window = struct {
            hwnd: HWND,
            id: c_int,
            style: u32,
            /// Relative to the Settings window's rectangle.
            rect: RECT,
            /// The client area's size: a text field's frame insets show here.
            client: [2]i32,
            check: usize,
            /// A dropdown's selection-field and list item heights.
            items: [2]isize,
            text: u64,
            font: Font,
        };

        windows: [128]Window = undefined,
        len: usize = 0,

        fn styleOf(hwnd: HWND) u32 {
            return @truncate(@as(usize, @bitCast(sys.GetWindowLongPtrW(hwnd, GWL_STYLE))));
        }

        fn of(settings: *const SettingsWindow) OpenState {
            const tree = OpenWork.Tree.of(settings.hwnd.?);
            var origin: RECT = undefined;
            _ = GetWindowRect(settings.hwnd.?, &origin);
            var state: OpenState = .{};
            for (tree.slice()) |hwnd| {
                var rect: RECT = undefined;
                _ = GetWindowRect(hwnd, &rect);
                var client: RECT = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
                _ = GetClientRect(hwnd, &client);
                var class_w: [16]u16 = undefined;
                const class_len = GetClassNameW(hwnd, &class_w, class_w.len);
                const class = class_w[0..@intCast(@max(0, class_len))];
                const button = std.mem.eql(u16, class, std.unicode.utf8ToUtf16LeStringLiteral("Button"));
                const combo = std.mem.eql(u16, class, std.unicode.utf8ToUtf16LeStringLiteral("ComboBox"));
                var text_w: [2048]u16 = undefined;
                const text_len = sys.GetWindowTextW(hwnd, &text_w, text_w.len);
                const font: HGDIOBJ = @ptrFromInt(@as(usize, @bitCast(sys.SendMessageW(hwnd, WM_GETFONT, 0, 0))));
                state.windows[state.len] = .{
                    .hwnd = hwnd,
                    .id = sys.GetDlgCtrlID(hwnd),
                    .style = styleOf(hwnd) & kept_styles,
                    .rect = .{ .left = rect.left - origin.left, .top = rect.top - origin.top, .right = rect.right - origin.left, .bottom = rect.bottom - origin.top },
                    .client = .{ client.right, client.bottom },
                    .check = if (button) @bitCast(sys.SendMessageW(hwnd, BM_GETCHECK, 0, 0)) else 0,
                    .items = if (combo) .{
                        sys.SendMessageW(hwnd, CB_GETITEMHEIGHT, std.math.maxInt(WPARAM), 0),
                        sys.SendMessageW(hwnd, CB_GETITEMHEIGHT, 0, 0),
                    } else .{ 0, 0 },
                    .text = std.hash.Wyhash.hash(0, std.mem.sliceAsBytes(text_w[0..@intCast(@max(0, text_len))])),
                    .font = if (font == null) .none else if (font == settings.ui_font) .ui else if (font == settings.secondary_font) .secondary else if (font == settings.emphasis_font) .emphasis else if (font == settings.header_font) .header else .other,
                };
                state.len += 1;
            }
            return state;
        }

        fn slice(self: *const OpenState) []const Window {
            return self.windows[0..self.len];
        }

        /// The windows shown now, which the user sees and reaches: what a
        /// section looks like does not depend on the hidden rows of others.
        fn shown(self: *const OpenState) OpenState {
            var result: OpenState = .{};
            for (self.slice()) |window| if (window.style & WS_VISIBLE != 0) {
                result.windows[result.len] = window;
                result.len += 1;
            };
            return result;
        }

        /// Two windows' states, `a` and `b`, the same in everything but the
        /// handle: two Settings windows built two ways.
        fn expectSame(a: *const OpenState, b: *const OpenState) !void {
            try std.testing.expectEqual(a.len, b.len);
            for (a.slice(), b.slice()) |first, second| {
                var other = second;
                other.hwnd = first.hwnd;
                errdefer print(first, second);
                try std.testing.expectEqualDeep(first, other);
            }
        }

        fn print(at_open: Window, after_switch: Window) void {
            std.debug.print("  id={d} at open: style=0x{x} check={d} font={s} rect=({d},{d},{d},{d}) client={d}x{d} items={d},{d} text={x}\n", .{ at_open.id, at_open.style, at_open.check, @tagName(at_open.font), at_open.rect.left, at_open.rect.top, at_open.rect.right, at_open.rect.bottom, at_open.client[0], at_open.client[1], at_open.items[0], at_open.items[1], at_open.text });
            std.debug.print("  id={d} switched: style=0x{x} check={d} font={s} rect=({d},{d},{d},{d}) client={d}x{d} items={d},{d} text={x}\n", .{ after_switch.id, after_switch.style, after_switch.check, @tagName(after_switch.font), after_switch.rect.left, after_switch.rect.top, after_switch.rect.right, after_switch.rect.bottom, after_switch.client[0], after_switch.client[1], after_switch.items[0], after_switch.items[1], after_switch.text });
        }
    };
};

test "settings Escape without the close prompt closes a clean window and prompts a dirty one" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            const hwnd = fixture.hwnd();

            // A dirty window asks first; Escape is the same request as the X.
            settings.markRawScalarEdit(.font_size);
            _ = sys.SetFocus(settings.fields.edit_font_size.?);
            try std.testing.expect(fixture.pumpKey(0x1B));
            try std.testing.expect(settings.close_prompt_visible);
            try std.testing.expectEqual(@as(u32, 0), fixture.closed);

            // With the prompt open Escape still means "keep editing".
            try std.testing.expect(fixture.pumpKey(0x1B));
            try std.testing.expect(!settings.close_prompt_visible);
            try std.testing.expectEqual(@as(u32, 0), fixture.closed);
            // ... and focus goes back to the field it was taken from.
            try std.testing.expectEqual(settings.fields.edit_font_size.?, sys.GetFocus().?);

            // A clean window closes.
            settings.raw_scalar_dirty[@intFromEnum(RawScalarField.font_size)] = false;
            try std.testing.expect(fixture.pumpKey(0x1B));
            try std.testing.expectEqual(@as(u32, 1), fixture.closed);
            try std.testing.expect(sys.IsWindow(hwnd) == 0);
        }
    }.body);
}

test "settings holds a quit for unsaved changes until Save or Discard closes the window" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            const hwnd = fixture.hwnd();

            // Nothing unsaved: the quit goes ahead.
            try std.testing.expect(!settings.holdQuitForUnsavedChanges());
            try std.testing.expect(!settings.close_prompt_visible);

            // Unsaved: the close prompt holds the quit; Keep editing drops it.
            settings.markRawScalarEdit(.font_size);
            try std.testing.expect(settings.holdQuitForUnsavedChanges());
            try std.testing.expect(settings.close_prompt_visible);
            try std.testing.expect(fixture.pumpKey(0x1B));
            try std.testing.expect(!settings.close_prompt_visible);
            try std.testing.expect(!settings.takeQuitAfterClose());

            // Discard closes the window and hands the quit back once.
            try std.testing.expect(settings.holdQuitForUnsavedChanges());
            settings.discardAndClose();
            try std.testing.expect(settings.close_posted);
            _ = SendMessageW(hwnd, WM_SETTINGS_CLOSE_NOW, 0, 0);
            try std.testing.expectEqual(@as(u32, 1), fixture.closed);
            try std.testing.expect(sys.IsWindow(hwnd) == 0);
            try std.testing.expect(settings.takeQuitAfterClose());
            try std.testing.expect(!settings.takeQuitAfterClose());
        }
    }.body);
}

test "settings Enter presses the focused push button and does nothing in a field" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;

            settings.setActiveSection(.advanced);
            _ = sys.SetFocus(settings.fields.btn_open_editor.?);
            try std.testing.expectEqual(settings.fields.btn_open_editor.?, sys.GetFocus().?);
            try std.testing.expect(fixture.pumpKey(0x0D));
            try std.testing.expectEqual(@as(u32, 1), fixture.editor_opened);

            // A held key clicks once.
            try std.testing.expect(fixture.pumpKeyRepeat(0x0D, true));
            try std.testing.expectEqual(@as(u32, 1), fixture.editor_opened);

            // With a change pending (Save enabled), Enter in a field neither
            // saves nor closes the window.
            settings.setActiveSection(.appearance);
            _ = sys.SendMessageW(settings.fields.combo_cursor_style.?, CB_SETCURSEL, 2, 0);
            settings.syncCombo(.cursor_style);
            try std.testing.expect(sys.IsWindowEnabled(settings.btn_save.?) != 0);
            _ = sys.SetFocus(settings.fields.edit_font_size.?);
            _ = fixture.pumpKey(0x0D);
            try std.testing.expectEqual(@as(u32, 0), fixture.saved);
            try std.testing.expectEqual(@as(u32, 1), fixture.editor_opened);
            try std.testing.expectEqual(@as(u32, 0), fixture.closed);
            try std.testing.expect(sys.IsWindow(fixture.hwnd()) != 0);

            // On the Save button itself it saves.
            _ = sys.SetFocus(settings.btn_save.?);
            try std.testing.expect(fixture.pumpKey(0x0D));
            try std.testing.expectEqual(@as(u32, 1), fixture.saved);
        }
    }.body);
}

test "settings Ctrl+S reaches Save through the accelerator hook" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            _ = sys.SendMessageW(settings.fields.combo_cursor_style.?, CB_SETCURSEL, 2, 0);
            settings.syncCombo(.cursor_style);
            _ = sys.SetFocus(settings.fields.edit_font_size.?);

            // The thread's key table starts as a copy of what the real keyboard
            // holds, so a test that sets only Ctrl in it inherits any Shift,
            // Alt or Ctrl the person running the suite has down (failed 2 of 6
            // runs on a reviewer's machine). Own every key the shortcut reads.
            var original: [256]u8 = undefined;
            try std.testing.expect(dialog_test.GetKeyboardState(&original) != 0);
            defer _ = dialog_test.SetKeyboardState(&original);

            // Without Ctrl the key is not ours.
            const focus = sys.GetFocus().?;
            try dialog_test.holdKeys(.{});
            try std.testing.expect(!settings.handleAccelerator(focus, WM_KEYDOWN, 'S', 0));
            try std.testing.expectEqual(@as(u32, 0), fixture.saved);

            // Ctrl with Shift or Alt is a different chord.
            try dialog_test.holdKeys(.{ .ctrl = true, .shift = true });
            try std.testing.expect(!settings.handleAccelerator(focus, WM_KEYDOWN, 'S', 0));
            try dialog_test.holdKeys(.{ .ctrl = true, .alt = true });
            try std.testing.expect(!settings.handleAccelerator(focus, WM_KEYDOWN, 'S', 0));
            try std.testing.expectEqual(@as(u32, 0), fixture.saved);

            // With only the thread's Ctrl key down it is consumed and saves.
            try dialog_test.holdKeys(.{ .ctrl = true });
            try std.testing.expect(settings.handleAccelerator(focus, WM_KEYDOWN, 'S', 0));
            try std.testing.expectEqual(@as(u32, 1), fixture.saved);
        }
    }.body);
}

test "settings Ctrl+S gate follows the Save button and a held Escape does not flap the prompt" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;

            // Clean: Save is disabled, so the shortcut's path saves nothing.
            settings.saveIfAllowed();
            try std.testing.expectEqual(@as(u32, 0), fixture.saved);
            _ = sys.SendMessageW(settings.fields.combo_cursor_style.?, CB_SETCURSEL, 2, 0);
            settings.syncCombo(.cursor_style);
            settings.saveIfAllowed();
            try std.testing.expectEqual(@as(u32, 1), fixture.saved);

            // Dirty again: Escape opens the prompt, its auto-repeats do not
            // toggle it, and nothing closes while a close is already posted.
            _ = sys.SendMessageW(settings.fields.combo_cursor_style.?, CB_SETCURSEL, 3, 0);
            settings.syncCombo(.cursor_style);
            _ = sys.SetFocus(settings.fields.edit_font_size.?);
            try std.testing.expect(fixture.pumpKey(0x1B));
            try std.testing.expect(settings.close_prompt_visible);
            for (0..3) |_| try std.testing.expect(fixture.pumpKeyRepeat(0x1B, true));
            try std.testing.expect(settings.close_prompt_visible);
            // The prompt blocks Save, so the shortcut's path saves nothing there.
            settings.saveIfAllowed();
            try std.testing.expectEqual(@as(u32, 1), fixture.saved);
            settings.close_posted = true;
            _ = fixture.pumpKey(0x1B);
            try std.testing.expectEqual(@as(u32, 0), fixture.closed);
            settings.close_posted = false;
        }
    }.body);
}

test "settings wheel accumulates touchpad deltas and scrolls the form" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            try fixture.makeFormScrollable();

            // Four precision deltas of 30 are one notch (120) between them.
            for (0..4) |_| dialog_test.Fixture.wheel(fixture.hwnd(), -30);
            try std.testing.expectEqual(settings.px(64), settings.content_scroll_y);

            // A whole notch up scrolls back.
            dialog_test.Fixture.wheel(fixture.hwnd(), 120);
            try std.testing.expectEqual(@as(i32, 0), settings.content_scroll_y);
        }
    }.body);
}

test "settings wheel over a closed dropdown scrolls the form instead of changing it" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            try fixture.makeFormScrollable();

            const combo = settings.fields.combo_cursor_style.?;
            _ = sys.SendMessageW(combo, CB_SETCURSEL, 1, 0);
            _ = sys.SetFocus(combo);
            // Focusing the combo may scroll it into view; measure from there.
            const before = settings.content_scroll_y;
            dialog_test.Fixture.wheel(combo, -120);
            try std.testing.expectEqual(@as(LRESULT, 1), sys.SendMessageW(combo, CB_GETCURSEL, 0, 0));
            try std.testing.expect(!settings.hasPendingChanges());
            try std.testing.expectEqual(@min(before + settings.px(64), settings.content_scroll_max), settings.content_scroll_y);
        }
    }.body);
}

test "settings reactivation restores the focused field" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            const hwnd = fixture.hwnd();

            const field = settings.fields.edit_font_size.?;
            _ = sys.SetFocus(field);
            try std.testing.expectEqual(field, sys.GetFocus().?);

            // Alt+Tab away and back: the system leaves focus on the frame.
            _ = sys.SendMessageW(hwnd, WM_ACTIVATE, WA_INACTIVE, 0);
            _ = sys.SetFocus(hwnd);
            _ = sys.SendMessageW(hwnd, WM_ACTIVATE, dialog_test.WA_ACTIVE, 0);
            try std.testing.expectEqual(field, sys.GetFocus().?);

            // A control that vanished meanwhile falls back to the section.
            _ = sys.SendMessageW(hwnd, WM_ACTIVATE, WA_INACTIVE, 0);
            _ = sys.ShowWindow(field, SW_HIDE);
            _ = sys.SetFocus(hwnd);
            _ = sys.SendMessageW(hwnd, WM_ACTIVATE, dialog_test.WA_ACTIVE, 0);
            try std.testing.expectEqual(settings.sectionButton(.appearance).?, sys.GetFocus().?);
        }
    }.body);
}

test "settings generated form labels immediately precede their controls" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            // Sections are made when first shown. Later ones first, so the
            // rows of most sections are made after rows that follow them.
            for ([_]Section{ .advanced, .shell, .privacy, .terminal, .keybindings, .updates }) |section| {
                settings.setActiveSection(section);
            }
            // Tab and the arrow keys follow z-order: the help text, then each
            // section's rows in order, a label right before its row, as if
            // every section had been made at once. The opacity's trackbar
            // comes before its field, as it sits left of it, and an up-down
            // after its field.
            const GW_HWNDNEXT: UINT = 2;
            const GW_CHILD: UINT = 5;
            var window = sys.GetWindow(settings.viewport.?, GW_CHILD);
            try std.testing.expectEqual(settings.text_help.?, window.?);
            for (std.enums.values(Section)) |section| for (formItemsForSection(section)) |item| {
                errdefer std.debug.print("settings form order breaks in {s} at control {d}\n", .{ @tagName(section), item.control_index });
                if (item.label_index) |index| {
                    window = sys.GetWindow(window.?, GW_HWNDNEXT);
                    try std.testing.expectEqual(settings.field_labels[index].?, window.?);
                }
                const companion = Companion.ofControl(item.control_index);
                if (companion == .opacity_slider) {
                    window = sys.GetWindow(window.?, GW_HWNDNEXT);
                    try std.testing.expectEqual(settings.companions[@intFromEnum(Companion.opacity_slider)].?, window.?);
                }
                window = sys.GetWindow(window.?, GW_HWNDNEXT);
                try std.testing.expectEqual(settings.controlHwnd(item.control_index).?, window.?);
                if (companion) |kind| if (kind != .opacity_slider) {
                    window = sys.GetWindow(window.?, GW_HWNDNEXT);
                    try std.testing.expectEqual(settings.companions[@intFromEnum(kind)].?, window.?);
                };
            };
            try std.testing.expectEqual(@as(?HWND, null), sys.GetWindow(window.?, GW_HWNDNEXT));
        }
    }.body);
}

test "settings Tab visits the fields in form order and Save last" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            const hwnd = fixture.hwnd();

            // A pending change makes Save eligible for dialog traversal.
            _ = sys.SendMessageW(settings.fields.combo_cursor_style.?, CB_SETCURSEL, 2, 0);
            settings.syncCombo(.cursor_style);
            try std.testing.expect(sys.IsWindowEnabled(settings.btn_save.?) != 0);

            // The cursor style differs from its default now, so its Reset
            // button follows it.
            try std.testing.expect(sys.IsWindowVisible(settings.reset_buttons[settings.controlIndex(settings.fields.combo_cursor_style.?).?].?) != 0);
            for (std.enums.values(Section)) |section| {
                settings.setActiveSection(section);
                // Unsupported controls are disabled and are not tab stops. A
                // shown Reset button comes right after its field.
                var fields: [settings_max_form_items * 2 + 1]HWND = undefined;
                var field_count: usize = 0;
                for (settings.formItems()) |item| {
                    const control = settings.controlHwnd(item.control_index).?;
                    if (sys.IsWindowEnabled(control) == 0) continue;
                    // The opacity's trackbar before its field, as it sits
                    // left of it. An up-down is no tab stop.
                    if (Companion.ofControl(item.control_index) == .opacity_slider) {
                        fields[field_count] = settings.companions[@intFromEnum(Companion.opacity_slider)].?;
                        field_count += 1;
                    }
                    fields[field_count] = control;
                    field_count += 1;
                    const reset = if (item.control_index < form_field_count) settings.reset_buttons[item.control_index] else null;
                    if (reset) |button| if (sys.IsWindowVisible(button) != 0) {
                        fields[field_count] = button;
                        field_count += 1;
                    };
                }
                // A page's list comes after its rows: the All settings page's
                // one tab stop, the last of the Keybindings page's.
                if (settings.sectionList(section)) |list| {
                    fields[field_count] = list.hwnd.?;
                    field_count += 1;
                }
                const first = fields[0];
                var visited: [24]HWND = undefined;
                var count: usize = 0;
                var current = first;
                while (count < visited.len) {
                    visited[count] = current;
                    count += 1;
                    current = dialog_test.GetNextDlgTabItem(hwnd, current, 0) orelse break;
                    if (current == first) break;
                }
                // Every field in form order, then Discard changes and Save (the
                // order they are laid out in), then the cycle wraps to the
                // search field at the top and the rail.
                try std.testing.expectEqual(field_count + 4, count);
                for (fields[0..field_count], 0..) |control, index| {
                    try std.testing.expectEqual(control, visited[index]);
                }
                try std.testing.expectEqual(settings.btn_discard_changes.?, visited[field_count]);
                try std.testing.expectEqual(settings.btn_save.?, visited[field_count + 1]);
                try std.testing.expectEqual(settings.edit_search.?, visited[field_count + 2]);
                try std.testing.expectEqual(settings.sectionButton(section).?, visited[field_count + 3]);
                // Shift+Tab from the rail is the search field, and from there Save.
                try std.testing.expectEqual(settings.edit_search.?, dialog_test.GetNextDlgTabItem(hwnd, settings.sectionButton(section).?, 1).?);
                try std.testing.expectEqual(settings.btn_save.?, dialog_test.GetNextDlgTabItem(hwnd, settings.edit_search.?, 1).?);

                // Shift+Tab walks it back: Save, Discard, the fields in reverse, the rail.
                try std.testing.expectEqual(settings.btn_discard_changes.?, dialog_test.GetNextDlgTabItem(hwnd, settings.btn_save.?, 1).?);
                var back = settings.btn_discard_changes.?;
                var index = field_count;
                while (index > 0) {
                    index -= 1;
                    back = dialog_test.GetNextDlgTabItem(hwnd, back, 1).?;
                    try std.testing.expectEqual(fields[index], back);
                }
                try std.testing.expectEqual(settings.sectionButton(section).?, dialog_test.GetNextDlgTabItem(hwnd, back, 1).?);
            }
        }
    }.body);
}

test "settings search reads the words typed and @modified, in any case" {
    var query = SearchQuery.parse("  Font  SIZE \t");
    try std.testing.expect(query.active());
    try std.testing.expect(!query.modified);
    try std.testing.expectEqual(@as(usize, 2), query.word_count);
    try std.testing.expectEqualStrings("font", query.word(0));
    try std.testing.expectEqualStrings("size", query.word(1));
    try std.testing.expectEqualStrings("Font  SIZE", query.typedText());

    query = SearchQuery.parse("@Modified cursor");
    try std.testing.expect(query.modified);
    try std.testing.expectEqual(@as(usize, 1), query.word_count);
    try std.testing.expectEqualStrings("cursor", query.word(0));
    // Alone it is a search too, of every row that differs.
    try std.testing.expect(SearchQuery.parse("@MODIFIED").active());
    // A word that only starts like it is an ordinary word, which no row has.
    query = SearchQuery.parse("@modifiedx");
    try std.testing.expect(!query.modified);
    try std.testing.expectEqual(@as(usize, 1), query.word_count);
    // Spaces alone are no search.
    try std.testing.expect(!SearchQuery.parse(" \t ").active());
    try std.testing.expect(!SearchQuery.parse("").active());

    // A space or a change of case looks for the same rows.
    const a = SearchQuery.parse("font");
    const b = SearchQuery.parse("Font ");
    try std.testing.expect(a.sameSearch(&b));
    try std.testing.expect(!a.sameSearch(&SearchQuery.parse("font s")));
    try std.testing.expect(!a.sameSearch(&SearchQuery.parse("font @modified")));

    // Every word is looked for, however many the field holds: a seventeenth
    // that no row has finds nothing, and a change to it is a new search.
    const fonts = "font " ** 16;
    query = SearchQuery.parse(fonts ++ "zzzz");
    try std.testing.expectEqual(@as(usize, 17), query.word_count);
    for (settings_search_text) |row| try std.testing.expect(!query.matchesText(row));
    try std.testing.expect(!query.sameSearch(&SearchQuery.parse(fonts ++ "zzzy")));
    // The most words the field's 128 units can hold: 64 of one letter.
    query = SearchQuery.parse(("a " ** 63) ++ "a");
    try std.testing.expectEqual(@as(usize, 64), query.word_count);
    // The text is kept whole up to its capacity and cut only between
    // characters.
    var long: [SearchQuery.capacity + 2]u8 = undefined;
    @memset(&long, 'x');
    // A two-byte character across the cut.
    long[SearchQuery.capacity - 1] = 0xC3;
    long[SearchQuery.capacity] = 0xA9;
    query = SearchQuery.parse(&long);
    try std.testing.expectEqual(@as(usize, SearchQuery.capacity - 1), query.typed_len);
    try std.testing.expect(std.unicode.utf8ValidateSlice(query.typedText()));
}

test "settings search finds a row by its label, caption, help and keywords, not by the words every row shares" {
    const Count = struct {
        fn of(comptime text: []const u8) usize {
            const query = SearchQuery.parse(text);
            var count: usize = 0;
            for (settings_search_text) |row| count += @intFromBool(query.matchesText(row));
            return count;
        }
        fn finds(comptime text: []const u8, control: usize) bool {
            return SearchQuery.parse(text).matchesText(settings_search_text[control]);
        }
    };
    const scrollback = comptime nativeControlIndex("edit_scrollback");
    // Its label, a keyword, its help, its config key, in any case.
    try std.testing.expect(Count.finds("Scrollback", scrollback));
    try std.testing.expect(Count.finds("history", scrollback));
    try std.testing.expect(Count.finds("bytes retained", scrollback));
    try std.testing.expect(Count.finds("scrollback-limit", scrollback));
    // Every word, each anywhere in it.
    try std.testing.expect(Count.finds("retained scrollback", scrollback));
    try std.testing.expect(!Count.finds("scrollback cursor", scrollback));
    // A checkbox by its caption, a projection by the palette's name for it.
    try std.testing.expect(Count.finds("trailing spaces", comptime nativeControlIndex("chk_trim_trail")));
    try std.testing.expect(Count.finds("clipboard copy notification", comptime nativeControlIndex("chk_app_notify_clipboard")));
    // The display rows by their keywords.
    try std.testing.expect(Count.finds("shortcut", comptime controlIndexOfBinding("btn_keybindings_editor")));
    try std.testing.expect(Count.finds("text editor", comptime controlIndexOfBinding("btn_open_editor")));
    // The words the palette gives every setting find nothing here.
    try std.testing.expectEqual(@as(usize, 0), Count.of("preferences"));
    try std.testing.expectEqual(@as(usize, 3), Count.of("padding"));
    try std.testing.expectEqual(@as(usize, 0), Count.of("zzzz"));
}

test "settings search says how many it found, and where, or what it looks in" {
    var buf: [SettingsWindow.help_text_bytes]u8 = undefined;
    var counts: [section_count]u16 = @splat(0);
    try std.testing.expectEqualStrings("No settings match.", searchSummaryText(&buf, &counts, 0, .appearance));
    counts[@intFromEnum(Section.appearance)] = 1;
    counts[@intFromEnum(Section.reference)] = 1;
    try std.testing.expectEqualStrings("1 setting matches: 1 on this page.", searchSummaryText(&buf, &counts, 1, .appearance));
    counts[@intFromEnum(Section.appearance)] = 0;
    counts[@intFromEnum(Section.terminal)] = 2;
    counts[@intFromEnum(Section.privacy)] = 4;
    counts[@intFromEnum(Section.reference)] = 9;
    // The total counts each setting once: the All settings page holds every
    // key the other pages do. A page with none says where the first are: a
    // reader hears this line.
    try std.testing.expectEqualStrings("9 settings match: none on this page, 2 on Terminal.", searchSummaryText(&buf, &counts, 9, .appearance));
    try std.testing.expectEqualStrings("9 settings match: 4 on this page.", searchSummaryText(&buf, &counts, 9, .privacy));
    try std.testing.expectEqualStrings("9 settings match: 9 on this page.", searchSummaryText(&buf, &counts, 9, .reference));
    var query = SearchQuery.parse("  Clip ");
    try std.testing.expectEqualStrings(
        "Nothing on this page matches \u{201C}Clip\u{201D}. Found on Terminal (2), Privacy (4), All settings (9). " ++
            "Enter in the search field goes to the first, or choose a page on the left.",
        searchEmptyText(&buf, &query, &counts, 9),
    );
    query = SearchQuery.parse("@modified");
    counts = @splat(0);
    const none = searchEmptyText(&buf, &query, &counts, 0);
    try std.testing.expect(std.mem.startsWith(u8, none, "Nothing on this page differs from its default. Nor does anything on the other pages."));
    try std.testing.expect(std.mem.indexOf(u8, none, "Escape in the search field clears it.") != null);
    // The longest search fits the help text's room.
    var long: [SearchQuery.capacity]u8 = undefined;
    @memset(&long, 'x');
    query = SearchQuery.parse(&long);
    for (&counts) |*count| count.* = 999;
    try std.testing.expect(std.mem.endsWith(u8, searchEmptyText(&buf, &query, &counts, 999), "choose a page on the left."));
}

