test "settings arrow-key groups stop at the rail and the action bar" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            const hwnd = fixture.hwnd();
            const viewport = settings.viewport.?;
            const VK_UP: u32 = 0x26;
            const VK_DOWN: u32 = 0x28;
            const rail = struct {
                fn has(window: *const SettingsWindow, control: HWND) bool {
                    for (std.enums.values(Section)) |section| {
                        if (window.sectionButton(section).? == control) return true;
                    }
                    return false;
                }
            }.has;

            // Down from the last rail button wraps to the first, rather than
            // running on into the fields, and no rail button's group reaches
            // past the rail. (The dialog manager clicks the rail's radio
            // buttons as it moves, so the rail is read rather than walked.)
            try std.testing.expectEqual(
                settings.btn_section_appearance.?,
                dialog_test.GetNextDlgGroupItem(hwnd, settings.btn_section_reference.?, 0).?,
            );
            for (std.enums.values(Section)) |section| for ([_]windows.BOOL{ 0, 1 }) |previous| {
                try std.testing.expect(rail(settings, dialog_test.GetNextDlgGroupItem(hwnd, settings.sectionButton(section).?, previous).?));
            };

            // A pending change shows and enables Discard changes and Save.
            _ = sys.SendMessageW(settings.fields.combo_cursor_style.?, CB_SETCURSEL, 2, 0);
            settings.syncCombo(.cursor_style);
            const actions = [_]HWND{ settings.btn_discard_changes.?, settings.btn_save.? };
            for (actions) |button| try std.testing.expect(sys.IsWindowVisible(button) != 0 and sys.IsWindowEnabled(button) != 0);

            // Down and Up as the App pump hands them to the dialog manager:
            // from a form control that leaves the arrows to it (a check box,
            // a push button) focus stays in the form, and from the action bar
            // it never reaches the form or the rail. Both sides rest on the
            // group the bar's first button starts at creation; the last
            // control on Advanced is a push button that is a group of its own.
            for (std.enums.values(Section)) |section| {
                settings.setActiveSection(section);
                errdefer std.debug.print("settings arrows on {s}\n", .{@tagName(section)});
                // The pump moves focus at all: Down goes from Discard to Save.
                _ = sys.SetFocus(actions[0]);
                try std.testing.expect(fixture.pumpKey(VK_DOWN));
                try std.testing.expectEqual(actions[1], sys.GetFocus().?);
                for (settings.formItems()) |item| {
                    const control = settings.controlHwnd(item.control_index).?;
                    if (sys.IsWindowVisible(control) == 0 or sys.IsWindowEnabled(control) == 0) continue;
                    if (SendMessageW(control, WM_GETDLGCODE, 0, 0) & DLGC_WANTARROWS != 0) continue;
                    for ([_]u32{ VK_DOWN, VK_UP }) |key| {
                        _ = sys.SetFocus(control);
                        try std.testing.expect(fixture.pumpKey(key));
                        try std.testing.expect(IsChild(viewport, sys.GetFocus().?) != 0);
                    }
                }
                for (actions) |button| for ([_]u32{ VK_DOWN, VK_UP }) |key| {
                    _ = sys.SetFocus(button);
                    try std.testing.expect(fixture.pumpKey(key));
                    const focus = sys.GetFocus().?;
                    try std.testing.expect(IsChild(viewport, focus) == 0 and !rail(settings, focus));
                };
                // The bar's group wraps within itself: past Save the walk
                // comes back to Discard changes, not on to the header, summary
                // and status lines, which are not focusable, so the arrows
                // would otherwise leave focus where it is.
                try std.testing.expectEqual(actions[0], dialog_test.GetNextDlgGroupItem(hwnd, actions[1], 0).?);
                try std.testing.expectEqual(actions[1], dialog_test.GetNextDlgGroupItem(hwnd, actions[0], 1).?);
                _ = sys.SetFocus(actions[1]);
                try std.testing.expect(fixture.pumpKey(VK_DOWN));
                try std.testing.expectEqual(actions[0], sys.GetFocus().?);
                try std.testing.expect(fixture.pumpKey(VK_UP));
                try std.testing.expectEqual(actions[1], sys.GetFocus().?);
            }

            // The close prompt's three buttons are the same run.
            settings.showClosePrompt();
            const prompt = [_]HWND{ settings.btn_save.?, settings.btn_discard_changes.?, settings.btn_close_keep_editing.? };
            for (prompt, 0..) |button, index| {
                try std.testing.expect(sys.IsWindowVisible(button) != 0 and sys.IsWindowEnabled(button) != 0);
                _ = sys.SetFocus(button);
                try std.testing.expect(fixture.pumpKey(VK_DOWN));
                try std.testing.expectEqual(prompt[(index + 1) % prompt.len], sys.GetFocus().?);
                _ = sys.SetFocus(button);
                try std.testing.expect(fixture.pumpKey(VK_UP));
                try std.testing.expectEqual(prompt[(index + prompt.len - 1) % prompt.len], sys.GetFocus().?);
            }
        }
    }.body);
}

test "settings one Save button is the bar's Save and the close prompt's Save and close" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.startWith(true);
            defer fixture.finish();
            const settings = &fixture.settings;
            const save = settings.btn_save.?;
            const provider = settings.control_uia_providers[settings.controlIndex(save).?].?;
            var buf: [64]u8 = undefined;
            try std.testing.expectEqual(@as(c_int, @intCast(BTN_SAVE)), sys.GetDlgCtrlID(save));
            try std.testing.expectEqualStrings("Save", try uiaStringProperty(&provider.base, @import("win32_uia/constants.zig").UIA_NamePropertyId, &buf));
            _ = sys.SendMessageW(settings.fields.combo_cursor_style.?, CB_SETCURSEL, 2, 0);
            settings.syncCombo(.cursor_style);

            // The prompt makes it "Save and close": its caption, its name
            // and the id its click and UIA's Invoke post.
            const names_before = win32_uia.events.testing_property_changes;
            settings.showClosePrompt();
            try std.testing.expect(sys.IsWindowVisible(save) != 0 and sys.IsWindowEnabled(save) != 0);
            try std.testing.expectEqual(@as(c_int, @intCast(BTN_CLOSE_SAVE)), sys.GetDlgCtrlID(save));
            try std.testing.expectEqualStrings("Save and close", readEditUtf8(save, &buf).?);
            try std.testing.expectEqualStrings("Save and close", try uiaStringProperty(&provider.base, @import("win32_uia/constants.zig").UIA_NamePropertyId, &buf));
            try std.testing.expect(win32_uia.events.testing_property_changes > names_before);
            settings.cancelClosePrompt();
            try std.testing.expectEqual(@as(c_int, @intCast(BTN_SAVE)), sys.GetDlgCtrlID(save));
            try std.testing.expectEqualStrings("Save", try uiaStringProperty(&provider.base, @import("win32_uia/constants.zig").UIA_NamePropertyId, &buf));

            // Clicked in the prompt, it saves and closes; in the bar, it
            // saves and stays.
            _ = sys.SendMessageW(save, BM_CLICK, 0, 0);
            try std.testing.expectEqual(@as(u32, 1), fixture.saved);
            try std.testing.expectEqual(@as(u32, 0), fixture.closed);
            _ = sys.SendMessageW(settings.fields.combo_cursor_style.?, CB_SETCURSEL, 2, 0);
            settings.syncCombo(.cursor_style);
            settings.showClosePrompt();
            _ = sys.SendMessageW(save, BM_CLICK, 0, 0);
            dialog_test.pump();
            try std.testing.expectEqual(@as(u32, 2), fixture.saved);
            try std.testing.expectEqual(@as(u32, 1), fixture.closed);
        }
    }.body);
}

