test "settings text resized inside a window of one size is drawn again" {
    try dialog_test.onHiddenDesktop(struct {
        fn sized(rect: RECT) [2]i32 {
            return .{ rect.right - rect.left, rect.bottom - rect.top };
        }

        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            const hwnd = fixture.hwnd();
            dialog_test.simulateDpi(hwnd, 96);
            var work: RECT = .{ .left = 0, .top = 0, .right = 1024, .bottom = 728 };
            _ = windowWorkArea(hwnd, &work);

            // A resize of the window repaints every child (the frame's class
            // has CS_HREDRAW | CS_VREDRAW); these resize text inside a window
            // that keeps its size. First a status message too long for the
            // room beside the buttons, which gets a row of its own, and a
            // short one that gives it back.
            const long_status = "A status message far too long to fit beside the buttons, so it takes a row of its own and wraps onto more than one line of it.";
            for ([_]i32{ 900, 760 }) |logical_width| {
                _ = SetWindowPos(hwnd, null, work.left, work.top, settings.px(logical_width), settings.px(560), SWP_NOZORDER | SWP_NOACTIVATE);
                dialog_test.flushPaint(hwnd);
                for ([_][]const u8{ long_status, "Saved." }) |message| {
                    const before = sized(dialog_test.rectIn(hwnd, settings.text_status.?));
                    settings.setStatus(message);
                    try std.testing.expect(!std.meta.eql(before, sized(dialog_test.rectIn(hwnd, settings.text_status.?))));
                    try dialog_test.expectNothingStale(hwnd);
                }
            }

            // Then a DPI change that leaves the window's size alone, as when
            // the window is already as large as the screen allows (a CI
            // runner's is 1024x768): `WM_SETFONT` draws the text in the new
            // font before the layout gives it its new width. Advanced has
            // the longest summary.
            const button = settings.sectionButton(.advanced).?;
            const id: usize = @intCast(GetDlgCtrlID(button));
            _ = SendMessageW(hwnd, WM_COMMAND, (@as(usize, BN_CLICKED) << 16) | id, @bitCast(@intFromPtr(button)));
            try std.testing.expectEqual(Section.advanced, settings.active_section);
            _ = SetWindowPos(hwnd, null, work.left, work.top, 1100, 800, SWP_NOZORDER | SWP_NOACTIVATE);
            dialog_test.flushPaint(hwnd);
            var window: RECT = undefined;
            _ = GetWindowRect(hwnd, &window);
            for ([_]u32{ 144, 96 }) |dpi| {
                const before = dialog_test.rectIn(hwnd, settings.text_summary.?);
                dialog_test.simulateDpi(hwnd, dpi);
                var now: RECT = undefined;
                _ = GetWindowRect(hwnd, &now);
                try std.testing.expectEqual(window, now);
                const after = dialog_test.rectIn(hwnd, settings.text_summary.?);
                try std.testing.expect(before.right - before.left != after.right - after.left);
                try dialog_test.expectNothingStale(hwnd);
            }
        }
    }.body);
}

test "settings field frames take the new colours when the theme changes" {
    try dialog_test.onHiddenDesktop(struct {
        fn alwaysHighContrast(_: *anyopaque) bool {
            return true;
        }

        /// The capture's pixel (0x00RRGGBB) as a COLORREF (0x00BBGGRR).
        fn colorAt(capture: dialog_test.Capture, x: i32, y: i32) u32 {
            const pixel = capture.pixels[@as(usize, @intCast(y)) * capture.width + @as(usize, @intCast(x))];
            return ((pixel & 0xFF) << 16) | (pixel & 0xFF00) | ((pixel >> 16) & 0xFF);
        }

        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            const hwnd = fixture.hwnd();
            const field = dialog_test.rectIn(hwnd, settings.fields.edit_font_family.?);
            const middle = @divTrunc(field.top + field.bottom, 2);

            dialog_test.flushPaint(hwnd);
            const light = try dialog_test.Capture.take(hwnd);
            defer light.deinit();
            try std.testing.expectEqual(settings.theme_adapter.colors.field_border, colorAt(light, field.left, middle));

            // High Contrast turns on: the frame is non-client, and must follow.
            settings.handle.highContrast = &alwaysHighContrast;
            settings.themeChanged();
            try std.testing.expect(settings.theme_adapter.colors.high_contrast);
            dialog_test.flushPaint(hwnd);
            const high_contrast = try dialog_test.Capture.take(hwnd);
            defer high_contrast.deinit();
            try std.testing.expectEqual(settings.theme_adapter.colors.field_border, colorAt(high_contrast, field.left, middle));

            // A theme change also gives every control its theme again and
            // reframes the text fields for the new font, and either of those
            // redraws the frame on its own. The adapter's own redraw must
            // cover the frame without them: new colours, then that redraw only.
            settings.theme_adapter.colors.field_border = 0x0000C0;
            settings.theme_adapter.colors.edit_bg = 0x00C000;
            _ = sys.EnumChildWindows(hwnd, invalidateThemeChild, 0);
            dialog_test.flushPaint(hwnd);
            const redrawn = try dialog_test.Capture.take(hwnd);
            defer redrawn.deinit();
            try std.testing.expectEqual(@as(u32, 0x0000C0), colorAt(redrawn, field.left, middle));
            try std.testing.expectEqual(@as(u32, 0x00C000), colorAt(redrawn, field.left + settings.fieldStroke(), field.top + settings.fieldStroke()));
        }
    }.body);
}

test "settings rail marks draw for unsaved and invalid sections at 100% and 150% in light, dark and High Contrast" {
    try dialog_test.onHiddenDesktop(struct {
        fn highContrast(_: *anyopaque) bool {
            return true;
        }

        fn darkColors(_: *anyopaque) win32_theme.ThemeColors {
            return win32_theme.darkTheme();
        }

        /// The capture's pixel (0x00RRGGBB) as a COLORREF (0x00BBGGRR).
        fn colorAt(capture: dialog_test.Capture, x: i32, y: i32) u32 {
            const pixel = capture.pixels[@as(usize, @intCast(y)) * capture.width + @as(usize, @intCast(x))];
            return ((pixel & 0xFF) << 16) | (pixel & 0xFF00) | ((pixel >> 16) & 0xFF);
        }

        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            const hwnd = fixture.hwnd();
            const button = settings.sectionButton(.appearance).?;
            const Mode = enum { light, dark, high_contrast };

            for ([_]Mode{ .light, .dark, .high_contrast }) |mode| for ([_]u32{ 96, 144 }) |dpi| {
                settings.discardChangesNow();
                settings.handle.themeColors = if (mode == .dark) &darkColors else null;
                settings.handle.highContrast = if (mode == .high_contrast) &highContrast else null;
                settings.themeChanged();
                dialog_test.simulateDpi(hwnd, dpi);
                try std.testing.expectEqual(mode == .high_contrast, settings.theme_adapter.colors.high_contrast);
                const colors = settings.theme_adapter.colors;
                // The section opened with the window is the selected one.
                const outer = dialog_test.rectIn(hwnd, button);
                const inner: RECT = .{ .left = 0, .top = 0, .right = outer.right - outer.left, .bottom = outer.bottom - outer.top };

                dialog_test.flushPaint(hwnd);
                const clean = try dialog_test.Capture.take(hwnd);
                defer clean.deinit();

                // Unsaved: the dot, in the accent (a text colour in High Contrast).
                _ = sys.SendMessageW(settings.fields.combo_cursor_style.?, CB_SETCURSEL, 2, 0);
                settings.syncCombo(.cursor_style);
                dialog_test.flushPaint(hwnd);
                const unsaved = try dialog_test.Capture.take(hwnd);
                defer unsaved.deinit();
                const dot = sectionMarkerRect(settings, inner, .unsaved);
                const dot_x = outer.left + @divTrunc(dot.left + dot.right, 2);
                const dot_y = outer.top + @divTrunc(dot.top + dot.bottom, 2);
                const dot_fill = sectionMarkerFill(colors, .unsaved, true);
                try std.testing.expectEqual(dot_fill, colorAt(unsaved, dot_x, dot_y));
                try std.testing.expect(colorAt(clean, dot_x, dot_y) != dot_fill);

                // Invalid: the larger disc with its mark, in the error colour.
                typeInto(settings.fields.edit_font_size.?, "1");
                settings.validationQuietElapsed();
                dialog_test.flushPaint(hwnd);
                const invalid = try dialog_test.Capture.take(hwnd);
                defer invalid.deinit();
                const disc = sectionMarkerRect(settings, inner, .invalid);
                try std.testing.expect(disc.right - disc.left > dot.right - dot.left);
                // Left of where the dot ends and inside the disc: only the disc.
                const probe_x = outer.left + disc.left + settings.px(3);
                const probe_y = outer.top + @divTrunc(disc.top + disc.bottom, 2);
                try std.testing.expect(probe_x < outer.left + dot.left);
                const disc_fill = sectionMarkerFill(colors, .invalid, true);
                try std.testing.expectEqual(disc_fill, colorAt(invalid, probe_x, probe_y));
                try std.testing.expect(colorAt(unsaved, probe_x, probe_y) != disc_fill);
                // Light and dark: the error color. High Contrast: the color of
                // the text on the selected (Highlight) button, which is what
                // reads against it, and not ButtonText.
                try std.testing.expectEqual(
                    if (mode == .high_contrast) colors.selection_text else colors.error_text,
                    disc_fill,
                );

                // Nothing is marked once the draft is thrown away.
                settings.discardChangesNow();
                dialog_test.flushPaint(hwnd);
                const discarded = try dialog_test.Capture.take(hwnd);
                defer discarded.deinit();
                try std.testing.expect(colorAt(discarded, probe_x, probe_y) != colors.error_text);
                try std.testing.expect(colorAt(discarded, dot_x, dot_y) != dot_fill);
            };
        }
    }.body);
}

test "settings a pressed rail button draws its mark and focus ring in the selection pair in High Contrast" {
    try dialog_test.onHiddenDesktop(struct {
        fn highContrast(_: *anyopaque) bool {
            return true;
        }

        /// The capture's pixel (0x00RRGGBB) as a COLORREF (0x00BBGGRR).
        fn colorAt(capture: dialog_test.Capture, x: i32, y: i32) u32 {
            const pixel = capture.pixels[@as(usize, @intCast(y)) * capture.width + @as(usize, @intCast(x))];
            return ((pixel & 0xFF) << 16) | (pixel & 0xFF00) | ((pixel >> 16) & 0xFF);
        }

        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            const hwnd = fixture.hwnd();
            settings.handle.highContrast = &highContrast;
            settings.themeChanged();
            dialog_test.simulateDpi(hwnd, 144);
            const colors = settings.theme_adapter.colors;
            try std.testing.expect(colors.high_contrast);
            // The pairs differ, or the test could not tell them apart.
            try std.testing.expect(colors.text != colors.selection_text);
            try std.testing.expect(colors.focus_ring != colors.selection_text);

            // Appearance invalid, and another section shown: its rail
            // button is marked and not selected.
            typeInto(settings.fields.edit_font_size.?, "1");
            settings.validationQuietElapsed();
            settings.showSection(.terminal, false);
            const button = settings.sectionButton(.appearance).?;
            try std.testing.expectEqual(win32_uia.SettingsSectionMarker.invalid, settings.section_markers[@intFromEnum(Section.appearance)]);
            try std.testing.expect(SendMessageW(button, BM_GETCHECK, 0, 0) != BST_CHECKED);

            // A press, as the pointer makes it: focus and the pushed state,
            // the section not yet chosen.
            var client: RECT = undefined;
            _ = GetClientRect(button, &client);
            const MK_LBUTTON: usize = 0x0001;
            const point: isize = (@as(isize, @divTrunc(client.bottom, 2)) << 16) | @as(isize, settings.px(settings_metrics.space_2));
            _ = SendMessageW(button, WM_LBUTTONDOWN, MK_LBUTTON, point);
            defer _ = sys.ReleaseCapture();
            try std.testing.expect((SendMessageW(button, BM_GETSTATE, 0, 0) & BST_PUSHED) != 0);
            try std.testing.expect(SendMessageW(button, BM_GETCHECK, 0, 0) != BST_CHECKED);
            try std.testing.expectEqual(@as(?HWND, button), GetFocus());

            _ = RedrawWindow(hwnd, null, null, RDW_INVALIDATE | RDW_ERASE | RDW_FRAME | RDW_ALLCHILDREN | RDW_UPDATENOW);
            const capture = try dialog_test.printClient(hwnd);
            defer capture.deinit();
            const outer = dialog_test.rectIn(hwnd, button);
            const inner: RECT = .{ .left = 0, .top = 0, .right = outer.right - outer.left, .bottom = outer.bottom - outer.top };
            const middle = outer.top + @divTrunc(inner.bottom, 2);
            // Filled like a selected button.
            try std.testing.expectEqual(colors.selection_bg, colorAt(capture, outer.left + settings.px(settings_metrics.space_4), outer.top + settings.px(settings_metrics.space_4)));
            // The disc in HighlightText, the text paired with that fill, not
            // ButtonText (1.46:1 on Highlight in Aquatic).
            const disc = sectionMarkerRect(settings, inner, .invalid);
            const in_window: RECT = .{ .left = outer.left + disc.left, .top = outer.top + disc.top, .right = outer.left + disc.right, .bottom = outer.top + disc.bottom };
            try std.testing.expectEqual(colors.selection_text, colorAt(capture, in_window.left + settings.px(3), middle));
            // Its "!" in the fill's colour: the pair again, the other way round.
            const disc_pixels = capture.inDisc(in_window, settings.px(2), colors.selection_text);
            try std.testing.expect(disc_pixels.fill * 2 >= disc_pixels.total);
            try std.testing.expect(disc_pixels.best >= contrastOf(colors.selection_bg, colors.selection_text) - 0.01);
            // The focus ring, which High Contrast shows for pointer focus
            // too, in HighlightText: in the focus colour (Highlight) it
            // would vanish into the fill.
            const ring_x = outer.left + settings.px(settings_metrics.space_1);
            try std.testing.expectEqual(colors.selection_text, colorAt(capture, ring_x, middle));
        }

        fn contrastOf(a: COLORREF, b: COLORREF) f64 {
            const RGB = @import("../terminal/color.zig").RGB;
            const first: RGB = .{ .r = @truncate(a), .g = @truncate(a >> 8), .b = @truncate(a >> 16) };
            const second: RGB = .{ .r = @truncate(b), .g = @truncate(b >> 8), .b = @truncate(b >> 16) };
            return first.contrast(second);
        }
    }.body);
}

test "settings an empty focused text field shows that it has focus" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            const hwnd = fixture.hwnd();
            const field = settings.fields.edit_font_family.?;
            var text: [8]u16 = undefined;
            try std.testing.expectEqual(@as(c_int, 0), GetWindowTextW(field, &text, @intCast(text.len)));

            for ([_]u32{ 96, 144 }) |dpi| {
                dialog_test.simulateDpi(hwnd, dpi);
                _ = SetFocus(settings.sectionButton(.appearance).?);
                dialog_test.flushPaint(hwnd);
                const unfocused = try dialog_test.Capture.take(hwnd);
                defer unfocused.deinit();
                _ = SetFocus(field);
                _ = dialog_test.HideCaret(null);
                dialog_test.flushPaint(hwnd);
                const focused = try dialog_test.Capture.take(hwnd);
                defer focused.deinit();
                try std.testing.expect(unfocused.countDifferent(focused, dialog_test.rectIn(hwnd, field), 0, 0) > 0);
                // Painted when focus arrived, not only by a later full repaint.
                try dialog_test.expectNothingStale(hwnd);
            }
        }
    }.body);
}

test "settings field frame insets centre one line inside the stroke" {
    // 48 px box, 3 px stroke, 22 px line: 13 above, 13 below.
    try std.testing.expectEqual(FieldFrameInsets{ .x = 3, .y = 13 }, fieldFrameInsets(360, 48, 22, 3));
    // An odd remainder goes below.
    try std.testing.expectEqual(FieldFrameInsets{ .x = 2, .y = 7 }, fieldFrameInsets(200, 32, 17, 2));
    // A line taller than the box keeps the stroke, and never more than half.
    try std.testing.expectEqual(FieldFrameInsets{ .x = 2, .y = 2 }, fieldFrameInsets(200, 20, 40, 2));
    try std.testing.expectEqual(FieldFrameInsets{ .x = 1, .y = 1 }, fieldFrameInsets(3, 3, 0, 2));
    try std.testing.expectEqual(FieldFrameInsets{ .x = 0, .y = 0 }, fieldFrameInsets(-5, -5, 10, 2));
    // Focus wins over an invalid value while the user is typing it.
    try std.testing.expectEqual(FieldFrameState.invalid, fieldFrameState(true, true));
    try std.testing.expectEqual(FieldFrameState.focused, fieldFrameState(true, false));
    try std.testing.expectEqual(FieldFrameState.invalid, fieldFrameState(false, true));
    try std.testing.expectEqual(FieldFrameState.rest, fieldFrameState(false, false));
    // A dropdown is asked for its field height less its own frame.
    try std.testing.expectEqual(@as(i32, 42), comboSelectionHeight(35, 29, 48));
    try std.testing.expectEqual(@as(i32, 1), comboSelectionHeight(80, 10, 4));
}

