            // The status names what wins, the command line, not the line the
            // save just wrote.
            try std.testing.expectEqual(StatusNote.saved_overridden, settings.status_note);
            try std.testing.expectEqualStrings(
                "Saved, but a later config file or command-line option overrides default-profile (the command line), so the saved value is not used.",
                settings.noteText(),
            );
        }
    }.body);
}

test "settings an origin-note says when the line it names has changed since the file was read" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const alloc = std.testing.allocator;
            var tmp = std.testing.tmpDir(.{});
            defer tmp.cleanup();
            try tmp.dir.writeFile(.{ .sub_path = "noctty.conf", .data = "font-size = 13\nscrollback-limit = 5000\n" });
            const path = try tmp.dir.realpathAlloc(alloc, "noctty.conf");
            defer alloc.free(path);

            const fixture = try dialog_test.Fixture.prepare(false);
            defer fixture.finish();
            try fixture.config.loadFile(alloc, path);
            fixture.source_path = path;
            const settings = &fixture.settings;
            try settings.open();
            dialog_test.makeAllSections(settings);
            const font = settings.controlIndex(settings.fields.edit_font_size.?).?;
            const scrollback = settings.controlIndex(settings.fields.edit_scrollback.?).?;
            try std.testing.expectEqualStrings("Set in noctty.conf, line 1", settings.origin_notes[font].text());
            try std.testing.expectEqualStrings("Set in noctty.conf, line 2", settings.origin_notes[scrollback].text());

            // The first line taken out, and the config not read again: both
            // lines named no longer hold what was read there.
            try tmp.dir.writeFile(.{ .sub_path = "noctty.conf", .data = "scrollback-limit = 5000\n" });
            settings.externalConfigChanged(&fixture.config, 2);
            try std.testing.expectEqualStrings("Set in noctty.conf, line 1; the file has changed since", settings.origin_notes[font].text());
            try std.testing.expectEqualStrings("Set in noctty.conf, line 2; the file has changed since", settings.origin_notes[scrollback].text());

            // Read again: the line is current, and so is the note.
            var reloaded = try Config.default(alloc);
            reloaded.loadFile(alloc, path) catch |err| {
                reloaded.deinit();
                return err;
            };
            fixture.config.deinit();
            fixture.config = reloaded;
            settings.externalConfigChanged(&fixture.config, 3);
            try std.testing.expectEqualStrings("Set in noctty.conf, line 1", settings.origin_notes[scrollback].text());
            try std.testing.expectEqualStrings("", settings.origin_notes[font].text());
        }
    }.body);
}

test "settings a Reset button whose MSAA name cannot change serves no other row, and is named on the next try" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            var fake: FakeAnnotations = .{};
            const fixture = try dialog_test.Fixture.prepareChanged(false);
            defer fixture.finish();
            const settings = &fixture.settings;
            settings.annotation_service = &fake.service;
            try settings.open();
            // Every field made, and described, while names can be set; only
            // Appearance's rows have held buttons.
            dialog_test.makeAllSections(settings);
            try fake.expectButtonsNamedForTheirIds(settings);

            // Names cannot be set now. Terminal's rows find only Appearance's
            // spares, which would need renaming: they stay Appearance's,
            // hidden, and Terminal's rows go without a button for now.
            fake.fail = true;
            settings.setActiveSection(.terminal);
            try fake.expectButtonsNamedForTheirIds(settings);
            var waiting: usize = 0;
            for (0..form_field_count) |index| {
                const on_page = if (settings.controlSection(index)) |page| page == .terminal else false;
                if (!on_page or !settings.differs_from_default[index]) continue;
                try std.testing.expectEqual(@as(?HWND, null), settings.reset_buttons[index]);
                waiting += 1;
            }
            try std.testing.expect(waiting > 0);
            // A field reset now keeps the description it had in MSAA.
            const scrollback = settings.fields.edit_scrollback.?;
            var kept: [FakeAnnotations.Entry.description_capacity]u8 = undefined;
            const before = try std.fmt.bufPrint(&kept, "{s}", .{fake.descriptionOf(scrollback)});
            try std.testing.expectEqualStrings("Changed from the default. Set in changed.ghostty, line 1.", before);
            settings.resetRow(settings.controlIndex(scrollback).?);
            try std.testing.expect(!settings.differs_from_default[settings.controlIndex(scrollback).?]);
            try std.testing.expectEqualStrings(before, fake.descriptionOf(scrollback));

            // Names can be set again: the next pass gives the rows their
            // buttons, named, and the description follows the reset.
            fake.fail = false;
            settings.syncDefaultMarks();
            try fake.expectButtonsNamedForTheirIds(settings);
            for (0..form_field_count) |index| {
                const on_page = if (settings.controlSection(index)) |page| page == .terminal else false;
                if (!on_page) continue;
                try std.testing.expectEqual(settings.differs_from_default[index], settings.reset_buttons[index] != null);
                if (settings.reset_buttons[index]) |button| try std.testing.expect(sys.IsWindowVisible(button) != 0);
            }
            // The saved value still comes from the file; only that it differs
            // from the default goes.
            try std.testing.expectEqualStrings("Set in changed.ghostty, line 1.", fake.descriptionOf(scrollback));
        }
    }.body);
}

test "settings a reset that cannot make its copies changes nothing and says so" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            // The arenas a successful reset stores into outlive the window,
            // and the allocator under them outlives both.
            var failing: std.testing.FailingAllocator = undefined;
            var kept: [2]?std.heap.ArenaAllocator = .{ null, null };
            defer for (&kept) |*slot| if (slot.*) |arena| arena.deinit();
            const fixture = try dialog_test.Fixture.start();
            defer fixture.finish();
            const settings = &fixture.settings;
            var buf: [256]u8 = undefined;
            const arena = fixture.config._arena.?.allocator();
            const owned: OwnedSettingField = .font_family;

            // A font typed over the blank default, then the file sets another:
            // the reset needs the default for the draft and the file's font
            // for the baseline.
            const family = settings.fields.edit_font_family.?;
            const index = settings.controlIndex(family).?;
            typeInto(family, "Consolas");
            settings.syncOwnedControl(owned);
            fixture.config.@"font-family" = try parseFontFamilyEditText(arena, "Cascadia Mono");
            settings.externalConfigChanged(&fixture.config, 2);
            try std.testing.expect(settings.owned_conflict[@intFromEnum(owned)]);

            // Each allocation the reset makes fails in turn. The draft and the
            // baseline get fresh arenas, so every copy asks the failing
            // allocator; their own arenas come back after.
            var fail_index: usize = 0;
            while (fail_index < 16) : (fail_index += 1) {
                errdefer std.debug.print("settings reset with allocation {d} failing\n", .{fail_index});
                failing = std.testing.FailingAllocator.init(std.testing.allocator, .{ .fail_index = fail_index });
                const pending = &settings.pending.?;
                const original = &settings.original.?;
                const pending_arena = pending._arena.?;
                const original_arena = original._arena.?;
                pending._arena = std.heap.ArenaAllocator.init(failing.allocator());
                original._arena = std.heap.ArenaAllocator.init(failing.allocator());
                settings.resetRow(index);
                const fresh: [2]std.heap.ArenaAllocator = .{ pending._arena.?, original._arena.? };
                pending._arena = pending_arena;
                original._arena = original_arena;
                if (failing.has_induced_failure) {
                    // Nothing was stored, so nothing points into the fresh arenas.
                    for (fresh) |unused| unused.deinit();
                    try std.testing.expectEqual(@as(usize, 1), settings.pending.?.@"font-family".count());
                    try std.testing.expectEqual(@as(usize, 0), settings.original.?.@"font-family".count());
                    try std.testing.expect(settings.owned_dirty[@intFromEnum(owned)]);
                    try std.testing.expect(settings.owned_conflict[@intFromEnum(owned)]);
                    try std.testing.expect(settings.hasPendingChanges());
                    try std.testing.expect(editHoldsText(family, " \t,"));
                    const status = try statusTextOf(settings, &buf);
                    try std.testing.expect(std.mem.startsWith(u8, status, "Could not reset "));
                    try std.testing.expect(std.mem.endsWith(u8, status, "; it keeps its value."));
                    continue;
                }
                kept = .{ fresh[0], fresh[1] };
                // With memory, the reset is made: the default, to save over
                // the file's font.
                try std.testing.expect(fail_index > 0);
                try std.testing.expectEqual(@as(usize, 0), settings.pending.?.@"font-family".count());
                try std.testing.expect(ownedSettingEql(&settings.original.?, &fixture.config, owned));
                try std.testing.expect(settings.owned_dirty[@intFromEnum(owned)]);
                try std.testing.expect(!settings.owned_conflict[@intFromEnum(owned)]);
                break;
            } else return error.TestUnexpectedResult;

            // A number field's reset copies values and cannot run out of
            // memory; it waits for a save in progress, changing nothing.
            const size = settings.fields.edit_font_size.?;
            typeInto(size, "16");
            settings.transaction.?.pending_apply_id = 1;
            settings.resetRow(settings.controlIndex(size).?);
            settings.transaction.?.pending_apply_id = null;
            try std.testing.expectEqual(@as(f32, 16), settings.pending.?.@"font-size");
            try std.testing.expect(settings.transaction.?.entryConst(.font_size).?.dirty);
            try std.testing.expect(std.mem.endsWith(u8, try statusTextOf(settings, &buf), "; it keeps its value."));
        }
    }.body);
}

test "settings a Reset button another page took is no focus to go back to, and no click of its old row" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.startChanged(false);
            defer fixture.finish();
            const settings = &fixture.settings;
            const font = settings.controlIndex(settings.fields.edit_font_size.?).?;
            const button = settings.reset_buttons[font].?;
            // Focused when the close prompt opens, then the page changes under
            // the prompt: the button goes to the spares, and maybe to a row
            // of the new page. "Keep editing" must not put focus there.
            _ = SetFocus(button);
            settings.showClosePrompt();
            try std.testing.expectEqual(@as(?HWND, button), settings.close_prior_focus);
            settings.setActiveSection(.terminal);
            try std.testing.expect(settings.close_prior_focus != button);
            settings.cancelClosePrompt();
            try std.testing.expectEqual(settings.sectionButton(.terminal).?, GetFocus().?);
            // A click that reaches the button late, with its old row's id,
            // resets nothing.
            const stale: WPARAM = BTN_RESET_FIRST + font;
            _ = SendMessageW(fixture.hwnd(), WM_COMMAND, stale, @bitCast(@intFromPtr(button)));
            try std.testing.expect(settings.differs_from_default[font]);
            // Nor does one with the row's id from a button the row does not
            // hold (another row's, which may once have served this one).
            settings.setActiveSection(.appearance);
            const held = settings.reset_buttons[font].?;
            const other = settings.reset_buttons[settings.controlIndex(settings.fields.edit_bg_opacity.?).?].?;
            _ = SendMessageW(fixture.hwnd(), WM_COMMAND, stale, @bitCast(@intFromPtr(other)));
            try std.testing.expect(settings.differs_from_default[font]);
            // From the button the row holds and shows, it does.
            _ = SendMessageW(fixture.hwnd(), WM_COMMAND, stale, @bitCast(@intFromPtr(held)));
            try std.testing.expect(!settings.differs_from_default[font]);
        }
    }.body);
}

test "settings only the shown page's rows hold Reset buttons, handed on from page to page" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            // With the custom providers: a button handed to another row gets
            // a provider of that row's.
            const fixture = try dialog_test.Fixture.startChanged(true);
            defer fixture.finish();
            const settings = &fixture.settings;
            var most: usize = 0;
            for (std.enums.values(Section)) |section| {
                settings.setActiveSection(section);
                const viewport = settings.viewport.?;
                var held: usize = 0;
                for (settings.reset_buttons) |button| held += @intFromBool(button != null);
                // A page's rows take spares before any button is made, so the
                // window holds exactly as many as the most one page has needed;
                // the All settings and Profiles pages, which have no rows, none
                // at all, and the pages after them start again.
                most = @max(most, held);
                if (section == .reference or section == .profiles) {
                    try std.testing.expectEqual(@as(usize, 0), held + settings.reset_spare_count);
                    most = 0;
                } else try std.testing.expectEqual(most, held + settings.reset_spare_count);
                for (settings.reset_spares[0..settings.reset_spare_count]) |spare| try std.testing.expect(sys.IsWindowVisible(spare) == 0);
                for (0..form_field_count) |index| {
                    const on_page = if (settings.controlSection(index)) |page| page == section else false;
                    // Every row that differs on this page has its button, and
                    // no other page's row has one: at most one page's worth.
                    try std.testing.expectEqual(on_page and settings.differs_from_default[index], settings.reset_buttons[index] != null);
                    // Made hidden during the switch, shown once placed:
                    // beside its control, at the top of the row.
                    const button = settings.reset_buttons[index] orelse continue;
                    try std.testing.expect(sys.IsWindowVisible(button) != 0);
                    // Whichever button a row took, its id and its provider
                    // name that row.
                    try std.testing.expectEqual(@as(LONG_PTR, @intCast(BTN_RESET_FIRST + index)), sys.GetWindowLongPtrW(button, GWLP_ID));
                    const provider = settings.reset_uia_providers[index].?;
                    try std.testing.expectEqual(button, provider.hwnd);
                    try std.testing.expectEqualStrings(reset_button_names[index], provider.name.?);
                    const control = childRectIn(viewport, settings.controlHwnd(index).?).?;
                    const end = childRectIn(viewport, settings.rowEnd(index).?).?;
                    const placed = childRectIn(viewport, button).?;
                    try std.testing.expectEqual(end.right + settings.px(settings_reset_gap), placed.left);
                    try std.testing.expectEqual(control.top, placed.top);
                }
            }
            // Back on Appearance from pages whose rows take none, each row has
            // the button it had, whose id and MSAA name are already its own.
            settings.setActiveSection(.appearance);
            const first = settings.reset_buttons;
            settings.setActiveSection(.keybindings);
            settings.setActiveSection(.advanced);
            settings.setActiveSection(.appearance);
            for (first, settings.reset_buttons) |was, now| try std.testing.expectEqual(was, now);
        }
    }.body);
}

test "settings a Reset button joins its row's arrow-key run and never a label's" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            const fixture = try dialog_test.Fixture.startChanged(false);
            defer fixture.finish();
            const settings = &fixture.settings;
            const hwnd = fixture.hwnd();
            for (std.enums.values(Section)) |section| {
                settings.setActiveSection(section);
                for (settings.formItems()) |item| {
                    if (item.control_index >= form_field_count) continue;
                    const button = settings.reset_buttons[item.control_index] orelse continue;
                    if (sys.IsWindowVisible(button) == 0) continue;
                    for ([_]windows.BOOL{ 0, 1 }) |previous| {
                        // A field or a Reset button of the form, never a label
                        // and never outside the form.
                        const next = dialog_test.GetNextDlgGroupItem(hwnd, button, previous).?;
                        try std.testing.expect(settings.rowOfWindow(next) != null);
                        try std.testing.expect(settings.textIndex(next) == null);
                    }
                }
            }
            // No run from a field or its button reaches a trackbar or an
            // up-down, and the trackbar's run is its own: the arrows step it.
            for (std.enums.values(Section)) |section| {
                settings.setActiveSection(section);
                for (settings.formItems()) |item| {
                    const control = settings.controlHwnd(item.control_index).?;
                    if (sys.IsWindowVisible(control) == 0 or sys.IsWindowEnabled(control) == 0) continue;
                    const reset = if (item.control_index < form_field_count) settings.reset_buttons[item.control_index] else null;
                    for ([_]?HWND{ control, reset }) |maybe| if (maybe) |window| if (sys.IsWindowVisible(window) != 0) {
                        for ([_]windows.BOOL{ 0, 1 }) |previous| {
                            errdefer std.debug.print("settings arrow run from control {d} reaches a trackbar or up-down\n", .{item.control_index});
                            try std.testing.expect(!isCompanion(settings, dialog_test.GetNextDlgGroupItem(hwnd, window, previous).?));
                        }
                    };
                }
            }
            settings.setActiveSection(.appearance);
            const slider = settings.companions[@intFromEnum(Companion.opacity_slider)].?;
            for ([_]windows.BOOL{ 0, 1 }) |previous| try std.testing.expectEqual(slider, dialog_test.GetNextDlgGroupItem(hwnd, slider, previous).?);

            // The button starts no group (a hidden one would still end its
            // control's run): the notification checkboxes' run takes each
            // shown button after its checkbox, and wraps.
            settings.setActiveSection(.privacy);
            const fields = &settings.fields;
            const run = [_]HWND{
                fields.chk_desktop_notifications.?,
                settings.reset_buttons[settings.controlIndex(fields.chk_desktop_notifications.?).?].?,
                fields.chk_app_notify_clipboard.?,
                settings.reset_buttons[settings.controlIndex(fields.chk_app_notify_clipboard.?).?].?,
                fields.chk_app_notify_config.?,
                settings.reset_buttons[settings.controlIndex(fields.chk_app_notify_config.?).?].?,
            };
            for (run, 0..) |window, i| {
                try std.testing.expectEqual(@as(u32, if (i == 0) WS_GROUP else 0), windowStyle(window) & WS_GROUP);
                try std.testing.expectEqual(run[(i + 1) % run.len], dialog_test.GetNextDlgGroupItem(hwnd, window, 0).?);
            }
        }
    }.body);
}

test "settings a config at its defaults marks no field, finalized as the app's is" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            @setEvalBranchQuota(20000);
            for ([_]bool{ false, true }) |pair| {
                const fixture = try dialog_test.Fixture.prepare(false);
                defer fixture.finish();
                // Settings copies the App's config, which is finalized: an unset
                // Auto-update channel becomes this build's channel, and with a
                // light/dark theme pair a Window theme of auto becomes system.
                try fixture.config.finalize();
                try std.testing.expect(fixture.config.@"auto-update-channel" != null);
                if (pair) fixture.config.@"window-theme" = .system;
                try fixture.settings.open();
                const settings = &fixture.settings;
                for (std.enums.values(Section)) |section| settings.setActiveSection(section);
                inline for (field_model.form_fields, 0..) |row, index| {
                    errdefer std.debug.print("settings marked at its default: {s}\n", .{row.native.binding});
                    try std.testing.expect(!settings.differs_from_default[index]);
                    try std.testing.expect(settings.reset_buttons[index] == null);
                }
                // A choice changed and reset leaves nothing to save: the reset
                // keeps the saved value the finalize made, which counts as the
                // default, rather than writing the raw default as a new line.
                const CB_GETCOUNT: UINT = 0x0146;
                inline for (.{ SettingField.auto_update_channel, SettingField.window_theme }) |field| {
                    errdefer std.debug.print("settings reset left an edit: {s} pair={}\n", .{ @tagName(field), pair });
                    const combo = (if (field == .auto_update_channel) settings.fields.combo_auto_update_channel else settings.fields.combo_window_theme).?;
                    const index = settings.controlIndex(combo).?;
                    const choices: usize = @intCast(sys.SendMessageW(combo, CB_GETCOUNT, 0, 0));
                    for (1..choices) |choice| {
                        _ = sys.SendMessageW(combo, CB_SETCURSEL, choice, 0);
                        settings.syncCombo(field);
                        if (settings.differs_from_default[index]) break;
                    }
                    try std.testing.expect(settings.differs_from_default[index]);
                    try std.testing.expect(settings.hasPendingChanges());
                    settings.resetRow(index);
                    try std.testing.expect(!settings.differs_from_default[index]);
                    try std.testing.expect(!settings.hasPendingChanges());
                    try std.testing.expect(settingValueEql(
                        settingValue(&settings.original.?, field),
                        settingValue(&settings.pending.?, field),
                    ));
                }
            }
        }
    }.body);
}

