fn settingsTextProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const owner = if (sys.GetParent(hwnd)) |parent| recoverOwner(parent) else null;
    if (owner) |settings| {
        const previous = settings.text_uia_prev_proc;
        if (settings.textIndex(hwnd)) |index| {
            if (msg == WM_GETOBJECT) {
                if (settings.text_uia_providers[index]) |provider| {
                    if (win32_uia.returnSettingsControlProvider(hwnd, wParam, lParam, provider)) |result| return result;
                }
            }
            if (msg == WM_NCDESTROY) {
                if (settings.text_uia_providers[index]) |provider| provider.detach();
                if (previous) |proc| {
                    _ = sys.SetWindowLongPtrW(hwnd, GWLP_WNDPROC, @as(LONG_PTR, @intCast(@intFromPtr(proc))));
                    return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
                }
            }
        }
        if (previous) |proc| return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

fn settingsControlProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const owner = if (sys.GetParent(hwnd)) |parent| recoverOwner(parent) else null;
    if (owner) |settings| {
        if (settings.controlIndex(hwnd)) |index| {
            const previous = settings.control_uia_prev_procs[index];
            if (msg == win32_uia.SettingsControlProvider.action_message) {
                if (settings.control_uia_providers[index]) |provider| {
                    const trace_action = settings.combo_trace.enabled() and
                        (wParam == @intFromEnum(win32_uia.SettingsControlProvider.Action.expand) or
                            wParam == @intFromEnum(win32_uia.SettingsControlProvider.Action.collapse));
                    if (trace_action)
                        settings.combo_trace.noteEvent(.action_received, sys.GetDlgCtrlID(hwnd), sys.SendMessageW(hwnd, CB_GETDROPPEDSTATE, 0, 0) != 0);
                    if (wParam == @intFromEnum(win32_uia.SettingsControlProvider.Action.expand) and sys.IsWindowEnabled(hwnd) != 0)
                        settings.ensureControlVisible(hwnd);
                    const hr = provider.handleAction(wParam, lParam);
                    if (trace_action)
                        settings.combo_trace.noteEvent(.action_returned, sys.GetDlgCtrlID(hwnd), sys.SendMessageW(hwnd, CB_GETDROPPEDSTATE, 0, 0) != 0);
                    return if (hr == @import("win32_uia/com.zig").S_OK) win32_uia.SettingsControlProvider.action_success else hr;
                }
                return @import("win32_uia/com.zig").UIA_E_ELEMENTNOTAVAILABLE;
            }
            if (msg == WM_GETOBJECT) {
                if (settings.control_uia_providers[index]) |provider| {
                    if (win32_uia.returnSettingsControlProvider(hwnd, wParam, lParam, provider)) |result| return result;
                }
            }
            if (msg == WM_NCDESTROY) {
                if (settings.control_uia_providers[index]) |provider| provider.detach();
                if (previous) |proc| {
                    _ = sys.SetWindowLongPtrW(hwnd, GWLP_WNDPROC, @as(LONG_PTR, @intCast(@intFromPtr(proc))));
                    return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
                }
            }
            if (previous) |proc| {
                if (settings.combo_trace.enabled() and settings_control_specs[index].role == .combo_box) {
                    const event: ?bench_trace.SettingsComboTrace.Event = switch (msg) {
                        WM_KILLFOCUS => .focus_lost,
                        0x0215 => .capture_changed, // WM_CAPTURECHANGED
                        else => null,
                    };
                    if (event) |tag|
                        settings.combo_trace.noteEvent(tag, sys.GetDlgCtrlID(hwnd), sys.SendMessageW(hwnd, CB_GETDROPPEDSTATE, 0, 0) != 0);
                }
                if (msg == 0x014F and settings.combo_trace.enabled())
                    settings.combo_trace.note(sys.GetDlgCtrlID(hwnd), wParam != 0, sys.SendMessageW(hwnd, CB_GETDROPPEDSTATE, 0, 0) != 0, null);
                const result = sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
                if (msg == 0x014F and settings.combo_trace.enabled())
                    settings.combo_trace.note(sys.GetDlgCtrlID(hwnd), wParam != 0, sys.SendMessageW(hwnd, CB_GETDROPPEDSTATE, 0, 0) != 0, result);
                if (msg == WM_SETFOCUS) {
                    if (settings.control_uia_providers[index]) |provider| provider.raiseFocusChanged();
                }
                // Native control messages also cover programmatic refresh /
                // Discard. Reads performed by syncNativeState do not reenter
                // this mutation-only gate.
                switch (msg) {
                    0x00F1, // BM_SETCHECK
                    CB_SETCURSEL,
                    0x014F, // CB_SHOWDROPDOWN
                    SettingsComboPopup.sync_message,
                    WM_KEYDOWN,
                    WM_KEYUP,
                    WM_SYSKEYDOWN,
                    0x0105, // WM_SYSKEYUP
                    WM_LBUTTONDOWN,
                    0x0202,
                    WM_KILLFOCUS,
                    => if (settings.control_uia_providers[index]) |provider| provider.syncNativeState(if (msg == CB_SETCURSEL or msg == SettingsComboPopup.sync_message) .explicit_selection else .observe),
                    else => {},
                }
                return result;
            }
        }
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

/// A Reset button's UIA provider (`attachResetUiaProvider`). The buttons are
/// made one at a time as rows come to differ from their defaults, so they are
/// not among the indexed controls `settingsControlProc` serves.
fn settingsResetButtonProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const owner = if (sys.GetParent(hwnd)) |parent| recoverOwner(parent) else null;
    if (owner) |settings| {
        const previous = settings.reset_uia_prev_proc;
        if (settings.resetButtonIndex(hwnd)) |index| {
            if (msg == WM_GETOBJECT) {
                if (settings.reset_uia_providers[index]) |provider| {
                    if (win32_uia.returnSettingsControlProvider(hwnd, wParam, lParam, provider)) |result| return result;
                }
            }
            if (msg == WM_NCDESTROY) {
                if (settings.reset_uia_providers[index]) |provider| provider.detach();
                if (previous) |proc| {
                    _ = sys.SetWindowLongPtrW(hwnd, GWLP_WNDPROC, @as(LONG_PTR, @intCast(@intFromPtr(proc))));
                    return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
                }
            }
            if (msg == WM_SETFOCUS) if (previous) |proc| {
                const result = sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
                if (settings.reset_uia_providers[index]) |provider| provider.raiseFocusChanged();
                return result;
            };
        }
        if (previous) |proc| return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

/// Observe direct stock-popup selection without replacing its UIA provider.
const SettingsComboPopup = struct {
    const sync_message: UINT = 0x8000 + 0x10D;
    const subclass_id: usize = 0x53455491;
    const Info = extern struct {
        size: u32 = @sizeOf(Info),
        item: sys.RECT = std.mem.zeroes(sys.RECT),
        button: sys.RECT = std.mem.zeroes(sys.RECT),
        state: u32 = 0,
        combo: ?HWND = null,
        edit: ?HWND = null,
        list: ?HWND = null,
    };
    extern "user32" fn GetComboBoxInfo(HWND, *Info) callconv(.winapi) BOOL;
    extern "comctl32" fn SetWindowSubclass(HWND, *const @TypeOf(proc), usize, usize) callconv(.winapi) BOOL;
    extern "comctl32" fn RemoveWindowSubclass(HWND, *const @TypeOf(proc), usize) callconv(.winapi) BOOL;
    extern "comctl32" fn DefSubclassProc(HWND, UINT, WPARAM, LPARAM) callconv(.winapi) LRESULT;

    fn attach(combo: HWND) void {
        var info: Info = .{};
        if (GetComboBoxInfo(combo, &info) == 0) return;
        if (info.list) |list| _ = SetWindowSubclass(list, &proc, subclass_id, @intFromPtr(combo));
    }

    fn proc(hwnd: HWND, msg: UINT, w: WPARAM, l: LPARAM, id: usize, data: usize) callconv(.winapi) LRESULT {
        if (msg == WM_NCDESTROY) _ = RemoveWindowSubclass(hwnd, &proc, id);
        const result = DefSubclassProc(hwnd, msg, w, l);
        // The stock SelectionItem proxy changes the list directly, bypassing
        // the combo's CB_SETCURSEL and its usual CBN_SELCHANGE notification.
        // Carry only the owning HWND, never a SettingsWindow/provider pointer.
        if (msg == 0x0186) _ = sys.SendMessageW(@ptrFromInt(data), sync_message, 0, 0); // LB_SETCURSEL
        return result;
    }
};

/// A closed COMBOBOX changes its selection on the wheel, so scrolling the
/// page past one goes to the form instead. Its previous procedure lives in
/// GWLP_USERDATA and is restored in WM_NCDESTROY.
fn settingsComboProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const previous = sys.GetWindowLongPtrW(hwnd, GWLP_USERDATA);
    if (previous == 0) return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
    if (msg == WM_MOUSEWHEEL and sys.SendMessageW(hwnd, CB_GETDROPPEDSTATE, 0, 0) == 0) {
        const parent = sys.GetParent(hwnd) orelse return 0;
        return sys.SendMessageW(parent, msg, wParam, lParam);
    }
    const proc: *const anyopaque = @ptrFromInt(@as(usize, @intCast(previous)));
    if (msg == WM_NCDESTROY) {
        _ = sys.SetWindowLongPtrW(hwnd, GWLP_WNDPROC, previous);
        _ = sys.SetWindowLongPtrW(hwnd, GWLP_USERDATA, 0);
    }
    return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
}

/// Install `proc` on a stock control and keep the procedure it replaces in
/// the control's `GWLP_USERDATA`, which the stock classes leave unused.
fn subclassKeepingPrevious(control: HWND, proc: win32_types.WNDPROC) void {
    // Already ours (the prior procedure is recorded): nothing to do.
    if (sys.GetWindowLongPtrW(control, GWLP_USERDATA) != 0) return;
    const previous = sys.SetWindowLongPtrW(
        control,
        GWLP_WNDPROC,
        @as(LONG_PTR, @intCast(@intFromPtr(proc))),
    );
    if (previous == 0) return;
    _ = sys.SetWindowLongPtrW(control, GWLP_USERDATA, previous);
}

/// Subclass for the text fields, which draw their own frame (`fieldFrameInsets`,
/// `SettingsWindow.paintFieldFrame`). The themed one-pixel border has no focused
/// state, so an empty focused field showed nothing but its caret, and a
/// single-line EDIT puts its text at the top of its box. The frame is the
/// non-client area: a stroke all round and, above and below, whatever centres
/// one line of text. Clicks there count as clicks in the field. The previous
/// procedure lives in `GWLP_USERDATA`, as for the dropdowns.
fn settingsEditProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const previous = sys.GetWindowLongPtrW(hwnd, GWLP_USERDATA);
    if (previous == 0) return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
    const proc: *const anyopaque = @ptrFromInt(@as(usize, @intCast(previous)));
    const owner = if (sys.GetParent(hwnd)) |parent| recoverOwner(parent) else null;
    switch (msg) {
        WM_NCCALCSIZE => if (owner) |settings| {
            // Both forms put the proposed window rect first: a bare RECT, or
            // `NCCALCSIZE_PARAMS.rgrc[0]`. It becomes the client rect.
            const rect: *RECT = @ptrFromInt(@as(usize, @bitCast(lParam)));
            const insets = fieldFrameInsets(
                rect.right - rect.left,
                rect.bottom - rect.top,
                settings.field_text_height,
                settings.fieldStroke(),
            );
            rect.left += insets.x;
            rect.right -= insets.x;
            rect.top += insets.y;
            rect.bottom -= insets.y;
            return 0;
        },
        WM_NCHITTEST => if (owner != null) return HTCLIENT,
        WM_NCPAINT => if (owner) |settings| {
            settings.paintFieldFrame(hwnd, null);
            return 0;
        },
        WM_SETFOCUS, WM_KILLFOCUS, WM_ENABLE => {
            const result = sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
            if (owner) |settings| settings.paintFieldFrame(hwnd, switch (msg) {
                WM_SETFOCUS => true,
                WM_KILLFOCUS => false,
                else => null,
            });
            return result;
        },
        WM_NCDESTROY => {
            _ = sys.SetWindowLongPtrW(hwnd, GWLP_WNDPROC, previous);
            _ = sys.SetWindowLongPtrW(hwnd, GWLP_USERDATA, 0);
        },
        WM_SETTEXT => if (lParam != 0) {
            if (setTextCut(hwnd, proc, wParam, @ptrFromInt(@as(usize, @bitCast(lParam))))) |result| return result;
        },
        else => {},
    }
    return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
}

/// A value set from outside the field (UIA `SetValue`, which calls
/// `SetWindowTextW`, or an MSAA `put_accValue`) arrives as `WM_SETTEXT`, which
/// `EM_LIMITTEXT` does not limit (per its documentation), while typing and
/// pasting stop at the limit and the code that reads a field reads only that
/// much: the search field 128 units (`searchTextChanged`), and the fields read
/// through `readEditUtf8` (the number fields among them, `syncNumberFromEdit`)
/// 4095. Over the limit, the field gets the text cut to it, never through a
/// surrogate pair, so it shows exactly what is read. Null when the text fits
/// and goes through as it is.
fn setTextCut(hwnd: HWND, proc: *const anyopaque, wParam: WPARAM, text: [*:0]const u16) ?LRESULT {
    var cut: [edit_text_max_code_units]u16 = undefined;
    const limit: usize = @intCast(@max(0, sys.SendMessageW(hwnd, EM_GETLIMITTEXT, 0, 0)));
    if (limit >= cut.len) return null;
    var len: usize = 0;
    while (len <= limit and text[len] != 0) len += 1;
    if (len <= limit) return null;
    var keep = limit;
    // A high surrogate last would be half a character.
    if (keep > 0 and text[keep - 1] & 0xFC00 == 0xD800) keep -= 1;
    @memcpy(cut[0..keep], text[0..keep]);
    cut[keep] = 0;
    return sys.CallWindowProcW(proc, hwnd, WM_SETTEXT, wParam, @bitCast(@intFromPtr(&cut)));
}

/// A check box painted as a toggle switch (`paintToggle`). The BUTTON is
/// still a `BS_AUTOCHECKBOX` underneath: its check state, Space, a click,
/// `BN_CLICKED`, `BM_SETCHECK` and the UIA Toggle pattern are the stock
/// ones, and only its look is ours. In High Contrast it is the stock check
/// box, in system colours. The previous procedure lives in `GWLP_USERDATA`,
/// as for the dropdowns.
/// Subclass for the opacity trackbar. A trackbar sends its parent no focus
/// notification, as a field's `EN_SETFOCUS` or a button's `BN_SETFOCUS`, so
/// focus that reaches it by Tab is seen here and scrolls it into view. The
/// previous procedure lives in `GWLP_USERDATA`.
fn settingsSliderProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const previous = sys.GetWindowLongPtrW(hwnd, GWLP_USERDATA);
    if (previous == 0) return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
    const proc: *const anyopaque = @ptrFromInt(@as(usize, @intCast(previous)));
    if (msg == WM_NCDESTROY) {
        _ = sys.SetWindowLongPtrW(hwnd, GWLP_WNDPROC, previous);
        _ = sys.SetWindowLongPtrW(hwnd, GWLP_USERDATA, 0);
        return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
    }
    const result = sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
    if (msg == WM_SETFOCUS) if (sys.GetParent(hwnd)) |parent| if (recoverOwner(parent)) |settings| {
        if (!settings.restoring_focus) settings.ensureControlVisible(hwnd);
    };
    return result;
}

fn settingsToggleProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const previous = sys.GetWindowLongPtrW(hwnd, GWLP_USERDATA);
    if (previous == 0) return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
    const proc: *const anyopaque = @ptrFromInt(@as(usize, @intCast(previous)));
    if (msg == WM_NCDESTROY) {
        _ = sys.SetWindowLongPtrW(hwnd, GWLP_WNDPROC, previous);
        _ = sys.SetWindowLongPtrW(hwnd, GWLP_USERDATA, 0);
        return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
    }
    const settings = (if (sys.GetParent(hwnd)) |parent| recoverOwner(parent) else null) orelse
        return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
    if (settings.theme_adapter.colors.high_contrast) return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
    switch (msg) {
        WM_ERASEBKGND => return 1,
        WM_PAINT => {
            var ps: PAINTSTRUCT = undefined;
            const hdc = BeginPaint(hwnd, &ps);
            defer _ = EndPaint(hwnd, &ps);
            paintToggle(settings, hwnd, hdc, toggleLook(hwnd, proc));
            return 0;
        },
        WM_PRINTCLIENT => {
            if (wParam != 0) paintToggle(settings, hwnd, @ptrFromInt(wParam), toggleLook(hwnd, proc));
            return 0;
        },
        // Read through the stock procedure below, never repainted for.
        BM_GETCHECK, BM_GETSTATE => return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam),
        else => {},
    }
    // The stock button draws some changes at once, outside WM_PAINT: a
    // classic one its whole face on BM_SETCHECK, even one that changes
    // nothing, and its focus rectangle on WM_SETFOCUS. After those, and
    // after anything that changed the look, the switch is painted over
    // before this returns, so the stock drawing is never what stays.
    const before = toggleLook(hwnd, proc);
    const result = sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
    const redraw = switch (msg) {
        BM_SETCHECK, BM_SETSTATE, BM_CLICK, WM_SETFOCUS, WM_KILLFOCUS, WM_SETTEXT, WM_SETFONT, WM_UPDATEUISTATE, WM_ENABLE => true,
        else => !std.meta.eql(before, toggleLook(hwnd, proc)),
    };
    if (redraw) _ = RedrawWindow(hwnd, null, null, RDW_INVALIDATE | RDW_UPDATENOW);
    return result;
}

/// What a toggle shows. `hot` is the stock button's hover state, which a
/// themed (comctl32 6) button keeps.
const ToggleLook = struct {
    on: bool,
    pressed: bool,
    focused: bool,
    hot: bool,
    enabled: bool,
};

fn toggleLook(hwnd: HWND, proc: *const anyopaque) ToggleLook {
    const BST_HOT: usize = 0x0200;
    const state: usize = @bitCast(sys.CallWindowProcW(proc, hwnd, BM_GETSTATE, 0, 0));
    return .{
        .on = @as(usize, @bitCast(sys.CallWindowProcW(proc, hwnd, BM_GETCHECK, 0, 0))) == BST_CHECKED,
        .pressed = state & BST_PUSHED != 0,
        .focused = GetFocus() == hwnd,
        .hot = state & BST_HOT != 0,
        .enabled = sys.IsWindowEnabled(hwnd) != 0,
    };
}

/// The parts of a toggle in a `rect` client area at `px` scale: the track
/// at the left, centred on the height, its thumb at the end the state names,
/// and the label after it. Windows 11's switch is 40 x 20 with a 12 thumb,
/// 14 under the pointer, and 17 x 14 pressed.
const ToggleParts = struct {
    track: RECT,
    thumb: RECT,
    label: RECT,
};

fn toggleParts(settings: *const SettingsWindow, rect: RECT, look: ToggleLook) ToggleParts {
    const track_width = settings.px(40);
    const track_height = settings.px(20);
    const left = rect.left + settings.px(settings_metrics.stroke_focus + settings_metrics.space_1);
    const top = rect.top + @divTrunc(rect.bottom - rect.top - track_height, 2);
    const track: RECT = .{ .left = left, .top = top, .right = left + track_width, .bottom = top + track_height };
    const thumb_height = settings.px(if (look.pressed or (look.hot and look.enabled)) 14 else 12);
    const thumb_width = if (look.pressed) settings.px(17) else thumb_height;
    const margin = @divTrunc(track_height - thumb_height, 2);
    const thumb_left = if (look.on) track.right - margin - thumb_width else track.left + margin;
    const thumb_top = track.top + margin;
    return .{
        .track = track,
        .thumb = .{ .left = thumb_left, .top = thumb_top, .right = thumb_left + thumb_width, .bottom = thumb_top + thumb_height },
        .label = .{
            .left = track.right + settings.px(settings_metrics.space_4),
            .top = rect.top,
            .right = rect.right - settings.px(settings_metrics.stroke_focus + settings_metrics.space_1),
            .bottom = rect.bottom,
        },
    };
}

/// The colours of a toggle in `look`: the track's fill and outline, the
/// thumb, and the label. On and off differ by the thumb's place as well
/// as by colour; a disabled toggle keeps the shapes in the disabled colour.
fn toggleColors(colors: win32_theme.SettingsColors, look: ToggleLook) struct { fill: COLORREF, outline: COLORREF, thumb: COLORREF, label: COLORREF } {
    if (!look.enabled) return .{
        .fill = if (look.on) colors.disabled_text else colors.window_bg,
        .outline = colors.disabled_text,
        .thumb = if (look.on) colors.window_bg else colors.disabled_text,
        .label = colors.disabled_text,
    };
    return .{
        .fill = if (look.on) colors.toggle_on_track else colors.window_bg,
        .outline = if (look.on) colors.toggle_on_track else colors.toggle_off,
        .thumb = if (look.on) colors.toggle_on_thumb else colors.toggle_off,
        .label = colors.secondary_text,
    };
}

fn paintToggle(settings: *SettingsWindow, hwnd: HWND, hdc: HDC, look: ToggleLook) void {
    const PS_INSIDEFRAME: i32 = 6;
    var rect: RECT = undefined;
    if (GetClientRect(hwnd, &rect) == 0) return;
    settings.proof_toggle_paint_count +%= 1;
    const colors = settings.theme_adapter.colors;
    const background = CreateSolidBrush(colors.window_bg) orelse return;
    defer _ = DeleteObject(background);
    _ = FillRect(hdc, &rect, background);
    const parts = toggleParts(settings, rect, look);
    const shade = toggleColors(colors, look);

    const fill = CreateSolidBrush(shade.fill) orelse return;
    defer _ = DeleteObject(fill);
    const outline = sys.CreatePen(PS_INSIDEFRAME, @max(1, settings.px(settings_metrics.stroke_hairline)), shade.outline) orelse return;
    defer _ = DeleteObject(outline);
    const previous_brush = SelectObject(hdc, fill);
    const previous_pen = SelectObject(hdc, outline);
    defer {
        if (previous_pen) |value| _ = SelectObject(hdc, value);
        if (previous_brush) |value| _ = SelectObject(hdc, value);
    }
    const track_height = parts.track.bottom - parts.track.top;
    _ = sys.RoundRect(hdc, parts.track.left, parts.track.top, parts.track.right, parts.track.bottom, track_height, track_height);

    // The thumb in a scope of its own: its brush is deselected before it is
    // deleted (a brush still selected into a DC is not deleted, and leaks).
    {
        const thumb = CreateSolidBrush(shade.thumb) orelse return;
        defer _ = DeleteObject(thumb);
        const previous_thumb_brush = SelectObject(hdc, thumb);
        defer _ = SelectObject(hdc, previous_thumb_brush);
        const previous_thumb_pen = SelectObject(hdc, GetStockObject(NULL_PEN));
        defer _ = SelectObject(hdc, previous_thumb_pen);
        // The null pen leaves the right and bottom edges out.
        const thumb_height = parts.thumb.bottom - parts.thumb.top;
        _ = sys.RoundRect(hdc, parts.thumb.left, parts.thumb.top, parts.thumb.right + 1, parts.thumb.bottom + 1, thumb_height, thumb_height);
    }

    var label: [128:0]u16 = undefined;
    const label_len = GetWindowTextW(hwnd, &label, @intCast(label.len));
    const font: usize = @bitCast(SendMessageW(hwnd, WM_GETFONT, 0, 0));
    const previous_font = if (font != 0) SelectObject(hdc, @ptrFromInt(font)) else null;
    defer {
        if (previous_font) |value| _ = SelectObject(hdc, value);
    }
    _ = SetBkMode(hdc, TRANSPARENT);
    _ = SetTextColor(hdc, shade.label);
    var text_rect = parts.label;
    if (label_len > 0) _ = DrawTextW(hdc, &label, label_len, &text_rect, DT_SINGLELINE | DT_VCENTER | DT_NOPREFIX | DT_END_ELLIPSIS);

    if (focus_cue.showRing(look.focused, !look.enabled, settings.focus_input_mode, false)) {
        const ring = CreateSolidBrush(colors.focus_ring) orelse return;
        defer _ = DeleteObject(ring);
        // Round the switch and its label, as a check box's focus rectangle
        // hugs its text, not the empty width of the row.
        var measured = parts.label;
        if (label_len > 0) _ = DrawTextW(hdc, &label, label_len, &measured, DT_SINGLELINE | DT_NOPREFIX | DT_CALCRECT);
        var focus_rect = rect;
        focus_rect.right = @min(rect.right, @max(parts.track.right, measured.right) + settings.px(settings_metrics.space_2 + settings_metrics.stroke_focus));
        var layer: i32 = 0;
        while (layer < @max(1, settings.px(settings_metrics.stroke_focus)) and focus_rect.right > focus_rect.left and focus_rect.bottom > focus_rect.top) : (layer += 1) {
            _ = FrameRect(hdc, &focus_rect, ring);
            focus_rect.left += 1;
            focus_rect.top += 1;
            focus_rect.right -= 1;
            focus_rect.bottom -= 1;
        }
    }
}

const FieldFrameInsets = struct { x: i32, y: i32 };

/// What a text field's frame takes from each side of a `width` x `height`
/// window: the stroke all round, and above and below whatever centres a
/// `line_height` line (an odd pixel goes below). Never more than half the box.
fn fieldFrameInsets(width: i32, height: i32, line_height: i32, stroke: i32) FieldFrameInsets {
    const w: i32 = @max(0, width);
    const h: i32 = @max(0, height);
    const centred: i32 = if (line_height > 0) @divTrunc(h - line_height, 2) else 0;
    return .{
        .x = @min(stroke, @divTrunc(w, 2)),
        .y = @min(@max(stroke, centred), @divTrunc(h, 2)),
    };
}

const FieldFrameState = enum { rest, focused, invalid };

/// An error wins over focus. A raw scalar field is only `invalid` once its
/// error is on screen, after the quiet period or when the user leaves it, so
/// the stroke does not flash with each keystroke, and a field that keeps focus
/// while it says it is wrong still looks wrong.
fn fieldFrameState(focused: bool, invalid: bool) FieldFrameState {
    if (invalid) return .invalid;
    if (focused) return .focused;
    return .rest;
}

/// Lines a full wheel notch moves, per the user's mouse setting.
fn systemWheelScrollLines() u32 {
    var lines: u32 = 3;
    if (sys.SystemParametersInfoW(SPI_GETWHEELSCROLLLINES, 0, &lines, 0) == 0) return 3;
    return lines;
}

/// Pixels one notch moves at `lines` lines per notch, where the default of
/// three lines moves `default_px`.
fn wheelNotchPixels(default_px: i32, lines: u32) i32 {
    const capped: i32 = @intCast(@min(lines, 100));
    return @divTrunc(default_px * capped, 3);
}

/// Turn a wheel delta into whole pixels. `remainder` carries what is left of a
/// pixel, in 1/`WHEEL_DELTA` pixel, between messages: a precision touchpad
/// sends many deltas far below one notch, and dividing each by the notch size
/// on its own rounds every one of them to nothing.
fn wheelScrollPixels(remainder: *i32, delta: i32, notch_px: i32) i32 {
    // The leftover belongs to the previous direction.
    if (delta != 0 and remainder.* != 0 and (delta < 0) != (remainder.* < 0)) remainder.* = 0;
    const total: i64 = @as(i64, remainder.*) + @as(i64, delta) * notch_px;
    const pixels: i64 = @divTrunc(total, WHEEL_DELTA);
    remainder.* = @intCast(total - pixels * WHEEL_DELTA);
    return @intCast(std.math.clamp(pixels, std.math.minInt(i32), std.math.maxInt(i32)));
}

/// Keep labels adjacent while excluding STATIC rows from neighboring arrow groups.
fn formGroupStarts(index: usize, previous_text: bool, text: bool) bool {
    return index == 0 or previous_text or text;
}

/// Show or hide a child window, leaving one already in that state alone. The
/// style bit is read rather than `IsWindowVisible`, which is false for every
/// child until the window itself is shown.
fn setChildShown(control: HWND, shown: bool) void {
    const style: u32 = @truncate(@as(usize, @bitCast(sys.GetWindowLongPtrW(control, GWL_STYLE))));
    if ((style & WS_VISIBLE != 0) == shown) return;
    _ = ShowWindow(control, if (shown) SW_SHOWNORMAL else SW_HIDE);
}

test "settings wheel carries sub-pixel movement between messages" {
    var remainder: i32 = 0;
    // 30/120 of a 64 px notch is exactly 16 px each.
    try std.testing.expectEqual(@as(i32, -16), wheelScrollPixels(&remainder, -30, 64));
    // Ten units on a 3 px notch is a quarter of a pixel: a pixel every fourth
    // message, and two over eight, where each message alone rounds to zero.
    remainder = 0;
    var total: i32 = 0;
    for (0..8) |_| total += wheelScrollPixels(&remainder, 10, 3);
    try std.testing.expectEqual(@as(i32, 2), total);
    // Reversing direction drops the leftover rather than cancelling against it.
    remainder = 0;
    _ = wheelScrollPixels(&remainder, 10, 5);
    try std.testing.expect(remainder > 0);
    _ = wheelScrollPixels(&remainder, -10, 5);
    try std.testing.expect(remainder <= 0);
}

test "settings wheel notch honours lines per notch" {
    try std.testing.expectEqual(@as(i32, 64), wheelNotchPixels(64, 3));
    try std.testing.expectEqual(@as(i32, 21), wheelNotchPixels(64, 1));
    try std.testing.expectEqual(@as(i32, 0), wheelNotchPixels(64, 0));
    try std.testing.expectEqual(wheelNotchPixels(64, 100), wheelNotchPixels(64, 4000));
}

fn shouldDrawSettingsSectionFocusRing(
    selected: bool,
    focused: bool,
    mode: focus_cue.InputMode,
    high_contrast: bool,
) bool {
    _ = selected;
    return focus_cue.showRing(focused, false, mode, high_contrast);
}

test "settings section focus ring follows keyboard focus, not selection" {
    try std.testing.expect(!shouldDrawSettingsSectionFocusRing(true, false, .keyboard, false));
    try std.testing.expect(shouldDrawSettingsSectionFocusRing(false, true, .keyboard, false));
    // The section that opens with the window, or was just clicked, holds
    // focus without a ring; a navigation key reveals it.
    try std.testing.expect(!shouldDrawSettingsSectionFocusRing(true, true, .pointer, false));
    // High Contrast keeps the ring on pointer focus.
    try std.testing.expect(shouldDrawSettingsSectionFocusRing(true, true, .pointer, true));
}

/// Flip the focus cue mode from an input message that reached a section
/// button, repainting the focused control when the mode changed.
fn noteSettingsInput(settings: *SettingsWindow, msg: UINT, wParam: WPARAM) void {
    const next: focus_cue.InputMode = switch (msg) {
        WM_KEYDOWN, WM_SYSKEYDOWN => if (focus_cue.keyRevealsRing(@intCast(wParam & 0xFFFF))) .keyboard else return,
        WM_LBUTTONDOWN, WM_RBUTTONDOWN, WM_MBUTTONDOWN => .pointer,
        else => return,
    };
    if (settings.focus_input_mode == next) return;
    settings.focus_input_mode = next;
    if (GetFocus()) |focused| _ = InvalidateRect(focused, null, 0);
}

fn paintSettingsSectionButton(hwnd: HWND, settings: *SettingsWindow) void {
    var ps: PAINTSTRUCT = undefined;
    const hdc = BeginPaint(hwnd, &ps);
    defer _ = EndPaint(hwnd, &ps);
    var rect: RECT = undefined;
    if (GetClientRect(hwnd, &rect) == 0) return;
    const colors = settings.theme_adapter.colors;
    const selected = SendMessageW(hwnd, BM_GETCHECK, 0, 0) == BST_CHECKED;
    const pressed = (SendMessageW(hwnd, BM_GETSTATE, 0, 0) & BST_PUSHED) != 0;
    const hovered = settings.section_hovered == hwnd;
    const focused = shouldDrawSettingsSectionFocusRing(
        selected,
        GetFocus() == hwnd,
        settings.focus_input_mode,
        colors.high_contrast,
    );
    // A pressed button is filled like a selected one, and everything drawn
    // on it takes the colours paired with that fill.
    const on_selection = selected or pressed;
    const fill_color = if (on_selection)
        colors.selection_bg
    else if (hovered and !colors.high_contrast)
        colors.button_bg
    else
        colors.rail_bg;
    const fill_brush = CreateSolidBrush(fill_color) orelse return;
    defer _ = DeleteObject(fill_brush);
    _ = FillRect(hdc, &rect, fill_brush);

    if (selected) {
        if (colors.high_contrast) {
            const border = CreateSolidBrush(colors.selection_text) orelse return;
            defer _ = DeleteObject(border);
            _ = FrameRect(hdc, &rect, border);
        } else {
            const pill_width = @max(1, settings.px(settings_metrics.stroke_emphasis));
            const pill_height = @min(rect.bottom - rect.top, settings.px(settings_metrics.space_6));
            const pill_top = rect.top + @divTrunc(rect.bottom - rect.top - pill_height, 2);
            const accent = CreateSolidBrush(colors.accent) orelse return;
            defer _ = DeleteObject(accent);
            const pill: RECT = .{ .left = rect.left, .top = pill_top, .right = rect.left + pill_width, .bottom = pill_top + pill_height };
            _ = FillRect(hdc, &pill, accent);
        }
    }

    var label: [64:0]u16 = undefined;
    const label_len = GetWindowTextW(hwnd, &label, @intCast(label.len));
    var text_rect = rect;
    text_rect.left += settings.px(settings_pane_padding);
    const font = if (selected) settings.emphasis_font else settings.ui_font;
    const previous_font = if (font) |value| SelectObject(hdc, value) else null;
    defer {
        if (previous_font) |value| _ = SelectObject(hdc, value);
    }
    _ = SetBkMode(hdc, TRANSPARENT);
    const section = settings.sectionForButton(hwnd);
    // While a search is typed, a page it found nothing on reads quieter, and
    // one it found rows on says how many beside its marker's place.
    const found: ?u16 = if (section) |value| settings.searchCountOf(value) else null;
    const text_color = if (on_selection)
        colors.selection_text
    else if (colors.high_contrast)
        colors.edit_text
    else if (found == 0)
        colors.secondary_text
    else
        colors.text;
    _ = SetTextColor(hdc, text_color);
    // The label stops short of the marker's place, or of the count.
    if (section) |value| if (settings.section_markers[@intFromEnum(value)] != .none) {
        text_rect.right = @max(text_rect.left, sectionMarkerRect(settings, rect, .invalid).left - settings.px(settings_metrics.space_2));
    };
    if (found) |count| if (count != 0) {
        var digits: [8:0]u16 = @splat(0);
        var digits_utf8: [8]u8 = undefined;
        const text = std.fmt.bufPrint(&digits_utf8, "{d}", .{count}) catch "";
        for (text, 0..) |c, i| digits[i] = c;
        var count_rect = rect;
        count_rect.right = sectionMarkerRect(settings, rect, .invalid).left - settings.px(settings_metrics.space_2);
        var measured = count_rect;
        _ = DrawTextW(hdc, &digits, @intCast(text.len), &measured, DT_SINGLELINE | DT_NOPREFIX | DT_CALCRECT);
        _ = DrawTextW(hdc, &digits, @intCast(text.len), &count_rect, DT_SINGLELINE | DT_VCENTER | DT_RIGHT | DT_NOPREFIX);
        text_rect.right = @max(text_rect.left, count_rect.right - (measured.right - measured.left) - settings.px(settings_metrics.space_2));
    };
    if (label_len > 0) _ = DrawTextW(hdc, &label, label_len, &text_rect, DT_SINGLELINE | DT_VCENTER | DT_NOPREFIX | DT_END_ELLIPSIS);

    if (section) |value| {
        const marker = settings.section_markers[@intFromEnum(value)];
        if (marker != .none) drawSectionMarker(hdc, settings, rect, marker, fill_color, on_selection);
    }

    if (focused) {
        const ring_color = if (colors.high_contrast and on_selection) colors.selection_text else colors.focus_ring;
        const ring = CreateSolidBrush(ring_color) orelse return;
        defer _ = DeleteObject(ring);
        var focus_rect = rect;
        const inset = settings.px(settings_metrics.space_1);
        focus_rect.left += inset;
        focus_rect.top += inset;
        focus_rect.right -= inset;
        focus_rect.bottom -= inset;
        var layer: i32 = 0;
        while (layer < @max(1, settings.px(settings_metrics.stroke_focus)) and focus_rect.right > focus_rect.left and focus_rect.bottom > focus_rect.top) : (layer += 1) {
            _ = FrameRect(hdc, &focus_rect, ring);
            focus_rect.left += 1;
            focus_rect.top += 1;
            focus_rect.right -= 1;
            focus_rect.bottom -= 1;
        }
    }
}

/// Where the mark sits in a rail button of client rectangle `rect`: the disc
/// of an invalid value is larger than the dot of an unsaved change.
fn sectionMarkerRect(settings: *const SettingsWindow, rect: RECT, marker: win32_uia.SettingsSectionMarker) RECT {
    const diameter = settings.px(if (marker == .invalid) settings_metrics.space_6 else settings_metrics.space_3);
    const right = rect.right - settings.px(settings_metrics.space_4);
    const top = rect.top + @divTrunc(rect.bottom - rect.top - diameter, 2);
    return .{ .left = right - diameter, .top = top, .right = right, .bottom = top + diameter };
}

/// The color the mark is filled with. High Contrast has one text color per
/// background, so the disc and the dot differ by shape; the error color there
/// is ButtonText, which a button filled with Highlight (selected, or pressed)
/// does not carry.
fn sectionMarkerFill(colors: win32_theme.SettingsColors, marker: win32_uia.SettingsSectionMarker, on_selection: bool) COLORREF {
    if (colors.high_contrast) return if (on_selection) colors.selection_text else colors.text;
    return if (marker == .invalid) colors.error_text else colors.accent;
}

/// The mark at the right end of a rail button (`SettingsWindow.syncMarkers`).
/// A small dot means unsaved changes; an invalid value is a larger disc with
/// an exclamation mark. They differ in shape and size, not only in colour, and
/// High Contrast draws both in a text colour.
fn drawSectionMarker(
    hdc: HDC,
    settings: *SettingsWindow,
    rect: RECT,
    marker: win32_uia.SettingsSectionMarker,
    background: COLORREF,
    on_selection: bool,
) void {
    const invalid = marker == .invalid;
    const bounds = sectionMarkerRect(settings, rect, marker);
    const fill = sectionMarkerFill(settings.theme_adapter.colors, marker, on_selection);
    const brush = CreateSolidBrush(fill) orelse return;
    defer _ = DeleteObject(brush);
    const previous_brush = SelectObject(hdc, brush);
    const previous_pen = SelectObject(hdc, GetStockObject(NULL_PEN));
    defer {
        if (previous_pen) |value| _ = SelectObject(hdc, value);
        if (previous_brush) |value| _ = SelectObject(hdc, value);
    }
    // The null pen leaves the right and bottom edges out of the ellipse.
    _ = sys.Ellipse(hdc, bounds.left, bounds.top, bounds.right + 1, bounds.bottom + 1);
    if (!invalid) return;
    var glyph = bounds;
    const previous_font = if (settings.emphasis_font) |font| SelectObject(hdc, font) else null;
    defer {
        if (previous_font) |value| _ = SelectObject(hdc, value);
    }
    _ = SetTextColor(hdc, sectionMarkerGlyph(settings.theme_adapter.colors, background));
    _ = DrawTextW(hdc, std.unicode.utf8ToUtf16LeStringLiteral("!"), 1, &glyph, DT_SINGLELINE | DT_VCENTER | DT_CENTER | DT_NOPREFIX);
}

/// The colour of the invalid disc's "!", text on the error colour and so
/// held to 4.5:1. The rail button's own background was not, on a selected
/// button in the light theme (4.32:1); the pane's colour is, in both app
/// themes (5.38:1 light, 7.35:1 dark), whatever the button's state. High
/// Contrast keeps the button's background: a system pair with the disc's
/// text colour.
fn sectionMarkerGlyph(colors: win32_theme.SettingsColors, button_background: COLORREF) COLORREF {
    return if (colors.high_contrast) button_background else colors.window_bg;
}

fn settingsSectionButtonProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const owner = if (sys.GetParent(hwnd)) |parent| recoverOwner(parent) else null;
    if (owner) |settings| {
        const previous = settings.section_button_prev_proc;
        if (previous == null) return DefWindowProcW(hwnd, msg, wParam, lParam);
        if (settings.sectionForButton(hwnd)) |section| {
            if (msg == WM_GETOBJECT) {
                if (settings.sectionProvider(section)) |provider| {
                    if (win32_uia.returnSettingsSectionProvider(hwnd, wParam, lParam, provider)) |result| return result;
                }
            }
            if (msg == WM_NCDESTROY) {
                if (settings.sectionProvider(section)) |provider| provider.detach();
                if (previous) |proc| {
                    _ = sys.SetWindowLongPtrW(hwnd, GWLP_WNDPROC, @as(LONG_PTR, @intCast(@intFromPtr(proc))));
                    return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
                }
            }
        }
        switch (msg) {
            WM_SETTINGS_PROOF_KILLFOCUS_COUNT => return @intCast(settings.proof_killfocus_count),
            WM_SETTINGS_PROOF_REDRAW_SUCCEEDED => return @intFromBool(settings.proof_redraw_succeeded),
            WM_SETTINGS_PROOF_UPDATE_PENDING => return @intFromBool(settings.proof_update_pending),
            WM_SETTINGS_PROOF_LIVE_FOCUS_RING => return @intFromBool(shouldDrawSettingsSectionFocusRing(
                SendMessageW(hwnd, BM_GETCHECK, 0, 0) == BST_CHECKED,
                GetFocus() == hwnd,
                settings.focus_input_mode,
                settings.theme_adapter.colors.high_contrast,
            )),
            WM_ERASEBKGND => return 1,
            WM_PAINT => {
                paintSettingsSectionButton(hwnd, settings);
                return 0;
            },
            WM_MOUSEMOVE => {
                if (settings.section_hovered != hwnd) {
                    if (settings.section_hovered) |previous_hover| _ = InvalidateRect(previous_hover, null, 0);
                    settings.section_hovered = hwnd;
                    _ = InvalidateRect(hwnd, null, 0);
                    var tracking: TRACKMOUSEEVENT = .{
                        .cbSize = @sizeOf(TRACKMOUSEEVENT),
                        .dwFlags = TME_LEAVE,
                        .hwndTrack = hwnd,
                        .dwHoverTime = 0,
                    };
                    _ = TrackMouseEvent(&tracking);
                }
            },
            WM_MOUSELEAVE => {
                if (settings.section_hovered == hwnd) settings.section_hovered = null;
                _ = InvalidateRect(hwnd, null, 0);
            },
            BM_SETCHECK, BM_SETSTATE => {
                if (previous) |proc| {
                    const result = CallWindowProcW(proc, hwnd, msg, wParam, lParam);
                    _ = InvalidateRect(hwnd, null, 0);
                    return result;
                }
            },
            WM_SETFOCUS, WM_KILLFOCUS => {
                if (previous) |proc| {
                    const result = CallWindowProcW(proc, hwnd, msg, wParam, lParam);
                    if (msg == WM_KILLFOCUS) {
                        settings.proof_killfocus_count +%= 1;
                        settings.proof_redraw_succeeded = RedrawWindow(hwnd, null, null, RDW_INVALIDATE | RDW_UPDATENOW) != 0;
                        var update_rect: RECT = undefined;
                        settings.proof_update_pending = GetUpdateRect(hwnd, &update_rect, 0) != 0;
                    } else _ = InvalidateRect(hwnd, null, 0);
                    if (msg == WM_SETFOCUS) if (settings.sectionForButton(hwnd)) |section| {
                        if (settings.sectionProvider(section)) |provider| provider.raiseFocusChanged();
                    };
                    return result;
                }
            },
            else => {},
        }
        if (previous) |proc| {
            return CallWindowProcW(proc, hwnd, msg, wParam, lParam);
        }
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

fn wndProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    if (msg == WM_NCCREATE) {
        const cs: *const CREATESTRUCTW = @ptrFromInt(@as(usize, @bitCast(lParam)));
        if (cs.lpCreateParams) |ptr| {
            _ = sys.SetWindowLongPtrW(hwnd, GWLP_USERDATA, @intCast(@intFromPtr(ptr)));
        }
    }

    const owner = recoverOwner(hwnd);
    switch (msg) {
        WM_SETTINGS_PROOF_VIEWPORT_TOP => {
            if (owner) |o| return @intCast(o.proof_viewport_top);
            return 0;
        },
        WM_SETTINGS_PROOF_VIEWPORT_BOTTOM => {
            if (owner) |o| return @intCast(o.proof_viewport_bottom);
            return 0;
        },
        WM_SETTINGS_PROOF_SET_FOCUS => {
            if (owner != null and wParam != 0) {
                const target: HWND = @ptrFromInt(wParam);
                if (IsChild(hwnd, target) != 0) {
                    _ = SetFocus(target);
                    return @intFromBool(GetFocus() == target);
                }
            }
            return 0;
        },
        WM_SETTINGS_PROOF_PAINT_COUNT => {
            if (owner) |o| return @intCast(o.proof_paint_count);
            return 0;
        },
        WM_SETTINGS_PROOF_LAYOUT_BATCHED => {
            if (owner) |o| return @intFromBool(o.proof_layout_batched);
            return 0;
        },
        WM_SETTINGS_PROOF_SEARCH_US => {
            if (owner) |o| return @intCast(if (lParam == 0) o.proof_search_filter_us else o.proof_search_total_us);
            return 0;
        },
        WM_SETTINGS_PROOF_CHILD => {
            if (owner) |o| {
                const index: usize = @intCast(wParam);
                const child = switch (lParam) {
                    0 => if (index < settings_clipped_control_count) o.controlHwnd(index) else null,
                    1 => if (index < o.field_labels.len) o.field_labels[index] else null,
                    2 => o.text_help,
                    else => null,
                };
                if (child) |value| return @intCast(@intFromPtr(value));
            }
            return 0;
        },
        WM_GETOBJECT => {
            if (owner) |o| {
                if (o.section_uia_group) |provider| {
                    if (win32_uia.returnSettingsSectionGroupProvider(hwnd, wParam, lParam, provider)) |result| return result;
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        WM_ERASEBKGND => return 1,
        WM_PRINTCLIENT => {
            if (owner) |o| if (wParam != 0) paintBackground(hwnd, o, @ptrFromInt(wParam));
            return 0;
        },
        WM_PAINT => {
            if (owner) |o| {
                o.proof_paint_count +%= 1;
                paint(hwnd, o);
            }
            return 0;
        },
        WM_CTLCOLORMSGBOX,
        WM_CTLCOLOREDIT,
        WM_CTLCOLORLISTBOX,
        WM_CTLCOLORBTN,
        WM_CTLCOLORDLG,
        WM_CTLCOLORSTATIC,
        => {
            if (owner) |o| {
                const hdc: HDC = @ptrFromInt(wParam);
                const child: ?HWND = if (lParam == 0)
                    null
                else
                    @ptrFromInt(@as(usize, @bitCast(lParam)));
                const colors = o.theme_adapter.colors;
                const edit_like = msg == WM_CTLCOLOREDIT or msg == WM_CTLCOLORLISTBOX;
                const background = if (edit_like) colors.edit_bg else if (msg == WM_CTLCOLORBTN)
                    colors.button_bg
                else
                    colors.window_bg;
                const foreground = if (child) |control|
                    if (sys.IsWindowEnabled(control) == 0)
                        colors.disabled_text
                    else if (edit_like)
                        colors.edit_text
                    else if (control == o.text_status and o.close_prompt_visible)
                        colors.text
                    else if (control == o.text_status)
                        switch (o.nextStatus()) {
                            .raw_validation, .owned_validation => colors.error_text,
                            .conflict, .owned_conflict => colors.text,
                            .none => colors.secondary_text,
                        }
                    else if (msg == WM_CTLCOLORBTN)
                        if (o.controlIndex(control)) |index|
                            if (controlIndexIsCheckbox(index)) colors.secondary_text else colors.button_text
                        else
                            colors.button_text
                    else if (control == o.text_summary or (o.textIndex(control) orelse 0) >= text_first_label_index)
                        colors.secondary_text
                    else
                        colors.text
                else
                    colors.text;
                _ = sys.SetTextColor(hdc, foreground);
                _ = sys.SetBkColor(hdc, background);
                if (msg == WM_CTLCOLORSTATIC) _ = sys.SetBkMode(hdc, TRANSPARENT);
                if (o.theme_adapter.controlBrush(msg)) |brush| {
                    return pointerLresult(brush);
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        WM_DPICHANGED => {
            if (owner) |o| {
                o.dpi = normalizedDpi(@intCast(wParam & 0xFFFF));
                // Fonts first: the resize below lays out and paints at once,
                // and must not paint the new size with the old fonts.
                o.recreateUiFont();
                const suggested: *const RECT = @ptrFromInt(@as(usize, @bitCast(lParam)));
                _ = sys.SetWindowPos(
                    hwnd,
                    null,
                    suggested.left,
                    suggested.top,
                    suggested.right - suggested.left,
                    suggested.bottom - suggested.top,
                    SWP_NOZORDER | SWP_NOACTIVATE,
                );
                layoutChildren(o);
                _ = sys.InvalidateRect(hwnd, null, 1);
            }
            return 0;
        },
        WM_SETTINGCHANGE, WM_SYSCOLORCHANGE, WM_THEMECHANGED => {
            if (owner) |o| o.themeChanged();
            return 0;
        },
        WM_GETMINMAXINFO => {
            if (owner) |o| {
                const info: *MINMAXINFO = @ptrFromInt(@as(usize, @bitCast(lParam)));
                var min_width = o.px(720);
                var min_height = o.px(520);
                var work_area: RECT = undefined;
                if (windowWorkArea(hwnd, &work_area)) {
                    min_width = cappedMinimum(720, o.dpi, work_area.right - work_area.left);
                    min_height = cappedMinimum(520, o.dpi, work_area.bottom - work_area.top);
                }
                info.ptMinTrackSize.x = min_width;
                info.ptMinTrackSize.y = min_height;
            }
            return 0;
        },
        WM_SIZE => {
            if (owner) |o| {
                layoutChildren(o);
                // Each step of a live resize is painted before the next one
                // arrives, rather than whenever the size loop gets to it.
                _ = RedrawWindow(hwnd, null, null, RDW_UPDATENOW | RDW_ALLCHILDREN);
            }
            return 0;
        },
        WM_MENUCHAR => {
            // An Alt chord typed into a settings control reaches the
            // control's DefWindowProc as WM_SYSCHAR, becomes SC_KEYMENU, and
            // the menu loop for it runs on this window: no menu bar, no
            // mnemonic to match, and the default reply is the shell's beep
            // (#250, same shape as the host window). Close the phantom loop
            // silently; the window menu after Alt+Space carries MF_POPUP and
            // keeps the default.
            const menu_flags: u32 = @intCast((wParam >> 16) & 0xFFFF);
            if (win32_input.menuCharClosesPhantomMenu(menu_flags)) {
                return @as(LRESULT, MNC_CLOSE) << 16;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        WM_MOUSEWHEEL => {
            if (owner) |o| {
                const delta: i16 = @bitCast(@as(u16, @truncate(wParam >> 16)));
                o.scrollByWheel(delta);
            }
            return 0;
        },
        WM_ACTIVATE => {
            // Deactivation (Alt+Tab away, minimize): remember the focused
            // child. Activation needs nothing here: DefWindowProc focuses the
            // frame, and WM_SETFOCUS below hands that on.
            if (owner) |o| if ((wParam & 0xFFFF) == WA_INACTIVE) o.rememberFocus();
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        WM_SETFOCUS => {
            // Focus landed on the frame itself (activation, restore from
            // minimized): forward it to the field the user was typing in.
            if (owner) |o| {
                o.forwardFrameFocus();
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        WM_COMMAND => {
            const id: usize = wParam & 0xFFFF;
            const notify: u16 = @intCast((wParam >> 16) & 0xFFFF);
            if (notify == 8 and lParam != 0) { // CBN_CLOSEUP
                if (owner) |o| if (o.profile_rows_stale and o.fields.combo_default_profile == @as(?HWND, @ptrFromInt(@as(usize, @bitCast(lParam))))) {
                    o.profile_rows_stale = false;
                    _ = sys.PostMessageW(hwnd, WM_SETTINGS_PROFILES_CHANGED, 0, 0);
                };
                if (owner) |o| if (o.combo_trace.enabled()) {
                    const control: HWND = @ptrFromInt(@as(usize, @bitCast(lParam)));
                    if (o.controlIndex(control)) |index| {
                        if (settings_control_specs[index].role == .combo_box)
                            o.combo_trace.noteEvent(.closeup, sys.GetDlgCtrlID(control), sys.SendMessageW(control, CB_GETDROPPEDSTATE, 0, 0) != 0);
                    }
                };
            }
            // Popup mouse input is delivered to its list HWND. Native combo
            // notifications are the reliable point to announce the resulting
            // expansion / selection state, after draft handlers have run.
            defer if (lParam != 0) {
                if (owner) |o| {
                    if (o.controlIndex(@ptrFromInt(@as(usize, @bitCast(lParam))))) |index| {
                        if (o.control_uia_providers[index]) |provider| provider.syncNativeState(if (notify == CBN_SELCHANGE) .native_notification else .observe);
                    }
                }
            };
            // IsDialogMessageW maps Escape to IDCANCEL as a synthetic
            // command with no originating control HWND. Only a click counts:
            // the button's BN_SETFOCUS notification must not cancel, or the
            // conservative default focus immediately dismisses the prompt.
            // The prompt's "Keep editing" button shares the ID, so a click
            // arrives here too; with no prompt open it is a close request.
            if (id == IDCANCEL and notify == BN_CLICKED) {
                if (owner) |o| o.cancelRequested(hwnd);
                return 0;
            }
            if (id == EDIT_SEARCH and notify == EN_CHANGE) {
                if (owner) |o| o.searchTextChanged();
                return 0;
            }
            if (lParam != 0 and (notify == EN_SETFOCUS or notify == CBN_SETFOCUS or notify == BN_SETFOCUS)) {
                if (owner) |o| if (!o.restoring_focus) o.ensureControlVisible(@ptrFromInt(@as(usize, @bitCast(lParam))));
            }
            if (notify == BN_CLICKED and id >= BTN_RESET_FIRST and id < BTN_RESET_FIRST + form_field_count) {
                if (owner) |o| o.resetButtonClicked(id - BTN_RESET_FIRST, lParam);
                return 0;
            }
            if (clickedButton(id, notify, BTN_OPEN_EDITOR) or clickedButton(id, notify, BTN_KEYBINDINGS_EDITOR)) {
                if (owner) |o| o.handle.openInEditor(o.handle.ctx);
                return 0;
            }
            if (clickedButton(id, notify, BTN_SAVE)) {
                if (owner) |o| o.saveIfAllowed();
                return 0;
            }
            // The action bar's Discard asks first; a click of it that arrives
            // once the prompt is up (queued before it opened) asks nothing more.
            if (clickedButton(id, notify, BTN_DISCARD_CHANGES)) {
                if (owner) |o| if (!o.close_prompt_visible) o.discardChanges();
                return 0;
            }
            if (clickedButton(id, notify, BTN_CLOSE_DISCARD)) {
                if (owner) |o| o.discardAndClose();
                return 0;
            }
            if (clickedButton(id, notify, BTN_CLOSE_SAVE)) {
                if (owner) |o| o.saveAndClose();
                return 0;
            }
            if (id == BTN_CONFLICT_KEEP and notify == BN_CLICKED) {
                if (owner) |o| {
                    if (o.active_conflict_field) |field| {
                        o.resolveConflict(field, .keep_mine);
                    } else if (o.active_owned_conflict_field) |field| {
                        o.resolveOwnedConflict(field, .keep_mine);
                    }
                }
                return 0;
            }
            if (id == BTN_CONFLICT_USE_DISK and notify == BN_CLICKED) {
                if (owner) |o| {
                    if (o.active_conflict_field) |field| {
                        o.resolveConflict(field, .use_disk);
                    } else if (o.active_owned_conflict_field) |field| {
                        o.resolveOwnedConflict(field, .use_disk);
                    }
                }
                return 0;
            }
            // A scalar departure is posted because EN_KILLFOCUS does not say
            // where focus went. Owned fields keep their existing deferred parse.
            if (notify == EN_KILLFOCUS) if (rawScalarForEditId(id)) |field| {
                if (owner != null) _ = sys.PostMessageW(hwnd, WM_SETTINGS_FIELD_LEFT, @intFromEnum(field), 0);
                return 0;
            };
            inline for (field_model.form_fields) |row| if (id == row.native.id) {
                const adapter = comptime @field(field_adapters, row.native.binding);
                const changed = switch (comptime row.kind()) {
                    .choice, .profile => CBN_SELCHANGE,
                    .boolean, .blur => BN_CLICKED,
                    else => EN_CHANGE,
                };
                if (notify == changed) {
                    if (owner) |o| adapter.changed(o);
                    return 0;
                }
                if (notify == EN_KILLFOCUS) if (adapter.left) |left| {
                    if (owner) |o| left(o);
                    return 0;
                };
            };
            if (clickedSection(id, notify)) |section| {
                if (owner) |o| {
                    const source: ?HWND = if (lParam == 0)
                        null
                    else
                        @ptrFromInt(@as(usize, @bitCast(lParam)));
                    if (validatedSectionClickFocusTarget(
                        source,
                        o.sectionButton(section),
                    )) |button| {
                        _ = SetFocus(button);
                    }
                    o.setActiveSection(section);
                }
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        WM_CLOSE => {
            if (owner) |o| o.requestClose(hwnd);
            return 0;
        },
        WM_QUERYENDSESSION => {
            if (owner) |o| if (o.handle.queryEndSession) |query| return @intFromBool(query(o.handle.ctx, lParam));
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        WM_ENDSESSION => {
            if (owner) |o| if (o.handle.endSession) |end| end(o.handle.ctx, wParam != 0, lParam);
            return 0;
        },
        WM_TIMER => {
            switch (wParam) {
                validation_timer_id => if (owner) |o| o.validationQuietElapsed(),
                search_announce_timer_id => if (owner) |o| o.searchAnnounceElapsed(),
                else => return sys.DefWindowProcW(hwnd, msg, wParam, lParam),
            }
            return 0;
        },
        WM_SETTINGS_FIELD_LEFT => {
            if (owner) |o| if (wParam < raw_scalar_field_count) o.fieldLeft(@enumFromInt(wParam));
            return 0;
        },
        WM_SETTINGS_PROFILES_CHANGED => {
            if (owner) |o| o.profilesChanged();
            return 0;
        },
        WM_SETTINGS_CLOSE_NOW => {
            if (owner) |o| {
                if (o.close_posted) o.closeNow(hwnd);
            }
            return 0;
        },
        WM_NCDESTROY => {
            // Clear back-pointer; the settings wndproc will no longer
            // dereference a freed owner even if a late paint slips
            // through. `onClosed` fires from closeNow in the
            // user-initiated close path; avoid firing here so
            // `App.deinit → settings_window.deinit` (which destroys
            // the HWND without the user closing it) doesn't re-enter
            // the quit-timer path during teardown.
            if (owner) |o| o.clearChildRefs();
            _ = sys.SetWindowLongPtrW(hwnd, GWLP_USERDATA, 0);
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        else => return sys.DefWindowProcW(hwnd, msg, wParam, lParam),
    }
}

/// The raw scalar field behind a text field's control id.
fn rawScalarForEditId(id: usize) ?RawScalarField {
    return switch (id) {
        EDIT_SCROLLBACK => .scrollback_limit,
        EDIT_FONT_SIZE => .font_size,
        EDIT_BG_OPACITY => .background_opacity,
        EDIT_PAD_X => .window_padding_x,
        EDIT_PAD_Y => .window_padding_y,
        else => null,
    };
}

fn recoverOwner(hwnd: HWND) ?*SettingsWindow {
    const raw = sys.GetWindowLongPtrW(hwnd, GWLP_USERDATA);
    if (raw == 0) return null;
    return @ptrFromInt(@as(usize, @intCast(raw)));
}

/// Control ids of the All settings list and the Keybindings page's list
/// (`ReferenceList`, one class for both).
const REFERENCE_LIST: usize = 310;
const KEYBIND_LIST: usize = 311;
const PROFILE_LIST: usize = 312;
/// The Profiles page's field being typed into (`ProfileEdit`), a child of its
/// list.
const PROFILE_EDIT: usize = 313;
const reference_list_class_name = std.unicode.utf8ToUtf16LeStringLiteral("noctty.win32.settings.list");
/// The commands of a list's context menu.
const reference_menu_copy: usize = 1;
const reference_menu_open: usize = 2;
const reference_menu_edit: usize = 3;
/// What each list's UIA help text says: the keys it takes.
const reference_list_help = "Up and Down move through the settings; the selected one shows its whole description and where the config file sets it. " ++
    "Enter opens the config file, Ctrl+C copies the setting's name, F2 edits a setting that has a control in Settings, and Shift+F10 offers these.";
const keybind_list_help = "Up and Down move through the key bindings in effect; the selected one shows what its action does. " ++
    "Enter opens the config file, where bindings are changed, Ctrl+C copies the binding as config lines, and Shift+F10 offers both.";
const reference_open_label = "Open config file (Enter)";
/// What the open row of a key with no Settings control says.
const reference_read_only_note = "Settings has no control for this setting: change it in the config file.";
/// Where an open binding comes from.
const keybind_default_note = "One of noctty's default bindings.";
const keybind_set_note = "Not one of the default bindings: the config file sets it.";

/// Which list a `ReferenceList` is: the All settings page's keys, the
/// Keybindings page's bindings, or the Profiles page's profiles and fields.
const ListKind = enum {
    reference,
    keybindings,
    profiles,

    fn copyLabel(self: ListKind) []const u8 {
        return switch (self) {
            .reference => "Copy name (Ctrl+C)",
            .keybindings => "Copy binding (Ctrl+C)",
            // The Profiles list has no Copy (`ensureMetrics`).
            .profiles => "",
        };
    }
};
/// The Profiles page's menu item that starts a profile.
const profile_menu_new: usize = 5;
/// What the Profiles list's UIA help text says: the keys it takes.
const profile_list_help = "Up and Down move through your profiles and their fields: command line, name, starting folder and variables. " ++
    "Enter edits the selected field, Delete removes it (a profile asks twice), Insert or Ctrl+N adds a profile, and Shift+F10 offers these.";
/// The help text of the field being typed into.
const profile_edit_help = "Enter keeps the change and Escape cancels it. Save writes your changes to the config file.";

/// The field of the Profiles page being typed into: one stock EDIT, made when
/// typing starts and destroyed when it ends, a child of the list, over the
/// open row (`SettingsWindow.beginProfileEdit`). It is the one window the page
/// adds while it is shown.
const ProfileEdit = struct {
    pub const Kind = enum {
        /// A new profile's id, then (`new_command`) its command line.
        new_id,
        new_command,
        command,
        name,
        folder,
        /// A variable's value.
        variable,
        /// A new variable, as `NAME=VALUE`.
        new_variable,
    };

    hwnd: ?HWND = null,
    kind: Kind,
    /// The row typed into (`settings_profiles.Row.identity`).
    row: u64,
    id_buf: [profile_map.max_id_len]u8 = undefined,
    id_len: usize = 0,
    /// `.variable`: its name (the window's allocator's).
    name: ?[]u8 = null,
    /// Its UIA name (`writeLabel`), which its provider holds a view of.
    label_buf: [160]u8 = undefined,
    label_len: usize = 0,
    provider: ?*win32_uia.SettingsControlProvider = null,
    /// Its text changed since it opened: an edit to save, which Save keeps
    /// first (`commitProfileEdit`), so Save is enabled for it.
    typed: bool = false,

    fn setId(self: *ProfileEdit, id_text: []const u8) void {
        const len = @min(id_text.len, self.id_buf.len);
        @memcpy(self.id_buf[0..len], id_text[0..len]);
        self.id_len = len;
    }

    fn id(self: *const ProfileEdit) []const u8 {
        return self.id_buf[0..self.id_len];
    }

    /// Its UIA name: the field and whose it is, never its value.
    fn writeLabel(self: *ProfileEdit) void {
        var writer: std.Io.Writer = .fixed(&self.label_buf);
        switch (self.kind) {
            .new_id => writer.writeAll("Id of the new profile") catch {},
            .new_command, .command => writer.print("Command line of {s}", .{self.id()}) catch {},
            .name => writer.print("Name of {s}", .{self.id()}) catch {},
            .folder => writer.print("Starting folder of {s}", .{self.id()}) catch {},
            .variable => writer.print("Value of {s} of {s}", .{ self.name orelse "", self.id() }) catch {},
            .new_variable => writer.print("New variable of {s}, as NAME=VALUE", .{self.id()}) catch {},
        }
        self.label_len = utf8Prefix(writer.buffered()).len;
    }

    fn label(self: *const ProfileEdit) []const u8 {
        return self.label_buf[0..self.label_len];
    }
};

/// A Profiles page action's label ("Edit (Enter)") as a menu item
/// ("&Edit\tEnter"), in `buf`.
fn profileMenuLabel(buf: []u8, action: []const u8) []const u8 {
    if (std.mem.startsWith(u8, action, "Remove")) return "&Remove profile\tDelete";
    const open = std.mem.lastIndexOf(u8, action, " (") orelse return action;
    if (!std.mem.endsWith(u8, action, ")")) return action;
    return std.fmt.bufPrint(buf, "&{s}\t{s}", .{ action[0..open], action[open + 2 .. action.len - 1] }) catch action;
}

/// The settings window a list window (`referenceListProc`) belongs to.
fn listOwner(list: HWND) ?*SettingsWindow {
    const raw = sys.GetWindowLongPtrW(list, GWLP_USERDATA);
    if (raw == 0) return null;
    const state: *ReferenceList = @ptrFromInt(@as(usize, @intCast(raw)));
    return state.owner();
}

/// The Profiles page's field (`ProfileEdit`). Tab keeps what it holds, as
/// Enter does (`handleAccelerator` takes Enter and Escape before the dialog
/// manager); the focus leaving it keeps it too, once the focus has landed
/// (`WM_SETTINGS_PROFILE_BLUR`); UIA finds its provider here. The previous
/// procedure lives in `GWLP_USERDATA` (`subclassKeepingPrevious`).
fn profileEditProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const previous = sys.GetWindowLongPtrW(hwnd, GWLP_USERDATA);
    if (previous == 0) return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
    const proc: *const anyopaque = @ptrFromInt(@as(usize, @intCast(previous)));
    const list_hwnd = sys.GetParent(hwnd);
    const settings: ?*SettingsWindow = if (list_hwnd) |list| listOwner(list) else null;
    const provider: ?*win32_uia.SettingsControlProvider = if (settings) |owner|
        (if (owner.profile_edit) |edit| (if (edit.hwnd == hwnd) edit.provider else null) else null)
    else
        null;
    switch (msg) {
        WM_GETDLGCODE => return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam) | DLGC_WANTTAB,
        WM_KEYDOWN => if (wParam == VK_TAB) {
            if (settings) |owner| _ = owner.commitProfileEdit(.stay);
            return 0;
        },
        // What Tab, Enter and Escape would type: they are keys here.
        WM_CHAR => if (wParam == '\t' or wParam == '\r' or wParam == 0x1B) return 0,
        WM_KILLFOCUS => if (list_hwnd) |list| {
            _ = sys.PostMessageW(list, WM_SETTINGS_PROFILE_BLUR, 0, 0);
        },
        WM_SETFOCUS => {
            const result = sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
            if (provider) |field| field.raiseFocusChanged();
            return result;
        },
        WM_GETOBJECT => if (provider) |field| {
            if (win32_uia.returnSettingsControlProvider(hwnd, wParam, lParam, field)) |result| return result;
        },
        WM_NCDESTROY => {
            if (settings) |owner| owner.profileEditDestroyed(hwnd);
            _ = sys.SetWindowLongPtrW(hwnd, GWLP_WNDPROC, previous);
            _ = sys.SetWindowLongPtrW(hwnd, GWLP_USERDATA, 0);
            return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
        },
        else => {},
    }
    return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
}
const CS_DBLCLKS: u32 = 0x0008;
const WM_LBUTTONDBLCLK: UINT = 0x0203;
const SIF_DISABLENOSCROLL: u32 = 0x0008;

/// The "All settings" page's list, and the Keybindings page's: one
/// owner-drawn window each, made when its page is shown and destroyed when it
/// goes, so a list costs one window, and only while it is on screen. The rows
/// are a model's, filtered by the search: on All settings every config key
/// (`SettingsWindow.reference_model`), a row showing the key, its value in
/// effect and the first sentence of what it does, or what Windows does with
/// it; on Keybindings every binding in effect (`SettingsWindow.keybind_model`),
/// its keys, its action and what that does. The selected row opens to the
/// whole description, where it comes from, and its actions. UIA sees a List of
/// ListItems (`win32_uia.PaletteListProvider`), the focus on the selected one.
/// The colour of an open list row's actions (Edit, Copy, Open): text on the
/// pane, so 4.5:1, which the accent is not in the light theme. In High
/// Contrast it is the pane's text colour (Highlight is a background colour).
fn referenceActionColor(colors: win32_theme.SettingsColors) COLORREF {
    return colors.action_text;
}

const ReferenceList = struct {
    kind: ListKind,
    hwnd: ?HWND = null,
    provider: ?*win32_uia.PaletteListProvider = null,
    /// The rows shown, as row ids (on All settings a key's index in
    /// `settings_reference.keys`, on Keybindings an index into the model's
    /// rows), and how many. The buffer has room for every row of the model,
    /// and is the window's allocator's (`forgetRows`).
    shown: []u16 = &.{},
    shown_count: usize = 0,
    /// The selected row's id, kept while a search hides it.
    selected: ?u16 = null,
    scroll_y: i32 = 0,
    /// Wheel movement not yet turned into whole pixels (`wheelScrollPixels`).
    wheel_remainder: i32 = 0,
    metrics: ?Metrics = null,
    /// The open row's text as it is drawn: what Windows does with the key and
    /// its description, and where it is set (UTF-16, owned by the window's
    /// allocator), for `open_key` from model build `open_generation`.
    open_body: ?[:0]u16 = null,
    open_location: ?[:0]u16 = null,
    open_key: ?u16 = null,
    open_generation: u64 = 0,
    /// Set while a click gives the list the focus: the row clicked is
    /// selected, not the one focusing would pick (`focused`).
    clicking: bool = false,
    /// What the last left-button press was on, for the double click that
    /// may follow it (`press`).
    pressed: Hit = .none,

    /// Row geometry in pixels, measured for what it records.
    const Metrics = struct {
        dpi: u32,
        width: i32,
        font_builds: u32,
        generation: u64,
        open_key: ?u16,
        pad_x: i32,
        pad_y: i32,
        gap: i32,
        bar: i32,
        /// One line of the key's font, and of the smaller one.
        title: i32,
        line: i32,
        /// A closed row, and the open one.
        row: i32,
        open: i32,
        /// The open row's description and location.
        body: i32,
        location: i32,
        /// The actions' widths (zero for one the row does not have), and the
        /// room between them.
        copy_width: i32,
        open_width: i32,
        edit_width: i32,
        action_gap: i32,
        /// The Profiles page: whether a field is being typed into, and the
        /// room its text field takes under the open row's title (zero
        /// otherwise).
        editing: bool = false,
        field: i32 = 0,
    };

    fn owner(self: *ReferenceList) *SettingsWindow {
        return switch (self.kind) {
            .reference => @fieldParentPtr("reference_list", self),
            .keybindings => @fieldParentPtr("keybind_list", self),
            .profiles => @fieldParentPtr("profile_list", self),
        };
    }

    fn ownerConst(self: *const ReferenceList) *const SettingsWindow {
        return switch (self.kind) {
            .reference => @fieldParentPtr("reference_list", self),
            .keybindings => @fieldParentPtr("keybind_list", self),
            .profiles => @fieldParentPtr("profile_list", self),
        };
    }

    /// How far right of the others row `id` starts: a profile's fields sit
    /// under it.
    fn indentOf(self: *const ReferenceList, metrics: Metrics, id: u16) i32 {
        if (self.kind != .profiles) return 0;
        const model = &self.ownerConst().profile_model;
        if (id >= model.rows.len or !model.rows[id].kind.isField()) return 0;
        return metrics.pad_x;
    }

    fn forgetOpenText(self: *ReferenceList, alloc: std.mem.Allocator) void {
        if (self.open_body) |text| alloc.free(text);
        if (self.open_location) |text| alloc.free(text);
        self.open_body = null;
        self.open_location = null;
        self.open_key = null;
        self.metrics = null;
    }

    /// Let go of the rows shown and the buffer that holds them.
    fn forgetRows(self: *ReferenceList, alloc: std.mem.Allocator) void {
        alloc.free(self.shown);
        self.shown = &.{};
        self.shown_count = 0;
        self.scroll_y = 0;
        self.metrics = null;
    }

    /// The row id shown at `position`, when there is one and the model has it:
    /// UIA asks by position, and a stale position (the rows changed under a
    /// client) or an id past the model (a model rebuilt before the rows were
    /// shown again) answers nothing rather than reading past either.
    fn shownId(self: *const ReferenceList, position: usize) ?u16 {
        if (position >= self.shown_count or !self.modelBuilt()) return null;
        const id = self.shown[position];
        const rows: usize = switch (self.kind) {
            .reference => settings_reference.key_count,
            .keybindings => self.ownerConst().keybind_model.rows.len,
            .profiles => self.ownerConst().profile_model.rows.len,
        };
        return if (id < rows) id else null;
    }

    /// Whether the list's model is built.
    fn modelBuilt(self: *const ReferenceList) bool {
        const settings = self.ownerConst();
        return switch (self.kind) {
            .reference => settings.reference_model.built(),
            .keybindings => settings.keybind_model.built(),
            .profiles => settings.profile_model.built(),
        };
    }

    /// Counts the builds of the list's model.
    fn generation(self: *const ReferenceList) u64 {
        const settings = self.ownerConst();
        return switch (self.kind) {
            .reference => settings.reference_generation,
            .keybindings => settings.keybind_generation,
            .profiles => settings.profile_generation,
        };
    }

    /// The field that edits the row's key from its page, when it has one: the
    /// first of the key's Settings controls (only All settings has any). A
    /// setting Windows does not support has a control, disabled, and no Edit.
    fn editField(self: *const ReferenceList, id: u16) ?SettingField {
        if (self.kind != .reference) return null;
        const rows = reference_form_rows[id];
        if (rows.len == 0) return null;
        const row = field_model.form_fields[rows[0]];
        if (row.descriptor.support == .unsupported_on_windows) return null;
        return row.field;
    }

    /// The row's first line: the key's name and its value in effect, or the
    /// binding's keys and its action.
    fn writeTitle(self: *const ReferenceList, id: u16, name: *std.Io.Writer, value: *std.Io.Writer) void {
        const settings = self.ownerConst();
        switch (self.kind) {
            .reference => {
                name.writeAll(@tagName(settings_reference.keys[id])) catch {};
                settings_reference.writeValue(value, &settings.reference_model.rows[id]) catch {};
                if (settings.referenceKeyDirty(id)) value.writeAll(" (changed here, not saved yet)") catch {};
            },
            .keybindings => {
                const row = &settings.keybind_model.rows[id];
                name.writeAll(row.trigger) catch {};
                value.writeAll(row.action) catch {};
            },
            .profiles => {
                const model = &settings.profile_model;
                name.writeAll(model.title(model.rows[id])) catch {};
                model.writeValue(model.rows[id], value) catch {};
            },
        }
    }

    /// The row's second line: what Windows does with the key or how its
    /// description starts, or how the action's does.
    fn summaryLine(self: *const ReferenceList, id: u16) []const u8 {
        const settings = self.ownerConst();
        return switch (self.kind) {
            .reference => settings_reference.notes[id] orelse settings.reference_model.rows[id].summary,
            .keybindings => settings.keybind_model.rows[id].summary,
            .profiles => settings.profile_model.summary(settings.profile_model.rows[id]),
        };
    }

    /// Whether the row has no value to show (drawn in the secondary colour).
    fn emptyValue(self: *const ReferenceList, id: u16) bool {
        if (self.kind == .profiles) {
            const model = &self.ownerConst().profile_model;
            return model.emptyValue(model.rows[id]);
        }
        if (self.kind != .reference) return false;
        const row = &self.ownerConst().reference_model.rows[id];
        return row.value.len == 0 and row.more == 0;
    }

    /// The open row's text: its description, and where it comes from (or,
    /// for a key Settings has no control for, that it is changed in the config
    /// file), in `body` and `location`.
    fn writeOpenText(self: *ReferenceList, id: u16, body: *std.Io.Writer, location: *std.Io.Writer) !void {
        const settings = self.owner();
        switch (self.kind) {
            .reference => {
                const row = &settings.reference_model.rows[id];
                if (settings_reference.notes[id]) |note| try body.print("{s}\n\n", .{note});
                try body.writeAll(row.doc);
                try settings.reference_model.writeLocation(location, row);
                // One with a disabled control says why in its Windows note.
                if (reference_form_rows[id].len == 0) {
                    if (location.end != 0) try location.writeAll("\n");
                    try location.writeAll(reference_read_only_note);
                }
            },
            .keybindings => {
                const row = &settings.keybind_model.rows[id];
                try body.writeAll(row.doc);
                // Without the defaults to compare with, where it comes from is
                // not known.
                if (settings.keybind_model.compared) try location.writeAll(if (row.differs) keybind_set_note else keybind_default_note);
            },
            .profiles => {
                const row = settings.profile_model.rows[id];
                try settings.profile_model.writeHelp(row, body);
                try settings.writeProfileOrigin(row, location);
            },
        }
    }

    /// Where the selected key is among the rows shown, if it is shown.
    fn selectedPosition(self: *const ReferenceList) ?usize {
        const key = self.selected orelse return null;
        for (self.shown[0..self.shown_count], 0..) |shown, position| if (shown == key) return position;
        return null;
    }

    /// The rows changed (a search, a rebuilt model, the page made): measure
    /// again, keep the scroll in range and repaint.
    fn contentChanged(self: *ReferenceList) void {
        self.metrics = null;
        self.syncScroll();
        if (self.hwnd) |hwnd| _ = InvalidateRect(hwnd, null, 0);
        if (self.kind == .profiles) self.owner().placeProfileEdit();
    }

    fn clientHeight(self: *const ReferenceList) i32 {
        const hwnd = self.hwnd orelse return 0;
        var client: RECT = undefined;
        if (GetClientRect(hwnd, &client) == 0) return 0;
        return client.bottom;
    }

    /// The row geometry for the list as it is now, measured again when the
    /// DPI, the fonts, the width, the model or the open row changed.
    fn ensureMetrics(self: *ReferenceList) ?Metrics {
        const hwnd = self.hwnd orelse return null;
        const settings = self.owner();
        var client: RECT = undefined;
        if (GetClientRect(hwnd, &client) == 0) return null;
        const position = self.selectedPosition();
        const open_key: ?u16 = if (position != null) self.selected else null;
        const editing = self.kind == .profiles and settings.profile_edit != null;
        if (self.metrics) |metrics| {
            if (metrics.dpi == settings.dpi and metrics.width == client.right and metrics.font_builds == settings.font_builds and
                metrics.generation == self.generation() and metrics.open_key == open_key and metrics.editing == editing) return metrics;
        }
        var metrics: Metrics = .{
            .dpi = settings.dpi,
            .width = client.right,
            .font_builds = settings.font_builds,
            .generation = self.generation(),
            .open_key = open_key,
            .pad_x = settings.px(settings_metrics.space_5),
            .pad_y = settings.px(settings_metrics.space_4),
            .gap = settings.px(settings_metrics.space_2),
            .bar = @max(1, settings.px(settings_metrics.stroke_emphasis)),
            .title = @max(1, fontLineHeight(hwnd, settings.emphasis_font)),
            .line = @max(1, fontLineHeight(hwnd, settings.secondary_font)),
            .row = 0,
            .open = 0,
            .body = 0,
            .location = 0,
            .copy_width = 0,
            .open_width = 0,
            .edit_width = 0,
            .action_gap = settings.px(settings_metrics.space_8),
            .editing = editing,
        };
        metrics.row = 2 * metrics.pad_y + metrics.title + metrics.gap + metrics.line;
        metrics.open = metrics.row;
        if (open_key) |key| {
            self.ensureOpenText(key);
            const width = @max(1, textWidth(metrics) - self.indentOf(metrics, key));
            if (self.open_body) |text| metrics.body = measureWrapped(hwnd, settings.ui_font, text, width);
            if (self.open_location) |text| metrics.location = measureWrapped(hwnd, settings.secondary_font, text, width);
            var label_w: [64]u16 = undefined;
            if (self.kind == .profiles) {
                // Its actions: what Enter and Delete do, and no Copy or Open.
                const actions = settings.profileActions(settings.profile_model.rows[key]);
                if (actions.enter) |label| metrics.edit_width = measureLine(hwnd, settings.secondary_font, utf8ToW(&label_w, label));
                if (actions.delete) |label| metrics.copy_width = measureLine(hwnd, settings.secondary_font, utf8ToW(&label_w, label));
                if (editing) metrics.field = settings.px(settings_control_height) + metrics.gap;
            } else {
                if (self.editLabel(key, &label_w)) |label| metrics.edit_width = measureLine(hwnd, settings.secondary_font, label);
                if (settings.handle.copyText != null) metrics.copy_width = measureLine(hwnd, settings.secondary_font, utf8ToW(&label_w, self.kind.copyLabel()));
                metrics.open_width = measureLine(hwnd, settings.secondary_font, std.unicode.utf8ToUtf16LeStringLiteral(reference_open_label));
            }
            metrics.open = 2 * metrics.pad_y + metrics.title + metrics.gap + metrics.field + metrics.body +
                (if (metrics.location > 0) metrics.gap + metrics.location else 0) +
                metrics.gap + metrics.line + metrics.pad_y;
        }
        self.metrics = metrics;
        return metrics;
    }

    /// The width text wraps to in a row: inside its padding, right of the bar
    /// that marks the open row.
    fn textWidth(metrics: Metrics) i32 {
        return @max(1, metrics.width - 2 * metrics.pad_x - metrics.bar);
    }

    /// The open row's text for row `key` (`writeOpenText`), as it is drawn.
    fn ensureOpenText(self: *ReferenceList, key: u16) void {
        const settings = self.owner();
        if (self.open_key == key and self.open_generation == self.generation()) return;
        const alloc = settings.handle.alloc;
        if (self.open_body) |text| alloc.free(text);
        if (self.open_location) |text| alloc.free(text);
        self.open_body = null;
        self.open_location = null;
        self.open_key = key;
        self.open_generation = self.generation();
        if (!self.modelBuilt()) return;
        var body: std.Io.Writer.Allocating = .init(alloc);
        defer body.deinit();
        var location: std.Io.Writer.Allocating = .init(alloc);
        defer location.deinit();
        self.writeOpenText(key, &body.writer, &location.writer) catch return;
        self.open_body = std.unicode.utf8ToUtf16LeAllocZ(alloc, body.written()) catch null;
        if (location.written().len != 0) self.open_location = std.unicode.utf8ToUtf16LeAllocZ(alloc, location.written()) catch null;
    }

    /// "Edit on <page> (F2)" for a row whose key has a Settings control, in
    /// `buf`.
    fn editLabel(self: *const ReferenceList, id: u16, buf: []u16) ?[*:0]const u16 {
        const field = self.editField(id) orelse return null;
        var text: [64]u8 = undefined;
        const label = std.fmt.bufPrint(&text, "Edit on {s} (F2)", .{self.ownerConst().settingDestination(field).section.headerText()}) catch return null;
        return utf8ToW(buf, label);
    }

    fn rowHeight(metrics: Metrics, selected_position: ?usize, position: usize) i32 {
        const open = if (selected_position) |selected| selected == position else false;
        return if (open) metrics.open else metrics.row;
    }

    /// Where row `position` starts, from the top of the list's content.
    fn rowTop(metrics: Metrics, selected_position: ?usize, position: usize) i32 {
        var top: i32 = @as(i32, @intCast(position)) * metrics.row;
        if (selected_position) |selected| if (selected < position) {
            top += metrics.open - metrics.row;
        };
        return top;
    }

    fn contentHeight(self: *const ReferenceList, metrics: Metrics) i32 {
        const count: i32 = @intCast(self.shown_count);
        var height = count * metrics.row;
        if (self.selectedPosition() != null) height += metrics.open - metrics.row;
        return height;
    }

    /// The row at `y` (from the top of the content), if there is one.
    fn positionAt(self: *const ReferenceList, metrics: Metrics, y: i32) ?usize {
        if (y < 0) return null;
        const selected = self.selectedPosition();
        var top: i32 = 0;
        for (0..self.shown_count) |position| {
            const height = rowHeight(metrics, selected, position);
            if (y < top + height) return position;
            top += height;
        }
        return null;
    }

    /// Keep the scroll position in range and tell the scroll bar.
    fn syncScroll(self: *ReferenceList) void {
        const hwnd = self.hwnd orelse return;
        const metrics = self.ensureMetrics() orelse return;
        const page = self.clientHeight();
        const content = self.contentHeight(metrics);
        self.scroll_y = std.math.clamp(self.scroll_y, 0, @max(0, content - page));
        const info: SCROLLINFO = .{
            .cbSize = @sizeOf(SCROLLINFO),
            .fMask = SIF_RANGE | SIF_PAGE | SIF_POS | SIF_DISABLENOSCROLL,
            .nMin = 0,
            .nMax = @max(0, content - 1),
            .nPage = @intCast(@max(0, page)),
            .nPos = self.scroll_y,
            .nTrackPos = 0,
        };
        _ = SetScrollInfo(hwnd, SB_VERT, &info, 1);
    }

    fn scrollTo(self: *ReferenceList, y: i32) void {
        const before = self.scroll_y;
        self.scroll_y = y;
        self.syncScroll();
        if (self.scroll_y == before) return;
        if (self.hwnd) |hwnd| _ = InvalidateRect(hwnd, null, 0);
        if (self.kind == .profiles) self.owner().placeProfileEdit();
    }

    /// Scroll so the selected row is in view: all of it when it fits, else
    /// its top. With `.unless_shown`, a row some of which is in view stays
    /// where it is: one being read a page at a time keeps its place when the
    /// focus comes back, or a click lands in it.
    fn revealSelected(self: *ReferenceList, how: enum { whole, unless_shown }) void {
        const metrics = self.ensureMetrics() orelse return;
        const position = self.selectedPosition() orelse return;
        const top = rowTop(metrics, position, position);
        const view = self.clientHeight();
        if (how == .unless_shown and top < self.scroll_y + view and top + metrics.open > self.scroll_y) return self.syncScroll();
        const height = @min(metrics.open, view);
        if (top < self.scroll_y) {
            self.scrollTo(top);
        } else if (top + height > self.scroll_y + self.clientHeight()) {
            self.scrollTo(top + height - self.clientHeight());
        } else self.syncScroll();
    }

    /// Select the row at `position` (among those shown), open it, keep it in
    /// view, and tell UIA.
    fn selectPosition(self: *ReferenceList, position: usize) void {
        if (position >= self.shown_count) return;
        const key = self.shown[position];
        if (self.selected != null and self.selected.? == key) return self.revealSelected(.unless_shown);
        if (self.kind == .profiles) self.owner().disarmProfileRemoval();
        self.selected = key;
        self.metrics = null;
        self.revealSelected(.whole);
        if (self.hwnd) |hwnd| _ = InvalidateRect(hwnd, null, 0);
        if (self.provider) |provider| provider.raiseSelectionChanged(position);
    }

    /// Move the selection by `delta` rows; with none selected, to the first.
    fn moveSelection(self: *ReferenceList, delta: isize) void {
        if (self.shown_count == 0) return;
        const current: isize = if (self.selectedPosition()) |position| @intCast(position) else return self.selectPosition(0);
        const next = std.math.clamp(current + delta, 0, @as(isize, @intCast(self.shown_count - 1)));
        self.selectPosition(@intCast(next));
    }

    /// Page Down (`down`) or Page Up. An open row taller than the list is
    /// read through a page at a time; otherwise the selection moves by as
    /// many rows as the list shows.
    fn turnPage(self: *ReferenceList, down: bool) void {
        const metrics = self.ensureMetrics() orelse return;
        const view = self.clientHeight();
        if (self.selectedPosition()) |position| {
            const top = rowTop(metrics, position, position);
            const bottom = top + metrics.open;
            const step = @max(metrics.row, view - metrics.row);
            if (down and bottom > self.scroll_y + view and top < self.scroll_y + view) return self.scrollTo(@min(self.scroll_y + step, bottom - view));
            if (!down and top < self.scroll_y and bottom > self.scroll_y) return self.scrollTo(@max(self.scroll_y - step, top));
        }
        const rows: isize = @max(1, @divTrunc(view, metrics.row) - 1);
        self.moveSelection(if (down) rows else -rows);
    }

    /// Enter, a double click, or UIA's Invoke on the selected row: open the
    /// config file, where its key is set or can be added.
    fn invokeSelected(self: *ReferenceList) void {
        if (self.selectedPosition() == null) return;
        const settings = self.owner();
        // A profile's row edits its field, or starts a profile or a variable.
        if (self.kind == .profiles) return settings.profileInvoke();
        settings.handle.openInEditor(settings.handle.ctx);
    }

    /// Ctrl+C: on All settings the key's name, on Keybindings the binding as
    /// config lines.
    fn copySelected(self: *ReferenceList) void {
        if (self.selectedPosition() == null) return;
        const settings = self.owner();
        switch (self.kind) {
            .reference => settings.copyReferenceKey(self.selected.?),
            .keybindings => settings.copyKeybind(self.selected.?),
            // Nothing to copy: its open row's second action is Remove
            // (`press`, `profileActions`).
            .profiles => {},
        }
    }

    /// F2: edit the selected key on its control's page (`openField`), when
    /// Settings has a control for it. True when it did.
    fn editSelected(self: *ReferenceList) bool {
        if (self.selectedPosition() == null) return false;
        if (self.kind == .profiles) {
            self.owner().profileInvoke();
            return true;
        }
        const field = self.editField(self.selected.?) orelse return false;
        // The switch destroys this list, whose window may be the one handling
        // the key or click: nothing of it is used after.
        self.owner().showField(field);
        return true;
    }

    /// The open row's actions, in client coordinates, left to right: Edit on
    /// its page (a key Settings has a control for), Copy (when the app can
    /// copy) and Open config file.
    fn actionRects(self: *ReferenceList, metrics: Metrics) struct { edit: ?RECT, copy: ?RECT, open: ?RECT } {
        const position = self.selectedPosition() orelse return .{ .edit = null, .copy = null, .open = null };
        const top = rowTop(metrics, position, position) - self.scroll_y;
        const y = top + 2 * metrics.pad_y + metrics.title + metrics.gap + metrics.field + metrics.body +
            (if (metrics.location > 0) metrics.gap + metrics.location else 0) + metrics.gap;
        var x = metrics.pad_x + metrics.bar + self.indentOf(metrics, self.shown[position]);
        const edit: ?RECT = if (metrics.edit_width > 0) .{ .left = x, .top = y, .right = x + metrics.edit_width, .bottom = y + metrics.line } else null;
        if (edit) |rect| x = rect.right + metrics.action_gap;
        const copy: ?RECT = if (metrics.copy_width > 0) .{ .left = x, .top = y, .right = x + metrics.copy_width, .bottom = y + metrics.line } else null;
        if (copy) |rect| x = rect.right + metrics.action_gap;
        const open: ?RECT = if (metrics.open_width > 0) .{ .left = x, .top = y, .right = x + metrics.open_width, .bottom = y + metrics.line } else null;
        return .{ .edit = edit, .copy = copy, .open = open };
    }

    /// What is under a point of the list.
    const Hit = union(enum) { none, edit, copy, open, row: usize };

    /// What `point` (client coordinates) is on: an action of the open row,
    /// or a row.
    fn hitTest(self: *ReferenceList, point: POINT) Hit {
        const metrics = self.ensureMetrics() orelse return .none;
        const actions = self.actionRects(metrics);
        if (actions.edit) |rect| if (rectContains(rect, point)) return .edit;
        if (actions.copy) |rect| if (rectContains(rect, point)) return .copy;
        if (actions.open) |rect| if (rectContains(rect, point)) return .open;
        const position = self.positionAt(metrics, point.y + self.scroll_y) orelse return .none;
        return .{ .row = position };
    }

    /// A mouse button went down at `point`. What it is on is found before the
    /// list takes the focus, which may open a row and move the rest. A double
    /// click is the second press of a click whose first may have done just
    /// that, so it acts on what the first press was on: a row's opens the
    /// config file, and an action's does nothing more.
    fn press(self: *ReferenceList, point: POINT, kind: enum { left, double, right }) void {
        if (kind == .double) {
            if (self.pressed == .row) self.invokeSelected();
            self.pressed = .none;
            return;
        }
        // What the press is on, as the user saw it.
        const hit = self.hitTest(point);
        // The Profiles page's field keeps what it holds first. A value
        // Settings refuses stops the click (`profileEditDone`), and so does a
        // kept change, which may have moved the rows under it.
        if (self.kind == .profiles and self.owner().profile_edit != null) {
            const before = self.generation();
            if (!self.owner().profileEditDone() or self.generation() != before) {
                self.pressed = .none;
                return;
            }
        }
        self.pressed = if (kind == .left) hit else .none;
        if (self.hwnd) |hwnd| if (GetFocus() != hwnd) {
            self.clicking = true;
            defer self.clicking = false;
            _ = SetFocus(hwnd);
        };
        switch (hit) {
            .none => {},
            .edit => if (kind == .left) {
                self.pressed = .none;
                _ = self.editSelected();
            },
            .copy => if (kind == .left) {
                if (self.kind == .profiles) self.owner().profileDelete() else self.copySelected();
            },
            .open => if (kind == .left) self.invokeSelected(),
            .row => |position| self.selectPosition(position),
        }
    }

    /// The selected row's menu: its actions (`actionRects`). From the
    /// keyboard it opens below the row's first line, the row scrolled into
    /// view first; from the mouse, where it was clicked, and only on a row
    /// (the press selected it).
    fn showMenu(self: *ReferenceList, lParam: LPARAM) void {
        const hwnd = self.hwnd orelse return;
        const settings = self.owner();
        const frame = settings.hwnd orelse return;
        if (self.selectedPosition() == null) return;
        var at: POINT = .{ .x = lparamX(lParam), .y = lparamY(lParam) };
        if (@as(u32, @truncate(@as(usize, @bitCast(lParam)))) == 0xFFFF_FFFF) {
            self.revealSelected(.unless_shown);
            const metrics = self.ensureMetrics() orelse return;
            const position = self.selectedPosition() orelse return;
            const below_title = rowTop(metrics, position, position) - self.scroll_y + 2 * metrics.pad_y + metrics.title;
            at = .{ .x = metrics.pad_x, .y = std.math.clamp(below_title, 0, @max(0, self.clientHeight() - 1)) };
            _ = sys.ClientToScreen(hwnd, &at);
        } else {
            var client = at;
            _ = sys.ScreenToClient(hwnd, &client);
            if (self.hitTest(client) == .none) return;
        }
        const menu = sys.CreatePopupMenu() orelse return;
        defer _ = sys.DestroyMenu(menu);
        if (self.kind == .profiles) return settings.showProfileMenu(menu, at, frame);
        if (self.editField(self.selected.?)) |field| {
            var item: [64]u8 = undefined;
            var item_w: [64]u16 = undefined;
            const text = std.fmt.bufPrint(&item, "&Edit on {s}\tF2", .{settings.settingDestination(field).section.headerText()}) catch "&Edit\tF2";
            _ = sys.AppendMenuW(menu, MF_STRING, reference_menu_edit, utf8ToW(&item_w, text));
        }
        if (settings.handle.copyText != null) _ = sys.AppendMenuW(menu, MF_STRING, reference_menu_copy, switch (self.kind) {
            .reference => std.unicode.utf8ToUtf16LeStringLiteral("&Copy name\tCtrl+C"),
            .keybindings => std.unicode.utf8ToUtf16LeStringLiteral("&Copy binding\tCtrl+C"),
            .profiles => unreachable,
        });
        _ = sys.AppendMenuW(menu, MF_STRING, reference_menu_open, std.unicode.utf8ToUtf16LeStringLiteral("&Open config file\tEnter"));
        const picked: usize = if (settings.context_menu_pick) |pick|
            pick(menu)
        else
            @intCast(@max(0, sys.TrackPopupMenu(menu, TPM_RETURNCMD | TPM_RIGHTBUTTON, at.x, at.y, 0, frame, null)));
        switch (picked) {
            reference_menu_edit => _ = self.editSelected(),
            reference_menu_copy => self.copySelected(),
            reference_menu_open => self.invokeSelected(),
            else => {},
        }
    }

    /// A key reaching the list. True when it was the list's.
    fn keyDown(self: *ReferenceList, vk: usize) bool {
        switch (vk) {
            focus_cue.vk_up => self.moveSelection(-1),
            focus_cue.vk_down => self.moveSelection(1),
            focus_cue.vk_home => self.selectPosition(0),
            focus_cue.vk_end => if (self.shown_count != 0) self.selectPosition(self.shown_count - 1),
            focus_cue.vk_prior => self.turnPage(false),
            focus_cue.vk_next => self.turnPage(true),
            'C' => {
                if (self.kind == .profiles or !win32_input.keyPressed(VK_CONTROL) or win32_input.keyPressed(VK_MENU) or win32_input.keyPressed(VK_SHIFT)) return false;
                self.copySelected();
            },
            VK_F2 => {
                if (win32_input.keyPressed(VK_CONTROL) or win32_input.keyPressed(VK_MENU) or win32_input.keyPressed(VK_SHIFT)) return false;
                return self.editSelected();
            },
            // The Profiles page: Delete removes what is selected, and Insert
            // or Ctrl+N starts a profile.
            VK_DELETE => {
                if (self.kind != .profiles or win32_input.keyPressed(VK_CONTROL) or win32_input.keyPressed(VK_MENU) or win32_input.keyPressed(VK_SHIFT)) return false;
                self.owner().profileDelete();
            },
            VK_INSERT => {
                if (self.kind != .profiles or win32_input.keyPressed(VK_CONTROL) or win32_input.keyPressed(VK_MENU) or win32_input.keyPressed(VK_SHIFT)) return false;
                self.owner().profileNew();
            },
            'N' => {
                if (self.kind != .profiles or !win32_input.keyPressed(VK_CONTROL) or win32_input.keyPressed(VK_MENU) or win32_input.keyPressed(VK_SHIFT)) return false;
                self.owner().profileNew();
            },
            else => return false,
        }
        return true;
    }

    /// The list took the keyboard focus: a row is selected (the last one, or
    /// the first) and in view, and UIA hears the focus on it. A click selects
    /// the row it is on instead (`press`).
    fn focused(self: *ReferenceList) void {
        // A page too short for the Keybindings list scrolls to it first, unless
        // the window is handing back its focus (`restoring_focus`), as the
        // other controls' focus does.
        if (self.kind == .keybindings and !self.owner().restoring_focus) if (self.hwnd) |hwnd| self.owner().ensureControlVisible(hwnd);
        if (!self.clicking and self.shown_count != 0) {
            if (self.selectedPosition() == null) {
                self.selected = self.shown[0];
                self.metrics = null;
            }
            // A window opened again keeps the key, not where it scrolled to.
            self.revealSelected(.unless_shown);
        }
        if (self.hwnd) |hwnd| _ = InvalidateRect(hwnd, null, 0);
        if (self.provider) |provider| provider.raiseFocusOnSelectedRow();
    }

    /// Row `position`'s bounds on screen while some of it is in view.
    fn rowScreenBounds(self: *ReferenceList, position: usize) ?win32_uia.UiaRect {
        const hwnd = self.hwnd orelse return null;
        if (position >= self.shown_count) return null;
        const metrics = self.ensureMetrics() orelse return null;
        if (sys.IsWindowVisible(hwnd) == 0) return null;
        const selected = self.selectedPosition();
        const top = rowTop(metrics, selected, position) - self.scroll_y;
        const bottom = top + rowHeight(metrics, selected, position);
        // The row, in screen coordinates, cut to the list's client area and to
        // the viewport's: the Keybindings list runs past the viewport on a
        // short window, and a row there is not on screen.
        var origin: POINT = .{ .x = 0, .y = 0 };
        if (sys.ClientToScreen(hwnd, &origin) == 0) return null;
        var shown: RECT = .{ .left = origin.x, .top = origin.y + @max(0, top), .right = origin.x + metrics.width, .bottom = origin.y + @min(self.clientHeight(), bottom) };
        if (self.owner().viewport) |viewport| {
            var client: RECT = undefined;
            var corner: POINT = .{ .x = 0, .y = 0 };
            if (GetClientRect(viewport, &client) == 0 or sys.ClientToScreen(viewport, &corner) == 0) return null;
            shown.left = @max(shown.left, corner.x);
            shown.top = @max(shown.top, corner.y);
            shown.right = @min(shown.right, corner.x + client.right);
            shown.bottom = @min(shown.bottom, corner.y + client.bottom);
        }
        if (shown.bottom <= shown.top or shown.right <= shown.left) return null;
        return .{
            .left = @floatFromInt(shown.left),
            .top = @floatFromInt(shown.top),
            .width = @floatFromInt(shown.right - shown.left),
            .height = @floatFromInt(shown.bottom - shown.top),
        };
    }

    /// Paint the rows that `clip` meets.
    fn paint(self: *ReferenceList, hdc: HDC, clip: RECT) void {
        const settings = self.owner();
        const colors = settings.theme_adapter.colors;
        fillSolid(hdc, clip, colors.window_bg);
        const hwnd = self.hwnd orelse return;
        const metrics = self.ensureMetrics() orelse return;
        _ = SetBkMode(hdc, TRANSPARENT);
        const selected = self.selectedPosition();
        const view = self.clientHeight();
        const ring = focus_cue.showRing(GetFocus() == hwnd, false, settings.focus_input_mode, colors.high_contrast);
        var top: i32 = -self.scroll_y;
        for (0..self.shown_count) |position| {
            const height = rowHeight(metrics, selected, position);
            defer top += height;
            if (top + height <= clip.top) continue;
            if (top >= @min(clip.bottom, view)) break;
            const row: RECT = .{ .left = 0, .top = top, .right = metrics.width, .bottom = top + height };
            if (selected == position) self.paintOpenRow(hdc, metrics, row, self.shown[position], ring) else self.paintRow(hdc, metrics, row, self.shown[position], position + 1 < self.shown_count);
        }
    }

    /// The row's first line (`writeTitle`): the key or the binding's keys,
    /// and then its value or action, from `left`.
    fn paintTitle(self: *ReferenceList, hdc: HDC, metrics: Metrics, row: RECT, key: u16, text_color: COLORREF, value_color: COLORREF) void {
        const settings = self.owner();
        const left = row.left + metrics.pad_x + metrics.bar + self.indentOf(metrics, key);
        const right = row.right - metrics.pad_x;
        const y = row.top + metrics.pad_y;
        var name_buf: [192]u8 = undefined;
        var name_text: std.Io.Writer = .fixed(&name_buf);
        var value_buf: [256]u8 = undefined;
        var value: std.Io.Writer = .fixed(&value_buf);
        self.writeTitle(key, &name_text, &value);
        var name_w: [192]u16 = undefined;
        const name = utf8ToW(&name_w, utf8Prefix(name_text.buffered()));
        const previous = SelectObject(hdc, settings.emphasis_font);
        defer _ = SelectObject(hdc, previous);
        _ = SetTextColor(hdc, text_color);
        var name_rect: RECT = .{ .left = left, .top = y, .right = right, .bottom = y + metrics.title };
        var measured = name_rect;
        _ = DrawTextW(hdc, name, -1, &measured, DT_SINGLELINE | DT_NOPREFIX | DT_CALCRECT);
        _ = DrawTextW(hdc, name, -1, &name_rect, DT_SINGLELINE | DT_NOPREFIX | DT_END_ELLIPSIS);
        const value_left = measured.right + settings.px(settings_metrics.space_6);
        if (value_left >= right) return;
        var value_w: [256]u16 = undefined;
        _ = SelectObject(hdc, settings.ui_font);
        _ = SetTextColor(hdc, value_color);
        var value_rect: RECT = .{ .left = value_left, .top = y, .right = right, .bottom = y + metrics.title };
        _ = DrawTextW(hdc, utf8ToW(&value_w, utf8Prefix(value.buffered())), -1, &value_rect, DT_SINGLELINE | DT_NOPREFIX | DT_END_ELLIPSIS | DT_VCENTER);
    }

    fn paintRow(self: *ReferenceList, hdc: HDC, metrics: Metrics, row: RECT, key: u16, separator: bool) void {
        const settings = self.owner();
        const colors = settings.theme_adapter.colors;
        self.paintTitle(hdc, metrics, row, key, colors.text, if (self.emptyValue(key)) colors.secondary_text else colors.text);
        const line_text = self.summaryLine(key);
        var line_w: [512]u16 = undefined;
        const previous = SelectObject(hdc, settings.secondary_font);
        defer _ = SelectObject(hdc, previous);
        _ = SetTextColor(hdc, colors.secondary_text);
        const y = row.top + metrics.pad_y + metrics.title + metrics.gap;
        var line_rect: RECT = .{ .left = row.left + metrics.pad_x + metrics.bar + self.indentOf(metrics, key), .top = y, .right = row.right - metrics.pad_x, .bottom = y + metrics.line };
        _ = DrawTextW(hdc, utf8ToW(&line_w, utf8Prefix(line_text[0..@min(line_text.len, line_w.len - 1)])), -1, &line_rect, DT_SINGLELINE | DT_NOPREFIX | DT_END_ELLIPSIS);
        if (separator) {
            const stroke = @max(1, settings.px(settings_metrics.stroke_hairline));
            fillSolid(hdc, .{ .left = row.left + metrics.pad_x, .top = row.bottom - stroke, .right = row.right - metrics.pad_x, .bottom = row.bottom }, colors.pane_separator);
        }
    }

    fn paintOpenRow(self: *ReferenceList, hdc: HDC, metrics: Metrics, row: RECT, key: u16, ring: bool) void {
        const settings = self.owner();
        const colors = settings.theme_adapter.colors;
        // The first line on the selection colour, the rest on the pane's, and
        // a bar down the left of the whole row. The focus ring goes round them
        // on the pane's colour, never over the band: in High Contrast the band
        // is Highlight, which the ring's colour is too.
        const ring_width: i32 = if (ring) @max(1, settings.px(settings_metrics.stroke_focus)) else 0;
        const band: RECT = .{ .left = row.left + ring_width, .top = row.top + ring_width, .right = row.right - ring_width, .bottom = row.top + 2 * metrics.pad_y + metrics.title };
        fillSolid(hdc, band, colors.selection_bg);
        fillSolid(hdc, .{ .left = band.left, .top = band.top, .right = band.left + metrics.bar, .bottom = row.bottom - ring_width }, colors.accent);
        self.paintTitle(hdc, metrics, row, key, colors.selection_text, colors.selection_text);
        const left = row.left + metrics.pad_x + metrics.bar + self.indentOf(metrics, key);
        const right = row.right - metrics.pad_x;
        // The Profiles page's text field, while one is typed into, sits here
        // (`placeProfileEdit`).
        var y = band.bottom + metrics.gap + metrics.field;
        const previous = SelectObject(hdc, settings.ui_font);
        defer _ = SelectObject(hdc, previous);
        if (self.open_body) |text| {
            _ = SetTextColor(hdc, colors.text);
            var rect: RECT = .{ .left = left, .top = y, .right = right, .bottom = y + metrics.body };
            _ = DrawTextW(hdc, text.ptr, @intCast(text.len), &rect, DT_WORDBREAK | DT_NOPREFIX | DT_EXPANDTABS);
        }
        y += metrics.body;
        _ = SelectObject(hdc, settings.secondary_font);
        if (self.open_location) |text| {
            y += metrics.gap;
            _ = SetTextColor(hdc, colors.secondary_text);
            var rect: RECT = .{ .left = left, .top = y, .right = right, .bottom = y + metrics.location };
            _ = DrawTextW(hdc, text.ptr, @intCast(text.len), &rect, DT_WORDBREAK | DT_NOPREFIX);
            y += metrics.location;
        }
        const actions = self.actionRects(metrics);
        _ = SetTextColor(hdc, referenceActionColor(colors));
        var label_w: [64]u16 = undefined;
        const profile_actions: ?SettingsWindow.ProfileActions = if (self.kind == .profiles) settings.profileActions(settings.profile_model.rows[key]) else null;
        if (actions.edit) |rect| if (if (profile_actions) |labels| (if (labels.enter) |text| utf8ToW(&label_w, text) else null) else self.editLabel(key, &label_w)) |label| {
            var edit_rect = rect;
            _ = DrawTextW(hdc, label, -1, &edit_rect, DT_SINGLELINE | DT_NOPREFIX);
        };
        if (actions.copy) |rect| {
            var copy_rect = rect;
            const label = if (profile_actions) |labels| labels.delete orelse "" else self.kind.copyLabel();
            _ = DrawTextW(hdc, utf8ToW(&label_w, label), -1, &copy_rect, DT_SINGLELINE | DT_NOPREFIX);
        }
        if (actions.open) |rect| {
            var open_rect = rect;
            open_rect.right = right;
            _ = DrawTextW(hdc, std.unicode.utf8ToUtf16LeStringLiteral(reference_open_label), -1, &open_rect, DT_SINGLELINE | DT_NOPREFIX | DT_END_ELLIPSIS);
        }
        if (ring) strokeRect(hdc, row, if (colors.high_contrast) colors.text else colors.focus_ring, ring_width);
    }
};

const DT_EXPANDTABS: u32 = 0x0040;

fn rectContains(rect: RECT, point: POINT) bool {
    return point.x >= rect.left and point.x < rect.right and point.y >= rect.top and point.y < rect.bottom;
}

/// `bytes` without a UTF-8 sequence cut short at its end.
fn utf8Prefix(bytes: []const u8) []const u8 {
    var end = bytes.len;
    var back: usize = 0;
    while (end > 0 and back < 4) : (back += 1) {
        const c = bytes[end - 1];
        if (c < 0x80) break;
        if (c & 0xC0 == 0xC0) {
            // A lead byte: keep it only with all of its sequence.
            const length = std.unicode.utf8ByteSequenceLength(c) catch return bytes[0 .. end - 1];
            return if (back + 1 >= length) bytes else bytes[0 .. end - 1];
        }
        end -= 1;
    }
    return bytes;
}

/// The height of `text` wrapped to `width` in `font`.
fn measureWrapped(hwnd: HWND, font: HGDIOBJ, text: [:0]const u16, width: i32) i32 {
    if (text.len == 0) return 0;
    const hdc = GetDC(hwnd) orelse return 0;
    defer _ = ReleaseDC(hwnd, hdc);
    const previous = SelectObject(hdc, font);
    defer _ = SelectObject(hdc, previous);
    var rect: RECT = .{ .left = 0, .top = 0, .right = width, .bottom = 0 };
    _ = DrawTextW(hdc, text.ptr, @intCast(text.len), &rect, DT_CALCRECT | DT_WORDBREAK | DT_NOPREFIX | DT_EXPANDTABS);
    return rect.bottom - rect.top;
}

/// The width of one line of `text` in `font`.
fn measureLine(hwnd: HWND, font: HGDIOBJ, text: [*:0]const u16) i32 {
    const hdc = GetDC(hwnd) orelse return 0;
    defer _ = ReleaseDC(hwnd, hdc);
    const previous = SelectObject(hdc, font);
    defer _ = SelectObject(hdc, previous);
    var rect: RECT = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
    _ = DrawTextW(hdc, text, -1, &rect, DT_CALCRECT | DT_SINGLELINE | DT_NOPREFIX);
    return rect.right - rect.left;
}

/// The file a save writes, as the All settings page reads it on the UI
/// thread: `override` (the `--config-file` path the process started with) or
/// the default the loader would pick, and its bytes. Every look at a file,
/// the default path's probes too, goes through `local_path.open` with
/// `Cloud.refuse`, so no link is followed unchecked and no placeholder is
/// recalled; a default whose candidates cannot all be looked at that way is
/// not named.
pub fn readConfigSource(alloc: std.mem.Allocator, override: ?[]const u8) settings_reference.ConfigSource {
    const path: []const u8 = if (override) |given|
        alloc.dupe(u8, given) catch return .{}
    else
        (config_file_load.preferredXdgPathProbed(alloc, &localFileState) catch return .{}) orelse
            return .{ .file = .unavailable };
    return .{ .path = path, .file = readConfigFile(alloc, path) };
}

/// The config file at `path`, for the lines that set each key: read only
/// through a handle `local_path.open` showed to be local, and only up to a
/// size a config file has. A file that is not there is `.missing`; one that
/// could not be shown to be local, or read, `.unavailable`. The bytes are the
/// caller's to free.
fn readConfigFile(alloc: std.mem.Allocator, path: []const u8) settings_reference.ConfigFile {
    const found = switch (local_path.open(alloc, path, .{ .data = true, .cloud = .refuse }) catch return .unavailable) {
        .found => |hit| hit,
        .missing => return .missing,
        .refused => return .unavailable,
    };
    defer found.deinit(alloc);
    return .{ .bytes = found.file.readToEndAlloc(alloc, reference_config_max_bytes) catch return .unavailable };
}

/// A default-path candidate's state for `preferredXdgPathProbed`, looked at
/// through `local_path.open`; null when it cannot be shown to be local.
fn localFileState(alloc: std.mem.Allocator, path: []const u8) ?config_file_load.FileState {
    const found = switch (local_path.open(alloc, path, .{ .cloud = .refuse }) catch return null) {
        .found => |hit| hit,
        .missing => return .missing,
        .refused => return null,
    };
    defer found.deinit(alloc);
    const stat = found.file.stat() catch return null;
    return if (stat.size == 0) .empty else .content;
}

/// The largest config file the All settings page reads for line numbers.
const reference_config_max_bytes = 4 * 1024 * 1024;

fn referenceListUiaState(list: *ReferenceList) win32_uia.PaletteListState {
    return .{
        .ctx = list,
        .name = &referenceUiaName,
        .localized_control_type = "list",
        .keyboard_focusable = true,
        .focused = &referenceUiaFocused,
        .row_count = &referenceUiaRowCount,
        .selected_index = &referenceUiaSelectedIndex,
        .row_name = &referenceUiaRowName,
        .row_id = &referenceUiaRowId,
        .select_row = &referenceUiaSelectRow,
        .invoke_row = &referenceUiaInvokeRow,
        .row_bounds = &referenceUiaRowBounds,
        .help_text = switch (list.kind) {
            .reference => reference_list_help,
            .keybindings => keybind_list_help,
            .profiles => profile_list_help,
        },
        .row_help = &referenceUiaRowHelp,
        .focus_selected_row = true,
        .use_com_threading = list.owner().canInitializeCustomUiaProviders(),
    };
}

fn referenceOwner(ctx: *anyopaque) *ReferenceList {
    return @ptrCast(@alignCast(ctx));
}

fn referenceUiaName(ctx: *anyopaque, buf: []u8) []const u8 {
    _ = buf;
    return switch (referenceOwner(ctx).kind) {
        .reference => "All settings",
        .keybindings => "Key bindings",
        .profiles => "Profiles",
    };
}

fn referenceUiaFocused(ctx: *anyopaque) bool {
    const list = referenceOwner(ctx).hwnd orelse return false;
    return GetFocus() == list;
}

fn referenceUiaRowCount(ctx: *anyopaque) usize {
    return referenceOwner(ctx).shown_count;
}

fn referenceUiaSelectedIndex(ctx: *anyopaque) ?usize {
    return referenceOwner(ctx).selectedPosition();
}

/// A row's name: the key and its value in effect, or the binding's keys and
/// its action.
fn referenceUiaRowName(ctx: *anyopaque, index: usize, buf: []u8) []const u8 {
    const list = referenceOwner(ctx);
    const id = list.shownId(index) orelse return "";
    var writer: std.Io.Writer = .fixed(buf);
    if (list.kind == .profiles) {
        const model = &list.ownerConst().profile_model;
        model.writeUiaName(model.rows[id], &writer) catch {};
        return utf8Prefix(writer.buffered());
    }
    var value_buf: [512]u8 = undefined;
    var value: std.Io.Writer = .fixed(&value_buf);
    list.writeTitle(id, &writer, &value);
    if (list.kind == .reference and list.ownerConst().referenceKeyDirty(id)) {
        // "key, value, changed here, not saved yet" reads better than the
        // drawn parenthesis.
        value.end = 0;
        settings_reference.writeValue(&value, &list.ownerConst().reference_model.rows[id]) catch {};
        value.writeAll(", changed here, not saved yet") catch {};
    }
    writer.print(", {s}", .{value.buffered()}) catch {};
    return utf8Prefix(writer.buffered());
}

/// A row's help text: on All settings what Windows does with the key, its
/// description, where the config file sets it, and how to edit it; on
/// Keybindings what the action does and where the binding comes from.
fn referenceUiaRowHelp(ctx: *anyopaque, index: usize, buf: []u8) []const u8 {
    const list = referenceOwner(ctx);
    const id = list.shownId(index) orelse return "";
    var writer: std.Io.Writer = .fixed(buf);
    var location_buf: [1024]u8 = undefined;
    var location: std.Io.Writer = .fixed(&location_buf);
    list.writeOpenText(id, &writer, &location) catch {};
    if (location.end != 0) writer.print("\n\n{s}", .{location.buffered()}) catch {};
    if (list.editField(id)) |field| writer.print("\n\nF2 edits it on {s}.", .{list.ownerConst().settingDestination(field).section.headerText()}) catch {};
    return utf8Prefix(writer.buffered());
}

/// A row's identity for UIA: on All settings the key's (its index is fixed);
/// on Keybindings the binding's own (`settings_keybinds.Row.id`), so a row UIA
/// holds across a rebuild is that binding, or gone, never the one now in its
/// place.
fn referenceUiaRowId(ctx: *anyopaque, index: usize) u64 {
    const list = referenceOwner(ctx);
    const id = list.shownId(index) orelse return 0;
    return switch (list.kind) {
        .reference => @as(u64, id) + 1,
        .keybindings => list.ownerConst().keybind_model.rows[id].id,
        .profiles => list.ownerConst().profile_model.rows[id].identity,
    };
}

fn referenceUiaSelectRow(ctx: *anyopaque, index: usize) void {
    referenceOwner(ctx).selectPosition(index);
}

fn referenceUiaInvokeRow(ctx: *anyopaque, index: usize) void {
    const list = referenceOwner(ctx);
    list.selectPosition(index);
    list.invokeSelected();
}

fn referenceUiaRowBounds(ctx: *anyopaque, index: usize) ?win32_uia.PaletteListRowBounds {
    return referenceOwner(ctx).rowScreenBounds(index);
}

fn referenceListDisconnect(ctx: *anyopaque) win32_uia.HRESULT {
    return (@as(*win32_uia.PaletteListProvider, @ptrCast(@alignCast(ctx)))).disconnect();
}

fn referenceListRelease(ctx: *anyopaque) void {
    const provider: *win32_uia.PaletteListProvider = @ptrCast(@alignCast(ctx));
    _ = win32_uia.PaletteListProvider.Release(&provider.base);
}

/// The lists' window procedure (`ReferenceList`): the window's user data is
/// its list.
fn referenceListProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    if (msg == WM_NCCREATE) {
        const cs: *const CREATESTRUCTW = @ptrFromInt(@as(usize, @bitCast(lParam)));
        if (cs.lpCreateParams) |ptr| _ = sys.SetWindowLongPtrW(hwnd, GWLP_USERDATA, @intCast(@intFromPtr(ptr)));
    }
    const raw = sys.GetWindowLongPtrW(hwnd, GWLP_USERDATA);
    if (raw == 0) return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
    const list: *ReferenceList = @ptrFromInt(@as(usize, @intCast(raw)));
    const owner = list.owner();
    switch (msg) {
        WM_ERASEBKGND => return 1,
        WM_PAINT => {
            var ps: PAINTSTRUCT = undefined;
            const hdc = sys.BeginPaint(hwnd, &ps);
            list.paint(hdc, ps.rcPaint);
            _ = sys.EndPaint(hwnd, &ps);
            return 0;
        },
        WM_PRINTCLIENT => {
            var rect: RECT = undefined;
            if (wParam != 0 and GetClientRect(hwnd, &rect) != 0) list.paint(@ptrFromInt(wParam), rect);
            return 0;
        },
        WM_SIZE => {
            list.syncScroll();
            _ = InvalidateRect(hwnd, null, 0);
            if (list.kind == .profiles) owner.placeProfileEdit();
            return 0;
        },
        // The Profiles page's text field takes the window's colours, as the
        // form's do.
        WM_CTLCOLOREDIT => if (owner.hwnd) |frame| return sys.SendMessageW(frame, msg, wParam, lParam),
        WM_SETTINGS_PROFILE_BLUR => {
            owner.profileEditBlurred();
            return 0;
        },
        // The Profiles page's field: typing into it is an edit Save can take.
        WM_COMMAND => if (list.kind == .profiles and @as(u16, @truncate(wParam >> 16)) == EN_CHANGE) {
            owner.profileEditTyped();
            return 0;
        },
        WM_GETDLGCODE => return DLGC_WANTARROWS | DLGC_WANTCHARS,
        WM_KEYDOWN => {
            noteSettingsInput(owner, msg, wParam);
            // A held Delete, Insert or Ctrl+N acts once on the Profiles page:
            // repeats would run through its rows, the second Delete a
            // removal asks for included.
            if (list.kind == .profiles and (lParam & (1 << 30)) != 0 and
                (wParam == VK_DELETE or wParam == VK_INSERT or wParam == 'N')) return 0;
            if (list.keyDown(wParam)) return 0;
        },
        WM_SETFOCUS => {
            list.focused();
            return 0;
        },
        WM_KILLFOCUS => {
            _ = InvalidateRect(hwnd, null, 0);
            return 0;
        },
        WM_LBUTTONDOWN, WM_LBUTTONDBLCLK, WM_RBUTTONDOWN => {
            noteSettingsInput(owner, if (msg == WM_RBUTTONDOWN) WM_RBUTTONDOWN else WM_LBUTTONDOWN, wParam);
            list.press(.{ .x = lparamX(lParam), .y = lparamY(lParam) }, switch (msg) {
                WM_LBUTTONDBLCLK => .double,
                WM_RBUTTONDOWN => .right,
                else => .left,
            });
            return 0;
        },
        WM_CONTEXTMENU => {
            list.showMenu(lParam);
            return 0;
        },
        WM_MOUSEWHEEL => {
            const delta: i16 = @bitCast(@as(u16, @truncate(wParam >> 16)));
            const lines = owner.wheel_lines_override orelse systemWheelScrollLines();
            const metrics = list.ensureMetrics() orelse return 0;
            // Three lines a notch scroll about one and a half rows.
            const notch: i32 = if (lines == WHEEL_PAGESCROLL) list.clientHeight() else wheelNotchPixels(@divTrunc(metrics.row * 3, 2), lines);
            const pixels = wheelScrollPixels(&list.wheel_remainder, delta, notch);
            if (pixels != 0) list.scrollTo(list.scroll_y - pixels);
            return 0;
        },
        WM_VSCROLL => {
            const metrics = list.ensureMetrics() orelse return 0;
            var tracking: SCROLLINFO = .{ .cbSize = @sizeOf(SCROLLINFO), .fMask = SIF_TRACKPOS, .nMin = 0, .nMax = 0, .nPage = 0, .nPos = 0, .nTrackPos = list.scroll_y };
            const code = wParam & 0xFFFF;
            if (code == SB_THUMBPOSITION or code == SB_THUMBTRACK) _ = GetScrollInfo(hwnd, SB_VERT, &tracking);
            const view = list.clientHeight();
            list.scrollTo(switch (code) {
                SB_LINEUP => list.scroll_y - metrics.row,
                SB_LINEDOWN => list.scroll_y + metrics.row,
                SB_PAGEUP => list.scroll_y - @max(metrics.row, view - metrics.row),
                SB_PAGEDOWN => list.scroll_y + @max(metrics.row, view - metrics.row),
                SB_THUMBPOSITION, SB_THUMBTRACK => tracking.nTrackPos,
                SB_TOP => 0,
                SB_BOTTOM => list.contentHeight(metrics),
                else => list.scroll_y,
            });
            return 0;
        },
        WM_GETOBJECT => if (list.provider) |provider| {
            if (win32_uia.returnPaletteListProvider(hwnd, wParam, lParam, provider)) |result| return result;
        },
        WM_NCDESTROY => {
            if (list.hwnd == hwnd) owner.listDestroyed(list);
            _ = sys.SetWindowLongPtrW(hwnd, GWLP_USERDATA, 0);
        },
        else => {},
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

/// A UIA string property of `element`, as UTF-8 in `buf`.
fn uiaStringProperty(element: *@import("win32_uia/com.zig").IRawElementProviderSimple, property: i32, buf: []u8) ![]const u8 {
    const com = @import("win32_uia/com.zig");
    var value = com.VARIANT.empty();
    try std.testing.expectEqual(com.S_OK, element.vtbl.GetPropertyValue(element, property, &value));
    defer _ = com.VariantClear(&value);
    try std.testing.expectEqual(@as(u16, com.VT_BSTR), value.vt);
    const bstr = value.value.bstr.?;
    return buf[0..try std.unicode.utf16LeToUtf8(buf, bstr[0..com.SysStringLen(bstr)])];
}

/// A Settings window on the config file `text` (`noctty.conf` in `tmp`),
/// which its Save writes and reads back. `path` is the caller's to free once
/// the fixture is finished.
fn profileFixture(tmp: *std.testing.TmpDir, text: []const u8, path: *[]u8) !*dialog_test.Fixture {
    const alloc = std.testing.allocator;
    try tmp.dir.writeFile(.{ .sub_path = "noctty.conf", .data = text });
    path.* = try tmp.dir.realpathAlloc(alloc, "noctty.conf");
    errdefer alloc.free(path.*);
    const fixture = try dialog_test.Fixture.prepare(true);
    errdefer fixture.finish();
    try fixture.config.loadFile(alloc, path.*);
    try fixture.config.loadRecursiveFiles(alloc);
    fixture.save_path = path.*;
    fixture.reload_from_disk = true;
    try fixture.settings.open();
    fixture.settings.setActiveSection(.profiles);
    _ = SetFocus(fixture.settings.profile_list.hwnd.?);
    return fixture;
}

/// The Profiles page's field being typed into; a test that expects one fails,
/// rather than panics, when there is none.
fn openEdit(settings: *SettingsWindow) !*ProfileEdit {
    return if (settings.profile_edit) |*edit| edit else error.TestExpectedProfileEdit;
}

fn profileRowName(settings: *SettingsWindow, position: usize, buf: []u8) []const u8 {
    return referenceUiaRowName(&settings.profile_list, position, buf);
}

test "settings the Profiles page lists the profiles and their fields, made with its page and gone with it" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            // Keys read as pressed alone, whatever the live keyboard holds.
            const keyboard = win32_input.TestingKeyboard.pinNone();
            defer keyboard.release();
            const alloc = std.testing.allocator;
            var tmp = std.testing.tmpDir(.{});
            defer tmp.cleanup();
            var path: []u8 = &.{};
            const fixture = try profileFixture(&tmp, "profile-command = py: python.exe\nprofile-name = py: Python\nprofile-env = py: MODE=1\n", &path);
            defer alloc.free(path);
            defer fixture.finish();
            const settings = &fixture.settings;
            const Tree = dialog_test.OpenWork.Tree;
            const list = settings.profile_list.hwnd.?;
            try std.testing.expect(sys.IsWindowVisible(list) != 0);
            // New profile, the profile, its three fields, its variable and
            // Add variable, each a ListItem a reader can name.
            try std.testing.expectEqual(@as(usize, 7), settings.profile_list.shown_count);
            var buf: [256]u8 = undefined;
            try std.testing.expectEqualStrings("New profile", profileRowName(settings, 0, &buf));
            try std.testing.expectEqualStrings("Python, profile user:py", profileRowName(settings, 1, &buf));
            try std.testing.expectEqualStrings("Command line of py, python.exe", profileRowName(settings, 2, &buf));
            try std.testing.expectEqualStrings("Starting folder of py, none", profileRowName(settings, 4, &buf));
            try std.testing.expectEqualStrings("MODE of py, 1", profileRowName(settings, 5, &buf));
            try std.testing.expectEqualStrings("Profiles", referenceUiaName(&settings.profile_list, &buf));
            // A Default profile chosen on Shell marks its profile here.
            settings.pending.?.@"default-profile" = try settings.pending.?._arena.?.allocator().dupeZ(u8, "user:py");
            settings.trackOwnedEdit(.default_profile);
            settings.setActiveSection(.shell);
            settings.setActiveSection(.profiles);
            try std.testing.expectEqualStrings("Python, profile user:py, default profile", profileRowName(settings, 1, &buf));
            // The open row says where the field is set.
            settings.profile_list.selectPosition(2);
            var help_buf: [2048]u8 = undefined;
            const help = referenceUiaRowHelp(&settings.profile_list, 2, &help_buf);
            try std.testing.expect(std.mem.endsWith(u8, help, "Set in noctty.conf, line 1"));

            // The page is one window, and another page takes it away.
            settings.setActiveSection(.terminal);
            try std.testing.expectEqual(@as(?HWND, null), settings.profile_list.hwnd);
            try std.testing.expect(sys.IsWindow(list) == 0);
            const without_list = Tree.of(fixture.hwnd()).len;
            settings.setActiveSection(.profiles);
            try std.testing.expectEqual(without_list + 1, Tree.of(fixture.hwnd()).len);
            settings.setActiveSection(.terminal);
            try std.testing.expectEqual(without_list, Tree.of(fixture.hwnd()).len);
            try dialog_test.expectNothingStale(fixture.hwnd());
        }
    }.body);
}

test "settings a profile's field is typed into in place, and Save writes its line alone" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            // Keys read as pressed alone, whatever the live keyboard holds.
            const keyboard = win32_input.TestingKeyboard.pinNone();
            defer keyboard.release();
            const alloc = std.testing.allocator;
            var tmp = std.testing.tmpDir(.{});
            defer tmp.cleanup();
            var path: []u8 = &.{};
            const text = "# mine\nprofile-command = py: python.exe\nprofile-name = py: Python\nprofile-command = other: o.exe\n";
            const fixture = try profileFixture(&tmp, text, &path);
            defer alloc.free(path);
            defer fixture.finish();
            const settings = &fixture.settings;
            const Tree = dialog_test.OpenWork.Tree;
            const list = &settings.profile_list;
            list.selectPosition(2);
            const windows_before = Tree.of(fixture.hwnd()).len;

            // Typing enables Save; Escape puts the field back, and Save with it.
            try std.testing.expect(fixture.pumpKey(VK_RETURN));
            typeInto((try openEdit(settings)).hwnd.?, "x");
            try std.testing.expect(sys.IsWindowEnabled(settings.btn_save.?) != 0);
            try std.testing.expect(fixture.pumpKey(VK_ESCAPE));
            try std.testing.expect(sys.IsWindowEnabled(settings.btn_save.?) == 0);
            try std.testing.expect(!settings.hasPendingChanges());

            // Enter opens a text field on the row: one window more, named
            // after the field for UIA, holding the value.
            try std.testing.expect(fixture.pumpKey(VK_RETURN));
            const edit = (try openEdit(settings)).hwnd.?;
            try std.testing.expectEqual(edit, sys.GetFocus().?);
            try std.testing.expectEqual(windows_before + 1, Tree.of(fixture.hwnd()).len);
            var buf: [256]u8 = undefined;
            try std.testing.expectEqualStrings("python.exe", readEditUtf8(edit, &buf).?);
            const provider = (try openEdit(settings)).provider.?;
            const constants = @import("win32_uia/constants.zig");
            try std.testing.expectEqualStrings("Command line of py", try uiaStringProperty(&provider.base, constants.UIA_NamePropertyId, &buf));
            // It sits on its row, under the row's title.
            const row_top = ReferenceList.rowTop(list.ensureMetrics().?, 2, 2) - list.scroll_y;
            try std.testing.expect(dialog_test.rectIn(list.hwnd.?, edit).top > row_top);

            // The focus leaving the window (Alt+Tab) keeps the field open.
            typeInto(edit, "  python.exe -X utf8  ");
            const other = sys.CreateWindowExW(0, std.unicode.utf8ToUtf16LeStringLiteral("STATIC"), std.unicode.utf8ToUtf16LeStringLiteral(""), 0x80000000 | 0x10000000, 0, 0, 1, 1, null, null, null, null).?; // WS_POPUP | WS_VISIBLE
            defer _ = sys.DestroyWindow(other);
            _ = SetFocus(other);
            dialog_test.pump();
            try std.testing.expectEqual(edit, (try openEdit(settings)).hwnd.?);
            _ = SetFocus(edit);

            // Enter keeps it, trimmed; the field goes and the focus is back on
            // the list.
            try std.testing.expect(fixture.pumpKey(VK_RETURN));
            try std.testing.expect(settings.profile_edit == null);
            try std.testing.expect(sys.IsWindow(edit) == 0);
            try std.testing.expectEqual(list.hwnd.?, sys.GetFocus().?);
            try std.testing.expectEqual(windows_before, Tree.of(fixture.hwnd()).len);
            try std.testing.expect(settings.hasPendingChanges());
            try std.testing.expect(settings.canSave());
            try std.testing.expectEqual(@as(usize, 1), settings.pendingFieldCount());
            try std.testing.expectEqualStrings("Command line of py, python.exe -X utf8, changed here, not saved yet", profileRowName(settings, 2, &buf));

            settings.save();
            try std.testing.expectEqual(@as(u32, 1), fixture.saved);
            const after = try tmp.dir.readFileAlloc(alloc, "noctty.conf", 1 << 20);
            defer alloc.free(after);
            try std.testing.expectEqualStrings("# mine\nprofile-command = py: python.exe -X utf8\nprofile-name = py: Python\nprofile-command = other: o.exe\n", after);
            try std.testing.expect(!settings.hasPendingChanges());
            try std.testing.expectEqualStrings("Command line of py, python.exe -X utf8", profileRowName(settings, 2, &buf));
        }
    }.body);
}

test "settings a new profile asks for its id, then its command line, and Save appends it" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            // Keys read as pressed alone, whatever the live keyboard holds.
            const keyboard = win32_input.TestingKeyboard.pinNone();
            defer keyboard.release();
            const alloc = std.testing.allocator;
            var tmp = std.testing.tmpDir(.{});
            defer tmp.cleanup();
            var path: []u8 = &.{};
            const fixture = try profileFixture(&tmp, "profile-command = py: python.exe\n", &path);
            defer alloc.free(path);
            defer fixture.finish();
            const settings = &fixture.settings;
            var buf: [256]u8 = undefined;
            try std.testing.expect(fixture.pumpKey(VK_INSERT));
            try std.testing.expectEqual(ProfileEdit.Kind.new_id, (try openEdit(settings)).kind);

            // An id the draft has already is refused; the field stays.
            typeInto((try openEdit(settings)).hwnd.?, "PY");
            try std.testing.expect(fixture.pumpKey(VK_RETURN));
            try std.testing.expectEqual(ProfileEdit.Kind.new_id, (try openEdit(settings)).kind);
            try std.testing.expectEqualStrings("Error: A profile with that id exists already.", try statusTextOf(settings, &buf));

            typeInto((try openEdit(settings)).hwnd.?, "dev");
            try std.testing.expect(fixture.pumpKey(VK_RETURN));
            try std.testing.expectEqual(ProfileEdit.Kind.new_command, (try openEdit(settings)).kind);
            const command = (try openEdit(settings)).hwnd.?;
            try std.testing.expectEqual(command, sys.GetFocus().?);
            const provider = (try openEdit(settings)).provider.?;
            try std.testing.expectEqualStrings("Command line of dev", try uiaStringProperty(&provider.base, @import("win32_uia/constants.zig").UIA_NamePropertyId, &buf));
            // An empty command line is refused.
            try std.testing.expect(fixture.pumpKey(VK_RETURN));
            try std.testing.expect(settings.profile_edit != null);
            typeInto(command, "cmd.exe /k");
            try std.testing.expect(fixture.pumpKey(VK_RETURN));
            try std.testing.expect(settings.profile_edit == null);
            // The new profile is selected, marked new.
            const selected = settings.profile_list.selectedPosition().?;
            try std.testing.expectEqualStrings("dev, profile user:dev, new, not saved yet", profileRowName(settings, selected, &buf));

            settings.save();
            const after = try tmp.dir.readFileAlloc(alloc, "noctty.conf", 1 << 20);
            defer alloc.free(after);
            try std.testing.expectEqualStrings("profile-command = py: python.exe\n\nprofile-command = dev: cmd.exe /k\n", after);
        }
    }.body);
}

test "settings removing a profile takes a second Delete, says what it does, and never says the command" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            // Keys read as pressed alone, whatever the live keyboard holds.
            const keyboard = win32_input.TestingKeyboard.pinNone();
            defer keyboard.release();
            const alloc = std.testing.allocator;
            var tmp = std.testing.tmpDir(.{});
            defer tmp.cleanup();
            var path: []u8 = &.{};
            const secret = "s3cr3t-token";
            const fixture = try profileFixture(&tmp, "profile-command = py: python.exe --token=" ++ secret ++ "\ndefault-profile = py\nprofile-command = keep: k.exe\n", &path);
            defer alloc.free(path);
            defer fixture.finish();
            const settings = &fixture.settings;
            const list = &settings.profile_list;
            var buf: [512]u8 = undefined;
            list.selectPosition(1);
            try std.testing.expect(fixture.pumpKey(VK_DELETE));
            var status = try statusTextOf(settings, &buf);
            try std.testing.expectEqualStrings("Press Delete again to remove profile py. Default profile names it, so new tabs will open the automatic shell; Save writes the change.", status);
            try std.testing.expect(!settings.hasPendingChanges());

            // A held Delete's repeats do nothing.
            try std.testing.expect(fixture.pumpKeyRepeat(VK_DELETE, true));
            try std.testing.expect(!settings.hasPendingChanges());

            // Moving away lets go of it: the next Delete asks again.
            try std.testing.expect(fixture.pumpKey(focus_cue.vk_down));
            try std.testing.expect(fixture.pumpKey(focus_cue.vk_up));
            try std.testing.expect(fixture.pumpKey(VK_DELETE));
            try std.testing.expect(!settings.hasPendingChanges());
            try std.testing.expect(fixture.pumpKey(VK_DELETE));
            try std.testing.expect(settings.hasPendingChanges());
            status = try statusTextOf(settings, &buf);
            try std.testing.expect(std.mem.startsWith(u8, status, "Removed profile py."));
            try std.testing.expect(std.mem.indexOf(u8, status, secret) == null);
            // New profile and keep's five rows are left, keep's own selected.
            try std.testing.expectEqual(@as(usize, 6), list.shown_count);
            try std.testing.expectEqualStrings("keep, profile user:keep", profileRowName(settings, list.selectedPosition().?, &buf));

            // Only this file defined it, but `default-profile` still names
            // it: its line becomes the tombstone, which keeps the id known
            // to the loader (`settings_patch.referencedElsewhere`).
            settings.save();
            const after = try tmp.dir.readFileAlloc(alloc, "noctty.conf", 1 << 20);
            defer alloc.free(after);
            try std.testing.expectEqualStrings("profile-command = py:\ndefault-profile = py\nprofile-command = keep: k.exe\n", after);
        }
    }.body);
}

test "settings a value the Profiles page refuses keeps its field, never repeats it, and Escape puts it back" {
    try dialog_test.onHiddenDesktop(struct {
        fn body() !void {
            // Keys read as pressed alone, whatever the live keyboard holds.
