            var tallest: usize = 0;
            var tallest_height: i32 = 0;
            for (0..list.shown_count) |position| {
                list.selectPosition(position);
                const metrics = list.ensureMetrics().?;
                errdefer std.debug.print("settings All settings row for {s}\n", .{@tagName(settings_reference.keys[list.shown[position]])});
                try std.testing.expect(metrics.body > 0);
                try std.testing.expect(metrics.open > metrics.row);
                const text = list.open_body.?;
                const hdc = GetDC(window).?;
                defer _ = ReleaseDC(window, hdc);
                const previous = SelectObject(hdc, settings.ui_font);
                defer _ = SelectObject(hdc, previous);
                var rect: RECT = .{ .left = 0, .top = 0, .right = ReferenceList.textWidth(metrics), .bottom = 0 };
                _ = DrawTextW(hdc, text.ptr, @intCast(text.len), &rect, DT_CALCRECT | DT_WORDBREAK | DT_NOPREFIX | DT_EXPANDTABS);
                try std.testing.expect(rect.right <= ReferenceList.textWidth(metrics));
                if (metrics.open > tallest_height) {
                    tallest = position;
                    tallest_height = metrics.open;
                }
            }
            dialog_test.flushPaint(fixture.hwnd());

            // The tallest is taller than the list: Page Down reads through it
            // before it moves on, and Page Up back to its top.
            list.selectPosition(tallest);
            const metrics = list.ensureMetrics().?;
            const view = list.clientHeight();
            try std.testing.expect(metrics.open > view);
            const top = ReferenceList.rowTop(metrics, tallest, tallest);
            try std.testing.expectEqual(top, list.scroll_y);
            var pages: usize = 0;
            while (list.scroll_y + view < top + metrics.open) : (pages += 1) {
                try std.testing.expect(fixture.pumpKey(focus_cue.vk_next));
                try std.testing.expectEqual(@as(?usize, tallest), list.selectedPosition());
            }
            try std.testing.expect(pages > 0);
            try std.testing.expectEqual(top + metrics.open - view, list.scroll_y);
            // Where it is being read stays when the focus leaves and comes
            // back (to the config file and back, say), and when a click lands
            // in its text.
            const reading = list.scroll_y;
            _ = SetFocus(settings.edit_search.?);
            _ = SetFocus(window);
            try std.testing.expectEqual(reading, list.scroll_y);
            const in_text: LPARAM = @bitCast((@as(usize, @intCast(@divTrunc(view, 2))) << 16) | @as(usize, @intCast(metrics.pad_x + metrics.bar + 1)));
            _ = sys.SendMessageW(window, WM_LBUTTONDOWN, 0, in_text);
            try std.testing.expectEqual(@as(?usize, tallest), list.selectedPosition());
            try std.testing.expectEqual(reading, list.scroll_y);
            if (tallest + 1 < list.shown_count) {
                try std.testing.expect(fixture.pumpKey(focus_cue.vk_next));
                try std.testing.expect(list.selectedPosition().? > tallest);
            }
        }
    }.body);
}

/// The form viewport (`SettingsWindow.viewport`). It paints only the pane
/// colour behind the fields and owns the scroll bar; the fields' commands and
/// colour queries go on to the Settings window, which handles them as it did
/// when the fields were its own children. The wheel needs nothing here:
/// `DefWindowProc` hands it to the parent.
fn viewportProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    if (msg == WM_NCCREATE) {
        const cs: *const CREATESTRUCTW = @ptrFromInt(@as(usize, @bitCast(lParam)));
        if (cs.lpCreateParams) |ptr| _ = sys.SetWindowLongPtrW(hwnd, GWLP_USERDATA, @intCast(@intFromPtr(ptr)));
    }
    const owner = recoverOwner(hwnd) orelse return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
    switch (msg) {
        WM_ERASEBKGND => return 1,
        WM_PRINTCLIENT => {
            var rect: RECT = undefined;
            if (wParam != 0 and GetClientRect(hwnd, &rect) != 0) paintViewport(owner, @ptrFromInt(wParam), rect);
            return 0;
        },
        WM_PAINT => {
            var ps: PAINTSTRUCT = undefined;
            const hdc = sys.BeginPaint(hwnd, &ps);
            paintViewport(owner, hdc, ps.rcPaint);
            _ = sys.EndPaint(hwnd, &ps);
            return 0;
        },
        // A label, a dropdown, a checkbox or a Reset button that was
        // right-clicked (or Shift+F10 on it), or the room between them. A text
        // field shows its own Cut/Copy/Paste menu and sends nothing here. What
        // is no row's (the scroll bar) keeps DefWindowProc's menu.
        WM_CONTEXTMENU => if (wParam != 0 and owner.showRowMenu(@ptrFromInt(wParam), lParam)) return 0,
        WM_COMMAND,
        WM_CTLCOLORMSGBOX,
        WM_CTLCOLOREDIT,
        WM_CTLCOLORLISTBOX,
        WM_CTLCOLORBTN,
        WM_CTLCOLORDLG,
        WM_CTLCOLORSTATIC,
        => if (owner.hwnd) |settings| return sys.SendMessageW(settings, msg, wParam, lParam),
        // The viewport's own scroll bar; an up-down's (lParam its window)
        // is not the page's.
        WM_VSCROLL => {
            if (lParam == 0) owner.scrollByBar(wParam & 0xFFFF);
            return 0;
        },
        WM_HSCROLL => {
            if (lParam != 0 and owner.companions[@intFromEnum(Companion.opacity_slider)] == @as(?HWND, @ptrFromInt(@as(usize, @bitCast(lParam))))) owner.sliderMoved();
            return 0;
        },
        WM_NOTIFY => if (owner.companionNotify(lParam)) |result| return result,
        WM_DRAWITEM => if (lParam != 0) {
            const draw: *const sys.DRAWITEMSTRUCT = @ptrFromInt(@as(usize, @bitCast(lParam)));
            if (std.mem.indexOfScalar(?HWND, &owner.field_labels, draw.hwndItem) != null) {
                owner.paintFieldLabel(draw);
                return 1;
            }
        },
        WM_GETOBJECT => if (owner.viewport_uia_provider) |provider| {
            if (win32_uia.returnSettingsControlProvider(hwnd, wParam, lParam, provider)) |result| return result;
        },
        WM_NCDESTROY => {
            if (owner.viewport_uia_provider) |provider| provider.detach();
            _ = sys.SetWindowLongPtrW(hwnd, GWLP_USERDATA, 0);
        },
        else => {},
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

fn settingsSectionDisconnect(ctx: *anyopaque) win32_uia.HRESULT {
    return (@as(*win32_uia.SettingsSectionProvider, @ptrCast(@alignCast(ctx)))).disconnect();
}

fn settingsSectionRelease(ctx: *anyopaque) void {
    const provider: *win32_uia.SettingsSectionProvider = @ptrCast(@alignCast(ctx));
    _ = win32_uia.SettingsSectionProvider.Release(&provider.base);
}

fn settingsSectionGroupDisconnect(ctx: *anyopaque) win32_uia.HRESULT {
    return (@as(*win32_uia.SettingsSectionGroupProvider, @ptrCast(@alignCast(ctx)))).disconnect();
}

fn settingsSectionGroupRelease(ctx: *anyopaque) void {
    const provider: *win32_uia.SettingsSectionGroupProvider = @ptrCast(@alignCast(ctx));
    _ = win32_uia.SettingsSectionGroupProvider.Release(&provider.base);
}

fn settingsControlDisconnect(ctx: *anyopaque) win32_uia.HRESULT {
    return (@as(*win32_uia.SettingsControlProvider, @ptrCast(@alignCast(ctx)))).disconnect();
}

fn settingsControlRelease(ctx: *anyopaque) void {
    const provider: *win32_uia.SettingsControlProvider = @ptrCast(@alignCast(ctx));
    _ = win32_uia.SettingsControlProvider.Release(&provider.base);
}

/// The viewport's own pixels inside `clip`: the pane colour, and the marker of
/// each row whose value differs from its default (`marker_rects`).
fn paintViewport(owner: *const SettingsWindow, hdc: HDC, clip: RECT) void {
    fillSolid(hdc, clip, owner.theme_adapter.colors.window_bg);
    const color = owner.markerColor();
    for (owner.marker_rects) |marker| if (marker) |rect| {
        const shown: RECT = .{
            .left = @max(rect.left, clip.left),
            .top = @max(rect.top, clip.top),
            .right = @min(rect.right, clip.right),
            .bottom = @min(rect.bottom, clip.bottom),
        };
        if (shown.left < shown.right and shown.top < shown.bottom) fillSolid(hdc, shown, color);
    };
}

fn paint(hwnd: HWND, owner: *SettingsWindow) void {
    var ps: PAINTSTRUCT = undefined;
    const hdc = sys.BeginPaint(hwnd, &ps);
    defer _ = sys.EndPaint(hwnd, &ps);
    paintBackground(hwnd, owner, hdc);
}

/// The frame window's own pixels: the pane colour, the rail and the three
/// separators. Under WS_CLIPCHILDREN this never reaches a child. Also drawn
/// into the DC a themed child hands over through DrawThemeParentBackground
/// (WM_PRINTCLIENT), which a button's rounded corners need now that the frame
/// no longer paints under its children.
fn paintBackground(hwnd: HWND, owner: *SettingsWindow, hdc: HDC) void {
    var rect: RECT = undefined;
    if (sys.GetClientRect(hwnd, &rect) == 0) return;
    const colors = owner.theme_adapter.colors;
    const geometry = backgroundGeometry(owner, rect);
    var pane = rect;
    pane.left = geometry.rail.right;
    fillSolid(hdc, pane, colors.window_bg);
    fillSolid(hdc, geometry.rail, colors.rail_bg);
    fillSolid(hdc, geometry.rail_separator, colors.rail_separator);
    fillSolid(hdc, geometry.header_separator, colors.pane_separator);
    fillSolid(hdc, geometry.action_separator, colors.pane_separator);
}

fn fillSolid(hdc: HDC, rect: RECT, color: COLORREF) void {
    _ = SetDCBrushColor(hdc, color);
    _ = FillRect(hdc, &rect, GetStockObject(DC_BRUSH));
}

/// A `width`-pixel line just inside `rect`.
fn strokeRect(hdc: HDC, rect: RECT, color: COLORREF, width: i32) void {
    const w = @min(width, @divTrunc(rect.right - rect.left, 2), @divTrunc(rect.bottom - rect.top, 2));
    if (w <= 0) return;
    const sides = [_]RECT{
        .{ .left = rect.left, .top = rect.top, .right = rect.right, .bottom = rect.top + w },
        .{ .left = rect.left, .top = rect.bottom - w, .right = rect.right, .bottom = rect.bottom },
        .{ .left = rect.left, .top = rect.top + w, .right = rect.left + w, .bottom = rect.bottom - w },
        .{ .left = rect.right - w, .top = rect.top + w, .right = rect.right, .bottom = rect.bottom - w },
    };
    for (sides) |side| fillSolid(hdc, side, color);
}

/// Line height of `font` (one line of `DrawText` is the font's full height,
/// as an EDIT lays out its line).
fn fontLineHeight(hwnd: HWND, font: HGDIOBJ) i32 {
    const hdc = GetDC(hwnd) orelse return 0;
    defer _ = ReleaseDC(hwnd, hdc);
    const previous = SelectObject(hdc, font);
    defer _ = SelectObject(hdc, previous);
    const sample = std.unicode.utf8ToUtf16LeStringLiteral("Ag");
    var rect: RECT = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
    _ = DrawTextW(hdc, sample, sample.len, &rect, DT_CALCRECT | DT_SINGLELINE | DT_NOPREFIX);
    return rect.bottom - rect.top;
}

/// The selection-field height to ask a dropdown for so that its window is
/// `target` tall, given its window height now and the field height it has.
fn comboSelectionHeight(window_height: i32, selection_height: i32, target: i32) i32 {
    return @max(1, target - (window_height - selection_height));
}

fn readEditUtf8(edit: HWND, buf: []u8) ?[]const u8 {
    var buf_w: [edit_text_max_code_units]u16 = undefined;
    const n = sys.GetWindowTextW(edit, &buf_w, @intCast(buf_w.len));
    const written = std.unicode.utf16LeToUtf8(buf, buf_w[0..@intCast(n)]) catch return null;
    return buf[0..written];
}

fn setEditText(edit: HWND, text: []const u8, suppress: *bool) void {
    var buf_w: [edit_text_max_code_units]u16 = undefined;
    const w = utf8ToW(&buf_w, text);
    suppress.* = true;
    _ = sys.SendMessageW(edit, WM_SETTEXT, 0, @bitCast(@intFromPtr(w)));
    suppress.* = false;
}

const parseFontFamilyEditText = field_model.parseFontFamilyEditText;
const writeCommandForEdit = field_model.writeCommandForEdit;

fn commandEql(a: Config.Command, b: Config.Command) bool {
    return switch (a) {
        .shell => |a_value| switch (b) {
            .shell => |b_value| std.mem.eql(u8, a_value, b_value),
            .direct => false,
        },
        .direct => |a_args| switch (b) {
            .shell => false,
            .direct => |b_args| args: {
                if (a_args.len != b_args.len) break :args false;
                for (a_args, b_args) |a_arg, b_arg| {
                    if (!std.mem.eql(u8, a_arg, b_arg)) break :args false;
                }
                break :args true;
            },
        },
    };
}

fn optionalThemeEql(a: ?Config.Theme, b: ?Config.Theme) bool {
    if (a == null or b == null) return a == null and b == null;
    return std.mem.eql(u8, a.?.light, b.?.light) and
        std.mem.eql(u8, a.?.dark, b.?.dark);
}

fn optionalCommandEql(a: ?Config.Command, b: ?Config.Command) bool {
    if (a == null or b == null) return a == null and b == null;
    return commandEql(a.?, b.?);
}

fn optionalStringEql(a: ?[:0]const u8, b: ?[:0]const u8) bool {
    if (a == null or b == null) return a == null and b == null;
    return std.mem.eql(u8, a.?, b.?);
}

fn ownedSettingEql(a: *const Config, b: *const Config, field: OwnedSettingField) bool {
    return switch (field) {
        .font_family => a.@"font-family".equal(b.@"font-family"),
        .theme => optionalThemeEql(a.theme, b.theme),
        .command => optionalCommandEql(a.command, b.command),
        .default_profile => optionalStringEql(a.@"default-profile", b.@"default-profile"),
    };
}

/// Whether `field` is unset in `config`: no font, theme, command or profile.
fn ownedSettingBlank(config: *const Config, field: OwnedSettingField) bool {
    return switch (field) {
        .font_family => config.@"font-family".count() == 0,
        .theme => config.theme == null,
        .command => config.command == null,
        .default_profile => config.@"default-profile" == null,
    };
}

/// Whether `edit` holds anything besides `blank` characters.
fn editHoldsText(edit: HWND, comptime blank: []const u8) bool {
    var text_w: [edit_text_max_code_units]u16 = undefined;
    const length = GetWindowTextW(edit, &text_w, @intCast(text_w.len));
    for (text_w[0..@intCast(@max(0, length))]) |unit| {
        if (unit > 0x7F or std.mem.indexOfScalar(u8, blank, @intCast(unit)) == null) return true;
    }
    return false;
}

fn copyOwnedSetting(target: *Config, source: *const Config, field: OwnedSettingField) !void {
    storeOwnedSetting(target, try cloneOwnedSetting(target, source, field));
}

/// One owned setting's value, as a config holds it.
const OwnedSettingValue = union(OwnedSettingField) {
    font_family: @FieldType(Config, "font-family"),
    theme: @FieldType(Config, "theme"),
    command: @FieldType(Config, "command"),
    default_profile: @FieldType(Config, "default-profile"),
};

/// `source`'s value of `field`, copied into `target`'s arena but not stored.
fn cloneOwnedSetting(target: *Config, source: *const Config, field: OwnedSettingField) std.mem.Allocator.Error!OwnedSettingValue {
    const alloc = target._arena.?.allocator();
    return switch (field) {
        .font_family => .{ .font_family = try source.@"font-family".clone(alloc) },
        .theme => .{ .theme = if (source.theme) |*value| try value.clone(alloc) else null },
        .command => .{ .command = if (source.command) |*value| try value.clone(alloc) else null },
        .default_profile => .{ .default_profile = if (source.@"default-profile") |value| try alloc.dupeZ(u8, value) else null },
    };
}

fn storeOwnedSetting(target: *Config, value: OwnedSettingValue) void {
    switch (value) {
        .font_family => |v| target.@"font-family" = v,
        .theme => |v| target.theme = v,
        .command => |v| target.command = v,
        .default_profile => |v| target.@"default-profile" = v,
    }
}

fn writeOwnedSettingValue(writer: *std.Io.Writer, config: *const Config, field: OwnedSettingField) !void {
    switch (field) {
        inline else => |owned| try field_model.writeOwnedSettingValue(owned.descriptor().key, writer, config),
    }
}

/// The room the Advanced page gives the save target and the config problems
/// ahead of the pending changes, and the part of it for each. The save target
/// is at most 240 bytes of path and an ellipsis.
const advanced_head_bytes = 1400;
const advanced_problems_bytes = 1000;
const advanced_target_bytes = 243;
const no_pending_changes_text = "No changes waiting to be saved.";

const writeSettingValue = field_model.writeSettingValue;

/// One line of the "waiting to be saved" list: `Cursor style: Block -> Bar`.
fn writeSettingDiffLine(writer: *std.Io.Writer, field: SettingField, baseline: SettingValue, draft: SettingValue) !void {
    try writer.print("{s}: ", .{field.label()});
    try writeSettingValue(writer, baseline);
    try writer.writeAll(" -> ");
    try writeSettingValue(writer, draft);
    try writer.writeByte('\n');
}

/// The status line for a setting that changed in the config file while it was
/// being edited here. `label` is the name the form shows, not the field tag.
fn conflictStatusText(buf: []u8, label: []const u8) []const u8 {
    return std.fmt.bufPrint(buf, "{s} also changed on disk. Choose Keep mine or Use disk.", .{label}) catch
        "A setting also changed on disk. Choose Keep mine or Use disk.";
}

/// Closes a diff list that did not fit; written into the buffer's reserved tail.
const more_changes_text = "...and more changes.\n";

const OwnedDiffs = struct { lines: usize, truncated: bool };

/// The lines of the owned fields (font family, theme, default command) that are
/// edited or in conflict. A line that does not fit is dropped whole, so a long
/// default command costs only its own line, not the short ones before it.
fn writeOwnedSettingDiffs(
    writer: *std.Io.Writer,
    original: *const Config,
    pending: *const Config,
    dirty: [owned_setting_field_count]bool,
    conflict: [owned_setting_field_count]bool,
) OwnedDiffs {
    var result: OwnedDiffs = .{ .lines = 0, .truncated = false };
    for (std.enums.values(OwnedSettingField)) |field| {
        const index = @intFromEnum(field);
        if (!dirty[index] and !conflict[index]) continue;
        const line_start = writer.end;
        writeOwnedSettingDiffLine(writer, original, pending, field, conflict[index]) catch {
            writer.end = line_start;
            result.truncated = true;
            break;
        };
        result.lines += 1;
    }
    return result;
}

fn writeOwnedSettingDiffLine(
    writer: *std.Io.Writer,
    original: *const Config,
    pending: *const Config,
    field: OwnedSettingField,
    conflict: bool,
) !void {
    try writer.print("{s}: ", .{field.label()});
    try writeOwnedSettingValue(writer, original, field);
    try writer.writeAll(" -> ");
    try writeOwnedSettingValue(writer, pending, field);
    if (conflict) try writer.writeAll(" (conflict)");
    try writer.writeByte('\n');
}

/// `wide` as UTF-8 in `buf`, a lone surrogate as U+FFFD. What does not fit is
/// left out, a whole character at a time.
fn utf16ToUtf8Lossy(buf: []u8, wide: []const u16) []const u8 {
    var len: usize = 0;
    var index: usize = 0;
    while (index < wide.len) {
        var codepoint: u21 = wide[index];
        index += 1;
        if (codepoint >= 0xD800 and codepoint <= 0xDBFF and index < wide.len and wide[index] >= 0xDC00 and wide[index] <= 0xDFFF) {
            codepoint = 0x10000 + ((codepoint - 0xD800) << 10) + (wide[index] - 0xDC00);
            index += 1;
        } else if (codepoint >= 0xD800 and codepoint <= 0xDFFF) {
            codepoint = 0xFFFD;
        }
        var bytes: [4]u8 = undefined;
        const count = std.unicode.utf8Encode(codepoint, &bytes) catch unreachable;
        if (len + count > buf.len) break;
        @memcpy(buf[len..][0..count], bytes[0..count]);
        len += count;
    }
    return buf[0..len];
}

/// Performance-counter ticks `start`..`end` in whole microseconds, capped.
fn elapsedMicroseconds(start: u64, end: u64, frequency: u64) u32 {
    if (frequency == 0 or end < start) return 0;
    const us = @as(u128, end - start) * std.time.us_per_s / frequency;
    return @intCast(@min(us, std.math.maxInt(u32)));
}

fn utf8ToW(buf: []u16, text: []const u8) [*:0]const u16 {
    std.debug.assert(buf.len > 0);
    if (!std.unicode.utf8ValidateSlice(text)) {
        buf[0] = 0;
        return @ptrCast(buf.ptr);
    }

    const capacity = buf.len - 1;
    var byte_end: usize = 0;
    var utf16_len: usize = 0;
    while (byte_end < text.len) {
        const scalar_len = std.unicode.utf8ByteSequenceLength(text[byte_end]) catch unreachable;
        const codepoint = std.unicode.utf8Decode(text[byte_end .. byte_end + scalar_len]) catch unreachable;
        const unit_len: usize = if (codepoint <= 0xFFFF) 1 else 2;
        if (utf16_len + unit_len > capacity) break;
        utf16_len += unit_len;
        byte_end += scalar_len;
    }

    const written = std.unicode.utf8ToUtf16Le(buf[0..capacity], text[0..byte_end]) catch unreachable;
    std.debug.assert(written == utf16_len);
    buf[written] = 0;
    return @ptrCast(buf.ptr);
}

test "win32_settings: utf8ToW rejects invalid input without a partial prefix" {
    var buf = [_]u16{0xAAAA} ** 8;
    const converted = utf8ToW(&buf, "valid\xFFinvalid");

    try std.testing.expectEqual(@as(usize, 0), std.mem.len(converted));
    try std.testing.expectEqual(@as(u16, 0), buf[0]);
}

test "win32_settings: utf8ToW truncates ASCII for the terminator" {
    var buf: [5]u16 = undefined;
    const converted = utf8ToW(&buf, "abcdef");

    try std.testing.expectEqualSlices(u16, &.{ 'a', 'b', 'c', 'd' }, converted[0..4]);
    try std.testing.expectEqual(@as(u16, 0), buf[4]);
}

test "win32_settings: utf8ToW never splits a supplementary scalar" {
    var too_small = [_]u16{0xAAAA} ** 2;
    const omitted = utf8ToW(&too_small, "🚀");
    try std.testing.expectEqual(@as(usize, 0), std.mem.len(omitted));
    try std.testing.expectEqual(@as(u16, 0), too_small[0]);

    var fits: [3]u16 = undefined;
    const converted = utf8ToW(&fits, "🚀");
    try std.testing.expectEqualSlices(
        u16,
        std.unicode.utf8ToUtf16LeStringLiteral("🚀"),
        converted[0..2],
    );
    try std.testing.expectEqual(@as(u16, 0), fits[2]);
}

test "settings pointer result preserves high-bit handle bits" {
    const pointer: *anyopaque = @ptrFromInt(std.math.maxInt(usize));
    try std.testing.expectEqual(@as(LRESULT, -1), pointerLresult(pointer));
}

test "settings background blur checkbox preserves enabled radius" {
    try std.testing.expectEqual(
        Config.BackgroundBlur{ .radius = 42 },
        backgroundBlurFromCheckbox(.{ .radius = 42 }, true),
    );
    try std.testing.expectEqual(
        .true,
        backgroundBlurFromCheckbox(.false, true),
    );
    try std.testing.expectEqual(
        .true,
        backgroundBlurFromCheckbox(.{ .radius = 0 }, true),
    );
}

test "settings background blur checkbox can disable any variant" {
    try std.testing.expectEqual(
        .false,
        backgroundBlurFromCheckbox(.true, false),
    );
    try std.testing.expectEqual(
        .false,
        backgroundBlurFromCheckbox(.{ .radius = 42 }, false),
    );
}

test "settings policy combo mappings round trip" {
    try std.testing.expectEqual(Config.ClipboardAccess.ask, clipboardAccessFromComboIndex(0).?);
    try std.testing.expectEqual(Config.ClipboardAccess.allow, clipboardAccessFromComboIndex(1).?);
    try std.testing.expectEqual(Config.ClipboardAccess.deny, clipboardAccessFromComboIndex(2).?);
    try std.testing.expectEqual(@as(?Config.ClipboardAccess, null), clipboardAccessFromComboIndex(3));
    try std.testing.expectEqual(@as(usize, 0), comboIndexFromClipboardAccess(.ask));
    try std.testing.expectEqual(@as(usize, 1), comboIndexFromClipboardAccess(.allow));
    try std.testing.expectEqual(@as(usize, 2), comboIndexFromClipboardAccess(.deny));

    try std.testing.expectEqual(true, linkUrlFromComboIndex(0).?);
    try std.testing.expectEqual(false, linkUrlFromComboIndex(1).?);
    try std.testing.expectEqual(@as(?bool, null), linkUrlFromComboIndex(2));
    try std.testing.expectEqual(@as(usize, 0), comboIndexFromLinkUrl(true));
    try std.testing.expectEqual(@as(usize, 1), comboIndexFromLinkUrl(false));

    try std.testing.expectEqual(Config.LinkPreviews.true, linkPreviewsFromComboIndex(0).?);
    try std.testing.expectEqual(Config.LinkPreviews.osc8, linkPreviewsFromComboIndex(1).?);
    try std.testing.expectEqual(Config.LinkPreviews.false, linkPreviewsFromComboIndex(2).?);
    try std.testing.expectEqual(@as(?Config.LinkPreviews, null), linkPreviewsFromComboIndex(3));
    try std.testing.expectEqual(@as(usize, 0), comboIndexFromLinkPreviews(.true));
    try std.testing.expectEqual(@as(usize, 1), comboIndexFromLinkPreviews(.osc8));
    try std.testing.expectEqual(@as(usize, 2), comboIndexFromLinkPreviews(.false));
}

